insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (1,'قرارات الرئيس','قرار رقم 9/هـ.ش.ع/2023: تحديد أُسس تأليف لجان التلزيم والاستلام لدى الجهات الشارية','2024-10-09','https://www.ppa.gov.lb/ar/pages/details/1','{"https://admin.ppa.gov.lb/storage/listing-pages/files/TIacPTQZEbiy0QlKYwRGqpFu0K8TNR3GmmNC-1760212615.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/TIacPTQZEbiy0QlKYwRGqpFu0K8TNR3GmmNC-1760212615.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=1),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "قرار رقم /9هـ.ش.ع2023/\n تحديد أسس تأليف لجان التلزيم واالستالم لدى الجهات الشارية\n ان رئيس هيئة الشراء العام،\nبناء على المادة ٨٨من قانون الشراء العام التي أوكلت إلى رئيس هيئة الشراء العام مهام الهيئة الى حين\n ً\n تعيينها.\nبناء على القانون رقم ٢0٢3/309تاريخ ٢0٢3/٤/١9المنشور في العدد ١٧من الجريدة الرسمية تاريخ\n ً\n ٢0٢3/٤/٢٦الذي عدل بعض مواد قانون الشراء العام (القانون رقم ٢٤٤تاريخ ٢0٢١/٧/١9النافذ\n اعتبا اًر من ،)٢0٢٢/٧/٢9ال سيما الفقرتين الخامسة والسادسة من المادة األولى منه ،التالي نصهما:\n▪ الفقرة الخامسة« :يستبدل نص الفقرة ١٤من المادة ٧٦من قانون الشراء العام (مهام هيئة الشراء\nالعام) بالنص التالي :التحقق من مؤهالت اعضاء لجان التلزيم واالستالم لدى الجهات الشارية\nوتضمين تقاريرها ،عند االقتضاء ،مدى مطابقة هذه المؤهالت لشروط الخبرة واالختصاص\n المطلوبة».\n▪ الفقرة السادسة« :تلغى الفقرات ٢و 3من المادة ( ١00أوالً) من قانون الشراء العام ،وتضاف إليها\nالفقرة التالية :يتم تأليف لجان التلزيم لدى الجهة الشارية من أهل الخبرة واالختصاص وفقاً ألسس\nتضعها هيئة الشراء العام على أن تكون األولوية في تشكيل هذه اللجان لألشخاص المدربين على\nالشراء العام .كما وتلغى الفقرات ١و ٢من المادة ١0١من قانون الشراء العام ،وتضاف إليها الفقرة\nالتالية :يتم تأليف لجان االستالم لدى الجهة الشارية من أهل الخبرة واالختصاص وفقاً ألسس\nتضعها هيئة الشراء العام على أن تكون األولوية في تشكيل هذه اللجان لألشخاص المدربين على\n الشراء العام».\nبناء على قرار المجلس الدستوري رقم ٢0٢3/٧تاريخ ٢0٢3/٦/٦المنشور في العدد ٤٤من الجريدة\n ً\nالرسمية بتاريخ ٢0٢3/٦/٨الذي قرر رد الطعن المقدم بالقانون المذكور في األساس في جميع األسباب\n التي بني عليها.\n1/4\n\f يقرر ما يلي:"}, {"o": 1, "l": null, "b": "مع التقيد بأحكام المادتين ١00و ١0١من قانون الشراء العام ،تعتمد في تأليف لجان التلزيم واإلستالم،\n األسس التالية:\n أواال :الوضع الوظيفي\nيتم إختيار رئيس وأعضاء لجان التلزيم واإلستالم (األصيلة والرديفة) من بين موظفي ومتعاقدي الجهات\nالشارية ،وفي حال عدم وجود عدد كاف من الموظفين والمتعاقدين فمن سائر العاملين المشمولين بأحكام\nالمادة ١١١من قانون الموازنة العامة لعام .٢0٢٢في البلديات ،وفي حال عدم توافر موظفين أو متعاقدين\n أو عاملين على نحو ما ورد أعالهُ ،يستعان بأعضاء من المجلس البلدي ،باستثناء رئيس البلدية.\n ثانيا :التخصص والتدريب\n ا\n -1تُعطى األولوية في اختيار رئيس وأعضاء لجان التلزيم واإلستالم للمدربين على الشراء العام لدى\nالمعاهد المعتمدة أصوًال ،وفقًا ألحكام المادة ٧٢من قانون الشراء العام ،ومنها معهد باسل فليحان\n المالي واالقتصادي والمعهد الوطني لإلدارة.\n -2تُراعى شروط توفر الخبرة واالختصاص بحسب موضوع التلزيم وفقًا ألحكام دفتر الشروط الخاص\n بالصفقة.\n ثال اثا :تشكيل لوائح لجان التلزيم واإلستالم\n -1على كل جهة شارية إعداد لوائح سنوية بأسماء األشخاص المقترحين لرئاسة وعضوية لجان التلزيم\nواإلستالم عن السنة القادمة ،توازياً مع تحضير خطة الشراء السنوية ،وذلك قبل نهاية السنة الجارية\n كحد أقصى ،وفقًا لما يلي:\nأ -تُقر الالئحة الخاصة بلجان التلزيم بقرار من الوزير أو رأس اإلدارة في اإلدارات العامة وبقرار من\nمجلس اإلدارة في المؤسسات العامة وبقرار من السلطة التقريرية في البلديات وغيرها من الهيئات،\n فصليا عند االقتضاء بالطريقة ذاتها.\n ً وتحدث\nب -تُقر الالئحة الخاصة بلجان االستالم بقرار من المدير العام في اإلدارات والمؤسسات العامة وبقرار\nفصليا عند االقتضاء بالطريقة\n ً من السلطة التقريرية في البلديات وغيرها من الهيئات ،وتحدث\n ذاتها.\n2/4"}, {"o": 2, "l": null, "b": "-2تتضمن اللوائح أسماء األشخاص وصفتهم الوظيفية ،اختصاصهم وعدد سنوات الخبرة في اختصاصهم\n وفي الشراء العام ،وما إذا كانوا قد خضعوا للتدريب على الشراء العام أم ال.\n الموحد الصادر عن هيئة الشراء العام.\n ّ ُ -3يعتمد في اعداد اللوائح وتحديثها النموذج\nمناسبا ،وعلى الجهات الشارية إرسال\n ً -4لهيئة الشراء العام طلب إيداعها هذه اللوائح في أي وقت تراه\n هذه اللوائح إلى الهيئة عند الطلب.\n ابعا :تعيين لجان التلزيم واإلستالم\n را\n -1تعيين لجان التلزيم:\nأ -تُعين لجنة تلزيم (أصيلة ورديفة) بقرار من المرجع الصالح لعقد النفقة لكل عملية تلزيم من اللوائح\nالمحدثة المشار إليها في البند (ثالثًا) أعاله ،وذلك قبل سبعة أيام عمل على األقل من\n ّ السنوية\n الموعد النهائي لتقديم العروض.\n ب -يتم تبليغ الرئيس واألعضاء بقرار تعيين اللجنة فور صدوره مرفقًا بملف التلزيم.\nج -يتعين على الجهة الشارية عدم الكشف عن أسماء رئيس واعضاء اللجنة ،الذين يقع عليهم الموجب\n عينه.\nد -على لجنة التلزيم االطالع على ملفات التلزيم الخاصة بالصفقة ودراستها قبل الموعد النهائي لتقديم\n العروض.\n -2تعيين لجان اإلستالم:\nالمحدثة المشار إليها في\n ّ أ -تُعين لجنة استالم (أصيلة ورديفة) لكل عملية تلزيم من اللوائح السنوية\nالفقرة (ثالثًا) اعاله ،بقرار من المدير العام في اإلدارات والمؤسسات العامة وبقرار من السلطة\nالتقريرية في البلديات وغيرها من الهيئات وفقًا ألحكام الفقرة الثانية من المادة ١0١من قانون\n الشراء العام ،وذلك قبل سبعة أيام عمل على األقل من الموعد النهائي لعمليات االستالم.\n ب -يتم تبليغ الرئيس واألعضاء بقرار تعيين اللجنة فور صدوره مرفقًا بملف التلزيم.\nج -يتعين على الجهة الشارية عدم الكشف عن أسماء رئيس واعضاء اللجنة ،الذين يقع عليهم الموجب\n عينه.\n د -على لجنة اإلستالم االطالع على ملفات التلزيم الخاصة بالصفقة ودراستها قبل إجراء اإلستالم."}, {"o": 3, "l": null, "b": "خامسا :غياب األصيل\n ا\nعند غياب الرئيس أو العضو األصيل ألي سبب كان ،يحل محله الرئيس أو العضو البديل من اللجنة\n الرديفة .تكون مسؤولية البديل من تاريخ مباشرة عمله والى حين إنجاز عمل اللجنة.\n3/4\n\f سادسا :عدم اإلدانة وتجنب تضارب المصالح\n ا\n -١ال يجوز أن يعين رئيساً أو عضواً في لجان التلزيم واالستالم من صدر بحقه حكم نهائي مبرم الرتكابه\nجناية او جنحة شائنة ولم يستعد اعتباره .او من ثبت ارتكابه لمخالفات مالية او مسلكية وعوقب بغرامة\nاو بعقوبات تأديبية ولم يمر خمس سنوات على تاريخ صدور القرار القاضي بفرض العقوبة .يكون\n التوقيع على تصريح النزاهة المستند المطلوب لتوفر هذه الشروط.\n -٢يجب أال يكون الرئيس أو أي من األعضاء في حالة تضارب مصالح ،على أن تعتمد بهذا الشأن\nالقواعد واألحكام المشار إليها في قانون الشراء العام ال سيما في المواد ٢ :فقرة ( )30و ١00فقرة ()١\n ثانيا و ١0١فقرة (.)٢\n من أوًال وفقرة ( )٢من ً\n -3يحظر على المدير العام في اإلدارات العامة ورئيس السلطة التنفيذية في البلديات ورئيس مجلس اإلدارة\n عضوا في لجان التلزيم أو االستالم.\n ً ئيسا أو\n -المدير العام -في المؤسسات العامة ان يكون ر ً\n -٤يوقع كل شخص تم تكليفه برئاسة أو عضوية لجان التلزيم أو اإلستالم (األصيلة أو الرديفة) نموذج\n «تصريح النزاهة» المرفق بهذا القرار.\nويتاح\n -5تحتفظ الجهة الشارية بهذه التصاريح الموقعة لمدة عشر ( )١0سنوات من نهاية عمل اللجنةُ ،\nاالطالع عليها لهيئة الشراء العام عند الطلب ،وكذلك للهيئات الرقابية والسلطات القضائية المختصة.\n سابعا :توثيق الق اررات واإلجراءات\n ا\nتوثق كافة االجراءات والق اررات المتخذة بشأن تشكيل لجان التلزيم واإلستالم وتعيين الخبراء وتدرج في سجل\n اجراءات الشراء المنصوص عليه في المادة 9من قانون الشراء العام."}, {"o": 4, "l": null, "b": "ثامانا :ان التكليف بأعمال لجان التلزيم واإلستالم هو من واجبات الوظيفة ويتعرض كل من يرفض قرار\n تكليفه دون مبرر للمساءلة وفقاً لألصول.\n تاسعاُ :يلغى كل نص مخالف ألحكام هذا القرار أو ال يتفق مع مضمونه.\n ا\n عاشرُ :يعمل بهذا القرار فور صدوره وينشر على المنصة اإللكترونية المركزية لدى هيئة الشراء العام.\n اا\n بيروت في 2023/١0/١0\n رئيس هيئة الشراء العام\n د .جان العلية\n4/4"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (6,'تدريب على الشراء العام','الندوة التي تتعلق بتطوير سياسة التدريب الوطنية المتعلّقة بالشراء العام في لبنان اليوم الجمعة الواقع في 24 تشرين الثاني 2023 في تمام الساعة 2:00 من بعد الظهر','2024-10-18','https://www.ppa.gov.lb/ar/pages/details/6','{}',null) on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
