insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (10,'تعاميم','تعميم رقم 7/2019 المتعلق بضرورة إعطاء أفضلية للعروض المحلية صادر عن رئاسة مجلس الوزراء 20 آذار 2019','2019-03-20','https://www.ppa.gov.lb/ar/pages/details/10','{"https://admin.ppa.gov.lb/storage/listing-pages/files/2024-11-10-1731219458-تعميم رقم 7-2019 المتعلق بضرورة إعطاء أفضلية للعروض المقدمة لسلع مصنوعة في لبنان.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/2024-11-10-1731219458-تعميم رقم 7-2019 المتعلق بضرورة إعطاء أفضلية للعروض المقدمة لسلع مصنوعة في لبنان.pdf"}',null) on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (11,'قوانين','قانون الشراء العام في لبنان رقم 244 تاريخ 19 تموز 2021 (مع تعديلاته 2024)','2023-07-18','https://www.ppa.gov.lb/ar/pages/details/11','{"https://admin.ppa.gov.lb/storage/listing-pages/files/St9tELocepeh8x6Py5CYm4dSGb0YGn00npk0-1760211488.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/7xNRr5sUYybbY12Yos2A8o8zvVG5JeDyR4qx-1778653649.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/1789504552-PP law-updated-Oct2024.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/St9tELocepeh8x6Py5CYm4dSGb0YGn00npk0-1760211488.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/7xNRr5sUYybbY12Yos2A8o8zvVG5JeDyR4qx-1778653649.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/1789504552-PP law-updated-Oct2024.pdf"}','ocr+text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=11),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "قانون الشراء العام\n في لبنان\n رقم 244تاريخ 2021/7/29\n الفعالّيـة التخطيط والدمج\nوالمنافسة في الموازنة\n المساءلة الشمولية\nالإستدامة الشفافيـة\n التخصص النزاهة\n\f\fقانون الشراء العام\n في لبنان\nرقم 244تاريخ 2021/7/29\n\f قانون الشراء العام | المبادىء الثمانية\n الفعالّيـة التخطيط والدمج\n والمنافسة في الموازنة\n المساءلة الشمولية\n الإستدامة الشفافيـة\n التخصص النزاهة\nالشمولية :تشمل أحكام هذا القانون كافة إدارات ومؤسسات وهيئات الدولة ،إن كان مصدر التمويل من\n أموال الموازنة أو الخزينة أو من قروض داخلية او خارجية أو هبات.\nالتخطيط والدمج :التخطيط والدمج مع الموازنات من خلال تشجيع عملية التخطيط المتوسط الأمد في إعداد\n الموازنات لتحسين تصميم وتخطيط دورة الشراء.\nالمساءلة :تطبيق آليات واضحة للإشراف والرقابة على أن تشمل استحداث إطار جديد وفّعال للشكاوى\n ت بها ،وتدابير عقاب ملائمة.\n والاعتراضات ضمن مهل محّددة للب ّ\nمـة والطريقة المعيارّيـة لإجراء عمليات الشراء\n الفعالّيـة والمنافسة :الإجراءات التنافسّية هي القاعدة العا ّ\n لتأمين فرص متكافئة وعادلة لجميع المورّدين المحتملين ،ومكافحة الفساد.\nالنزاهة :تعريف النزاهة وتضارب المصالح وتحديد أنواع العقوبات التي تطال موظفي القطاعين العام والخاص\n بدرجات تتناسب مع نوع المخالفة.\n صة الاكترونّية المركزّية مما يتيح الوصول إلى المعلومات والبيانات.\n الشفافّيـة :وجوب النشر على المن ّ\nل من الإحتراف والنزاهة.\n التخصص :تخصيص موارد بشرّية عالية المهنّية وتدريبها بشكل مستمر لتكون على قدٍر عا ٍ\nالإستدامة :مراعاة أهداف التنمية المستدامة بأبعادها الاقتصادّية ،الاجتماعّية والبيئية ،بشكل متوازن مع\n الأهداف الأساسّية للشراء العام.\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 2\n\f فهرست\n 7 الأسباب الموِجبة لاقتراح قانون الشراء العام\n 10 أو ً"}, {"o": 1, "l": null, "b": "لا :الإطار الماكرو-اقتصادي والمالي\n 11 ثانياً :أداء منظومة الشراء العام\n 12 ثالثاً :الفعالّيـة والمنافسة\n 13 رابعاً :الشفافية والنزاهة والمساءلة\n 13 خامساً :مهنّيـة الشراء العام\n 14 سادساً :الاستدامة والتنمية المحلية\n 15 سابعاً :الإطار المؤ ّ\n سساتي -هيئة الشراء العام ولامركزيته\n 17 قانون الشراء العام في لبنان\n 18 الفصل الأول | أحكام عامة\n 18 المادة :1هدف القانون ومبادُئه العامة\n 18 المادة :2تعاريف\n 22 المادة :3نطاق التطبيق\n 22 المادة :4اللغة\n 22 المادة :5العملة\n 23 المادة :6السرية\n 23 المادة :7شروط مشاركة العارضين\n 24 المادة :8استبعاد العارض بسبب عرضه منافع أو من جّراء ميزة تنافسية غير منصفة أو بسبب تضارب المصالح\n 25 المادة :9سجل إجراءات الشراء\n 26 المادة :10قواعد السلوك\n 27 الفصل الثاني | قواعد عامة لإعداد وإجراء وتنفيذ عملية الشراء\n 27 البند الأول | تخطيط الاحتياجات وتحديدها\n 27 المادة :11وضع خطط الشراء\n 28 المادة :12الإعلان عن الشراء\n 28 المادة :13القيمة التقديرية لمشروع الشراء\n 29 المادة :14تجزئة الشراء\n 29 المادة :15استدامة وسياسات تنموية\n 29 المادة :16الأنظمة التفضيلية\n 30 المادة :17وصف موضوع الشراء\n 31 المادة :18معايير التقييم\n 31 البند الثاني | إجراءات التلزيم\n 31 المادة :19إجراءات التأهيل المسبق للعارضين\n 33 المادة :20طريقة ومكان تقديم طلبات التأّهل المسبق و/أو العروض والموعد النهائي لتقديمها\n 33 المادة :21طلبات الاستيضاح\n التخطيط\n الفعالّيـة والدمج في\n3 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\f34 المادة :22مدة صلاحية العرض\n35 المادة :23العروض المشتركة\n35 المادة :24قواعد قبول العرض الفائز )أو التلزيم المؤقت( وبدء تنفيذ العقد\n36 المادة :25الغاء الشراء و/أو اي من اجراءاته\n37 المادة :26قواعد الإعلان عن إرساء التلزيم"}, {"o": 2, "l": null, "b": "37 المادة :27قواعد بشأن العروض المنخفضة الأسعار انخفاضاً غير عادياً\n37 المادة :28مواقع العمل\n38 البند الثالث | تنفيذ العقد\n38 المادة :29قيمة العقد وشروط تعديلها\n38 المادة :30التعاقد الثانوي\n39 المادة :31الإشراف على التنفيذ والكشوفات\n39 المادة :32تنفيذ العقد والاستلام\n40 المادة :33أسباب انتهاء العقد ونتائجه\n41 البند الرابع | الأمور المالّيـة والضمانات\n41 المادة :34ضمان العرض\n42 المادة :35ضمان حسن التنفيذ\n42 المادة :36طريقة دفع الضمانات\n42 المادة :37دفع قيمة العقد\n43 المادة :38الغرامات\n43 المادة :39الاقتطاع من الضمان\n43 المادة :40الإقصاء\n44 الفصل الثالث | طرق الشراء\n44 المادة :41طرق الشراء\n44 المادة :42القواعد العامة التي تطّبق على اختيار طريقة الشراء\n44 البند الأول | شروط استخدام طرق الشراء\n44 المادة :43شروط استخدام المناقصة على مرحلتين\n45 المادة :44شروط استخدام طلب عروض الأسعار\n45 المادة :45شروط استخدام طلب الاقتراحات للخدمات الاستشارية\n45 المادة :46شروط الاتفاق الرضائي\n46 المادة :47شروط الشراء بالفاتورة\n46 المادة :48شروط استخدام إجراءات الاتفاق الإطاري\n47 البند الثاني | اجراءات المناقصة العمومية\n47 المادة :49الدعوة إلى المناقصة العمومية\n47 المادة :50محتويات الدعوة إلى المناقصة العمومية\n48 المادة :51توفير دفاتر الشروط )أو ملفات التلزيم(\n48 المادة :52محتويات دفاتر الشروط )أو ملفات التلزيم(\n49 المادة :53تقديم العروض\n50 المادة :54فتح العروض\n50 المادة :55تقييم العروض\n51 المادة :56حظر المفاوضات مع العارضين\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 4\n\f 51 البند الثالث | المناقصة على مرحلتين\n 51 المادة :57إجراءات المناقصة على مرحلتين\n 52 البند الرابع | طلب عروض الأسعار\n 52 المادة :58إجراءات طلب عروض الأسعار\n 53 البند الخامس | طلب الاقتراحات للخدمات الاستشارية"}, {"o": 3, "l": null, "b": "53 المادة :59اجراءات طلب الاقتراحات للخدمات الاستشارية\n 55 البند السادس | الشراء بالفاتورة\n 55 المادة :60الدعوة إلى الشراء بالفاتورة\n 55 المادة :61العرض الفائز بالشراء بالفاتورة\n 55 البند السابع | الاتفاق الرضائي\n 55 المادة :62إجراءات التعاقد بالاتفاق الرضائي\n 56 البند الثامن | اتفاقات الاطار\n 56 المادة :63إرساء الاتفاق الإطاري\n 56 المادة :64المتطلبات المتعلقة بالاتفاقات الإطارية\n 57 المادة :65المرحلة الثانية من إجراءات الاتفاق الإطاري\n 59 الفصل الرابع | أحكام خاصة بالشراء الالكتروني\n 59 المادة :66نظام المشتريات الالكتروني\n 59 المادة :67إجراءات الشراء الالكتروني\n 59 المادة :68التسجيل بالنظام الالكتروني\n 60 المادة :69تقديم العروض الكترونياً\n 60 المادة :70فتح وتقييم العروض الكترونياً\n 60 المادة :71تطبيق الشراء الالكتروني\n 61 صص وبناء القدرات\n الفصل الخامس | التخ ّ\n 61 المادة :72التدريب\n 61 المادة :73التسمية الوظيفّيـة\n 62 الفصل السادس | حوكمة الشراء العام\n 62 البند الأول | هيئة الشراء العام\n 62 المادة :74إنشاء هيئة الشراء العام\n 62 المادة :75تشكيل الهيئة\n 63 المادة :76مهام هيئة الشراء العام\n 64 المادة :77صلاحيات رئيس الهيئة\n 65 المادة :78شروط وآلية تعيين رئيس وأعضاء الهيئة\n 66 المادة :79حالات التمانع والتفّرغ\n 67 المادة :80اجتماعات الهيئة\n 67 المادة :81انتهاء العضوية\n 68 المادة :82التعويضات\n 68 المادة :83مالية الهيئة\n التخطيط\n الفعالّيـة والدمج في\n5 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\f68 المادة :84علانية المعطيات\n68 المادة :85قرارات الهيئة\n69 المادة :86طرق المراجعة في قرارات الهيئة\n69 المادة :87النظام الداخلي والأنظمة الإدارية وأنظمة العاملين\n69 المادة :88أحكام انتقالية\n69 البند الثاني | هيئة الاعتراضات\n69 المادة :89انشاء هيئة الاعتراضات"}, {"o": 4, "l": null, "b": "70 المادة :90تشكيل الهيئة\n70 المادة :91شروط وآلية تعيين رئيس وأعضاء هيئة الاعتراضات\n70 المادة :92حالات التمانع والتفّرغ\n71 المادة :93انتهاء العضوية\n71 المادة :94التعويضات\n72 المادة :95مالية هيئة الاعتراضات\n72 المادة :96آلية عمل الهيئة\n73 المادة :97النظام الداخلي والأنظمة الإدارية وأنظمة العاملين\n73 المادة :98التقارير\n73 المادة :99السرية\n73 البند الثالث | لجان التلزيم والاستلام\n73 المادة :100لجان التلزيم :تشكيلها ومهامها\n74 المادة :101لجان الاستلام :تشكيلها ومهامها\n76 البند الرابع | سلطات التعاقد\n76 المادة :102سلطات التعاقد\n77 الفصل السابع | إجراءات الاعتراض\n77 المادة :103الحق في الاعتراض\n77 المادة :104مفعول الاعتراض\n78 المادة :105تقديم طلب إعادة النظر\n79 المادة :106تقديم شكوى لدى هيئة الاعتراضات\n81 المادة :107حقوق المشاركين في الاعتراض\n81 المادة :108السرية في اجراءات الاعتراض\n82 الفصل الثامن | النزاهة والمساءلة\n82 المادة :109الشفافية\n82 المادة :110النزاهة\n83 المادة :111التدقيق الداخلي\n84 المادة :112العقوبات\n86 الفصل التاسع | أحكام انتقالية ختامية\n86 المادة :113الملفات الجارية\n86 المادة :114إلغاء المواد المتعارضة\n86 المادة :115دقائق التطبيق\n87 المادة :116بدء العمل بالقانون\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 6\n\fالأسباب الموِجبة\n لاقتراح قانون\n الشراء العام\n في لبنان\n\f الأسباب الموِجبة لاقتراح\n قانون الشراء العام\nحد للشراء العام )المعروف أيضاً بالصفقات العامة( ،إذ\n لما كان القانون اللبناني يفتقر إلى نص عصري ومو ّ\nُيعتبر الإطار القانوني الحالي مبعثرا ً ومتقادماً وينطوي على أحكام متعددة متفّرقة من أبرزها قانون المحاسبة\nالعمومية )المرسوم رقم 14969تاريخ 1963/12/30المعدل( ونظام المناقصات )المرسوم رقم 2866تاريخ"}, {"o": 5, "l": null, "b": "1959/12/16المعدل بتاريخ ،(1962/02/10بالإضافة إلى عدد من النصوص الخاصة بالبلديات والمؤسسات\n العامة والأجهزة الأمنية والجيش وغيرها من الهيئات والمجالس،\nولما كانت الأحكام اللبنانية الناظمة للشراء العام بمجملها لا تعتمد معايير واضحة تعكس التوجهات الدولّيـة\nلجهة (1 :فتح مجال المنافسة ,لاسّيما أمام المؤسسات الصغيرة والمتوسطة (2 ,احترام معايير النزاهة والشفافية\n قبل الجهة الشارية ومن ِ\nقبل القطاع الخاص (3 ،تأمين الجهاز/الملاك البشري المتخصص والقادر على من ِ\nممارسة وظيفته وعلى التصّرف بالمال العام بأعلى مستويات من المهنّية والفعالية والنزاهة ,و (4تحقيق\n أهداف التنمية المستدامة )الاقتصادّيـة والبيئّيـة والاجتماعّيـة( التي التزمت بها الحكومة اللبنانية،\nولما كانت الدراسات والمسوحات ،وآخرها وأشملها المسح الدولي لمنظومة الشراء العام ) ،(MAPSقد\nأشارت إلى ثغرات لجهة وجوب توحيد الإجراءات واعتماد معايير واضحة .مرّد ذلك تعّدد النصوص والأحكام\nحدة\n المرعّيـة الإجراء ونقص في آليات الشكأوى والاعتراض .كما أشار المسح إلى عدم وجود معايير ووثائق مو ّ\n)دفاتر شروط نموذجية أو عقود نموذجية( ،واللجوء الُمفرط للشراء بالتراضي .كما أشار إلى تداخل في أدوار\nالجهات المعنّيـة ،واللجوء إلى استثناءات تتناقض مع القوانين والأنظمة المرعية الإجراء والمبادئ العامة ذات\nالصلة ،كما وتفسيرات متعّددة مما يزيد من مخاطر الممارسات الانتقائية وغير المتسقة ،ويؤثر سلباً على\nحددت ثغرات عّدة على مستوى القدرات المؤسساتية والُبنية التحتية التكنولوجية وعدم\n الرقابة .هذا وقد ُ\nكفاءة أنظمة إدارة المعلومات ومحدودية الاستثمار فيها لتطويرها ،مّما يعيق الوصول إلى المعلومات ،ويحّد\nمن فعالّيـة الرقابة ويزيد من مخاطر الفساد ومن الكلفة التي ترّتبها هذه الثغرات على المالّية العامة وخسارة\n جدد وذات فعاّلية اقتصادّيـة عالية،"}, {"o": 6, "l": null, "b": "فرص استقطاب مورّدين ُ\nولما كانت ،في موازاة ذلك قد تطّورت المعايير الدولّية المعتمدة في الشراء العام بشكل كبير خلال السنوات\n العشرين الماضية ،بحيث ُ\nطّورت قوانين مرجعّيـة ،ومبادئ وتوجيهات وممارسات جّيدة صدرت عن كل من\nمنظمة الأمم المتحدة ،والبنك الدولي ،ومنظمة التعأون الاقتصادي والتنمية ،والمفوضية الأوروبية ،والبنك\n الأوروبي لإعادة الاعمار والتنمية ،وغيرها من الجهات الدولّيـة،\nولما كانت عّدة محأولات جرت في لبنان لاقتراح مشاريع قوانين ومراسيم تنظيمّيـة بهذا الصدد ولكنها لم\nتصل إلى خواتيمها المرجّوة من بينها مشروع قانون الصفقات العمومية الذي استردته الحكومة من مجلس\nالنواب في 2018/3/27والذي كان قد أحيل إلى مجلس النواب بموجب المرسوم رقم 9506بتاريخ .2012/12/12\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 8\n\f وقد أدرجت حكومة “مواجهة التحديات” في بيانها الوزاري ،وتحديدا ً في الباب الخامس المتعّلق بالإصلاحات\n الهيكلية ،وجوب “الالتزام بمتابعة كافة الجهود التي بذلتها وزارة المالّيـة لإصلاح منظومة الشراء العام بما\n في ذلك استكمال المسح الدولي ) (MAPSوإقرار توصياته واعتمادها والعمل على الإقرار الفوري لمشروع\n قانون عصري للشراء العام مع الأخذ بعين الاعتبار ملاحظات الجهات المختصة”،\n ولما كانت الدولة اللبنانية قد التزمت في مؤتمر “سيدر” الذي ُعقد في باريس )نيسان (2018القيام\n بإصلاحات قطاعية وأخرى شاملة عابرة للقطاعات ،أبرزها مكافحة الفساد وتحديث الشراء العام ،ولما كانت\n مجموعة الدعم الدولّيـة عادت خلال اجتماعاتها المتتالية لتؤكد على أهمية تنفيذ هذه الالتزامات في ظ ّ\n ل\n التحديات المالّية والاقتصادّية التي تمّر بها البلاد .وقد شّددت على الشراء العام كأحد أبرز الإصلاحات\n حوكمة المالّيـة وتحسين جودة الخدمات العامة ،وجذب الاستثمارات ،وتعزيز\n الهيكلّيـة الضرورّيـة لتعزيز ال َ"}, {"o": 7, "l": null, "b": "الشفافية ،ودعم جهود مكافحة الفساد وإهدار المال العام .تشّكل هذه الاصلاحات شرطاً أساسياً لتمويل\n برامج الانفاق الاستثماري في قطاعات اقتصادية حيوّيـة،\n ولما كان المجتمع المدني عموماً ،والحراك الشعبي خصوصاً ،يطالب منذ عقود ،وخصوصاً منذ 17تشرين\n الأول ،2019بمكافحة الفساد وبإرساء دولة الحق وحكم القانون تكريساً للحقوق والحريات الأساسية ولمبادئ\n سامية كالنزاهة والشفافية والمساءلة والعدالة والإنصاف والمساواة،\n لذلـك،\n نتقّدم باقتراح قانون الشراء العام ،الذي أعده معهد باسل فليحان المالي والاقتصادي بتكليف من وزير\n م العمل على هذا الاقتراح من خلال\n المالّيـة ،وهو يتطابق مع الأحكام والمبادئ الدولّيـة والممارسات الجّيدة .ت ّ\n منهجية ارتكزت على دراسات مقارنة ،وبيانات علمّيـة صادرة عن مسح منظومة الشراء العام في لبنان\n صة ،وتوصيات لخبراء واختصاصيين دوليين .يرتكز اقتراح القانون على\n ) ،(MAPSومشاورات مع الجهات المخت ّ\n ثمانية مبادئ للشراء العام ،لا تستقيم الأمور دون لحظها ومراعاتها ،مستقاة من المبادىء الدولّيـة الإثني\n عشر الصادرة عن منظمة التعاون الاقتصادي والتنمية ،وهي:\n .1الميــزة الشاملــة حيث تشمل أحكام اقتراح القانون كل الجهات الشارية وأي شخص من أشخاص القانون\n العام ينفق ماًلا عاماً ،بتمويل محلي أو اجنبي .يشمل المبدأ ك ّ\n ل أنواع المشتريات العامة ،أي تنفيذ\n الأشغال ،وتوريد اللوازم وتقديم الخدمات بما فيها الخدمات الاستشارية ،وبما لا يخالف أحكام المعاهدات\n والاتفاقيات الدولّيـة المبرمة أصوًلا من ِ\n قبل الدولة اللبنانية.\n .2التخطيط والدمج مع الموازنات من خلال تشجيع عملية التخطيط المتوسط الأمد في إعداد الموازنات\n لتحسين تصميم وتخطيط دورة الشراء.\n .3المساءلة من خلال تطبيق آليات واضحة للإشراف والرقابة ،في كافة مراحل الشراء ،على أن تشمل\n ت بها وتدابير العقاب الملاءمة"}, {"o": 8, "l": null, "b": "استحداث إطار جديد وفّعال للشكاوى والاعتراضات ضمن مهل محّددة للب ّ\n بما يعزز الثقة بالأداء.\n التخطيط\n الفعالّيـة والدمج في\n9 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\fمـة والطريقة المعيارية\n .4الفعالّيـة والمنافسة أي الحرص على أن تكون الإجراءات التنافسّيـة هي القاعدة العا ّ\nلإجراء عمليات الشراء كوسيلة لتعزيز الكفاءة ،وتأمين فرص متكافئة وعادلة لجميع الموردين المحتملين،\nملزماً لكل الجهات\n حدة )دفاتر شروط نموذجّيـة( بحيث يكون استخدامها ُ\n وإعتماد وثائق واضحة ومتكاملة ومو ّ\nالشارية ،ومكافحة الفساد واعتماد ضوابط صارمة تحّد من الاتفاقات الرضائّيـة وتوفير طرق شراء جديدة\n تتماشى مع متطلبات الحداثة.\n .5النزاهة من خلال وضع تعريف واضح لها كما ولتضارب المصالح وتحديد حالاته المتعددة وتحديد انواع\nالعقوبات التي تطال موظفي القطاعين العام والخاص بدرجات تتناسب مع نوع العمل أو الفعل أو\nالإمتناع عنه ،بالإضافة إلى تحديد أنواع الرقابة والعقوبات التي تطال موظفي القطاعين العام والخاص\n بدرجات تتناسب مع نوع المخالفة.\nصة الاكترونّيـة المركزّيـة مما يتيح الوصول إلى المعلومات\n .6الشفافيـة من خلال وجوب النشر على المن ّ\nوالبيانات لكافة المهتمين والمتدخلين ،مع الحفاظ على موجب السرّيـة بموجب ما تقتضيه أحكام اقتراح\n القانون.\n .7التخصص من جهة تخصيص موارد بشرّيـة عالية المهنّيـة للقيام بعمليات الشراء وموجب التدريب المستمر\n ل من المهنّيـة والاحتراف والنزاهة.\n لهم لتكون على َقدٍر عا ٍ\n .8الإستدامة من خلال عمليات تراعي أهداف التنمية المستدامة بأبعادها الاقتصادّيـة والاجتماعّيـة والبيئّيـة،\n بشكل متوازن مع الأهداف الأساسّيـة من الشراء العام.\nصل من بينها الأمور السبعة\n يراعي اقتراح القانون مقتضيات المصلحة العامة على مختلف الأصعدة ،نف ّ\n التالية:\n أو ً"}, {"o": 9, "l": null, "b": "لا :الإطار الماكرو-اقتصادي والمالي\nيقع الشراء العام في صلب النشاط المالي للدولة ويرتبط ارتباطاً عضوياً بتخطيط التزاماتها المالّيـة على\nالمديين المتوسط والبعيد عند إعداد الموازنات العامة ،بما في ذلك تأمين الالتزامات المالّيـة الناتجة عن\nعمليات تنفيذ العقود وربطها بتوافر السيولة في الخزينة وتأمين التزامات الدولة المالّية بحسب أولوية\nاستحقاقاتها .يُقّدر حجم الشراء العام في لبنان بــ %20من النفقات العامة و 6.5من الناتج المحلي الإجمالي\n)حوالي 3.4مليار دولار عام (2019على المستوى المركزي ،دون أن يتضّمن هذا التقدير حجم مشتريات\n المؤسسات العامة والبلديات واتحاداتها.\nوُيعاني لبنان من عجز هيكلي ويرزح تحت عبء مديونّيـة عالية مع وصول نسبة الدين العام من الناتج المحلي\nالإجمالي إلى %176عام .2019ويضيق هامش الانفاق الاستثماري للدولة إذ لم يتعّد %2من الانفاق العام\nصة\n لسنة 2020و %4لسنة ,2019وذلك بسبب خدمة الدين العام التي تشكل حوالي ربع الإنفاق العام ,وح ّ\nالرواتب والأجور وملحقاتها التي تصل إلى %50منه .بالإضافة إلى ذلك ,يشهد لبنان تباطؤا ً في النمو\nالحقيقي بحيث قّدر بنمو سلبي ) (%12-للعام ,2020وتشير التقديرات إلى نمو سلبي بنسبة ) (%21-للعام\n .2021\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 10\n\f جـل لبنان تراجعاً لجهة سهولة الأعمال إذ يحت ّ\n ل المرتبة 143من أصل 190بلدا ً بسبب من ناحية أخرى ،يس ّ\n الفساد والنقص في كفاءة وجودة البنى التحتية وعدم ملاءمتها مع متطلبات النمو والتنافسية حيث يسجل\n المرتبة 130من أصل 137بلدا ً لمؤشر جودة البنى التحتية .وتبقى فرص لبنان من جهوزيته العالية لاستخدام\n التكنولوجيا والابتكار لدفع الاقتصاد الوطني ضائعة بسبب تراجع الأداء وعدم تأمين بيئة جاذبة للأعمال\n والمستثمرين."}, {"o": 10, "l": null, "b": "ُتفيد التجربة الدولّيـة وتوصيات مجلس منظمة التعأون الاقتصادي والتنمية ) (OECDبضرورة أن يكون ذلك\n جزءا ً لا يتجّزأ من العمل المالي للدولة بحيث لا يجوز ،في ظ ّ\n ل أوضاع مالية واقتصادية دقيقة كالتي يمّر بها\n لبنان في الأونة الأخيرة وعلى المدى المتوسط ،إّلا أن تكون الإدارة المالّيـة متكاملة ومترابطة وخاضعة\n لضوابط صارمة خصوصاً لجهة استشراف وإدارة عمليات الموازنة والخزينة.\n بناًء على ما تقّدم ،وفي ضوء التحّول الطارئ على المفاهيم الدولّيـة للشراء العام من مقاربة تقليدّيـة إدارّيـة\n ن الإطار القانوني الحالي لا يحّدد مسارا ً\n بحتة إلى مقاربة استراتيجّيـة متصلة بالأهداف المالّيـة للدولة ،وبما أ ّ\n يجري وفقه تحديد احتياجات الجهات الشارية وتقييمها وتبويبها وتصنيفها ،كما وربطها بعملية إعداد الموازنة\n وتخطيط وإدماج الحاجات التمويلّية الحالّيـة والمستقبلية في الموازنة العامة ،الأمر الذي من شأنه أن يضع\n الدولة أمام خطر عدم القدرة على جدولة التزاماتها في إطار متوسط أو طويل الأمد ،يقترح هذا القانون:\n أ .حرصاً على الإدارة المتكاملة للمال العام ،دمج الشراء العام بالموازنة من خلال إلزام كافة الجهات\n الشارية تخطيط عمليات الشراء وربطها بالموازنة بما يحقق القيمة الفضلى لإنفاق المال العام،\n ويؤمن استدامة الموارد الاقتصادية والبيئّية والاجتماعية والُنظم والأطر الفّعالة للمساءلة.\n ب .تحديد الاحتياجات وتحضير الخطط السنوية عن العام المقبل تزامناً مع إعداد النفقات العامة ،وبالاستناد\n حدة واجراءات تصدر عن هيئة الشراء العام.\n إلى نماذج مو ّ\n ج .إمكانية لحظ خطة شراء سنوية أو متعّددة السنوات في حال تتضّمن مشاريع يقتضي تنفيذها جدولة\n التزامات في اطار متوسط أو طويل الأمد ،على أن تتضمن المعلومات ذات الصلة بموضوع الشراء،"}, {"o": 11, "l": null, "b": "ومصدر التمويل والمبلغ التقديري ،ووصف موجز للمشروع ،وطريقة الشراء ،والتاريخ المحتمل لاجرائه.\n ثانيًا :أداء منظومة الشراء العام\n ن التقارير الدولّيـة تصف منظومة الشراء العام في لبنان بأّنها ذات جودة متدنّيـة مقارنة مع مثيلاتها في\n حي ث أ ّ\n ن تحديث هذه المنظومة يحّقق وفرا ً سنوًيا بقيمة 500\n بلدان المنطقة العربية وفي العالم ،وهي تشير إلى أ ّ\n سن نوعية الخدمات المقّدمة\n مليون دولار ،مّما من شأنه أن يزيد هامش الإنفاق الاستثماري للدولة ويح ّ\n للمواطنين وفرص مشاركة القطاع الخاص ،والثقة بالأداء .لذلك ،وبغية سّد هذه الثغرات في المنظومة،\n والتي حّددها أيضاً مسح ،MAPSيتضّمن اقتراح القانون تحديثات جوهرية أهّمها )بالإضافة إلى الميزة\n الشاملة وفق ما ورد أعلاه(:\n حوكمة عصرية للشراء العام من خلال إطار مؤسساتي وتنظيمي متجانس ُتحَّدد فيه أدوار المؤسسات\n أ .إعتماد َ\n المعنّيـة ،منعاً للتداخل الوظيفي غير الفّعال ،وبما يسمح بالتركيز على الأهداف والتحّقق من جودة الخدمات،\n ورفع الكفاءة وفعالّيـة الإجراءات والحّد من الأعباء الإدارّيـة ،ويشمل ذلك استحداث جهتين أساسّيـتين هما:\n التخطيط\n الفعالّيـة والدمج في\n11 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\f (1هيئة الشراء العام ،وهي هيئة ناظمة ومستقلة ،ذات دور تنظيمي واشرافي غير متوفر في\n المنظومة الحالية،\nت بالمراجعات\n (2وهيئة الاعتراضات الإدارية ،وهي هيئة مستقلة ،تعمل وفق آليات ومسارت للب ّ\nوالشكاوى مع أحكام خاصة بها ،وذلك خلال فترة ما قبل التعاقد ،وبطريقة عادلة وشفافة وفي\n الوقت المناسب.\n ب .إدراج أحكام ترعى الإشراف والرقابة والإبلاغ الواضح وتدابير العقاب الفّعالة؛\nمثبت جدواها دولّيـاً ،تساهم في توحيد الإجراءات وتعّزز الممارسات الكفؤة\n ج .لحظ إجراءات وتدابيرُ ،\n والجّيدة.\n ثالثًا :الفعالّيـة والمنافسة"}, {"o": 12, "l": null, "b": "مطرد في التنافسية إذ تراجع من المرتبة 80في العام 2018إلى\n ن الاقتصاد اللبناني يعاني من تراجع ُ\n حي ث أ ّ\nالمرتبة 88في العام ) 2019من أصل 141بلدا ً ( ،لذلك ولمواجهة هذا الواقع ،يتضّمن القانون المقترح أحكاماً\nتساهم في تأمين فرص متكافئة وعادلة لجميع الموردين المحتملين للمشاركة في عمليات الشراء على\n قاعدة التنافسّيـة ،من ضمنها:\nمـة والطريقة المعيارية لإجراء عمليات\n أ .الحرص على أن تكون الإجراءات التنافسية هي القاعدة العا ّ\n الشراء كوسيلة لتعزيز الكفاءة ،ومكافحة الفساد؛\n ب .إعتماد ضوابط صارمة تحّد من الاتفاقات الرضائية؛\nسساتّيـة وقانونّيـة وتنظيمّيـة متماسكة ومستقرة وواضحة وبسيطة من شأنها أن\n ج .العمل بأطر مؤ ّ\nتضمن نفاذ المتنافسين المحتملين من جميع الأحجام إلى فرص المشتريات ،بما في ذلك المورّدين\n الأجانب ،وتشجيع المعاملة العادلة والمنصفة والشفافة لهم؛\nد .مساواة كافة العارضين الراغبين في المشاركة لجهة إتمام إجراءات التأهيل المسبق بحسب آلية\n صلة وواضحة تسمح بتحديد أهلية مقّدم العرض وقدرته على تنفيذه؛\n مف ّ\nملزماً لكافة\n حدة )دفاتر شروط نموذجّيـة( بحيث يكون استخدامها ُ\n هـ .إعتماد وثائق واضحة ومتكاملة ومو ّ\n الجهات التي يشملها قانون الشراء؛\nصل كيفية وصف موضوع الشراء بطريقة موضوعّيـة وذات صلة بما في ذلك كيفية\n و .لحظ أحكام تف ّ\nوضع المواصفات الفنّيـة أو غيرها من المواصفات ،وبشكل لا يحّد من المنافسة؛ وكذلك أحكام تنظّم\n طلبات الاستيضاح على وثائق الشراء بطريقة تضمن حق العارض وُتجّنب التواطؤ؛\nز .تحديد طرق شراء متعّددة تضمن إجراءات تنافسية وأخرى أقل تنافسية )في حالات استثنائية محّددة\nفي اقتراح القانون( توّفر مجموعة مناسبة من الخيارات لضمان الحصول على القيمة الفضلى من\n إنفاق المال العام وإشراك العارضين المستحقين فقط؛\nصلة لتقييم العروض المقّدمة ليس فقط على أساس السعر الأدنى بل"}, {"o": 13, "l": null, "b": "ح .إعتماد قواعد واضحة ومف ّ\nعلى أساس معايير محّددة كالمعايير البيئّيـة أو دورة حياة المنتج ،مع تحديد شروط وضوابط لتعديل\n قيمة العقد عند الإقتضاء.\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 12\n\f رابعًا :الشفافية والنزاهة والمساءلة\n ن الإحصاءات تشير عالمياً إلى أ ّ\n ن %57من المعاملات الحكومية المعّرضة للفساد مرتبطة بالشراء حي ث ا ّ\n العام ,وحيث ان لبنان ,في هذا الإطار تحديدا ً ,تراجع على مؤشر مدركات الفساد إذ احت ّ\n ل المرتبة 149من بين\n 180بلدا ً عام ،2020لذلك يأتي اقتراح قانون الشراء العام ليساهم في تحقيق التزامات الدولة اللبنانّيـة لجهة\n مكافحة الفساد وتعزيز الشفافية ،ويشير إلى أهمية البنية التحتّيـة المعلوماتّيـة لدى الجهات الشارية ،وهيئة\n صة الاكترونّيـة المركزّيـة ،كأساس لنظام إفصاح ورقابة فعلّيـة ،علماً أ ّ\n ن دول عربّيـة الشراء العام ،من خلال المن ّ\n عّدة نجحت في هذه الخيارات وقطعت أشواطاً نحو الشراء الالكتروني الُملزم .إنطلاقاً من كون المصلحة العامة\n هي أولوّيـة الأولوّيات .يعالج القانون الثغرات التي قد تؤدي إلى خرق مبادىء الشفافية والنزاهة والمساءلة،\n من خلال:\n صة الكترونية مركزّيـة لدى هيئة الشراء العام والزام الجهات الشارية نشر المعلومات\n أ .إعتماد من ّ\n الاساسية المتعلقة بمراحل الشراء على هذه المنصة ،والسماح بالنفاذ الحر لجميع أصحاب المصلحة،\n بما في ذلك المورّدين المحليين والأجانب المحتملين والمجتمع المدني والجمهور إلى المعلومات\n ص عليها القانون؛\n الخاصة بالمشتريات ،مع مراعاة حالات السرّيـة التي ين ّ\n ب .الحّد من إمكانية تضارب المصالح ،وتكريس موجب الكشف عن المعلومات ،وذلك عبر وضع تعريفات\n واضحة لتضارب المصالح وللفساد والاحتيال والتواطؤ ،وكيفية معالجة هذه الحالات واستبعاد العارضين\n بناًء على أي من تلك الإعتبارات؛"}, {"o": 14, "l": null, "b": "ج .فرض مستويات عالية من النزاهة على جميع أصحاب المصلحة في دورة الشراء من خلال توسيع\n المعايير المدرجة في أطر النزاهة ومدونات قواعد السلوك وتطبيقها على المتدخلين في كافة مراحل\n الشراء ،والتدريب على النزاهة للقطاعين العام والخاص؛\n حد الممارسات لدى الجهات الشارية مترافقة مع ادماج التكنولوجيا الرقمّيـة في\n د .العمل بإجراءات تو ّ\n استبدال أو إعادة تصميم الإجراءات الورقّيـة في كافة مراحل الشراء؛\n هـ .إحترام الموضوعّيـة والشفافّية في وضع دفاتر الشروط؛\n و .إشراك القطاع الخاص والمجتمع المدني عند وضع اقتراحات أو مشاريع التعديلات القانونّيـة أو\n التنظيمّيـة؛\n ز .تحديد طريقة حفظ السجلات والمستندات والبيانات خلال إجراءات التلزيم بما يسّهل الرقابة والوصول\n إلى المعلومات؛\n ح .توفير المدخل القانوني إلى الشراء الالكتروني وإدارة البيانات.\n خامسًا :مهنّيـة الشراء العام\n ن الدولة اللبنانية تشكو من نقص كبير في القدرات والكفايات على كافة المستويات ذات الصلة ،ومن\n حي ث أ ّ\n عدم تلاؤم بين المهارات المطلوبة مع تلك المتوافرة حالياً ،إذ أ ّ\n ن %48من العاملين في الشراء غير ملّمين\n بالممارسات الدولّيـة الجيدة .وفي معظم الحالات ،ليس الشراء العام قائماً بحّد ذاته في لبنان بحيث ينعدم\n الوصف الوظيفي والإطار الواضح للكفايات باعتباره وظيفة عامة .وقد أشارت معظم التقارير الدولّيـة\n لا وعدم تلاؤمها مع المعايير الدولّية يمثّل خطرا ً ائتمانياً كبيرا ً\n ن النقص في الكفايات المالّية إجما ً\n صصة أ ّ\n المتخ ّ\n بالنسبة إلى الحكومة ،لأّنه يؤثر مباشرة على الأداء،\n التخطيط\n الفعالّيـة والدمج في\n13 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\fوحيث أن مرّد ذلك هو عدم خضوع جميع الموظفين المعنيين إلى تدريب إلزامي ولا لتحديث مستمر"}, {"o": 15, "l": null, "b": "لمعارفهم بما يتلاءم مع متطلبات الإدارة المالّيـة الحديثة والمتغّيـرات الدولّية ،الأمر الذي يضعف قدرة الدولة\nن الأمر يكتسب أهمية أكبر إذا ما أ ُخذ في\n على إدارة نظام الإدارة المالّية وإصلاحه .كما وأّكدت التقارير أعلاه أ ّ\nن تحقيق أعلى درجات\n ن هذا النقص ُيعتبر من الصفات الأبرز للحوكمة المالّيـة الضعيفة .وحيث ا ّ\n الاعتبار أ ّ\nالمهنّية والاحتراف لدى المولجين مهام الشراء العام ُيعتبر ضمانة أساسّية لتحقيق الأهداف التي يصبو إليها\n قانون الشراء العام ،لذلك يُنص اقتراح القانون على:\nأ .إدراج الشراء العام كمهنة محّددة ،قائمة بذاتها ،ضمن الهيكل الوظيفي في الدولة ،بحيث تعمل كل\nجهة شارية على إيجاد فريق عمل متخصص وملائم من حيث العدد والمهارات نسبة لحجم الشراء\n لديها دون الحاجة إلى توظيف أو تعاقد إضافي إلا عند الاقتضاء؛\nب .تحديد أطر الكفايات وشروط التوظيف والترفيع الخاصة بهذه المهنة من خلال مراسيم تطبيقّيـة ،بما\n في ذلك الكفاءات العلمّيـة والمهارات والخبرة والسلوكيات والأخلاقيات؛\nج .إخضاع القائمين بمهام الشراء العام وكافة المتدخلين في دورته لتدريب متخصص مستمر إلزامي لدى\n معهد باسل فليحان المالي والاقتصادي.\nن جميع الموظفين المسؤولين عن الشراء العام أو المتدخلين ،في أي مرحلة من مراحله ،بما\n د .التأكد من أ ّ\n في ذلك أعضاء لجان التلزيم والاستلام ،يستوفون المعايير المهنّيـة العالية؛\n هـ .وضع أدّلة عملّيـة وإجرائّيـة للشراء العام في متناول الجهات الشارية؛\nصة وسائر المعنيين في\n و .إشراك القطاع الخاص والهيئات الإقتصادّيـة المعنّيـة ومراكز المعرفة المخت ّ\n المجتمع المدني في مسار تعزيز القدرات على المستوى الوطني؛\n ز .رفع مستوى الوعي حول مبادىء النزاهة والشفافّية والتنمية المستدامة.\n سادسًا :الاستدامة والتنمية المحلية"}, {"o": 16, "l": null, "b": "ن الشراء العام المستدام هو إحدى الممارسات الدولّيـة الجيدة المعتمدة حول العالم والهادفة إلى تحفيز\n حي ث أ ّ\nالمؤسسات الصغيرة والمتوسطة على دخول سوق الشراء العام وتشجيع المنافسة والابتكار وتلبية متطلبات\nالتنمية المستدامة تماشياً مع خطة التنمية المستدامة للعام 2030التي اعتمدتها الجمعية العامة للأمم\nن المؤسسات الصغيرة والمتوسطة تشّكل بين %93إلى %95من\n المتحدة في 25أيلول .2015وحيث أ ّ\n إجمالي مؤسسات القطاع الخاص ,وُتو ّ\nظف %51من اليد العاملة ,لكّنها تبقى غير قادرة على ولوج فرص\nالمشاركة بفاعلّيـة في العقود الحكومية لأسباب مختلفة ,أهّمها :عدم قدرتها وجهوزيتها للمشاركة ) 88%من\nالحالات( ,التأّخر في الدفع من قبل الجهة الشارية ) ,(75%وعدم إمكانية الوصول إلى المعلومات المتعلقة\nبالشراء العام وشروط المشاركة بها والصعوبة في تشكيل تكّتلات )(63%؛ لكل ذلك ،يعالج اقتراح القانون\n هذه الثغرات والتحديات إذ:\nأُ .يعتبر رافعة للتنمية الاقتصادية من خلال ضمان حق مشاركة المؤسسات الصغيرة والمتوسطة على\nنحو عادل وشفاف في العقود الحكومّيـة ،واعتماد معايير الاستدامة أي تلك الصديقة للبيئة والمعايير\nجع التنمّيـة الاقتصادّيـة المتكافئة )دعم المشاركة الاقتصادّيـة للنساء ،التنمية الريفّيـة ،الخ(،\n التي تش ّ\nوتراعي المسؤولّيـة الاجتماعّيـة )تجّنب عمالة الأطفال ،التأمين الالزامي للعّمال ضد حوادث العمل ،الخ(؛\nب .يلحظ توجيهاً للقدرة الشرائية للدولة اللبنانية ،حيث أمكن ،نحو السلع والخدمات المستدامة بهدف\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 14\n\f تقليص الاثر البيئي وتحقيق الاهداف الاقتصادّيـة والاجتماعّيـة المنصوص عليها في المواثيق\n والمعاهدات والاتفاقيات الدولّيـة المبرمة من ِ\n قبل الدولة اللبنانّيـة ووفقاً للأولوّيـة الوطنّيـة ،مع الحرص"}, {"o": 17, "l": null, "b": "على تحقيق التوازن بين المنافع المحتملة وعلى تحقيق القيمة الفضلى من انفاق المال العام،\n وبشكل يسمح بإعطاء حوافز للمؤسسات الصغيرة والمتوسطة وللانتاج المحلي وللخبرات الوطنّية؛\n م التلزيم على أساس أقساماً ومجموعات ،وذلك من أجل الإفادة الاجتماعّيـة\n ج .يجيز ،عند الامكان ،أن يت ّ\n والاقتصادّيـة ،على أن يحّدد دفتر الشروط الخاص تفصيل عدد الأقسام وطبيعتها ،وشروط الاشتراك\n وطريقة إسناد التلزيم؛\n ص على أنظمة تفضيلية تطال المنتجات والخدمات الفكرية الوطنّيـة والخبرات الوطنّيـة ،مع ضمان\n د .ين ّ\n عدم استبعادها في حال وجودها بجودة ونوعية تفي بالمطلوب بشهادة صادرة عن الإدارة المختصة؛\n هـ .يوفر مدخ ً\n لا لبلورة قواعد وسياسات للشراء العام المستدام.\n سابعًا :الإطار المؤ ّ\n سساتي -هيئة الشراء العام ولامركزيته\n لا يحّدد الإطار القانوني والتنظيمي الحالي وظيفة معيارية ناظمة للشراء العام ،وبالتالي لا وجود لسلطة أو\n سلطات مختصة مخّولة تحديدا ً القيام بهذه الوظيفة ،كما لا توجد أي إدارة أو مؤسسة أو هيئة وطنية مكّلفة\n بذلك على المستوى الوطني .بذلك ،يغيب عن منظومة الشراء مبدأ بلورة سياسات الشراء العام ،وتقديم\n المشورة للجهات الشارية والمتدخلين ،وتوفير المستندات المرجعّيـة ،ووضع الارشادات ،وجمع المعلومات\n على كافة مستويات الشراء وتوفيرها للمعنيين والجمهور من خلال منصة موحدة ،والدفع ُقُدماً لتطوير هذه\n المنظومة من خلال اقتراح الإصلاحات وصياغة التعديلات على الإطار القانوني والتنظيمي ،بما يتلاءم\n جهات الحديثة الُفضلى.\n والمعايير الدولّية والتو ّ\n تتولى حالياً إدارة المناقصات ،المرتبطة بالتفتيش المركزي ،تنفيذ عمليات شراء اللوازم والأشغال وبعض\n انواع الخدمات لصالح الوزارات ،والتي تجرى بطريقة المناقصة العامة )للمشتريات التي تتجاوز قيمتها مائة"}, {"o": 18, "l": null, "b": "مليون ليرة لبنانية( أو استدراج العروض .ولا تخضع لها المؤسسات العامة )مثل مجلس الإنماء والإعمار\n وكهرباء لبنان وغيرها( ووزارة الدفاع الوطني ووزارة الداخلية والبلديات وغيرها من الهيئات تقوم إدارة\n المناقصات بمهامها استنادا ً إلى البرنامج السنوي للمناقصات الذي ُيصادق عليه مجلس الوزراء ،وهي\n مسؤولة عن مراجعة ملفات المناقصات والتدقيق في محتوياتها للتأكد من خلّوها من المخالفات والنواقص\n ملزم إلى الادارة التي يجري الشراء لصالحها ،والاعلان عن الشراء\n )مادة ،17نظام المناقصات( ،وابداء رأي غير ُ\n واستلام العروض وفتحها وتقييمها ،وليس لها دور رقابي كون هذا الدور مناط بديوان المحاسبة الذي يمارس\n سع حاجات الدولة في\n الرقابة المسبقة واللاحقة على المناقصات .لم يتطّور دور إدارة المناقصات مع تو ّ\n الحصول على سلع وخدمات وتنفيذ أشغال تواكب التطّورات والظروف الاقتصادّيـة والاجتماعّيـة والانسانّيـة\n سساتية والبشرية والمالّيـة والتقنّيـة الضرورية ،مما\n م منحها الاستقلالية والقدرات المؤ ّ\n والتكنولوجّيـة ولم يت ّ\n أعاق قيامها بمهامها بشكل فّعال ولم يسمح لها بمجاراة متطلبات التقدم التكنولوجي والمعايير المعتمدة\n دولياً .كما غاب الدور الناظم ومهام الإشراف ووضع السياسات لصالح الدور التنفيذي ،علما أنه من الموصى\n به عالمّيـاً فصل الوظائف التشغيلية عن الوظائف الرئيسية في مجال الإشراف ووضع السياسات.\n التخطيط\n الفعالّيـة والدمج في\n15 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\f بالاستناد إلى هذا الواقع ،ين ّ\nظم اقتراح القانون عمليات الشراء العام على أساس لا مركزي لدى كافة الجهات\nالشارية ،بالموازاة مع تطوير وتوسيع في صلاحيات إدارة المناقصات لتصبح “هيئة الشراء العام” وايلائها\nجـه وتحرص على حسن تطبيق المبادئ الدور الناظم وهو غير موجود في المنظومة الحالية ،بحيث ُتن ّ\n ظم وتو ّ"}, {"o": 19, "l": null, "b": "والمعايير المحددة في القوانين والأنظمة المرعية الاجراء لاسّيما مبادىء العلنّيـة والمساءلة والشفافّيـة\nالموصى بها من قبل منظمة التعاون الإقتصادي والتنمية الـ OECDوالتي توصي باجراء عمليات الشراء\n بشكل علني وواضح ونشر للمعلومات والبيانات المتعّلقة بها بك ّ\nل الوسائط بما في ذلك الوسائط الرقمّيـة\nوبشكل يتيح تكافؤ الفرص لجميع المورّدين المحتملين .كذلك تساهم “هيئة الشراء العام” في توحيد الاجراءات\nعبر وضع مستندات معيارّيـة ودفاتر شروط نموذجّيـة .كما يشمل دورها الاعتراض على سير عملّيـة شراء متى\nتعارضت مع مقتضيات المصلحة العامة ،وتحديد مكامن الخلل والتدّخل حيث يلزم ،بما في ذلك إصدار قرارات\nالاقصاء وحفظها في سجل علني ونشرها على المنصة الإلكترونّيـة ورفع تقارير إلى رئاسة الجمهورية ومجلس\n النواب ومجلس الوزراء وديوان المحاسبة والتفتيش المركزي.\nإضافة إلى ما سبق ،أناط اقتراح القانون بهيئة الشراء العام مهمة التعاون مع المؤسسات الدولّيـة والهيئات\n الأخرى محلّيـاً ودولّيـاً لتطوير نظام الشراء العام.\nص اقتراح القانون على تفعيل دور إدارة المناقصات لُتسّمى “هيئة الشراء العام” ،وليكون دورها\n بالتالي ،ين ّ\nرصدّيـاً وتنظيمياً وإشرافياً على عملّيـات الشراء بالتنسيق بين مختلف الادارات المعنّيـة ،ويكون توسيع\nصلاحيات هذه الهيئة ضرورّيـاً وأساسّيـاً مع وجوب إعطائها الاستقلالين المالي والوظيفي والموارد اللازمة\n لإجراء مهامها بكل موضوعّيـة.\n الفعالّيـة التخطيط والدمج\n والمنافسة في الموازنة\n المساءلة الشمولية\n الإستدامة الشفافيـة\n التخصص النزاهة\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 16\n\f قانون الشراء\n العام في لبنان\nرقم 244تاريخ 2021/7/29\n هذه الوثيقة هي نص القانون رقم 244تاريخ 2021/7/29معد ً\nلا بحسب:\n .1قرار المجلس الدستوري رقم 2021/5الصادر في الجريدة الرسمية\n بتاريخ 2021/9/23"}, {"o": 20, "l": null, "b": ".2تصحيح الاخطاء المادية الصادر في الجريدة الرسمية بتاريخ 2022/1/6\n .3القانون رقم 309الصادر في الجريدة الرسمية بتاريخ 2023/4/26\n .4قرار المجلس الدستوري رقم 2023/7تاريخ 2023/5/11\n .5المرسوم رقم 11339الصادر عن مجلس الوزراء بتاريخ 2023/5/29\n الصادر في الجريدة الرسمية بتاريخ 2023/6/8\nفي حال وجود خطأ مادي أو اختلاف بين النصوص ُيعَتمد النص الأساسي\n الصادر في الجريدة الرسمّيـة وتعديلاته.\n\f الفصل الأول | أحكـام عامـة"}, {"o": 21, "l": "المادة 1", "b": "المادة | 1هدف القانون ومبادُئه العامة\n يحّدد هذا القانون قواعد إجراء الشراء العام وتنفيذه ومراقبته ،وهو يرتكز على المبادىء التالية:\n .1تطبيق الإجراءات التنافسية كقاعدة عامة.\n .2إتاحة فرص متكافئة دون تمييز للمشاركة في الشراء العام.\n .3توفير معاملة عادلة ومتساوية وشفافة ومسؤولة لجميع العارضين والملتزمين.\n .4علنية الإجراءات ونزاهتها ومهنيتها بشكل يفّعل الرقابة والمحاسبة.\n .5تشجيع التنمية الاقتصادية المحلية والعمالة الوطنّية والإنتاج الوطني على أساس القيمة الفضلى من\n إنفاق المال العام ،دون الإخلال بالفعالية.\n حوكمة الرشيدة وتأخذ بالاعتبار مقتضيات التنمية المستدامة.\n تخضع عمليات الشراء إلى قواعد ال َ\n ُتعتَبر المبادىء العامة الواردة في هذه المادة من الانتظام القانوني العام."}, {"o": 22, "l": "المادة 2", "b": "المادة | 2تعاريـف\nيكون للكلمات والعبارات الواردة في هذا القانون المعاني المبّيـنة تجاهها أدناه ،ما لم يدّل سياق النص على\n خلاف ذلك:\n .1الدولة :الدولة اللبنانية.\n .2قانون المحاسبة العمومية :القانون الصادر بالمرسوم 14969تاريخ 1963/12/30وتعديلاته.\n .3الجهة الشارية أو سلطة التعاقد :هي الدولة وإداراتها ،ومؤسساتها العامة ،والهيئات الإدارية المستقلة،\nوالمحاكم التي لديها موازنات خاصة بها ،والهيئات ،والمجالس ،والصناديق ،والبلديات واتحاداتها ،والأجهزة\nالأمنية والعسكرية )والمؤسسات والإدارات والوحدات التابعة لها( ،والبعثات الدبلوماسية في الخارج،\nوالهيئات الناظمة ،والشركات التي تملك فيها الدولة وتعمل في بيئة احتكارية ،والمرافق العامة التي\n ي شخص من أشخاص القانون العام ينفق ما ً\n لا عاماً. تديرها شركات خاصة لصالح الدولة ،وأ ّ\n .4إدارة المناقصات :إدارة المناقصات الُمنشأة بالمرسوم رقم 2460تاريخ ) 1959/11/9تنظيم التفتيش المركزي(.\n .5المرجع الصالح :المرجع المختص بعقد النفقة وفقاً للقوانين المرعّيـة الإجراء.\n .6الشخص :الشخص الطبيعي أو المعنوي.\n .7المال العام :أي المال الذي تملكه أو تتصّرف به الجهات الشارية أو غيرها من أشخاص القانون العام ،أو\nمن تطَّبق عليهم أحكام هذا القانون ،وكذلك الأموال المودعة في الخزينة ،وذلك سواء كان مصدرها\n إيرادات الموازنة أو القروض أو الهبات.\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 18\n\f .8الشراء أو الشراء العام :يعني حيازة الجهة الشارية لوازماً أو أشغا ً\n لا أو خدمات.\n .9اللوازم :الأموال المنقولة أّياً كان نوعها ووصفها ،والخدمات المتعّلقة بها إذا كانت قيمتها لا تتجاوز قيمة\n اللوازم نفسها.\n .10الأشغال :أعمال ذات منفعة عامة ُتنَّفذ على الأراضي اللبنانية حسب تعريفها القانوني لحساب شخص"}, {"o": 23, "l": "المادة 2", "b": "من أشخاص القانون العام أو بواسطته أو تحت إدارته وهي تشمل على سبيل المثال لا الحصر الأعمال\n المرتِبطة بالبناء والتعمير ،وإعداد مواقع العمل ،والهدم ،وإصلاح أو صيانة أو تجديد الطرق والجسور ،أو\n إنشاء البنى التحتية أو الفوقية ،أو التركيب ،أو أشغال البناء المتعّلقة بالحفر والتشييد وصيانة المباني\n والمعامل ،وكذلك تركيب المعدات والتجهيزات والمواد ،والديكور ،والخدمات التابعة للأشغال إذا كانت\n قيمة هذه الخدمات لا تتجاوز قيمة الأشغال نفسها.\n .11الخدمات الاستشارية :أي الخدمات التي يغلب عليها الطابع الفكري أو الإرشادي ،ومن ذلك على سبيل\n المثال لا الحصر :الدراسات الهندسية أو المهنية أو الاقتصادية أو المالّيـة أو القانونية أو البيئّيـة وأعمال\n المساحة بما في ذلك مهام التصميم أو إعداد المواصفات أو الإشراف على التنفيذ أو التقييم أو\n الاستلام أو دراسة الأثر البيئي أو دراسات الجدوى الاقتصادية.\n .12الخدمات غير الاستشارية :أي الخدمات التي يكون التعاقد فيها على أساس أداء عمل مادي يمكن\n توصيفه من غير الخدمات الاستشارية ،ومن ذلك :الحراسة ،النظافة ،خدمات النقل ،التأمين والصيانة\n وغيرها.\n .13العاِرض :مقِّدم العرض أو العارض المحتَمل للاشتراك في إجراءات التلزيم أو التأهيل المسبق أو\n الشخص المشاِرك في هذه الإجراءات.\n .14إجراءات التلزيم أو إجراءات الشراء :وتعني الإجراءات المتعّلقة بالشراء بدءا ً من مرحلة الإعلان عنها أو\n طلب العروض إلى إبرام العقد.\n .15العرض :العرض المقَّدم من العارض لتقديم اللوازم أو الأشغال أو الخدمات.\n .16اتفاق الإطار :اتفاقية سارية المفعول لمدة محّددة ،بين جهة شارية أو أكثر ،وواحد أو أكثر من المورّدين أو\n المقاولين أو الإستشاريين أو مقّدمي الخدمات ،تهدف إلى تحديد شروط العقد المنوي إرساؤه ضمن\n صة تلك المتعّلقة بالأسعار والكميات حيثما كان ذلك مناسباً.\n مهلة محَّددة ،خا ّ"}, {"o": 24, "l": "المادة 2", "b": ".17العقد :اتفاق موَّقع بين الجهة الشارية والمورّد أو المقاول أو الاستشاري أو مقِّدم الخدمات والناتج عن\n إجراءات الشراء.\n .18الشروط المرجعّيـة :الشروط التي تحِّدد أهداف وغايات ونطاق المهمة الاستشارية وتقِّدم معلومات عن\n الخدمة المطلوبة.\n .19المورِّد :الشخص الذي يقوم بموجب العقد المبرم مع الجهة الشارية بتوريد السلع أو اللوازم والخدمات\n ذات الصلة بها نتيجة إجراءات الشراء.\n .20المقاول :الشخص الذي يقوم بتنفيذ أشغال بموجب عقد مبرم مع الجهة الشارية نتيجة إجراءات الشراء.\n .21مقِّدم الخدمات :الشخص الذي يقوم بتقديم الخدمات غير الاستشارية بموجب عقد مبَرم مع الجهة\n الشارية نتيجة إجراءات الشراء.\n م التعاقد معه على تقديم الخدمات الاستشارية نتيجة إجراءات الشراء.\n .22الاستشاري :الشخص الذي يت ّ\n .23الملتِزم :هو المورِّد أو المقاول أو مقِّدم الخدمات أو الاستشاري الذي أ ُبِرم معه عقد الشراء.\n التخطيط\n الفعالّيـة والدمج في\n19 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\f ي يوم من أيام الأسبوع.\n .24اليوم :يعني أ ّ\nي يوم من أيام الأسبوع باستثناء الأعياد الرسمية وأيام التعطيل الرسمي أو القسري\n .25يوم عمل :يعني أ ّ\n الناتج عن قوة قاهرة.\n .26دفتر الشروط أو ملفات التلزيم :المستندات كافة المتعّلقة بالشراء الصادرة إلى العارضين والتي\nيستخدمونها لغرض إعداد عروضهم بما في ذلك المواصفات الفنّيـة والمتطلبات الأخرى والإجراءات\n الواِجب اتباعها لتقديم العروض ،كذلك النماذج التي يتعَّين استخدامها وشروط العقد العامة والخاصة.\n .27الوسائل الإلكترونّيـة :استعمال التجهيزات الإلكترونّية )بما في ذلك الضغط الرقمي( لمعالجة وتخزين\nي\nم إرسالها ونقلها واستلامها بواسطة وسائل سلكية أو إشعاعية أو بصرية أو أ ّ\n المعلومات التي يت ّ\n وسائل كهرومغناطيسية أخرى."}, {"o": 25, "l": "المادة 2", "b": ".28التأهيل المسَبق :الإجراء المنصوص عليه في"}, {"o": 26, "l": "المادة 19", "b": "المادة 19من هذا القانون ،تّتخذه الجهة الشارية ،وتعلن\nعنه للتأّكد من توافر القدرات الفنّية والإمكانيات المالّية والإدارية والبشرية وغيرها لدى العارضين للقيام\nبتنفيذ أحد العقود بالكفاءة المطلوبة قبل دعوتهم لتقديم العروض ،وذلك وفقاً لمتطّلبات ومعايير\n التأهيل المحّددة في مستندات طلب التأهيل المسبق.\nم بين طرفين أو أكثر قبل أو بعد تقديم العرض ،لتحقيق غَرض غير مشروع أو للإخلال\n .29التواطؤ :ترتيب يت ّ\nبمبدأ تكافؤ الفرص ،ومبدأ حرية المنافسة بما في ذلك التأثير بشكل مباشر أو غير مباشر على تصّرفات\n طرف آخر ،وتقسيم العقود بين العارضين أو تثبيت أسعار العروض أو التلاعب بها بشكل غير تنافسي.\nي موقف يكون فيه للموظف العام أو أحد العارضين\n .30تضارب المصالح :يشمل مفهوم تضارب المصالح أ ّ\nأو غيرهم ممن يؤثّرون على نتيجة إجراء الشراء ،مصلحة خاصة ،مالية أو اقتصادية أو غيرها ،مباشرة أو غير\n مباشرة ،تهّدد حياد واستقلالية إجراءات الشراء .يتحقق أيضاً تضارب المصالح في الحالات التالية:\nأ .إذا كان العارض أو أحد العاملين لديه قد قام ،بشكل مباشر أو غير مباشر ،بنفسه أو بالإشتراك مع غيره\nبتقديم خدمات استشارية لتحضير الدراسة أو المواصفات أو مستندات أخرى خاصة بالشراء ،وكذلك\nعندما يكون قد عمل خلال السنتين السابقتين لدى مؤسسة قامت بهذه الخدمات ،باستثناء الحالة\nالتي يجري فيها الشراء على أساس مشروع متكامل ) (Turnkey projectيقوم فيه الملتزم بتنفيذ\nمراحل متعّددة منه جزئياً أو كلياً وترى الجهة الشارية مصلحة عامة بتلزيمه بهذه الطريقة ،وعندها\n يقتضي الإفصاح مسبقاً عن ذلك مع الأسباب التبريرية؛\nب .إذا كانت تربط بين العارضين صلات معَّيـنة كأن يكون لديهم شريك مشترك يسيطر على أعمالهم ،أو\n لديهم الممثل القانوني نفسه في العرض؛\nج .إذا تقدم العارض بأكثر من عرض واحد خلال عملية الشراء ،إّلا في حال إجازة ذلك في ملف التلزيم"}, {"o": 27, "l": "المادة 19", "b": "الخاص بالشراء؛\nي من الحالات المنصوص عليها في شرعة قواعد السلوك وفقاً للمادة 10من هذا القانون،\n د .في أ ّ\nحي الموظفين عن العمل الذي يقومون به إذا كان له علاقة بالشراء،\n والتي يجب تضمينها وجوب تن ّ\nفي حال كانت تربطهم صلات قربى حتى الدرجة الرابعة أو مصالح مشتركة واضحة مع العارض أو\nالعاملين لديه أو الشركاء في الشركة العارضة ،وكان ُيخشى معها عدم اّتصاف عملهم بالحياد أو تحمل\n بشكل واضح على الشك بهذا الحياد.\n .31حالات الطوارىء :حالات الخطر الداهم والكوارث المعلنة وفقاً للقانون.\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 20\n\f .32الإغاثة :الحالة العاجلة التي يقتضي معها إنقاذ الأرواح وحماية الممتلكات إثر التعّرض لخطر أو كوارث\n مفاجئة ،على سبيل المثال لا الحصر البحث عن الضحايا وإجلائهم واتخاذ إجراءات الإيواء والحماية وضبط\n الممتلكات والمحافظة عليها.\n .33المواصفاتُ :يقصد بها المواصفات الفنّية أو الوظيفّية أو مواصفات الأداء ،وهي كافة التعليمات الفنّية\n أو الوظيفّية أو تلك المتعلقة با َ\n لأداء التي تتضّمنها ملفات التلزيم والتي تحِّدد المواصفات والوظائف\n للسلع أو الخدمات أو الأشغال المطلوبة.\n جزة خلال تنفيذ عقد الشراء.\n جـزات :هي اللوازم المقَّدمة أو الخدمات أو الأشغال المن َ\n .34المن َ\n م النشر إلزامياً على المنصة الإلكترونّيـة المركزّيـة لدى هيئة الشراء العام ،وعلى الموقع\n .35النشر :يت ّ\n ي وسيلة أخرى تراها\n م النشر عبر أ ّ\n الالكتروني للجهة الشارية إن ُوجد .كما يجوز ،بالإضافة إلى ذلك ،أن يت ّ\n الجهة الشارية منا ِ\n سبة ،على أن ُيعتّد بتاريخ النشر على المنصة الإلكترونّيـة في كاّفة المهل المنصوص\n عليها في هذا القانون.\n م إلزامّيـاً عبر المن ّ\n صة الإلكترونّيـة ي تبليغ إلا الذي يت ّ .36التبليغ :خلافاً لأ ّ\n ي نص آخر ،عام أو خاص ،لا ُيعتّد بأ ّ"}, {"o": 28, "l": "المادة 19", "b": "المركزّيـة لدى هيئة الشراء العام.\n .37الشطر/الشريحة :هو مبلغ مالي يتراوح بين حَّدين مالَّيين أدنى وأعلى.\n .38السلطة التقريرية :هي الجهة المخَّولة قانوناً باتخاذ القرارات لدى الجهة الشارية.\n .39هيئة الشراء العام :هي الهيئة التي ُتعنى بتنظيم الشراء العام كما هي محّددة في الفصل السادس من\n هذا القانون.\n .40القائمون بمهام الشراء :كاّفة الموظفين والمسؤولين المباشرين المعنيين في عمليات الشراء في\n الجهات الشارية بالإضافة إلى أعضاء لجان التلزيم والاستلام.\n .41التثقيل :وضع علامة أو نسبة مئوية للدرجة المالّيـة والفنّيـة للعرض المقَّدم ُتستعمل في معادلة\n إحتساب العلامة النهائية التي ينالها كل عارض.\n .42هيئة معتَمدة :هي هيئة موثوقة تشّكل طرفاً ثالثاً ُتعتَبر مصادقُته على موضوع معّين اعترافاً رسمياً\n بالكفاءة والمطابقة.\n .43متعاقد ثانوي :أي شخص طبيعي أو معنوي يتعاقد معه الملتزم لتنفيذ جزء أو أكثر من الأشغال موضوع\n الشراء العام.\n م إلزامياً على المنصة\n جه إلى جهة أو جهات محَّددة ،وهو يت ّ\n .44إشعار :إعلام رسمي بموضوع معّين مو َّ\n الإلكترونّية المركزّية لدى هيئة الشراء العام ،وعلى الموقع الالكتروني للجهة الشارية إن ُوجد.\n .45فترة التجميد :هي الفترة المنصوص عليها في"}, {"o": 29, "l": "المادة 24", "b": "المادة 24من هذا القانون.\n .46ميزة تنافسية غير منصفة :هي ميزة تعطي العارض موقعاً تفضيلياً يتناقض مع مبادىء التنافس\n والمساواة بين العارضين ،والتشريعات المنا ِ\n هضة للاحتكار وتضارب المصالح.\n مدَرج ضمن العطل الرسمية ،يشّكل حالة عامة.\n .47تعطيل قسري :تعطيل اضطراري وطارئ ،غير ُ\n التخطيط\n الفعالّيـة والدمج في\n21 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية"}, {"o": 30, "l": "المادة 3", "b": "المادة | 3نطاق التطبيق\n .1تخضع لأحكام هذا القانون جميع عمليات الشراء العام من لوازم وأشغال وخدمات التي تقوم بها الجهات\nالشارية ،سواء كان تمويل العقد من أموال الموازنة أو الخزينة أو من قروض داخلية أو خارجية أو هبات غير\nمقَّيدة بشروط الواهب ،مع مراعاة أحكام المعاهدات والاتفاقيات الدولّية المبرمة مع الدولة اللبنانية .ولا\nيجوز لأي جهة شارية ،في غير الحالات المنصوص عليها في هذا القانون ،القيام بأي عملّيـة شراء إلا طبقاً\n لأحكامه.\n .2يجوز أن تقوم جهة شارية معَّيـنة بعمليات شراء لتلبية حاجات مشتركة بينها وبين جهات شارية أخرى ،كما\n يجوز أن تقوم جهة شارية معَّيـنة بعمليات شراء لحساب جهات شارية أخرى.\n .3عندما يكون الشراء مختلطاً ،أي عندما تتضّمن عملّيـة الشراء نوَعين أو أكثر من لوازم وأشغال وخدمات،\n تخضع عملّيـة الشراء للأحكام الخاصة بتلزيم نوع الشراء الذي يغلب على عملّيـة الشراء.\nي التزام أو امتياز لاستغلال مورد من موارد\n ُ .4يستثنى من أحكام هذا القانون الشراء الذي يهدف إلى منح أ ّ\nثروة البلاد الطبيعية أو مصلحة ذات منفعة عامة أو أي احتكار ،إلا فيما يتعلق بالإجراءات التي تسبق منح\nالامتياز أو الاحتكار ،حيث تخضع تلك الإجراءات إلى المبادئ العامة المنصوص عليها في المادة الأولى\n من هذا القانون فيما لا يتعارض مع أي نصوص خاصة واردة في قوانين أخرى.\nُ .5تطَّبق أحكام هذا القانون على عقود الشراكة بين القطاعين العام والخاص في كل ما لا يتعارض مع قانون\n تنظيم الشراكة بين القطاعين العام والخاص رقم 48تاريخ 2017/9/7وتعديلاته.\nُ .6تطَّبق أحكام هذا القانون على عمليات الشراء التي يجريها مصرف لبنان باستثناء طباعة وإصدار النقد\n وتحويلاته.\nُ .7تطَّبق في ما خص الحالات المستثناة أعلاه المبادىء العامة الواردة في متن المادة الأولى من هذا\n القانون."}, {"o": 31, "l": "المادة 4", "b": "المادة | 4اللغة\nُتعَتمد اللغة العربية في مستندات الشراء وفي قرارات الجهة الشارية .إلا أنه يمكن اعتماد اللغة الانكليزية\n و/أو الفرنسية مع العربية للمراسلات كافة ووضع المواصفات الفنّيـة أو الشروط المرجعّيـة.\n صين العربي والأجنبي َيسود الأول على الثاني.\n عند التعارض بين الن ّ"}, {"o": 32, "l": "المادة 5", "b": "المادة | 5العملة\n يحِّدد دفتر الشروط عملة العقد وكيفية المحاسبة في العقود بالعملة الأجنبية.\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 22"}, {"o": 33, "l": "المادة 6", "b": "المادة | 6السّرية\n .1تحافظ الجهة الشارية وجميع المعنيين بعملية الشراء على سّرية المعلومات المتعِّلقة بحماية المصالح\n الأمنية الرئيسية للدولة ،وتلك التي ُيخاِلف إفشاؤها القانون أو ُيعيق تنفيذه أو يم ّ\n س بالمصالح التجارّيـة\n مر الجهات القضائية المختصة بإفشاء تلك المشروعة للعارضين ،أو ُيعيق التنافس المن ِ\n صف ،ما لم تأ ُ\n المعلومات.\n .2باستثناء حالات توفير المعلومات أو نشرها بمقتضى القوانين النافذة ،تمتِنع الجهة الشارية في طلبات\n التأهيل الُمسبق والعروض المقَّدمة عن إفشاء محتوياتها ومضمونها بما فيها الأسرار المهنّيـة والتقنّيـة\n والمحمّيـة بقوانين الملكّية الفكرّيـة والتي من شأن الإفصاح عنها إحداث ضرر غير مشروع للعارضين ،أو\n ي شخص آخر غير مأذون له بالاطلاع على هذا النوع من المعلومات.\n بالعارضين المنافسين أو بأ ّ\n ي عارض\n ُ .3تراَعى السّرية في أية مناقشات أو اتصالات أو مفاوضات أو حوارات ُتجَرى بين الجهة الشارية وأ ّ\n ي مناقشات أو اتصالات أو\n ي طرف في أ ّ\n في كل ما لا يتعارض مع القوانين المرعّية الإجراء .ولا يجوز لأ ّ\n ي معلومات تقنية أو مالية أو معلومات\n ي شخص آخر أ ّ\n مفاوضات أو حوارات من هذا القبيل أن ُيفشي لأ ّ\n أخرى تتعّلق بهذه المناقشات أو الاتصالات أو المفاوضات أو الحوارات من دون موافقة الطرف الاخر ،إّلا\n صة. ص القانون على ذلك أو أ َ َ\n مَرت به المحاكم المخت ّ إذا ن ّ"}, {"o": 34, "l": "المادة 7", "b": "المادة | 7شروط مشاركة العارضين\n أو ً\n لا :شروط المشاركة\n .1يجب أن تتوافر في العارضين الشروط التالية ،إضافة إلى أية شروط تراها الجهة الشارية مناسبة وذات\n صلة بموضوع الشراء:\n أ .أّلا يكون قد ثَُبَتت مخالفتهم للأخلاق المهنية المنصوص عليها في النصوص ذات الصلة ،إن ُوجدت؛\n ب .الأهلية القانونية لإبرام عقد الشراء؛\n ج .الايفاء بالالتزامات الضريبية واشتراكات الضمان الاجتماعي؛\n صَدَرت بحقهم أو بحق مديريهم أو مستخدميهم المعنيين بعملية الشراء أحكام نهائية ولو\n د .ألا يكون قد َ\n ي جرم يتعّلق بسلوكهم المهني ،أو بتقديم بيانات كاذبة أو ملّفقة بشأن\n غير مبرمة ُتدينهم بارتكاب أ ّ\n أهلّيتهم لإبرام عقد الشراء أو بإفساد مشروع شراء عام أو عملية تلزيم ،وأّلا تكون أهلّيـتهم قد\n و آخر بمقتضى إجراءات إيقاف أو حرمان إدارية ،وألا يكونوا في َوضع الإقصاء عن أ ُسِق َ\n طت على نح ٍ\n الاشتراك في الشراء العام؛\n صَدَرت بحقهم أحكام إفلاس؛\n هـ .ألا يكونوا قيد التصفية أو َ\n مبرم؛ حِكموا بجرائم اعتياد الربى وتبييض الأموال بموجب ُ\n حكم نهائي وإن غير ُ و .ألا يكونوا قد ُ\n ي من أعضاء السلطة\n ز .ألا يكونوا مشاركين في السلطة التقريرية لسلطة التعاقد وألا يكون لديهم مع أ ّ\n التقريرية مصالح مادية أو تضارب مصالح؛\n التخطيط\n الفعالّيـة والدمج في\n23 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\fح .غير ذلك من الشروط التي َتفِرضها سلطة التعاقد في دفتر الشروط الخاص بمشروع الشراء والتي\n تتناسب مع الأعمال المطلوبة.\nط .إفادة من وزارة الاقتصاد والتجارة تثبت انطباق أحكام قانون مقاطعة العدو الإسرائيلي بالنسبة\n للشركات الأجنبية.\n ي .التصريح عن أصحاب الحق الاقتصادي حتى آخر درجة ملكية.\n ن إثبات زوال المانع أو إعادة الإعتبار ُيعيدان حكماً للعارضين حق المشاركة.\n .2إ ّ\n ثانيًا :مؤهلات العارضين"}, {"o": 35, "l": "المادة 7", "b": "صد بمؤهلات العارضين المؤهلات المهنية والتقنية والبيئّيـة والكفاءة المهنية والموارد المالّية\n ُ .1يق َ\n والمعّدات والَمراِفق المادية الأخرى والَمق ِ\nدرة الإدارية والخبرة والموارد البشرية لتنفيذ العقد والمحَّددة\n م تحديدها بشكل متنا ِ\n سب مع موضوع الشراء. في ملف التأهيل المسبق أو ملف التلزيم على أن يت ّ\nي معيار أو شرط أو إجراء يمثّل تمييزا ً تجاههم\n .2لا َتفِرض الجهة الشارية بشأن مؤّهلات اشتراك العارضين أ ّ\n أو فيما بينهم أو تجاه فئات منهم ،لا يمكن تبريره موضوعياً.\nُ .3تَقِّيم الجهة الشارية مؤّهلات اشتراك العارضين وفقاً لمعايير وإجراءات التأهيل المبَّينة في ملفات\n التلزيم.\n ُ .4تسِقط الجهة الشارية أهلّية أ ّ\n ي عارض في الحالات التالية:\nأ .إذا أثبَتت في أي وقت أن المعلومات المقَّدمة عن مؤّهلاته كاذبة أو مغلوطة أو أنها تنطوي على خطأ\n أو نقص جوهريين؛\n ب .إذا َف ِ\nشل العارض المؤَّهل إعادة إثبات توّفر المؤهلات التي صار على أساسها التأهيل المسبق وفقاً\n للمادة 19من هذا القانون."}, {"o": 36, "l": "المادة 8", "b": "المادة | 8استبعاد العارض بسبب عرضه منافع أو من جّر اء ميزة تنافسية\n غير منصفة أو بسبب تضارب المصالح\n .1تستبعد الجهُة الشارية العارض من إجراءات التلزيم في إحدى الحالتين التاليتين:\n مح َّ\nظر بموجب أحكام هذا القانون أو أي جريمة شائنة ي مخالفة أو عمل ُ\n أ .في حال قام العارض بإرتكاب أ ّ\nي\nأو أحد الجرائم المشمولة بقانون الفساد ،لا سّيما جرائم صرف النفوذ والرشوة ،إذا عرض على أ ّ\nحُه أو وافق\n مَن َ\n موظف أو مستخَدم حالي أو سابق لدى الجهة الشارية أو لدى سلطة حكومية أخرى ،أو َ\nي شيء آخر ذي قيمة ،بهدف التأثير على منِحه ،بطريقة مباشرة أو غير مباشرة ،منفعة أو عم ً\n لا أو أ َّ على َ\n تصُّرف أو قرار ما من جانب الجهة الشارية أو على إجراء تَّتبعه في ما يتعلق بإجراءات التلزيم؛ أو\nب .إذا كان لدى العارض ميزة تنافسية غير منصفة أو كان لديه تضارب في المصالح بما يخاِلف أحكام هذا\n القانون والقوانين المرعية الاجراء.\n ُ .2يدَرُج ك ّ\nل قرار تَّتخُذه الجهة الشارية باستبعاد العارض من إجراءات التلزيم بمقتضى هذه المادة ،وأسباب\n م إبلاغ القرار إلى العارض الَمعني.\n ذلك الاستبعاد ،في سجل إجراءات الشراء ،كما يت ّ\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 24"}, {"o": 37, "l": "المادة 9", "b": "المادة | 9سجل إجراءات الشراء\n ُ .1تنشئ الجهة الشارية سج ً\n لا خاصاً ُتضِّمُنه كل المعلومات المتعلقة بعملية الشراء ،وَتحَفظ فيه جميع\n الوثائق المتعلقة بإجراءات التلزيم وُتِعّد ملفات لها وتحافظ عليها .يمكن الاطلاع على هذا السجل وفقاً\n لأحكام هذه المادة وُيعتَمد مرجعاً تسُهل مراجعته واستقاء المعلومات منه ،وُيحَفظ الكترونياً في حال كان\n توّفره ممكناً ،وُتدَرج فيه المعلومات التالية:\n أ .وصف موجز لموضوع الشراء يتضّمن إلزامياً تواريخ إطلاق عملية الشراء وتقديم العروض وطلبات\n التأّهل إن ُوِجَدت وفتح العروض وتحديد العرض الفائز؛\n ب .إسماء وعناوين العارضين وإسم وعنوان الجهة الملتزمة ،بالإضافة إلى قيمة العقد )وفي حال إجراء\n إتفاق إطاري :إسم وعنوان الجهة التي ُيبَرم معها هذا الإتفاق(؛\n ج .بيان بالأسباب والظروف التي استَنَدت إليها الجهة الشارية في اتخاذ قرارها بشأن وسيلة الإعلان؛\n د .في حال استخدام الجهة الشارية طريقة شراء أخرى غير المناقصة العمومية ،بيان بالأسباب والظروف\n التي استَنَدت إليها لتبرير استخدام تلك الطريقة الأخرى؛\n هـ .في حال إجراء إتفاق إطاري ،بيان بالأسباب والظروف التي استَنَدت إليها الجهة الشارية لتبرير استخدام\n إجراءات الاتفاق الإطاري؛\n و .في حال إلغاء الشراء بمقتضى الفقرتين 1و 2من"}, {"o": 38, "l": "المادة 25", "b": "المادة 25من هذا القانون ،بيان بهذا الشأن\n وبالأسباب والظروف التي استَنَدت إليها الجهة الشارية في اتخاذ قرارها بإلغاء الشراء؛\n ز .في حال تطبيق سياسات اجتماعية-اقتصادية في إجراءات التلزيم ،تحديد معلومات تفصيلية عن هذه\n السياسات وآليات تفعيلها؛\n ح .في حال عدم تطبيق فترة تجميد بحسب الفقرة 3من"}, {"o": 39, "l": "المادة 24", "b": "المادة 24من هذا القانون ،بيان بالأسباب\n والظروف التي استَنَدت إليها الجهة الشارية لاتخاذ قرارها بعدم تطبيق فترة التجميد؛\n ط .في حال الاعتراض أو المراجعة بمقتضى أحكام الفصل السابع من هذا القانون ،يجب الإشارة صراحًة\n إلى جميع طلبات إعادة النظر أو الشكوى أو المراجعة ،وإلى تاريخ ورقم تسجيلها إضافة إلى نسخة عن\n جع عن هذه الاعتراضات والأسباب التي خذة بشأن ك ّ\n ل منها والإشارة إلى أي ترا ُ القرارات الّنهائّية المّت َ\n أّدت إلى ذلك؛\n ي .نسخة عن الاشعار عن فترة التجميد الممنوحة وفقاً للفقرة 2من للمادة 24من هذا القانون ،في حال\n الانطباق؛\n ك .في حال أَّدت إجراءات التلزيم إلى إرساء الشراء بمقتضى الفقرة 8من"}, {"o": 40, "l": "المادة 24", "b": "المادة 24من هذا القانون،\n بيان بهذا الشأن وبالأسباب التي أّدت إلى ذلك؛\n م أحكامه وشروطه؛ بالإضافة إلى نسخة عنه .وفي حالة إجراءات الاتفاق الإطاري،\n ل .قيمة العقد وأه ّ\n جز؛\n خص لأهم أحكامه وشروطه ونسخة عن الاتفاق الإطاري المكتوب الُمن َ\n ُيضاف مل ّ\n م أحكامه وشروطه الأخرى؛\n خص لأه ّ\n مل ّ\n مقَّدم و ُ\n م .قيمة كل عرض ُ\n ن .في حال اعتبار المعلومات سّرية بمقتضى الفقرة 1من"}, {"o": 41, "l": "المادة 6", "b": "المادة 6أو بمقتضى"}, {"o": 42, "l": "المادة 108", "b": "المادة 108من هذا\n القانون ،تحديد الأسباب والظروف التي استندت إليها الجهة الشارية في اعتماد السرّية؛\n التخطيط\n الفعالّيـة والدمج في\n25 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\fي معلومات أخرى يلزم إدراجها في السجل بمقتضى أحكام هذا القانون أو القوانين المرعية الإجراء أو\n س .أ َّ\n بمقتضى وثائق التلزيم؛\nع .في حال َرفض عرض مقَّدم بمقتضى"}, {"o": 43, "l": "المادة 27", "b": "المادة 27من هذا القانون ،بيان بهذا الشأن وبالأسباب\n والظروف التي استَنَدت إليها الجهة الشارية في ذلك القرار؛\nخص طلبات الإستيضاح المتعلقة بوثائق التأهيل المسبق ،إن ُوجدت ،أو ملفات التلزيم ،والردود\n مل َّ\n فُ .\n خص لكل تعديل على هذه الوثائق أو الملفات؛\n مل َّ\n على هذه الطلبات ،و ُ\nص .المعلومات المتعلقة بمؤّهلات العارضين مقدمي طلبات تأُّهل والعروض ،إن وِجَدت ،أو بافتقارهم\n إلى المؤّهلات؛\nق .في حال استبعاد عارض من إجراءات التلزيم بمقتضى المادتين 7أو 8من هذا القانون ،بيان بهذا\n الشأن وبالأسباب والظروف التي استَنَدت إليها الجهة الشارية في ذلك القرار.\n ُ .2يتاح الا ِّ\nطلاع على الجزء من السجل الُمشار إليه في الفقرات الفرعية )أ( إلى )ط( من الفقرة 1من هذه\n ي شخص بعد التلزيم المؤقت أو بعد إلغاء الشراء ،عند الطلب.\n المادة لأ ّ\n .3مع مراعاة أحكام الفقرة 4من هذه المادةُ ,يتاح الا ِّ\nطلاع على الجزء من السجل الُمشار إليه في الفقرات\nالفرعية )ي( إلى )س( من الفقرة 1من هذه المادة ،عند الطلب ،للعارضين الذين قَّدموا عروضاً ،بعد\n أخذهم علماً بقرار التلزيم المؤقت.\nُ .4تطَّبـق بالنسبة للمعلومات الواردة في السجل أحكام"}, {"o": 44, "l": "المادة 6", "b": "المادة 6من هذا القانون ,وخاصة في ما يتعَّلق\nخص المشار إليه في الفقرة الفرعية\n بالمعلومات المرتبطة بفتح العروض المقّدمة وتقييمها ,باستثناء المل َّ\n )م( من الفقرة 1من هذه المادة."}, {"o": 45, "l": "المادة 10", "b": "المادة | 10قواعد السلوك\n ضع هيئة الشراء العام بموجب قرار تنظيمي ُ\nشرعة لقواعد السلوك والأخلاق المهنّيـة والمواطنة الصالحة َت َ\nالخاصة بعملّيـات الشراء العام ُتطَّبـق على كافة العاملين في الجهات الشارية وعلى المتعاقدين معها ،على\nصة أحكام أن تتضَّمن هذه ال ُ\n شرعة على سبيل المثال لا الحصر المعايير المنصوص عليها في هذا القانون خا ّ\nحكم الرشيد والحياد والإنصاف والمعرفة\n النزاهة والشفافّيـة ومنع تضارب المصالح إضافة إلى قواعد ال ُ\nحظ التدابير التنظيمية الواِجبة التطبيق على العاملين والاجراءات المّتبعة للتحُّقق من\n والكفاءة .كما يجب أن َتل َ\n حسن المسلكية ووجوب كشف المخالفات.\n الكفاءة و ُ\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 26\n\f قـواعد عامة لإعداد وإجراء الفصل الثـاني\n وتنفيذ عملية الشراء\n البند الأول | تخطيط الاحتياجات وتحديدها"}, {"o": 46, "l": "المادة 11", "b": "المادة | 11وضع خطط الشراء\n َ .1تسري أحكام هذه المادة على مشاريع الشراء التي تتعّدى قيمُتها التقديرية سقفاً مالياً محّددا ً بمبلغ\n خمسة مليارات ليرة لبنانيةُ .يعَّدل هذا السقف المالي بناًء على توصية من هيئة الشراء العام وبموجب\n خذ في مجلس الوزراء بناًء على اقتراح رئيسه ,على أّلا يؤدي التعديل إلى مخالفة أهداف هذه\n مرسوم ُيَّت َ\n المادة والمبادئ التي كّرسها هذا القانونُ .تستثنى من أحكام هذه المادة عمليات الشراء التي تَّتسِم\n بالسرية والمتعّلقة بالأمن والدفاع الوطني بحسب الفقرة الرابعة من المادة .46\n .2يتعّين على الجهة الشارية تحديد احتياجاتها وتحضير خ ّ\n طتها السنوية عن العام المقبل تزامناً مع إعداد\n ضر الخطة السنوية للشراء\n نفقاتها العامة بما يتوافق مع الاعتمادات المطلوبة في مشروع موازنتهاُ .تح َّ\n حد وإجراءات َتصُدر عن هيئة الشراء العام .يمكن ان تكون الخطة سنوية أو متعّددة\n بناًء على نموذج مو َّ\n السنوات في حال كانت تتضَّمن مشاريع يقتضي تنفيذها جدولة التزامات في اطار متوسط أو طويل\n الأمد ،على أن تتضَّمن على الأقل المعلومات التالية:\n أ .موضوع الشراء؛\n ب .طبيعة الشراء )لوازم أو أشغال أو خدمات(؛\n ج .مصدر التمويل والقيمة التقديرية بحسب الشطر ،عند إمكانية إعلانه ،وتنسيبه في الموازنة؛\n د .وصف موجز لمشروع الشراء؛\n هـ .طريقة الشراء؛\n و .التاريخ الُمحتمل بالإشارة إلى الشهر في ما يتعّلق ببدء إجراءات التلزيم؛\n ز .الشطر الذي َتَقع ضمنه القيمة التقديرية لموضوع الشراء؛\n ح .الملاحظات والمعلومات المفيدة الأخرى التي من شأنها أن تساعد العارضين المحتملين على فهم\n وتحضير عروض جيدة وضمن المهل.\n ُ .3تر ِ\n سل الجهة الشارية خطتها المكتملة إلى هيئة الشراء العام في مهلة شهرين من بدء السنة المالية.\n حدة ونشرها خلال مهلة 30يوم\n َتعَمد هيئة الشراء العام إلى توحيد الخطط في خطة شراء سنوية مو َّ\n عمل."}, {"o": 47, "l": "المادة 11", "b": "ي تعديل على خطتها السنوية ,لا سّيما الحصول على قروض أو هبات ,يجب على الجهة\n .4عند إدخال أ ّ\n الشارية نشر هذا التعديل على موقعها الالكتروني إن ُوِجد ,وعلى المنصة الإلكترونّيـة المركزّيـة لدى هيئة\n الشراء العام ,مع احترام مهل الإعلان المنصوص عليها في المادة .12\n التخطيط\n الفعالّيـة والدمج في\n27 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية"}, {"o": 48, "l": "المادة 12", "b": "المادة | 12الإعلان عن الشراء\n .1تتم الدعوة إلى التنافس عبر الاعلان عن الشراء على المنصة الإلكترونّيـة المركزّيـة في هيئة الشراء العام\nوعلى الموقع الإلكتروني الخاص بالجهة الشارية إن ُوِجد .كما يعود للجهة الشارية أن ُتقِّرر نشر الإعلان\n ي وسيلة إضافية أخرى.\n في أ ّ\nُ .2تحَّدد مدة الإعلان وفقاً لأهمية مشروع الشراء وتعقيداته على أن لا تقل في جميع الأحوال عن واحد\nوعشرين يوماً من الموعد الأقصى لتقديم العروض .يمكن تخفيض مدة الإعلان إلى خمسة عشر يوماً\n عندما يتعّذر عملياً اعتماد القاعدة العامة ,وذلك في ظروف استثنائية ,وبعد أن ُتص ِ\nدر الجهة الشارية قرارا ً\n معّل ً\nلا يحِّدد طبيعة هذه الظروف ,على أن ُيدَّون التعليل في سجل إجراءات الشراء وفقاً للمادة 9من هذا\n القانون.\nع آخر يوم لتقديم العروض يوم عطلة رسمية أو\n .3لا َيدُخل يوم نشر الإعلان في احتساب المهلة ،وإذا َوَق َ\nتعطيل قسريُ ،تمَّدد المهلة حكماً إلى أول يوم عمل يلي التعطيل دون الحاجة إلى الإعلان مسبقاً عن\n ذلك."}, {"o": 49, "l": "المادة 13", "b": "المادة | 13القيمة التقديرية لمشروع الشراء\n .1يجب على كل جهة شارية تحديث تقديراتها لقيمة مشروع الشراء قبل الإعلان عنه إلا في الحالات\n الإستثنائية التي يتعَّذر فيها ذلك ،على أن ُتبِّين الأسباب بشكل معَّلل وواضح.\n ُ .2تِعّد الجهة الشارية القيمة التقديرية لمشروع الشراء إستنادا ً إلى أسعار السوق الواقعية وَتق ّ\nصي الأسعار\nلدى الإدارات الأخرى ،وبعد الأخذ بالاعتبار كل زيادة يمكن أن َتنُتج عن تطبيق البنود الاختيارية الملحوظة في\n دفتر الشروط )على سبيل المثال زيادة في الكميات ،الحوافز ،الخ.(...\n .3في ما يتعّلق باتفاقات الإطار ،تؤخذ بالاعتبار القيمة التقديرية القصوى لمجمل العقود المتوّقعة طوال\n فترة الاتفاق.\nم احتساب القيمة التقديرية لكافة المجموعات التي يتألف\n .4عند إجراء الشراء على أساس مجموعات ،يت ّ\n منها الالتزام.\n .5يجب أن تكون قيمة مشروع الشراء التقديرية محَّددة لدى الجهة الشارية عند الإعلان عنها أو عند البدء\n بإجراءات التلزيم.\n ُ .6يح َّ\nظر على الجهة الشارية احتساب قيمة مشروع الشراء التقديرية بأقل أو أكثر من قيمته الفعلية بهدف\n تفادي تطبيق أحكام القانون.\n .7عند احتساب القيمة التقديرية لمشروع الشراء يجب الأخذ بالاعتبار كافة العناصر اللازمة لتنفيذها.\n .8يجب أن تبقى القيمة التقديرية لمشروع الشراء سّرية قبل التلزيم وبعده ،إلا إذا رأت الجهة الشارية عكس\nذلك لغايات تتعَّلق بالمنافسة والحرص على نجاح التلزيم ،أو في الصفقات المعلومة أسعارها بشكل\n ي وواضح ،وعندها ُيعَلن عن القيمة التقديرية وفق الأصول .في جميع الأحوال لا ُيحَت ّ\nج بالسرية أمام جل ّ\n ديوان المحاسبة والهيئات الرقابية.\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 28"}, {"o": 50, "l": "المادة 14", "b": "المادة | 14تجزئة الشراء\n .1يجوز للجهة الشارية تجزئة الشراء إلى أجزاء مستقلة في الحالتين التاليتين فقط:\n أ .عندما تتطَّلب ذلك طبيعة الأعمال أو السلع أو الخدمات ،ووجود مبِّررات واضحة كتنّوع مصادر التوريد\n وتعُّددها أو اختلاف الأجزاء عن بعضها بما يؤدي إلى منفعة أكيدة من التجزئة ،على أن يكون القرار\n مبَّررا ً وخاضعاً للرقابة وفقاً للقوانين المرعية الإجراء.\n ب .عند تنفيذ سياسات تنموية للحكومة كتشجيع مشاركة المؤسسات الصغيرة والمتوسطة في الشراء\n العام.\n .2لا يجوز تجزئة الشراء إلى جزئيات لتطبيق أحكام خاصة بكل جزء منها بَغَرض تخفيض القيمة التقديرية\n لمشروع الشراء أو بقصد التهّرب من الرقابة أو من تطبيق أحكام هذا القانون أو القوانين والأنظمة الأخرى."}, {"o": 51, "l": "المادة 15", "b": "المادة | 15استدامة وسياسات تنموية\n َ .1تعتِمد الجهات الشارية ،حيث أمكن ،الشراء العام المستدام لتوجيه القدرة الشرائية للدولة نحو السلع\n والخدمات المستدامة بهدف تقليص الأثر البيئي وتحقيق الأهداف الاقتصادّيـة والاجتماعّيـة المنصوص\n عليها في الاتفاقيات الدولّيـة ووفقاً للأولوية الوطنّيـة ،مع الحرص على تحقيق التوازن بين المنافع\n المحتملة والحرص على تحقيق القيمة الفضلى من إنفاق المال العام وبشكل يسَمح بإعطاء حوافز\n للمؤسسات الصغيرة والمتوسطة الحجم وللإنتاج المحلي والخبرات الوطنّية.\n ل ما كان ذلك ممكناً ،أن يت ّ\n م التلزيم على أساس أقسام أو مجموعات ،على أن ُيحِّدد دفتر الشروط .2يجب ،ك ّ\n الخاص عدد تلك الأقسام أو المجموعات وطبيعتها والشروط المفروضة للاشتراك في قسم أو مجموعة\n من التلزيم وطريقة إسناد ذلك التلزيم وذلك من أجل الإفادة الاجتماعّيـة والاقتصادّيـة .توضع قواعد\n خذ في مجلس الوزراء بناًء على اقتراح الوزير أو\n وسياسات للشراء العام المستدام بموجب مراسيم ُتّت َ\n الوزراء المختصين."}, {"o": 52, "l": "المادة 16", "b": "المادة | 16الأنظمة التفضيلية\n .1خلافاً لأي نص آخر ,يمكن إعطاء العروض المتضمنة سلعاً أو خدمات ذات منشأ وطني أفضلية بنسبة\n //10//عشرة بالمئة عن العروض المقّدمة لسلع أو خدمات أجنبيةُ .تعطى الأفضلية لمكّونات العرض ذات\n المنشأ الوطنيُ .تحَّدد السلع والخدمات الوطنّيـة والشروط التي يجب أن تتوّفر فيها للاستفادة من هذه\n الأفضلية وفقاً لقواعد المنشأ.\n ُ .2يح َّ\n ظر تضمين ملفات التلزيم أو ملفات التأهيل المسبق أحكاماً تؤدي إلى استبعاد السلع المصنوعة في\n لبنان أو الخدمات الاستشارية والفكرية اللبنانية في حال وجودها بجودة ونوعية َتفي بالمطلوب.\n التخطيط\n الفعالّيـة والدمج في\n29 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية"}, {"o": 53, "l": "المادة 17", "b": "المادة | 17وصف موضوع الشراء\n ُ .1تحِّدد الجهة الشارية في ملفات التلزيم أوصاف موضوع الشراء تحديدا ً واضحاً وَت َ\nضع المعايير التي\nستستخدمها في تقييم العروض المقّدمة ،بما في ذلك المتطلبات الدنيا التي يجب أن تفي بها العروض\n المقَّدمة كي ُتعَتبر مستجيبًة للمتطلبات والمواصفات المطلوبة ،وكيفية تطبيق تلك المتطلبات الدنيا.\n .2يكون وصف موضوع الشراء موضوعياً وعاماً ،وُتحَّدد في ذلك الوصف الخصائص الفنّيـة والوظيفّيـة ذات\nالصلة و/أو الخصائص المتعّلقة بالأداءُ .تحَّدد المواصفات الفنّيـة والشروط المرجعّيـة وفقاً للمعايير التالية:\nأ .وفقاً للمقاييس الوطنّية أو الدولّية الصادرة عن المراجع المختصة ،والموافقات الفنّيـة أو المواصفات\n الفنّيـة الرسمية العائدة لتصميم الأشغال والمنتجات واحتسابها وتنفيذها واستعمالها،\n و/أو\n ب .على أساس الخصائص الوظيفّيـة أو متطّلبات الأداء عندما يكون ذلك ممكناً.\n .3يمكن أن َيشتِمل وصف موضوع الشراء على مواصفات ،ومخططات ،ورسوم ،وتصاميم ،ومتطلبات،\n واختبارات وطرق لإجرائها ،وتغليف ،وعلامات أو شهادات مطاِبقة ،ورموز ومصطلحات.\n .4لا يمكن أن ُيشير وصف موضوع الشراء إلى علامة تجارّيـة معَّيـنة أو إسم تجاري أو براءة اختراع أو تصميم\n ي منها ،إ َّ\nلا في الحالة التي يستحيل معها وصف منَتج معّين أو إدراج إشارة إلى أ ٍّ\n أو نوع أو منشأ معّين أو ُ\nموضوع الشراء بطريقة أخرى دقيقة ومفهومة بما يكفي لوصف الخصائص ،على أن ُيرَفق بعبارة “أو ما\n يعادلها”.\n ُ .5يراعى استخدام الصفات والمتطّلبات والرموز والمصطلحات المو َّ\nحدة ،عندما تكون متاحة ،لدى صياغة\nوصف موضوع الشراء الذي ُيراد إدراجه في ملفات التلزيم أو ملفات التأهيل المسبق في حال وجودها،\n وذلك في ما يتعّلق بالخصائص الفنّيـة والوظيفّيـة لموضوع الشراء وخصائصه المتعّلقة بالأداء."}, {"o": 54, "l": "المادة 17", "b": ".6عندما َتعتِمد سلطات التعاقد طريقة الرجوع إلى المواصفات المذكورة في الفقرة ) - 2أ( من هذه المادة،\nن المنتجات والخدمات موضوع الشراء لا تستوفي المواصفات المذكورة\n جـة أ ّ\n لا يمكنها رفض عرض بح ّ\n عندما ُيبر ِ\nهن العارض أن العرض الذي َتقَّدم به يستوفي المستلزمات الُمحَّددة بالمواصفات الفنّية بأية\nضر ويقِّدم تقريرا ً تقنياً من المصِّنع أو شهادة مطابقة من\n وسيلة كانت .بهدف تحقيق ذلك ،يمكن أن ُيح ِّ\n معتَمدة.\n هيئ ة ُ\n .7عندما َتعتِمد الجهات الشارية خيار وضع المواصفات على أساس الأداء والخصائص الوظيفّية ،لا يمكنها\nرفض عرض يتوافق والمقاييس الدولّيـة أو الوطنّيـة إذا كانت المواصفات تستوفي الأداء والخصائص\n ق للعارض أن ُيبر ِ\nهن للجهات الشارية ،وبأي وسيلة كانت واستنادا ً إلى المقاييس، الوظيفّيـة المحّددة ،ويح ُّ\nأن الأشغال أو المنتجات أو الخدمات تتوافق والأداء المطلوب والخصائص الوظيفّيـة التي فرضتها الجهات\nضر ويقِّدم تقريرا ً تقنياً من المصِّنع أو شهادة مطابقة من هيئة\n الشارية .بهدف تحقيق ذلك ،يمكن أن يح ِّ\n معتَمدة.\n ُ\n ُ .8تدَرج كلما كان ذلك ممكناً ،الخصائص البيئّيـة المحّددة بالرجوع إلى علامة بيئّيـة ُ\nمعَتَرف بها يمكن لجميع\n الاطراف المعنّيـة الحصول عليها.\nضع ولا ُتصاغ على الوجه الذي يؤدي إلى استبعاد\n .9تكون المواصفات متناسبة مع الحاجة المطلوبة ولا تو َ\n عارضين بصورة غير مشروعة.\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 30"}, {"o": 55, "l": "المادة 18", "b": "المادة | 18معايير التقييم\n .1يجب أن تكون معايير التقييم متعّلقة بموضوع الشراء.\n .2إضافة إلى السعر ،يمكن أن َتتضَّمن معايير التقييم تكاليف تشغيل السلع أو الأشغال وصيانتها وإصلاحها،\n ووقت تسليم السلع أو إنجاز الأشغال أو تقديم الخدمات ،وخصائص موضوع الشراء ،مثل الخصائص\n الوظيفّيـة للسلع أو الأشغال والخصائص البيئّيـة ،والمخ ّ\n طط التنفيذي وخبرة فريق العمل ،والشروط\n الخاصة بتسديد الثمن ،وبالكفالات المتعلقة بها وغيرها من المعايير.\n .3يمكن أن َتشَمل معايير التقييم أي معايير يكون أخذها في الاعتبار مسموحاً به بموجب القوانين المرعية\n الإجراء أو مشروطاً بالمراسيم أو الأنظمة النافذة.\n ُ .4تبِّين الجهة الشارية في ملفات التلزيم:\n م على أساس السعر الأدنى أو العرض الأفضل ،الذي\n أ .المعايير التي سُتعَتمد للتقييم وما إذا كان سيت ّ\n َيعتِمد معايير أخرى غير السعر؛\n حِّدَدت بمقتضى هذه المادة ،بما فيها السعر المعَّدل بحسب الهامش\n ب .جميع معايير التقييم التي ُ\n ي شكل من أشكال التفضيل؛\n التفضيلي المنصوص عليه في"}, {"o": 56, "l": "المادة 16", "b": "المادة 16من هذا القانون أو أ ِّ\n ج .الِن َ\n سب المحَّددة لكل معيار من معايير التقييم ،على أن تكون متناسبة مع أهمية المعيار وحاجته\n لموضوع الشراء؛\n د .كيفية تطبيق تلك المعايير في إجراءات التقييم.\n .5لدى تقييم العروض المقَّدمة وتحديد العرض الفائزَ ،تستخ ِ\n دم الجهُة الشارية المعايير والإجراءات المبّيـنة\n في ملفات التلزيم فقط ،وتطِّبـق تلك المعايير والإجراءات على النحو الُمعَلن عنه في تلك الملفات .ولا\n م النص عليه في هذه الفقرة.\n ي معيار أو إجراء لم يت ّ\n ُيستخَدم أ ُّ\n البند الثاني | إجراءات التلزيم"}, {"o": 57, "l": "المادة 19", "b": "المادة | 19إجراءات التأهيل المسبق للعارضين\n .1يمكن للجهة الشارية أن تقوم بإجراءات تأهيل مسبق للعارضين ،وفقاً لأحكام هذا القانون ،لكي ُتحِّدد\n العارضين المؤَّهلين .وُتطَّبـق على إجراءات التأهيل المسبق أحكام"}, {"o": 58, "l": "المادة 7", "b": "المادة 7من هذا القانون.\n ُ .2تن َ\n شر الدعوة إلى التأهيل المسبق وفقاً للمادة 12من هذا القانون.\n .3تتضَّمن الدعوة إلى التأهيل المسبق ما يلي:\n أ .إسم الجهة الشارية وعنوانها؛\n ب .ملخصاً لأه ّ\n م الأحكام والشروط المطلوبة في عقد الشراء أو الاتفاق الإطاري الذي ُيبَرم في سياق\n اجراءات التلزيم ،يشمل طبيعة وكمية السلع الُمراد توريدها ومكان تسليمها ،أو طبيعة وموقع\n الأشغال الُمراد تنفيذها ،أو طبيعة الخدمات والمو ِ\n قع الذي ُيراد تقديمها فيه ،وكذلك تاريخ تسليم\n السلع أو إنجاز الأشغال أو تقديم الخدمات؛\n التخطيط\n الفعالّيـة والدمج في\n31 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\fج .المعايير والإجراءات التي ُتستخَدم للتأُّكد من مؤِّهلات العارضين ،وفقاً للمادة 7من هذا القانون؛ تكون\n هذه المعايير خاضعة لموافقة هيئة الشراء العام المسبقة.\n د .طريقة الحصول على ملفات التأهيل المسبق ومكان تسّلم هذه الملفات أو الاطلاع عليها؛\nهـ .كيفية ومكان تقديم طلبات التأُّهل المسبق والموعد النهائي لتقديمها ،وكذلك كيفية ومكان تقديم\n العروض والموعد النهائي لتقديمها ،إن كانت معروفًة آنذاك ،وفقاً للمادة 20من هذا القانون؛\n و .مكان وزمان )ُيحَّدد بالساعة واليوم والشهر والسنة( فض ملفات التأهيل المسبق؛\n ز .الِمهل التي يجب خلالها إبلاغ العارضين بنتائج التأهيل؛\n ح .أصول تبليغ العارضين نتائج التأّهل؛\n ط .كل المعلومات الإضافية التي تقّرر الجهة الشارية إدراجها في الدعوة.\nُ .4توِّفر الجهة الشارية مجموعة من وثائق التأهيل المسبق على موقعها الالكتروني إن ُوِجد وعلى المنصة\n الإلكترونّيـة المركزّيـة لدى هيئة الشراء العام بالتزامن مع نشر الدعوة.\n ُ .5تضَّمن وثائق التأهيل المسبق المعلومات التالية:\n أ .التعليمات الخاصة بإعداد طلبات التأُّهل المسبق وتقديمها؛"}, {"o": 59, "l": "المادة 7", "b": "ي أدّلة أو مستندات أو معلومات أخرى يجب أن يقّدمها العارضون لإثبات مؤهلاتهم؛\n ب .أ َّ\n ج .إسم واحد أو أكثر من موظفي الجهة الشارية أو مستخَدميها يكون مسؤو ً\nلا عن الاتصال مباشرة\nبالعارضين وبتلّقي اتصالات مباشرة منهم فيما يتعّلق بإجراءات التأهيل المسبق ،وكذلك الصفة\n الوظيفّيـة لذلك الموظف أو المستخَدم وعنوانه؛\nد .إحالات مرجعية إلى هذا القانون ومراسيمه التطبيقّيـة وسائر القوانين التي لها صلة مباشرة بإجراءات\n التأهيل المسبق ومراسيمها التطبيقّيـة؛\nهـ .ما قد تضعه الجهة الشارية وفقاً لهذا القانون من شروط أخرى بشأن إعداد طلبات التأُّهل المسبق وتقديمها\nوبشأن إجراءات التأهيل المسبق ،على أن لا تحّد هذه الشروط الإضافية من مشاركة العارضين المحتملين.\n َ .6تدُرس الجهة الشارية ملفات التأهيل لك ّ\nل عارض يقِّدم طلباً للتأُّهل المسبق ،وتقِّرر تأهيل العارضين الذين\nتتوّفر فيهم الشروط المطلوبة .لا ُتطِّبـق الجهُة الشارية ،عند اتخاذها قرارها ،سوى المعايير والإجراءات\n المنصوص عليها في الدعوة إلى التأُّهل المسبق وفي وثائق التأهيل.\nم تأهيلهم مسبقاً ،على أّلا\n ق الاستمرار في المشاركة في إجراءات التلزيم إلا للعارضين الذين ت ّ\n .7لا يح ّ\nتتجاوز الفترة الزمنّيـة التي تفصل ما بين تاريخ إعلان نتائج التأهيل المسبق والبدء بإجراءات التلزيم مهلة\n معقولة تتناسب مع أهمية المشروع وتعقيداته.\n م طلباً للتأُّهل المسبق بنتيجة تأُّهله سلباً أم ايجاباً. ُ .8تبِّلغ الجهة الشارية ك َّ\n ل عارض قَّد َ\n ُ .9تبِّلغ الجهة الشارية ك َّ\n ل عارض لم ُيؤَّهل بأسباب عدم تأُّهله.\n .10تضع هيئة الشراء بالإشتراك مع الجهات المعنية معايير التصنيف للصفقات المتشابهة وتصدرها بقرار\n تنظيمي.\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 32"}, {"o": 60, "l": "المادة 20", "b": "المادة | 20طريقة ومكان تقديم طلبات التأّهل المسبق و/أو العروض\n والموعد النهائي لتقديمها\n ُ .1تحَّدد طريقة ومكان تقديم طلبات التأُّهل المسبق والموعد النهائي لتقديمها في الدعوة إلى التأُّهل المسبق\n سل الغلافات التي تحتوي على العروض باليد أو بواسطة البريد العام أو الخاص المغفل\n وفي وثائق التأهيلُ .تر َ\n إلى الجهة المخَّولة استلامها .كما ُيحَّدد مكان تقديم العروض والموعد النهائي لتقديمها في ملفات التلزيم.\n .2تحاِفظ الجهة الشارية على أَمن الطلبات والعروض وسلامتها وسرّيـتها ،وتكفل عدم الاطلاع على محتواها\n إ ّ\n لا بعد فتحها وفقاً للأصول.\n ُ .3يعَّبر عن المهل الزمنّيـة لتقديم طلبات التأُّهل المسبق أو تقديم العروض بتاريخ معّين وساعة معّيـنة،\n ويجب أن ُتتيح تلك المهل للعارضين وقتاً كافياً لإعداد وتقديم طلباتهم أو عروضهم ،على أن ُيؤَخذ\n بالاعتبار حاجة الجهة الشارية وظروف التسليم.\n .4إذا أصَدَرت الجهة الشارية توضيحاً أو تعدي ً\n لا لوثائق التأهيل المسبق أو ملفات التلزيم ،يجب عليها أن\n ُتبادر ،قبل الموعد النهائي لتقديم الطلبات أو العروض ،إلى تمديد ذلك الموعد النهائي إذا اقتضت\n الضرورة أو على النحو المطلوب بمقتضى الفقرة - 4من أو ً\n لا -من"}, {"o": 61, "l": "المادة 21", "b": "المادة 21من هذا القانون ،بغية إتاحة\n وقت كاف للعارضين لأخذ الإيضاح أو التعديل بالاعتبار في طلباتهم أو عروضهم المقَّدمة.\n م تبليغ تمديد الموعد النهائي إلى كل عارض زَّودته الجهة الشارية بوثائق التأهيل المسبق أو بملفات\n .5يت ّ\n م نشر التمديد على المنصة الإلكترونّيـة المركزّيـة لدى هيئة الشراء العام.\n التلزيم ،كما يت ّ"}, {"o": 62, "l": "المادة 21", "b": "المادة | 21طلبات الاستيضاح\n أو ً\n لا :حول ملفات التلزيم وملفات التأهيل المسبق\n ق للعارض تقديم طلب استيضاح خ ّ\n طي حول ملفات التلزيم أو ملفات التأهيل المسَبق خلال مهلٍة .1يح ّ\n تنتهي قبل عشرة أيام من تاريخ تقديم العروض أو طلبات التأهيل المسَبق .على الجهة الشارية الإجابة\n سل\n خلال مهلة تنتهي قبل ستة أيام من الموعد النهائي لتقديم العروض أو طلبات التأُّهل المسبق .وُير َ\n مص ِ\n در الطلب ،إلى جميع العارضين الذين زّودتهم الإيضاح خطّيـاً ،في الوقت عينه ،من دون تحديد هوّيـة ُ\n الجهة الشارية بملفات التلزيم.\n ُ .2يمكن للجهة الشارية ،عند الاقتضاء ،تحديد موعد معَّين للعارضين المحتملين لمعاينة الموقع.\n ي ي وق ٍ\n ت قبل الموعد النهائي لتقديم العروض أو طلبات التأُّهل المسبق ،ولأ ِّ ُ .3يمكن للجهة الشارية ،في أ ِّ\n ب كان ،سواء بمبادرة منها أم نتيجًة لطلب استيضاح مقَّدم من أحد العارضين ،أن تعِّدل ملفات التلزيم\n سب ٍ\n سل التعديل فورا ً إلى جميع العارضين الذين زّودتهم\n أو ملفات التأهيل الُمسبق بإصدار إضافة إليها .وُير َ\n ملِزماً لهؤلاء العارضين\n الجهة الشارية بملفات التلزيم أو ملفات التأهيل المسبق ،ويكون ذلك التعديل ُ\n وُين َ\n شر على المنصة الإلكترونّيـة المركزّيـة لدى هيئة الشراء العام وعلى موقع الجهة الشارية إن ُوجد.\n ت المنشورة في ملفات التلزيم أو ملفات التأهيل المسَبق مختلفة جوهرياً ،نتيجًة\n .4إذا أصبحت المعلوما ُ\n لإيضاح أو تعديل صدر وفقاً لهذه المادة ،فعلى الجهة الشارية أن تؤ ِّ\n من نشر المعلومات المعَّدلة بالطريقة\n التخطيط\n الفعالّيـة والدمج في\n33 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\f نفسها التي ُن ِ\nشَرت بها المعلومات الأصلية وفي المكان نفسه ،وأن ُتَمِّدد الموعد النهائي لتقديم العروض\n أو طلبات التأُّهل المسبق على النحو المنصوص عليه في الفقرة 4من"}, {"o": 63, "l": "المادة 20", "b": "المادة 20من هذا القانون.\n .5إذا َعقدت الجهُة الشارية اجتماعاً للعارضين ،فعَليها أن تضع محضرا ً لذلك الاجتماع يتضَّمن ما ُيقَّدم فيه\nمن طلبات استيضاح حول ملفات التلزيم ،وما ُتقِّدمه هي من ردود على تلك الطلبات ،من دون تحديد\nهوية مصادر الطلباتُ .يبَّلغ المحضر لجميع العارضين الذين زَّوَدتهم الجهة الشارية بملفات التلزيم أو ملفات\nالتأهيل المسبق ،وذلك لتمكينهم من إعداد طلباتهم للتأهيل أو عروضهم على ضوء المعلومات المقدمة.\n ثانيًا :المعلومات المتعّلقة بالمؤِّهلات والعروض\nي مرحلة من مراحل إجراءات التلزيم ،أن تطلب خطياً من العارض إيضاحات\n .1يمكن للجهة الشارية ،في أ ِّ\nبشأن المعلومات المتعِّلقة بمؤهلاته أو بشأن عروضه ،لمساعدتها في التأُّكد من المؤّهلات أو فحص\n العروض المقَّدمة وتقييمها.\nي أخطاء حسابية محضة تكتشفها أثناء فحصها العروض المقَّدمة وفقاً لأحكام دفتر\n حح الجهُة الشارية أ َّ\n ُ .2تص ِّ\n الشروط ،وتبِّلغ التصحيحات إلى العارض المعني بشكل فوري.\nي تغيير جوهري في المعلومات المتعِّلقة بالمؤهلات أو بالعرض\n .3لا يمكن طلب إجراء أو السماح بإجراء أ ِّ\n لا من العارضين مؤَّه ً\nلا أو جعل عرض غير من ليس مؤَّه ً\n المقَّدم ،بما في ذلك التغييرات الرامية إلى جعل َ\n مستو ٍ\n ف للمتطلبات مستوفياً لها.\nي مفاوضات بين الجهة الشارية والعاِرض بخصوص المعلومات المتعّلقة بالمؤهلات أو\n .4لا يمكن إجراُء أ ِّ\nي تغيير في السعر إثر طلب استيضاح من أي عارض بموجب\n بخصوص العروض المقَّدمة ،ولا يجوز إجراء أ ِّ\n هذه المادة.\nُ .5تدَرج جميع المراسلات التي تجري بموجب هذه المادة في سجل إجراءات الشراء بحسب"}, {"o": 64, "l": "المادة 9", "b": "المادة 9من هذا\n القانون."}, {"o": 65, "l": "المادة 22", "b": "المادة | 22مدة صلاحية العرض\n .1تحِّدد ملفات التلزيم مدة صلاحية العرض على أن تكون متناسبة مع طبيعة الشراء ،على ألا تق ّ\nل عن\n ثلاثين يوماً من التاريخ النهائي لتقديم العروض.\n .2يمكن للجهة الشارية أن تطلب من العارضين ،قبل انقضاء فترة صلاحية عروضهم ،أن يمّددوا تلك الفترة\n لمدة إضافية محّددة .وُيمكن للعارض رفض ذلك الطلب من دون مصادرة ضمان عرضه.\n .3على العارضين الذين يوافقون على تمديد فترة صلاحية عروضهم أن يمِّددوا فترة صلاحية ضمانات\n العروض ،أو أن ُيقِّدموا ضمانات عروض جديدة ُتغ ّ\nطي فترة تمديد صلاحية العروض .وُيعتَبر العاِرض الذي\nلم ُيمِّدد ضمان عرضه ،أو الذي لم يقِّدم ضمان عرض جديد ،أنه قد َرَفض طلب تمديد فترة صلاحية عرضه.\n .4يمكن للعارض أن يعِّدل عرضه أو أن يسحبه قبل الموعد النهائي لتقديم العروض دون مصادرة ضمان\nعرضه .ويكون التعديل أو طلب سحب العرض ساري المفعول عندما تتسّلمه الجهة الشارية قبل الموعد\n النهائي لتقديم العروض.\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 34\n\f ُ .5تمَّدد صلاحية العرض حكماً في حال تجميد الاجراءات لفترة محَّددة من قبل هيئة الاعتراضات وفق أحكام\n الفصل السابع من هذا القانون ،وذلك لفترة زمنية تعادل فترة تجميد الاجراءات .وعلى العارض تمديد\n فترة ضمان عرضه تبعاً لذلك."}, {"o": 66, "l": "المادة 23", "b": "المادة | 23العروض المشتَركة\n يجوز أن يشترك في تنفيذ مشروع شراء واحد عدة مورّدين أو مقِّدمي خدمات أو مقاولين ممن تتوَّفر فيهم\n جـه إلى سلطة التعاقد\n الشروط الفنّيـة والقانونية من هذا القانون شرط أن يعِّينوا ،بموجب كتاب رسمي مو َّ\n ومن ضمن وثائق العرض المقَّدم ،شريكاً رئيسياً يمثّلهم مجتمعين بالتكافل والتضامن ويوِّقع باسمهم\n وتنصرف أعماُله إليهم.\n تحَّدد سائر شروط المشاركة المنصوص عليها في هذه المادة في ملفات التلزيم الخاصة بكل مشروع شراء."}, {"o": 67, "l": "المادة 24", "b": "المادة | 24قواعد قبول العرض الفائز )أو التلزيم المؤقت( وبدء تنفيذ العقد\n َ .1تقبل الجهُة الشارية العَرض المقَّدم الفائز ما لم:\n أُ .تسَقط أهلَّيـُة العارض الذي قَّدم العَرض الفائز وذلك بمقتضى"}, {"o": 68, "l": "المادة 7", "b": "المادة 7من هذا القانون؛ أو\n غ الشراء بمقتضى الفقرة 1من"}, {"o": 69, "l": "المادة 25", "b": "المادة 25من هذا القانون؛ أو\n بُ .يل َ\n جُ .يرَفض العرض الفائز عند اعتباره منخِفضاً انخفاضاً غير عادي بمقتضى"}, {"o": 70, "l": "المادة 27", "b": "المادة 27من هذا القانون؛ أو\n دُ .يستبَعد العارض الذي قَّدم العرض الفائز من إجراءات التلزيم للأسباب المبَّيـنة في"}, {"o": 71, "l": "المادة 8", "b": "المادة 8من هذا القانون.\n .2بعد التأُّكد من العرض الفائز ُتبلغ الجهة الشارية العارض الذي قَّدم ذلك العرض ،كما تنشر بالتزامن قرارها\n بشأن قبول العرض الفائز )التلزيم المؤقت( والذي يدخل حّيـز التنفيذ عند انتهاء فترة التجميد البالغة عشرة\n أيام عمل تبدأ من تاريخ النشر ،الذي يجب أن يتضَّمن على الأق ّ\n ل ،المعلومات التالية:\n أ .إسم وعنوان العارض الذي قَّدم العرض الفائز )الملتزم المؤقت(؛\n ب .قيمة العرض ،ويمكن إضافة ملخص لسائر خصائص العرض الفائز ومزاياه النسبية إذا كان العرض\n م تأكيده على أساس السعر ومعايير أخرى؛\n الفائز قد ت ّ\n ج .مدَة فترة التجميد بحسب هذه الفقرة.\n .3لا ُتطَّبـق فترة التجميد في الحالات التالية:\n أ .في العقود اللاحقة لاتفاقات الاطار غير المنطوية على تنافس في مرحلة ثانية والتي تتم بموجب\n هذه الاتفاقات؛\n ب .عند الشراء بالفاتورة؛\n ج .عند الشراء بالتراضي تطبيقاً للفقرتين 2و 4من"}, {"o": 72, "l": "المادة 46", "b": "المادة 46من هذا القانون.\n .4فور انقضاء فترة التجميد ,تقوم الجهة الشارية بإبلاغ الملتزم المؤقت بوجوب توقيع العقد خلال مهلة لا\n تتعّدى //15//خمسة عشر يوماً.\n التخطيط\n الفعالّيـة والدمج في\n35 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\f .5يوِّقع المرجع الصالح لدى الجهة الشارية العقد خلال مهلة //15//خمسة عشر يوماً من تاريخ توقيع العقد\nقَبل الملتزم المؤّقت .يمكن أَن ُتمَّدد هذه المهلة إلى //30//ثلاثين يوماً في حالات معَّيـنة تحَّدد من\n من ِ\n قبل المرجع الصالح.\n .6يبدأ نفاذ العقد عندما يوِّقع الملتزم المؤّقت والمرجع الصالح لدى سلطة التعاقد عليه.\nي إجراٍء يتعارض مع بدء نفاذ العقد أو مع تنفيذ الشراء خلال\n .7لا تَّتخذ سلطة التعاقد ولا الملتزم المؤّقت أ َّ\n الفترة الزمنّيـة الواقعة ما بين تبليغ العارض المعني بالتلزيم المؤقت وتاريخ بدء نفاذ العقد.\n .8في حال تمُّنع الملتزم المؤقت عن توقيع العقدُ ،تصاِدر الجهة الشارية ضمان عرضه .في هذه الحالة يمكن\nللجهة الشارية أن ُتلغي الشراء أو أن تختار العرض الأفضل من بين العروض الأخرى الفائزة وفقاً للمعايير\nوالاجراءات المحَّددة في هذا القانون وفي ملفات التلزيم ،والتي لا تزال صلاحيتها سارية المفعول.\n ُتطَّبق أحكام هذه المادة على هذا العرض بعد إجراء التعديلات اللازمة.\n ي من اجراءاته"}, {"o": 73, "l": "المادة 25", "b": "المادة | 25إلغاء الشراء و/أو أ ّ\nي وقت قبل إبلاغ الملتزم المؤقت إبرام\n ي من إجراءاته في أ ِّ\n .1يمكن للجهة الشارية أن ُتلغي الشراء و /أو أ ّ\n العقد ،في الحالات التالية:\nأ .عندما تجد الجهة الشارية ضرورة إحداث تغييرات جوهرية غير متوَّقعة على ملفات التلزيم بعد الإعلان\n عن الشراء؛\n ب .عندما َتطرأ تغييرات غير متوَّقعة على موازنة الجهة الشارية؛\n ج .عندما تنتفي الحاجة لموضوع الشراء نتيجة ظرو ٍ\nف غير متوَّقعة وموضوعية وعندها لا ُيعاد التلزيم خلال\n الموازنة أو السنة المالّية نفسها.\n ي عرض و/أو ُقِّدمت عروض غير مقبولة.\n ي من إجراءاته إذا لم يقَّدم أ ّ\n .2كما يمكنها إلغاء الشراء و/أو أ ّ\nي من إجراءاته بعد قبول العرض المقَّدم الفائز في الحالة\n .3كما ُيمكن للجهة الشارية أن ُتلغي الشراء و/أو أ ّ\n الُمشار إليها في الفقرة 8من"}, {"o": 74, "l": "المادة 24", "b": "المادة 24من هذا القانون.\nق لها اّتخاذ\n ي من إجراءاته في حالة العرض الوحيد المقبول ،غير أنه يح ّ\n ُ .4تلغي الجهة الشارية الشراء و/أو أ ّ\n قرار معَّلل بالتعاقد مع مقِّدم العرض الوحيد المقبول إذا توافرت الشروط التالية مجتمعة:\nمطَّبـقة وأن لا يكون العرض الوحيد ناتجاً عن شروط حصرية\n أ .أن تكون مبادىء وأحكام هذا القانون ُ\n َتضَّمَنها دفتر الشروط الخاص بمشروع الشراء؛\n سِجماً مع دراسة القيمة التقديرية؛\n من َ مِل ّ\n حة والسعر ُ ب .أن تكون الحاجة أساسية و ُ\nصاً صريحاً ِبتقُّدم العارض\n ج .أن يتضَّمن َنشر قرار الجهة الشارية بقبول العرض الفائز )التلزيم المؤقت( ن ّ\n الوحيد المقبول ونّيـة التعاُقد معه.\n ب ذلك القرار في سج ّ\nل إجراءات الشراء، ي من إجراءاته وأسبا ُ\n ُ .5يدَرُج قراُر الجهة الشارية بإلغاء الشراء و/أو أ ّ\n ل العارضين المشاركين ضمن مهلة لا تتخ ّ\nطى الخمسة أيام من تاريخ قرار الإلغاء. م إبلاغه إلى ك ّ\n ويت ّ\nت إضافًة إلى ذلكَ ،تنشر الجهة الشارية إشعارا ً بإلغاء الشراء بنفس الطريقة التي ُن ِ\nشرت بها المعلوما ُ\nالأصلية المتعِّلقة بإجراءات التلزيم وفي المكان نفسه ،وُتعيد العروض والاقتراحات التي لم ُتفَتح لحين\n اّتخاذ قرار الإلغاء إلى العارضين الذين قّدموها كما َتعمد إلى تحرير الضمانات المقَّدمة.\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 36\n\f .6لا تتحَّمل الجهُة الشارية ,عند تطبيق الفقرة 1و 2من هذه المادة أ َّ\n ي َتبعة تجاه العارضين.\n .7لا َتفتح الجهة الشارية أّيـة عروض أو اقتراحات بعد اّتخاذ قراٍر بإلغاء الشراء."}, {"o": 75, "l": "المادة 26", "b": "المادة | 26قواعد الإعلان عن إرساء التلزيم\n َ .1تنشر الجهة الشارية إعلاناً بإرساء التلزيم أو الاتفاق الإطاري ،وذلك عندما َيبدأ نفاذ العقد أو ُيبَرم اتفا ٌ\n ق\n إطاريُ ،يحَّدد فيه إسم الُملتزم وقيمة العقد.\n ل قيمتها عن السق ِ\n ف المالي المحَّدد في شروط استخدام .2لا ُتطَّبق الفقرُة 1على تلزيم العقود التي تق ّ\n ن على الجهة الشارية أن َتنشر ,مرة في السنة على الأقل ,إعلاناً جامعاً لك ّ\n ل طريقة الشراء بالفاتورة .إّلا أ ّ\n ما أ ُرسي من عقود من هذا القبيل .كما لا ُتطَّبق الفقرة 1على تلزيم العقود التي َتّتسم بالسرية\n والمتعِّلقة بالأمن والدفاع الوطني بحسب الفقرة 4من المادة .46\n ُ .3تن َ\n شر المعلومات المنصوص عليها في هذه المادة على الموقع الالكتروني للجهة الشارية إن ُوجد ،وعلى\n المنصة الإلكترونّية المركزّية لدى هيئة الشراء العام."}, {"o": 76, "l": "المادة 27", "b": "المادة | 27قواعد بشأن العروض المنخفضة الأسعار انخفاضًا غير عاديًا\n مقترناً بسائر العناصر المكِّونة لذلك العرض\n ن السعرُ ،\n ي عرض إذا قَّرَرت أ َّ\n .1يجوز للجهة الشارية أن ترفض أ َّ\n ي قياساً إلى موضوع الشراء وقيمته التقديرية ،وأنه يثير الشك لديها\n منخفض انخفاضاً غير عاد ّ\n المقَّدمُ ،\n بشأن قدرة العارض على تنفيذ العقد ،وذلك شرط أن تكون الجهة الشارية قد طلبت من العارض المعني\n خ ط ي اً ت ف ا ص ي َ\n ل العرض المقَّدم بشكل يسمح لها بتحليل المعلومات التفصيلية واستنتاج ما إذا كان العاِرض\n سيكون قادرا ً على تنفيذ عقد الشراء بالسعر المقَّدم .من التفاصيل التي يمكن أن تطلبها الجهة الشارية،\n على سبيل المثال لا الحصر:\n أ .معلومات وعِّينات أو ما ُيشابههاُ ،تثبت جودة موضوع الشراء المقَّدم في العرض؛\n بُ .\n طرق التصنيع ذات الصلة؛\n متاحة للعاِرض لتنفيذ العقد موضوع\n مؤاتية بشكل استثنائي ُ\n ي شروط ُ\n ج .الحلول التقنية المختارة و/أو أ ّ\n الشراء.\n ُ .2يدَرُج في تقرير التقييم قراُر الجهة الشارية ِبَرفض عرض ما وفقاً لأحكام هذه المادة ،وأسبا ُ\n ب ذلك القرار\n ل الايضاحات التي جرت مع العارضين .وُيبَّلغ العارض المعني ،على الفور ،بقرار الجهة الشارية وأسبابه.\n وك ُّ"}, {"o": 77, "l": "المادة 28", "b": "المادة | 28مواقع العمل\n لا يجوز إطلاق إجراءات شراء تتعّلق بتنفيذ أشغال إّلا بعد إتمام جميع الإجراءات القانونية من قبل الجهة\n الشارية المتعِّلقة بَتهِيئة مواقع العمل بما فيها ُ\n صدور قرارات وضع اليد.\n التخطيط\n الفعالّيـة والدمج في\n37 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\f البند الثالث | تنفيذ العقد"}, {"o": 78, "l": "المادة 29", "b": "المادة | 29قيمة العقد وشروط تعديلها\n .1تكون البدلات المَّتفق عليها في العقد ثابتة ولا َتقبل التعديل والمراجعة إلا عند إجازة ذلك أثناء تنفيذه\nضمن ضوابط محَّددة وفقاً لشروط التعديل والمراجعة في الحالات الاستثنائية التالية ،على أن يكون\n منصوص عليها صراحة في ملفات التلزيم:\nأ .تطبيقاً لمعادلات َتسَتنِد إلى مؤشرات أسعار رسمية محلية وعند الإقتضاء دولّيـة عندما لا تكون هذه\n مغطّاة ضمن قيمة العقد؛\n المعادلات ُ\n ب .تطبيقاً لتعديلات ضريبية ُتؤدي إلى زيادة تكلفة تنفيذ العقد؛\nج .عندما َتبرز الحاجة إلى كميات إضافية لأشغال أو سلع أو معدات أو تكنولوجيا أو خدمات من نفس\nالمورّد أو المقاول ،لأسباب تتعلَّق بتوحيد المواصفات أو بسبب الحاجة إلى التوافق مع السلع أو\nالمعدات أو التكنولوجيا أو الخدمات أو الأشغال الموجودة ،مع الأخذ في الاعتبار فعالّيـة عملية الشراء\nالأصلية في تلبية احتياجات الجهة الشارية ،وعلى أّلا تتخطى قيمة الإضافة %20من قيمة العقد\n الأساسي لعقود اللوازم والخدمات و %15لعقود الأشغال؛\n د .في الحالة المنصوص عليها في الفقرة 3من"}, {"o": 79, "l": "المادة 46", "b": "المادة 46؛\nهـ .عندما تصُدر قوانين أو مراسيم من شأنها التأثير على قيمة العقد ،وعلى أن ُيعلَّـل ذلك بموجب تقرير\n من الجهة الشارية.\n ُ .2تراعى شروط الإعلان المنصوص عليها في"}, {"o": 80, "l": "المادة 26", "b": "المادة 26من هذا القانون عند تعديل قيمة العقد."}, {"o": 81, "l": "المادة 30", "b": "المادة | 30التعاقد الثانوي\n .1يجب على الملتِزم الأساسي أن يتولّى بنفسه تنفيذ العقد ويبقى مسؤولاً تجاه سلطة التعاقد عن تنفيذ\n جميع بنوده وشروطه ،وُيمنع عليه تلزيم كامل موجباته التعاقدية لغيره.\n .2في عقود الأشغال والخدمات ,وفي حال أَجاز دفتر الشروط الخاص ذلكُ ,يمكن أن َيعهد الملتزم إلى\nمتعاقد ثانوي تنفيذ جزءٍ من العقد ضمن النسبة المسموح بها والمنصوص عليها في دفتر الشروط\n ُ\nالخاص والتي يجب أّلا تتخطّى %50من قيمة العقد .على الملتزم أَخذ الموافقة الُمسبقة على التعاقد\nالثانوي من سلطة التعاقد التي يجب عليها اّتخاذ قرارها بالموافقة أو الرفض المعلَّل خلال مهلة زمنية\n ُتحَّدد في شروط العقد ،وُيَعّد سكوتها عند انقضاء هذه المهلة قرارا ً ضمنياً بالقبول.\n ُ .3تطَّبق على المتعاقد الثانوي أحكام البند “أولاً” من المادة السابعة من هذا القانون.\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 38"}, {"o": 82, "l": "المادة 31", "b": "المادة | 31الإشراف على التنفيذ والكشوفات\n أو ً\n لا :الإشراف\n .1في عقود الأشغال ،وفي العقود الأخرى التي تستدعي ذلك كعقود الخدمات والتصنيع لمصلحة سلطة\n التعاقدُ ،يطَّبق الإشراف الُمتلازم مع تنفيذ الأعمال المطلوبة بالشكل الذي َيضَمن استمرارية العمل\n وتحقيقه المواصفات المطلوبة والنتائج المرجّوة قبل حلول موعد الاستلام المؤقت.\n من ُتكِّلفه سلطة التعاقد بذلك من ذوي الاختصاص والخبرة والقدرة على متابعة العمل،\n .2يتوّلى الإشراف َ\n وفق أحكام هذا القانون.\n من داخل سلطة التعاقد ،أو خارجها عند الاقتضاء ،وعندها َيجري التعاقد مع الُمشِرف ِ\n ُ .3توضع بنتيجة الإشراف تقارير دورية عن سير العمل وَوصف التنفيذ ،وعلى الُمشرف إبلاغ سلطة التعاقد\n منطبق على الأصول ينَّفذ في مواقع العمل. بك ّ\n ل مخالفة أو تصُّرف غير ُ\n من صحة واستمرارية العمل ،كما يدِّقق في الكشوفات وَيحضر\n َ .4يحضر الُمشرف إلى مواقع العمل بصورة تؤ ِّ\n عملية تسليم مواقع العمل والاستلام المؤقت والنهائي ،وُيبدي رأيه باقتراحات الُملتزم وبالتعديلات\n سب ،وَيرفع تقريرا ً بذلك إلى\n المطلوبة على الأعمال الملَّزمة ،وَيقترح الملائم لتنفيذ العمل بطريقة أن َ\n سلطة التعاقد لتأخذ القرار المناسب.\n .5يتحّمل من يتوّلى الإشراف على الأعمال مسؤوليًة شخصيًة عن أ ّ\n ي تقصير في الموجبات الملقاة على\n عاتقه بموجب هذه المادة وَيَتعَّرض للعقوبات المنصوص عليها في الفصل الثامن من هذا القانون.\n ثانيًا :الكشوفات\n يجب أن ُيحَّدد في شروط العقد ما يلي:\n ُ .1وجوب تقديم الُملتزم كشوفات السلع أو الخدمات أو الأعمال المنَّفذة على اختلافها ووجوب تصديقها\n من قبل سلطة التعاقد.\n .2المهلة القصوى الُمعطاة للملتِزم لإعداد هذه الكشوفات و ِ\n مهل الموافقة عليها أو تعديلها من قبل\n سلطة التعاقد.\n .3المهلة القصوى لإصدار أمر الدفع."}, {"o": 83, "l": "المادة 32", "b": "المادة | 32تنفيذ العقد والاستلام\n َ .1تسَتِلم اللوازم والأشغال والخدمات لجنة الاستلام المنصوص عليها في"}, {"o": 84, "l": "المادة 101", "b": "المادة 101من هذا القانون\n وُتقِّدم تقريرها خلال مدة زمنية أقصاها ثلاثين يوماً َتبدأ من تاريخ تقديم طلب الاستلام من ِ\n قـَبـل الملتزم.\n َ .2تسَتـِلم الخدمات الاستشارية الجهة الُمشِرفة على تنفيذ العقد ،في حال وجودها.\n .3في حال َتطَّلَبت طبيعة المشروع وحجمه مدة تتجاوز الثلاثين يوماً ،على اللجنة تبرير أسباب ذلك خ ّ\n طياً\n ووضع اقتراحاتها بهذا الشأن ،على أّلا تتجاوز المهلة في جميع الأحوال الستين يوماً َتبدأ من تاريخ تقديم\n طلب الاستلام من ِ\n قَبـل الملتزم.\n ُ .4تذكر مهلة الاستلام في شروط العقد.\n َ .5يجري الاستلام وفقاً للمادة 101من هذا القانون.\n التخطيط\n الفعالّيـة والدمج في\n39 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية"}, {"o": 85, "l": "المادة 33", "b": "المادة | 33أسباب انتهاء العقد ونتائجه\n أو ً\n لا :النكول\nلا إذا خاَلف شروط تنفيذ العقد أو أحكام دفتر الشروط ،وبعد إنذاره رسمياً بوجوب التقيُّد\n ُ .1يعتبر الملتِزم ناك ً\nبكاّفة موجباته من قبل سلطة التعاقد ،وذلك ضمن مهلة تتراوح بين خمسة أيام كحٍّد أدنى وخمسة عشر\n يوماً كحٍّد أقصى ،وانقضاء المهلة هذه دون أن َيقوم الُملتزم بما ُ\n طلب إليه.\nلا إّلا بموجب قرار معَّلل َيصدر عن سلطة التعاقد بناًء على موافقة هيئة الشراء\n .2لا يجوز اعتبار الُملتزم ناك ً\n العام.\n لاُ ،يفسخ العقد حكماً دون الحاجة إلى أ ِّ\nي إنذار ،وُتطَّبق الإجراءات المنصوص عليها في .3إذا اعُتبر الملتزم ناك ً\n الفقرة الأولى من البند الرابع من هذه المادة.\n ثانيًا :الإنهاء\n .1ينتهي العقد حكماً دون الحاجة إلى أ ّ\n ي إنذار في الحالتين التاليتين:\n أ .عند وفاة الملتزم إذا كان شخصاً طبيعياً ،إ ّ\nلا إذا وافقت سلطة التعاقد على طلب مواصلة التنفيذ من\n قبل الورثة.\nحَّلت الشركة ،وُتطَّبق عندئذ الإجراءات المنصوص عليها في\n سرا ً أو ُ مفلساً أو ُ\n مع َ ب .إذا أصَبح الُملتزم ُ\n الفقرة الثانية من البند الرابع من هذه المادة.\nي من إلتزاماته التعاقدية بنتيجة القوة القاهرة.\n َ .2يجوز لسلطة التعاقد إنهاء العقد إذا تعّذر على الملتزم القيام بأ ّ\n ثالثًا :الفسخ\n ي من الحالات التالية: ُ .1يفسخ العقد حكماً دون الحاجة إلى أ ّ\n ي إنذار في أ ٍّ\nي جرم من جرائم الفساد أو التواطؤ أو الإحتيال أو الغش أو\n ي ب ارتكاب أ ّ\n م نهائ ّ\n ق الُملتزم حك ٌ\n أ .إ ذ ا ص َد َر ب ح ّ\nتبييض الأموال أو تمويل الإرهاب أو تضارب المصالح أو التزوير أو الإفلاس الإحتيالي ،وفقاً للقوانين\n المرعية الاجراء؛\n ي حالة من الحالات المذكورة في"}, {"o": 86, "l": "المادة 8", "b": "المادة 8من هذا القانون؛\n ب .إذا تحَّقَقت أ ّ\n ج .في حال ُفقدان أهلية الملتزم.\n .2إذا ُف ِ\nسخ العقد لأحد الأسباب المذكورة في الفقرة الأولى من هذا البند ُتطَّبق الإجراءات المنصوص عليها\n في الفقرة الأولى من البند الرابع من هذه المادة.\n رابعًا :نتائج انتهاء العقد\n .1في حال تطبيق إحدى حالات النكول أو الفسخ المحَّددة في هذه المادةَ ،تعمد سلطة التعاقد إلى إعادة\nالتلزيم وفقاً للأصول المنصوص عليها في هذا القانون أو ُتنّفذها بنفسها إذا كان لديها المؤهلات\nي نوع من أنواع التعاقد .فإذا أَسَفر التلزيم الجديد أو التنفيذ عن\n والقدرات الكافية لذلك دون اللجوء إلى أ ّ\nوفٍر في الأكلاف ،عاد الوفر إلى الخزينة ،وإذا أسفر عن زيادة في الأكلاف ،رجعت سلطة التعاقد على\n ِ\n الملتزم الناكل بالزيادة .في جميع الأحوال يصاَدر ضمان حسن التنفيذ مؤقتاً إلى حين تصفية التلزيم.\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 40\n\f .2في حال تحَّقَقت حالة إفلاس الملتزم أو إعسارهُ ،تَّتبع فورا ً ،خلافاً لأ ّ\n ي نص آخر ،الإجراءات التالية:\n أُ .يصاَدر ضمان حسن التنفيذ مؤّقتاً لحساب الخزينة؛\n ب .تحصي سلطة التعاقد الأشغال أو اللوازم أو الخدمات المنَّفذة أو المواد الُمَّدخرة قبل تاريخ إعلان\n الإفلاس وُتن ِّ\n ظم بها كشفاً تصرف قيمته مؤقتاً أمانة بإسم الخزينة؛\n جَ .تعمد سلطة التعاقد إلى إعادة التلزيم وفقاً للأصول المنصوص عليها في هذا القانون أو ُتنّفذها\n ي نوع من أنواع التعاقد ،فإذا\n بنفسها إذا كان لديها المؤّهلات والقدرات الكافية لذلك دون اللجوء إلى أ ّ\n وفر إلى الخزينة ،وُيدفع ضمان حسن أَسفر التلزيم الجديد أو التنفيذ عن ِ\n وفٍر في الأكلاف ،يعود ال ِ\n التنفيذ وقيمة الكشف المبَّين في الفقرة السابقة إلى وكيل التفليسة .وإذا أسفرت عن زيادة في\n الأكلافُ ،تقَت َ"}, {"o": 87, "l": "المادة 8", "b": "طع الزيادة من الضمان وقيمة الكشف المذكور وُيدَفع الباقي إلى وكيل التفليسة .وإذا\n لم َيك ِ\n ف ذلك لتغطية الزيادة بكاملهاُ ،يكتفى بقيمة الضمان والكشف.\n .3في حال وفاة الملتزم وعدم متابعة التنفيذ من قبل الورثةُ ,تستَلم الأعمال أو الخدمات المنَّفذة أو السلع\n المقَّدمة ,وُتصَرف قيمة مستحقاته باسم الَوَرثة.\n ي من الجرائم\n ي تعويض عن الخدمات الُمقَّدمة أو الأشغال المنَّفذة من قبل من يثبت قيامه بأ ٍّ\n .4لا يترَّتب أ ّ\n المنصوص عليها في الفقرة الفرعية “أ” من الفقرة الأولى من “ثالثاً” من هذه المادة.\n ُ .5ينشر قرار انتهاء العقد وأسبابه على الموقع الالكتروني لسلطة التعاقد إن ُوِجد وعلى المنصة الإلكترونّيـة\n المركزّيـة لدى هيئة الشراء العام.\n البند الرابع | الأمور المالّيـة والضمانات"}, {"o": 88, "l": "المادة 34", "b": "المادة | 34ضمان العرض\n حَّدد ضمان العرض بمقدار َيضمن جّدية العارض وَيأخذ بالاعتبار قيمة مشروع الشراء وأهميته دون أن َيحّد\n ُ .1ي َ\n من المنافسة ,على أن يكون مقطوعاً وأّلا يتعّدى الثلاثة بالمئة من القيمة التقديرية لمشروع الشراء.\n حَّددا ً .2لا يكون ضمان العرض إلزامياً لمشاريع الشراء التي لا تتجاوز قيمتها التقديرية سقفاً مالياً ُ\n م َ\n بـ //2.500.000.000//مليارين وخمسمائة مليون ليرة لبنانيةُ .يعَّدل هذا السقف المالي بناًء على توصية\n خذ في مجلس الوزراء بناًء على اقتراح رئيسه ،على أّلا يؤدي\n من هيئة الشراء العام وبموجب مرسوم ُيَّت َ\n التعديل إلى مخالفة أهداف هذه المادة والمبادئ التي كَّرسها هذا القانون.\n .3لا يكون ضمان العرض إلزامياً في حالات التعاقد الرضائي المنصوص عليها في"}, {"o": 89, "l": "المادة 46", "b": "المادة 46من هذا\n القانون.\n ُ .4تحَّدد صلاحية ضمان العرض بإضافة //28//ثمانية وعشرين يوماً على صلاحية العرض.\n س عليهم\n ُ .5يعاد ضمان العرض إلى الملتزم عند تقديمه ضمان حسن التنفيذ ،وإلى العارضين الذين لم ير ُ\n التلزيم في مهلة أقصاها بدء نفاذ العقد.\n التخطيط\n الفعالّيـة والدمج في\n41 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية"}, {"o": 90, "l": "المادة 35", "b": "المادة | 35ضمان حسن التنفيذ\n ُ .1يحَّدد مبلغ ضمان حسن التنفيذ بنسبة مئوية لا تزيد عن عشرة بالمائة من قيمة العقد.\nُ .2تعفى من ضمان حسن التنفيذ العقود المبرمة بحسب حالات التعاقد الرضائي المنصوص عليها في\n الفقرة 5من"}, {"o": 91, "l": "المادة 46", "b": "المادة 46من هذا القانون وفي حالات الشراء بالفاتورة.\n .3يجب تقديم ضمان حسن التنفيذ خلال الفترة المحّددة في شروط العقد على أّلا تتجاوز //15//خمسة عشر\n يوماً من تاريخ نفاذ العقد .وفي حال التخُّلف عن تقديم ضمان حسن التنفيذُ ،يصاَدر ضمان العرض."}, {"o": 92, "l": "المادة 36", "b": "المادة | 36طريقة دفع الضمانات\nيكون ضمان العرض كما ضمان حسن التنفيذ إما نقدياً ُيدفع إلى صندوق الخزينة أو إلى صندوق سلطة\nالتعاقد ،وإما بموجب كتاب ضمان مصرفي غير قابل للرجوع عنه ،صادر عن مصرف مقبول من مصرف لبنان\n ُيبِّين أنه قابل للدفع غب الطلب."}, {"o": 93, "l": "المادة 37", "b": "المادة | 37دفع قيمة العقد\n ُ .1تدفع قيمة العقد بعد تنفيذه وفقاً لأحكام"}, {"o": 94, "l": "المادة 5", "b": "المادة 5من هذا القانون.\n .2\nأُ .تحِّدد شروط العقد طريقة الدفع بحسب مراحل التنفيذ أو بحسب الُمنجزات ،على أن تتناسب الدفعات\nمع الُمنجزات ،وعلى ألا تتجاوز تسعة أعشار المبلغ المستحق ،ويبقى العشر موقوفاً في الخزينة إلى\n م الاستلام النهائي.\n أ ن يت ّ\nبُ .ترّد هذه التوقيفات عند الاستلام النهائي إذا كان العقد لا يحِّدد مدة لضمان اللوازم أو الأشغال أو\nف عن اقتطاع التوقيفات العشرية عندما تغطي الضمانات\n الخدمات .ويمكن لسلطة التعاقد أن تك ّ\nق لها استبدال التوقيفات العشرية بضمانة موازية.\n الُمعطاة مخاطر ما تبّقى من تنفيذ العقد .كما يح ّ\nج .عند تسديد الدفعات وفقاً لأحكام هذه الفقرة يجب الأخذ بالاعتبار حسم المبالغ الضرورية لتسديد\n الدفعات على الحساب المشار إليها في الفقرة 3ادناه.\n .3\n أُ .يمكن أن ُيجيز العقد لسلطة التعاقد إعطاء الملتزم سلفات لا تتخ ّ\nطى //20//عشرين بالمئة من قيمة\nمحَّددا ً بخمسة مليارات ليرة لبنانيةُ .يعَّدل هذا السقف\n ي حال سقفاً مالياً ُ\n العقد على ألا تتجاوز في أ ّ\nالمالي بناًء على توصية من هيئة الشراء العام وبموجب مرسوم ُيَّتخذ في مجلس الوزراء بناًء على\nاقتراح رئيسه ،على أّلا يؤدي التعديل إلى مخالفة أهداف هذه المادة والمبادىء التي كّرسها هذا\nصت شروط\n القانون .يمكن لسلطة التعاقد ،عند تجاوز النسبة المحَّددة في هذه الفقرة ،وفي حال ن َّ\n العقد على ذلك ،إعطاء الملتزم سلفات لقاء كفالات مصرفية ،وذلك بعد إبلاغ هيئة الشراء العام.\n بُ .تعاد الكفالة المصرفية الُمشار إليها في هذه الفقرة إلى الملتزم عند حسم كامل مبالغ السلفات.\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 42"}, {"o": 95, "l": "المادة 38", "b": "المادة | 38الغرامـات\n جب على الملتزم التقُّيد بالمهل المحَّددة في العقد تحت طائلة دفع الغرامات المحَّددة فيه.\n يتو ّ\n ل حكمي على الملتزم بُمجّرد مخالفته أحكام العقد دون حاجة لإثبات الضرر.\n ُتفرض الغرامات بشك ٍ"}, {"o": 96, "l": "المادة 39", "b": "المادة | 39الاقتطاع من الضمان\n إذا ترّتب على الملتزم في سياق التنفيذ مبلغ ما ،تطبيقاً لأحكام وشروط العقد ،ح َّ\n ق لسلطة التعاقد اقتطاع\n هذا المبلغ من ضمان حسن التنفيذ ودعوة الملتزم إلى إكمال المبلغ ضمن مّدة معَّينة ،فإذا لم يفعل اعُتبِر\n لا وفقاً لأحكام البند “أو ً\n لا” من"}, {"o": 97, "l": "المادة 33", "b": "المادة 33من هذا القانون. ناك ً"}, {"o": 98, "l": "المادة 40", "b": "المادة | 40الإقصـاء\n لا” من المادة ُ ،33يقصى عن المشاركة في الشراء العام ن الملتزم الذي ُيعَتبر ناِك ً\n لا وفقاً للبند “أو ً .1إ ّ\n وذلك:\n أ .لمدة سنة كاملة عند تطبيق هذه الإجراءات عليه للمرة الأولى تبدأ من تاريخ نشر قرار الإقصاء الأول؛\n ب .لمدة سنتين عند تطبيقها عليه لمرة ثانية تبدأ من تاريخ نشر القرار الثاني القاضي بالإقصاء؛\n ج .لمدة خمس سنوات عند تطبيقها عليه للمرة الثالثة أو أكثر.\n م قضائي نهائي يتعّلق بإحدى\n ُ .2يقصى حكماً عن الاشتراك في الشراء العام الُملتزم الذي َيصُدر بحقه حك ٌ\n حالات الفسخ المحَّددة في"}, {"o": 99, "l": "المادة 33", "b": "المادة 33من هذا القانون.\n ُ .3تبِّلغ سلطة التعاقد قرار الإقصاء إلى الملتزم المقصى .كما ُين َ\n شر قرار الإقصاء على المنصة الإلكترونّيـة\n المركزّيـة لدى هيئة الشراء العام وعلى الموقع الالكتروني لسلطة التعاقد إن ُوِجد.\n ن زوال المانع أو إعادة الاعتبار ُيعيدان للعارضين حق المشاركة.\n .4إ ّ\n .5على هيئة الشراء العام تحديث سجل الإقصاء على المنصة الإلكترونّيـة المركزّيـة لديها وشطب أسماء\n الملتزمين الُمستعادة شروط اشتراكهم في عقود الشراء العام عفوا ً أو بناًء على طلبهم.\n .6يمكن الطعن بقرارات الإقصاء أمام مجلس شورى الدولة.\n التخطيط\n الفعالّيـة والدمج في\n43 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\f الفصل الثـالث | طـرق الشراء"}, {"o": 100, "l": "المادة 41", "b": "المادة | 41طرق الشراء\n .1يمكن للجهة الشارية ان تقوم بالشراء بواسطة:\n وفقاً لأحكام"}, {"o": 101, "l": "المادة 42", "b": "المادة 42والبند الثاني من هذا الفصل، المناقصة العمومية\n وفقاً لأحكام المادتين 42و 43والبند الثالث من هذا الفصل، المناقصة على مرحلتين\n وفقاً لأحكام المادتين 42و 44والبند الرابع من هذا الفصل، طلب عروض الأسعار\n طلب الاقتراحات للخدمات الاستشارية وفقاً لأحكام المادتين 42و 45والبند الخامس من هذا الفصل،\n وفقاً لأحكام المادتين 42و 46والبند السابع من هذا الفصل، الاتفاق الرضائي\n وفقاً لأحكام المادتين 42و 47والبند السادس من هذا الفصل. الشراء بالفاتورة\n .2كما يمكن للجهة الشارية أن تقوم بإجراءات اتفاق إطاري وفقاً لأحكام البند الثامن من هذا الفصل."}, {"o": 102, "l": "المادة 42", "b": "المادة | 42القواعد العامة التي تطَّبق على اختيار طريقة الشراء\n .1يجري الشراء العام بصورة أساسية بواسطة المناقصة العمومية ,غير أنه َيجوز في الحالات المنصوص\n عليها في المواد 43إلى 48اعتماد طرق الشراء الأخرى عند توُّفر شروطها.\n .2في حال تعَّذر اعتماد المناقصة العمومية لعدم توُّفر شروطها واختيار طريقة أخرى ،على الجهة الشارية\n السعي إلى زيادة التنافس إلى أقصى حّد ممكن.\nدر قرارا ً صريحاً ومعَّللاً\n مت طريقة شراء أخرى غير المناقصة العمومية أن ُتص ِ\n .3على الجهة الشارية إذا استخَد َ\nن بالأسباب والظروف التي\n م إدراجه في السجل المنصوص عليه في"}, {"o": 103, "l": "المادة 9", "b": "المادة 9من هذا القانون مع بيا ٍ\n يت ّ\n استندت إليها في تبرير استخدام تلك الطريقة.\n البند الأول | شروط استخدام طرق الشراء"}, {"o": 104, "l": "المادة 43", "b": "المادة | 43شروط استخدام المناقصة على مرحلتين\nوفقاً للبند الثالث من هذا الفصل\n َ .1يجوز للجهة الشارية أن َتقوم بالشراء بواسطة المناقصة على مرحلتين ِ\n في الحالتين التاليتين:\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 44\n\f وفقاً لما َتفُرضه\n أ .عندما يتعَّذر على الجهة الشارية َوصف موضوع الشراء وصياغُته بالدقة المطلوبة ِ\n أحكام"}, {"o": 105, "l": "المادة 17", "b": "المادة 17من هذا القانون ،وذلك نظرا ً لطبيعته المعَّقدة .يعود لها في هذه الحالة إجراء\n صل إلى تحديد الح ّ\n ل الأكثر إرضاًء لحاجاتها الشرائية؛ مناقشات مع العارضين بهدف التو ُّ\n ب .عندما تكون الجهة الشارية قد أَجَرت مناقصة عمومية لمرتين متتاليتين ولكن لم تقَّدم أي عروض أو\n تكون هذه الجهة قد ألَغت عملية الشراء وفقاً للفقرة 3أو 4من"}, {"o": 106, "l": "المادة 25", "b": "المادة 25من هذا القانون ،وهي ترى\n ن الدخول في إجراءات مناقصة عمومية جديدة ،أو استخدام إحدى ُ\n طُرق الشراء الُمنَدِرجة في إطار أ ّ\n جح أن ُيؤدي إلى إبرام عقد شراء.\n الفصل الثالث من هذا القانون ،لا ُير َّ\n .2في جميع الأحوال ,على الجهة الشارية أن َتحصل على الموافقة المسبقة لهيئة الشراء العام لاستخدام\n سل من الجهة الشارية\n المناقصة على مرحلتين .على هيئة الشراء العام أن ُتبدي رأيها بطلب المواَفقة المر َ\n خلال //15//خمسة عشر يوماً ،على أن ُتعَتَبر هذه الهيئة مواِفقة بعد انقضاء هذه المهلة دون إبداء الرأي."}, {"o": 107, "l": "المادة 44", "b": "المادة | 44شروط استخدام طلب عروض الأسعار\n وفقاً للبند الرابع من هذا الفصل إذا كانت\n يجوز للجهة الشارية أن َتقوم بالشراء بواسطة طلب عروض الأسعارِ ،\n القيمة المقَّدرة لمشروع الشراء لا تتجاوز سقفاً مالياً محَّددا ً بخمسة مليارات ليرة لبنانيةُ .يعَّدل هذا السقف\n خذ في مجلس الوزراء بناًء على اقتراح\n المالي بناًء على توصية من هيئة الشراء العام وبموجب مرسوم ُيَّت َ\n رئيسه ،على أّلا يؤدي التعديل إلى مخالفة أهداف هذه المادة والمبادىء التي كَّر َ\n سها هذا القانون."}, {"o": 108, "l": "المادة 45", "b": "المادة | 45شروط استخدام طلب الاقتراحات للخدمات الاستشارية\n يجوز للجهة الشارية أن تقوم بالشراء بواسطة طلب الاقتراحات وفقاً للبند الخامس من هذا الفصل ،عندما\n تقوم بشراء الخدمات الاستشارية والتي يكون موضوعها الرئيسي تقديم خدمات ذات أثر فكري أو فني.\n يدخل في نطاق الخدمات الاستشارية على سبيل المثال لا الحصر:\n -التدريب والتدقيق ومشاريع البرمجة المعلوماتية وسواها من الأعمال الإستشارية المختصة؛\n مراقبة تنفيذ أشغال ومشاريع ومراقبة تقديم خدمات.\n -إعداد الدراسات والتصاميم ووضع دفاتر شروط و ُ\n منَفصل بحيث لا تدرسها إّلا بعد\n في هذه الحالة َتدُرس الجهة الشارية الجوانب المالّيـة من الاقتراحات على نحو ُ\n الانتهاء من فحص وتقييم خصائص الاقتراح الفنّيـة والوظيفّيـة والُمتعّلقة بالأداء."}, {"o": 109, "l": "المادة 46", "b": "المادة | 46شروط الاتفاق الرضائي\n يجوز للجهة الشارية أن َتقوم بالشراء بواسطة اتفاق رضائي ،وفقاً لأحكام البند السابع من هذا الفصل ،في\n الظروف الاستثنائية التالية:\n التخطيط\n الفعالّيـة والدمج في\n45 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\f .1عند عدم توُّفر موضوع الشراء إّلا عند مورِّد أو مقاول واحد ,أو عندما تكون لمورّد أو مقاول حقوق ملكية\n ص موضوع الشراء ,ويتعّذر اعتماد خيار أو بديل آخر.\n فكرية في ما َيخ ّ\nي\nمَتَوَّقع ,ونتيجة ذلك لا يكون استخدام أ ّ\n جّراء وقوع حدث كارثي وغير ُ\n .2في حالات الطوارىء والإغاثة من َ\n طريقة شراء أ ُخرى أسلوباً عملياً لمواجهة هذه الحالات.\n .3عند حاجة الجهة الشارية إلى التعاقد مع الملتزم الأساسي عند توُّفر الشروط التالية مجتمعة:\n أ .حصول الحاجة أثناء تنفيذ العقد؛\n ب .توُّفر حالة العجلة القصوى ووجوب التعاقد لمنع التأخير في التنفيذ؛\nج .وجوب توحيد المواصفات والتوافق أو التماثل مع السلع أو المعدات أو التكنولوجيا أو الخدمات أو\n الأشغال الموجودة؛\n د .عدم تأدية الإضافات إلى تبديل هدف العقد الأساسي أو قلب اقتصادياته أو ضرب مبدأ المنافسة؛\nهـ .تشكيل اللوازم أو الأشغال أو الخدمات ملحقاً للشراء الأساسي وجزءا ً متِّمماً له أو وجوب تنفيذ\n الأشغال في مكان العمل؛\n و .عدم إمكانية توُّقع الحاجة الإضافية أثناء التعاقد الأساسي.\n .4عند شراء لوازم أو خدمات أو عند تنفيذ أشغال تستوجب المحافظة على طابعها السري من أجل مقتضيات\n الأمن أو الدفاع الوطني ،وذلك وفقاً لقرار ُيَّت َ\nخذ في مجلس الوزراء بناًء على اقتراح الوزير المختص الذي\n ُيحِّدد الصفة السرية للشراء وأسباب التعاقد الرضائي.\n .5عند التعاقد مع أشخاص القانون العام كالمؤسسات العامة والبلديات أو المنظمات الدولّية.\n .6عند التعاقد مع المستشفيات والمراكز الطبية والمختبرات."}, {"o": 110, "l": "المادة 47", "b": "المادة | 47شروط الشراء بالفاتورة\nوفقاً للبند السادس من هذا الفصل ،إذا كانت القيمة المقَّدرة\n يجوز للجهة الشارية أن تقوم بالشراء بالفاتورة ِ\nلمشروع الشراء ،بما فيه الخدمات الاستشارية ،لا تتجاوز سقفاً مالياً محَّددا ً بخمسمائة //500//مليون ليرة\nلبنانيةُ .يعَّدل هذا السقف المالي بناًء على توصية من هيئة الشراء العام وبموجب مرسوم ُيَّتخذ في مجلس\nالوزراء بناًء على اقتراح رئيسه ،على أّلا يؤدي التعديل إلى مخالفة أهداف هذه المادة والمبادىء التي كّرسها\n هذا القانون."}, {"o": 111, "l": "المادة 48", "b": "المادة | 48شروط استخدام إجراءات الاتفاق الإطاري\n .1يمكن للجهة الشارية أن َتلجأ إلى إجراءات اتفاق إطاري ،وفقاً لأحكام البند الثامن من هذا الفصل ،في\n إحدى الحالتين التاليتين:\n محتَملة الوقوع على نحو متكّرر وغير مؤَّكدة التاريخ؛\n أ .عندما تكون الحاجة ُ\nمستعجل أثناء فترة معَّينة من الزمن.\n ب .عندما تنشأ الحاجة إلى موضوع الشراء ،بحكم طبيعته ،على نحو ُ\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 46\n\f ُ .2تعَقد اتفاقات الإطار في حالات الشراء المركزي للسلع والخدمات والأشغال البسيطة الُمدَرجة ضمن\n وفقاً لأحكام\n مرسوم ُيَّتخذ في مجلس الوزراء لهذه الغاية بناًء على توصية من هيئة الشراء العام ,وذلك ِ\n الفقرة الثانية من"}, {"o": 112, "l": "المادة 3", "b": "المادة 3من هذا القانون .في ما عدا ذلك ,على الجهة الشارية إبلاغ هيئة الشراء العام\n ِبِنَّيِتها استخدام الاتفاق الإطاري قبل //10//عشرة أيام على الأقل من بدء الإجراءات .لا يح ّ\n ق للجهة الشارية\n استخدام اتفاقات الإطار لمنع التنافس أو الحد منه.\n ُ .3تدِرج الجهة الشارية في السجل المنصوص عليه بمقتضى"}, {"o": 113, "l": "المادة 9", "b": "المادة 9من هذا القانون بياناً بالأسباب والظروف\n التي استندت إليها في تبرير اللجوء إلى إجراءات الاتفاق الإطاري ونوع الاتفاق الإطاري الذي اختارته.\n البند الثاني | اجراءات المناقصة العمومية"}, {"o": 114, "l": "المادة 49", "b": "المادة | 49الدعوة إلى المناقصة العمومية\n يجب أن يسِبق كل عملية شراء ُتجرى بموجب مناقصة عمومية صدور إعلان للعموم وفقاً لأحكام"}, {"o": 115, "l": "المادة 12", "b": "المادة 12من\n مسبق بمقتضى"}, {"o": 116, "l": "المادة 19", "b": "المادة 19من هذا القانون.\n هذا القانون ,باستثناء عمليات الشراء التي َيسبقها تأهيل ُ"}, {"o": 117, "l": "المادة 50", "b": "المادة | 50محتويات الدعوة إلى المناقصة العمومية\n تتضّمن الدعوة إلى تقديم العروض المعلومات التالية:\n أ .إسم الجهة الشارية وعنوانها؛\n خصاً لأهم الأحكام والشروط المطلوبة في عقد الشراءَ ،يشمل طبيعة وكمية السلع الُمراد توريدها\n ب .مل ّ\n ومكان تسليمها ،أو طبيعة وموقع الأشغال المراد تنفيذها ،أو طبيعة الخدمات والموقع الذي ُيراد\n م فيه توريد السلع أو إنجاز الأشغال أو تقديم\n تقديمها فيه ،وكذلك الوقت المرغوب أو الذي يجب أن يت ّ\n الخدمات؛\n ج .الأساس الُمعتَمد لإجراء المناقصة؛\n خصاً للمعايير والإجراءات التي ُتستخَدم للتأّكد من مؤّهلات العارضين ،ولأ ّ\n ي أدلة مستندية أو مل ّ\n دُ .\n معلومات أخرى يجب على العارضين أن ُيقّدموها لإثبات مؤهلاتهم ،بما يتوافق مع"}, {"o": 118, "l": "المادة 7", "b": "المادة 7من هذا\n القانون؛\n هـ .قيمة ضمان العرض ،في حال الانطباق؛\n و .المكان وكيفية الحصول على ملفات التلزيم؛\n ز .مكان وزمان الا ّ\n طلاع على ملفات التلزيم؛\n ح .البدل الذي تتقاضاه الجهة الشارية عن ملفات التلزيم ووسيلة الدفع والعملة التي ُيدَفع بها ،إن كان لها\n بدل؛\n ط .اللغة )العربية( أو اللغات التي تتوَّفر فيها ملفات التلزيم؛\n التخطيط\n الفعالّيـة والدمج في\n47 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\f جـه إليها العروض؛\n ي .الجهة التي توَدع لديها أو التي تو َّ\n ك .أ ُصول تقديم العروض ومكان ومهلة تقديمها بالساعة واليوم والشهر والسنة؛\n ل .مكان وزمان فتح العروض على أن ُيحَّدد الزمان بالساعة واليوم والشهر والسنة؛\n م .جميع البيانات والمعلومات الإضافية التي تقِّرر الجهة الشارية إدارجها في الإعلان."}, {"o": 119, "l": "المادة 51", "b": "المادة | 51توفير دفاتر الشروط )أو ملفات التلزيم(\nُتوِّفر الجهة الشارية دفتر الشروط أو ملف التلزيم للعارضين على موقعها الالكتروني إن ُوجد ،وعلى المنصة\nالإلكترونّيـة المركزّيـة لدى هيئة الشراء العام بالتزامن مع الإعلان عن الشراء .وفي حال القيام بإجراءات تأهيل\n مسبقُ ،تَوِّفر الجهة الشارية مجموعة من ملفات التلزيم لكل عارض يكون قد َتأَّهل ُ\nمسبقاً ويدفع البدل ُ\nجب عن تلك الملفات ،إن كان لها بدل .ويجب أن يوازي البدل الذي ُيمكن للجهة الشارية أن تتقاضاه مقابل\n المتو ِّ\n ملفات التلزيم تكلفة توفير تلك الملفات للعارضين."}, {"o": 120, "l": "المادة 52", "b": "المادة | 52محتويات دفاتر الشروط )أو ملفات التلزيم(\n ُتضَّمن دفاتر الشروط المعلومات التالية:\n أ .التعليمات الخاصة بإعداد العروض؛\nب .المعايير والإجراءات التي ُتطَّبق ،وفقاً لأحكام"}, {"o": 121, "l": "المادة 7", "b": "المادة 7من هذا القانون ،للتأُّكد من مؤّهلات العارضين\n ي إثبات إضافي بشأن تلك المؤّهلات؛\n وأ ّ\nج .المتطّلبات المتعّلقة بالمستندات الثبوتية لتوُّفر المؤهلات أو غيرها من المعلومات التي يجب أن\n يقّدمها العارضون لإثبات مؤّهلاتهم؛\n ص ً\nلا لموضوع الشراء ،وفقاً للمادة 17من هذا القانون ،وكمية السلع المراد شراؤها، د .وصفاً مف ّ\nوالخدمات الُمراد تقديمها ،والمكان الذي ُيراد فيه تسليم السلع أو تنفيذ الأشغال أو تقديم الخدمات،\n والوقت المطلوب توريد السلع أو إنجاز الأشغال أو تقديم الخدمات فيه ،في حال وجوده؛\n هـ .أحكام وشروط العقد واستمارة العقد التي يوِّقع عليها الطرفان ،إن ُوجدت؛\n و .في حال السماح ببدائل لخصائص موضوع الشراء أو للأحكام والشروط أو لمتطّلبات أخرى ُ\nمبَّينة في\n ملفات التلزيم ،بياناً بهذا الشأن ووصفاً للطريقة التي َيجري فيها تقييم العروض البديلة؛\nز .في حال السماح للعارضين بتقديم عروض بشأن مجموعة فحسب من موضوع الشراء ،تحديدا ً ووصفاً\n للمجموعة أو المجموعات التي يجوُز تقديم عروض بشأنها؛\nح .الطريقة التي يوضع بها سعر العرض ويعَّبر بها عنه ،بما في ذلك بيان حول ما إذا كان السعر يشمل\n عناصر أخرى غير تكلفة موضوع الشراء ذاته كان َيشُمل مث ً\nلا ما يمكن تطبيقه من رسوم جمركية وضرائب؛\n ط .العملة أو العملات التي سيوضع بها سعر العرض وُيعَّبر بها عنه؛\n ي .اللغة )العربية( أو اللغات التي ُتَعّد بها العروض ،وفقاً للمادة 4من هذا القانون؛\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 48\n\f ي ضمان للعرض يتعَّين على العارض توفيره وفقاً\n ي شروط تضعها الجهة الشارية بشأن مصدر أ ّ\n ك .أ ّ\n للمواد 34و 35من هذا القانون ،وبشأن طبيعة ذلك الضمان وشكله ومقداره وأهم أحكامه وشروطه\n ي شروط من هذا القبيل بشأن ما َيتعَّين على المورِّد أو المقاول الذي ُيبِرم عقد الشراء أن يوِّفره\n الأخرى ،وأ ّ"}, {"o": 122, "l": "المادة 7", "b": "من ضمانة لتنفيذ ذلك العقد ،بما في ذلك ضمانات مثل الكفالات المتعّلقة باليد العاملة والمعدات؛\n ل .كيفيَة تقديم العروض ومكان تقديمها وموعدها النهائي ،وفقاً لأحكام"}, {"o": 123, "l": "المادة 20", "b": "المادة 20من هذا القانون؛\n م .وسيلة الاستيضاح حول ملفات التلزيم من قبل العارضين بحسب"}, {"o": 124, "l": "المادة 21", "b": "المادة 21من هذا القانون ،وبياناً بما\n إذا كانت الجهة الشارية َتعتزم عقد اجتماع للعارضين في هذه المرحلة؛\n ن .المدَة التي تكون فيها العروض صالحة وفقاً للمادة 22من هذا القانون؛\n س .كيفيَة فتح العروض ومكان فتحها وتاريخه بالساعة واليوم والشهر والسنة ،وفقاً للمادة 54من هذا القانون؛\n ع .معاييَر وإجراءات تقييم العروض بناًء على وصف موضوع الشراء ووفقاً للمادتين 18و 55من هذا القانون؛\n ف .العملَة التي ُتستخَدم لتقييم العروض؛\n ص .أحكام مرجعية لهذا القانون ولمراسيمه التطبيقّيـة ،إن ُوجدت ،وسائر القوانين والمراسيم التي لها\n علاقة مباشرة بإجراءات التلزيم ،بما فيها تلك التي ُتطَّبق على الشراء الذي يتضَّمن معلومات سرّيـة؛\n ق .إسم واحد أو أكثر من موظفي الجهة الشارية أو مستخدميها يكون مسؤو ً\n لا عن الاتصال مباشرًة\n بالعارضين وبتلّقي اتصالات مباشرة منهم فيما يتعَّلق بإجراءات الشراء وكذلك التسمية الوظيفّيـة\n لذلك المو ّ\n ظف أو المستخَدم وعنوانه؛\n ص عليه الفصل السابع من هذا القانون في الشكوى أو المراجعة بشأن ما َتَّتِخذه\n ر .إشعارا ً بالحق الذي ين ّ\n الجهة الشارية من قرارات أو تدابير ُيزَعم بأنها لا تمتثل لأحكام هذا القانون ،مع معلومات عن مدة فترة\n ي فترة تجميد ،بياناً بهذا الشأن والأسباب الداعية إلى ذلك؛\n التجميد المطَّبـقة ،وفي حال عدم تطبيق أ ِّ\n ي إجراءات شكلية يجب استيفاؤها متى ُقِبل العرض المقَّدم الفائز لكي يصبح عقد الشراء نافذ\n ش .أ َّ\n المفعول ،بمقتضى"}, {"o": 125, "l": "المادة 24", "b": "المادة 24من هذا القانون؛\n ي شروط إضافية ُتقِّررها الجهة الشارية ،بما يتوافق مع هذا القانون ومراسيمه التطبيقّيـة.\n ت .أ َّ"}, {"o": 126, "l": "المادة 53", "b": "المادة | 53تقديم العروض\n ُ .1تقَّدم العروض وفق ما تنص عليه ملفات التلزيم لجهة كيفية تقديم العرض ومكانه وموعده النهائي.\n ُ .2يقَّدم العرض خطياً وموَّقعاً عليه في غلاف مختوم .يجوز تقديم العروض بحسب نظام الغلافين أو\n الغلاف الواحد وفقاً لما تن ّ\n ص عليه ملفات التلزيم.\n ي بالإضافة إلى تاريخ َتسُّلم العرض بالساعة ُ .3تزِّود الجهُة الشارية العاِرض بإيصال ُيبَّين فيه رق ٌ\n م تسلسل ٌّ\n واليوم والشهر والسنة.\n ُ .4تحاِفظ الجهة الشارية على أمن العرض وسلامته وسّريته ،وتكفل عدم الاطلاع على محتواه إلا بعد فتحه\n وفقاً للأصول.\n ي عرض تتسّلمه الجهة الشارية بعد الموعد النهائي لتقديم العروض ،بل ُيعاد مختوماً إلى\n .5لا ُيفَتح أ ُّ\n العارض الذي قّدمه.\n التخطيط\n الفعالّيـة والدمج في\n49 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية"}, {"o": 127, "l": "المادة 54", "b": "المادة | 54فتح العروض\nَ .1تفَتح العروض لجنة التلزيم المنصوص عليها في"}, {"o": 128, "l": "المادة 100", "b": "المادة 100من هذا القانون ،وذلك في جلسة علنية\nبحضور الأشخاص الَمأذون لهم في ملف التلزيم ،في الوقت والمكان ووفقاً للطريقة المحَّددة في هذا\n الملف ،على أن ُتعَقد هذه الجلسة فور انتهاء مهلة تقديم العروض.\nق لجميع العارضين المشاركين في عملية الشراء أو لممثّليهم المفّوضين وفقاً للأصول ،كما َيح ّ\nق .2يح ّ\nللمراقب المندوب من قبل هيئة الشراء العام حضور جلسة فتح العروض .كما يمكن للجهة الشارية دعوة\n حظ ذلك في ملف التلزيم.\n وسائل الإعلام لحضور هذه الجلسة على أن َتل َ\n ُ .3تفَتح العروض بحسب الآلية المحَّددة في ملف التلزيم.\nجـل وقائع فتح العروض خطياً في محضر يوِّقع عليه رئيس وأعضاء لجنة التلزيم ,كما توضع لائحة\n ُ .4تس َّ\nبالحضور يوِّقع عليها المشاركون من ممثّلي الجهة الشارية وهيئة الشراء العام ,والعارضين وممثليهم\nعلى أن يشّكل ذلك إثباتاً على حضورهمُ .تدَرج كل المعلومات والوثائق المتعِّلقة بوقائع الجلسة في\n سج ّ\n ل إجراءات الشراء المنصوص عليه في"}, {"o": 129, "l": "المادة 9", "b": "المادة 9من هذا القانون."}, {"o": 130, "l": "المادة 55", "b": "المادة | 55تقييم العروض\nمنفصل بحيث َتدرسها بعد الانتهاء من تدقيق وتقييم\n َ .1تدرس الجهة الشارية العروض المالّية على نحو ُ\n العروض الإدارية والفنّية.\n .2رهناً بأحكام الفقرة ) (3من هذه المادةَ ,تعتبر الجهُة الشارية العرض مستجيباً جوهرياً للمتطّلبات إذا كان\n يفي بجميع المتطّلبات المبَّينة في وثائق التلزيم وفقاً للمادة 17من هذا القانون.\n .3في حال كانت المعلومات أو المستندات المقَّدمة في العرض ناقصة أو خاطئة أو في حال غياب وثيقة\n معَّيـنةَ ,يجوز للجهة الشارية الطلب خ ّ\nطياً من العارض المعني توضيحات حول عرضه ,أو طلب تقديم أو\nاستكمال المعلومات أو الوثائق ذات الصلة خلال فترة زمنية محَّددة ,شرط أن تكون كافة المراسلات خطية\nواحترام مبادىء الشفافية والمساواة في المعاملة بين العارضين في طلبات التوضيح أو الاستكمال\n الخطية ,ومع مراعاة أحكام الفقرة 3من البند الثاني من"}, {"o": 131, "l": "المادة 21", "b": "المادة 21من هذا القانون.\n َ .4ترُفض الجهُة الشارية العرض:\nمؤَّهل بالنظر إلى شروط التأهيل الواردة في دفتر الشروط وتطبيقاً لأحكام المادة\n أ .إذا كان العارض غير ُ\n 7من هذا القانون؛\n مستجيب جوهرياً للمتطِّلبات المحَّددة في ملف التلزيم؛\n ب .إذا كان العرض غير ُ\n ج .في الحالات الظرفّية المشار إليها في المادتين 8أو 25من هذا القانون.\nُ .5تقِّيم الجهُة الشارية العروض المقبولة ،بغية تحديد العرض الفائز وفقاً للمعايير والإجراءات الواردة في\n ي معيار أو إجراء لم َيِرد في هذه الملفات.\n ملفات التلزيم .ولا ُيستخَدم أ ُّ\n ُ .6يعَتَبر العرض فائزا ً في إحدى الحالتين التاليتين:\n أ .العرض الأدنى سعرا ً ،عندما يكون السعُر هو المعيار الوحيد لإرساء التلزيم؛\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 50\n\f ب .العرض الأفضل بالاستناد إلى معايير وإجراءات التقييم المحَّددة في وثائق التلزيم وفقاً للمادة 18\n من هذا القانون ،عندما تكون هناك معايير مالية ومعايير أخرى غير السعر.\n .7تقوم الجهة الشارية بتقييم العروض ضمن مهلة معقولة تتلاءم مع مهلة صلاحية العروض ومع طبيعة\n ل إجراءات الشراء المنصوص عليه في"}, {"o": 132, "l": "المادة 9", "b": "المادة 9من هذا القانون. ضع محضرا ً بذلك ُيدَرُج في ِ\n سِج ّ الشراء ،وَت َ"}, {"o": 133, "l": "المادة 56", "b": "المادة | 56حظر المفاوضات مع العارضين\n مه ذلك العارض.\n ي من العارضين بشأن العرض الذي قَّد َ ُتح َّ\n ظر المفاوضات بين الجهة الشارية وأ ّ\n البند الثالث | المناقصة على مرحلتين"}, {"o": 134, "l": "المادة 57", "b": "المادة | 57إجراءات المناقصة على مرحلتين\n .1تسري أحكام البند الثاني من هذا الفصل على إجراءات المناقصة على مرحلتين ،بقدر عدم َتعاُرضه مع\n أحكام هذا البند.\n .2تدعو الجهة الشارية العارضين إلى أن ُيقِّدموا ،في المرحلة الأولى من إجراءات المناقصة على مرحلتين،\n عروضاً أولية تتضَّمن اقتراحاتهم من دون عروض مالية .يجوز أن تتضَّمن ملفات التلزيم طلب اقتراحات\n بشأن المواصفات الفنّية أو الوظيفّية أو المتعِّلقة بالأداء ،أو بشأن الأحكام والشروط التعاقدية ،وكذلك\n معلومات ووثائق ثبوتية عن كفاءة العارضين المهنية والتقنية والمالّية.\n .3يجوز للجهة الشارية ،في المرحلة الأولى ،أن ُتجري مناقشات مع العارضين الذين لم ُترفض عروضهم\n ي عارضُ ،تتيح\n ي جانب من جوانب تلك العروض .وعندما ُتجري الجهة الشارية مناقشات مع أ ّ\n الأولية ،بشأن أ ّ\n لجميع العارضين فرصة متساوية للمشاركة في تلك المناقشات وَتلَتِزم بمعايير الشفافية والمساواة في\n التعامل بشكل مطلق .وتكون المناقشات موثَّقة إ ّ\n مـا بكتب خطية أو الكترونية وإما بموجب جلسات فيديو\n ثنائّية عبر الانترنت توثَّق في محاضر إجتماعات يوِّقع عليها المشاركون .عند الإنتهاء من دراسة المقترحات\n لا بمجريات المرحلة الأولى َتسَتِند إليه في إعداد المتطّلبات\n ص ً\n والمناقشات ،تضع الجهة الشارية تقريرا ً مف َّ\n التقنية النهائية .وُيدَرج التقرير كما محاضر المناقشات في سجل إجراءات الشراء المنصوص عليه في"}, {"o": 135, "l": "المادة 9", "b": "المادة 9من هذا القانون.\n .4\n أ .في المرحلة الثانية من إجراءات المناقصة على مرحلتين ،تدعو الجهة الشارية جميع العارضين الذين لم\n ُترفض عروضهم الأولية في المرحلة الأولى إلى تقديم عروض نهائية تشمل العروض الفنّية\n والمالّيـة ،وذلك استجابة لصيغة منَّقحة من الأحكام والشروط الخاصة بعملية الشراء.\n ب .لدى تنقيح دفتر الشروط وأحكامه ذات الصلة ،لا يجوز للجهة الشارية تعديل موضوع الشراء ولكن يجوز\n سن من جوانب وصف موضوع الشراء عبر القيام بما يلي:\n لها أن ُتح ِّ\n التخطيط\n الفعالّيـة والدمج في\n51 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\fي جانب من المواصفات الفنّيـة أو الوظيفّيـة أو المتعّلقة بالأداء المنصوص عليها\n (1حذف أو تعديل أ ّ\n ي مواصفات جديدة تتوافق مع أحكام هذا القانون؛\n في المرحلة الأولى ،وإضافة أ ّ\nي معيار\n ي معيار لتقييم العروض منصوص عليه في المرحلة الأولى ،وإضافة أ ّ\n (2حذف أو تعديل أ ّ\nجديد يتوافق مع أحكام هذا القانون ،على أن يقتصر ذلك الحذف أو التعديل أو الإضافة على\nالحالات التي يكون فيها ذلك الحذف أو التعديل أو الإضافة ضرورياً بسبب ما أ ُدخل من تغييرات\n على المواصفات الفنّية أو الوظيفّية أو مواصفات الأداء.\nُ .5يبَّلغ العارضون بالدعوة إلى تقديم عروضهم النهائية وُيوَّفر لهم ملف التلزيم النهائي بعد تعديله عم ً\n لا\n بالفقرة الفرعية )ب( من الفقرة 4من هذه المادة؛\n .6يجوز للعارض الذي لا يرغب بتقديم عرض نهائي أن ينسحب من إجراءات المناقصة دون أن َيسُقط حّقه\n في استرداد ضمان العرض الذي يكون قد قَّدمه؛\n ُ .7تقَّيم العروض النهائية من أجل التأُّكد من العرض الفائز بحسب الفقرة 5من"}, {"o": 136, "l": "المادة 55", "b": "المادة 55من هذا القانون.\n البند الرابع | طلب عروض الأسعار"}, {"o": 137, "l": "المادة 58", "b": "المادة | 58إجراءات طلب عروض الأسعار\n .1تسري أحكام البند الثاني من هذا الفصل على إجراءات طلب عروض الأسعار ,باستثناء أحكام"}, {"o": 138, "l": "المادة 49", "b": "المادة 49\n )الدعوة إلى المناقصة العمومية(.\nُ .2تحِّدد الجهة الشارية المورِّدين أو المقاولين الذين ترغب بدعوتهم للاشتراك في المنافسة بحسب المادة\nجه الدعوة إليهم بطريقة مباشرة وبوسيلة سريعة ومضمونةُ .تعتَمد لهذه الغاية\n 44من هذا القانون ,وُتو ِّ\nلوائح ُتعُّدها الجهة الشارية على أن ُتدرج اللائحة المعتمدة في سجل إجراءات الشراء المنصوص عليه في"}, {"o": 139, "l": "المادة 9", "b": "المادة 9من هذا القانون .ويقتضي تحديث هذه اللائحة دورياً لإدخال عارضين ُ\nجُدد إليها بالاستناد إلى\n الإرشادات التي َتصدر عن هيئة الشراء العام بهذا الصدد.\n .3يجب أن لا يق ّ\n ل عدد العارضين المدعّوين عن ثلاثة.\n ت كا ٍ\nف يتيح للعارضين تحضير عروضهم انسجاماً مع أهمية مشروع الشراء وتعقيده ُ .4تحَّدد مدة الإعلان بوق ٍ\n ل في ك ّ\nل الأحوال عن //10//عشرة أيام من الموعد الأقصى لتقديم العروضُ .يمكن على أن لا تق ّ\nتخفيض مدة الإعلان إلى //5//خمسة أيام بقرار معَّلل في حالات العجلة المبَّررة ,على أن ُيدَّون التعليل\n في سجل إجراءات الشراء المنصوص عليه في"}, {"o": 140, "l": "المادة 9", "b": "المادة 9من هذا القانون.\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 52\n\f البند الخامس | طلب الاقتراحات للخدمات الاستشارية"}, {"o": 141, "l": "المادة 59", "b": "المادة | 59إجراءات طلب الاقتراحات للخدمات الاستشارية\n م الدعوة إلى .1عندما تقوم الجهُة الشارية بالشراء بواسطة طلب الاقتراحات ِ\n وفق أحكام المادة ,45تت ّ\n المشاركة وفقاً للمادة 12من هذا القانون.\n ن الدعوة ما يلي:\n ُ .2تضَّم ُ\n أ .إسم الجهة الشارية وعنوانها؛\n صلاً لموضوع الشراء وفقاً للمادة 17من هذا القانون ،بالإضافة إلى تاريخ ومكان التسليم؛\n ب .وصفاً مف ّ\n م وشروط عقد الشراء واستمارة العقد التي يوِّقع عليها الطرفان ،في حال وجودها؛\n ج .أحكا َ\n ي أدلة مستندية أو معلومات أخرى\n د .المعايير والإجراءات التي ُتستخَدم للتأُّكد من مؤّهلات العارضين وأ َّ\n يجب أن يقِّدمها العارضون لإثبات مؤَّهلاتهم؛\n وفقاً للمادتين 15و 18من هذا القانون ,بما في ذلك\n هـ .معاييَر وإجراءات فتح الاقتراحات وتقييمها ِ\n المتطلّبات الدنيا بشأن الخصائص الفنّيـة والوظيفّيـة والخصائص المتعلّقة بالأداء التي يجب أن تفي\n بها الاقتراحـات لكي ُتعَتَبر مستجيـبـة للمتطلِّبـات وفقاً للمادة 17من هذا القانـون ،وبيـاناً ُيفيـد بـأ َّ\n ن\n الاقتراحات التي لا تفي بتلك المتطلّبات سوف ُترَفض باعتبارها غير ُ\n مستجيبة للمتطلبات؛\n ن الذي تقتضيه"}, {"o": 142, "l": "المادة 12", "b": "المادة 12من هذا القانون؛\n و .الإعلا َ\n ز .وسائلَ الحصول على طلب الاقتراحات والمكان الذي يمكن الحصول عليه منه؛\n ن الذي تتقاضاه الجهة الشارية مقابل طلب الاقتراحات ،إن كان له ثمن؛\n ح .الثم َ\n ط .وسيلَة دفع ثمن طلب الاقتراحات والعملة التي ُيدفع بها في حال تقاضيه؛\n ي .اللغَة )العربية( أو اللغات التي تتوَّفر بها طلبات الاقتراحات؛\n ك .كيفيَة تقديم الاقتراحات والمكان والموعد النهائي لتقديمها.\n ُ .3توِّفر الجهُة الشارية طلب الاقتراحات عبر موقعها الالكتروني إن ُوجد وعلى المنصة الإلكترونّيـة المركزّيـة\n لدى هيئة الشراء العام ،بالإضافة إلى:\n أ .كلّ عارض يستجيب للدعوة إلى المشاركة في إجراءات طلب الاقتراحات ،وفقاً للإجراءات والمتطلبات\n المحّددة فيها؛ أو\n ب .كل عارض أ ُِّهل أولياً وفقاً للمادة 19من هذا القانون ،وفي حالة التأهيل المسبق.\n ُ .4يضَّمن طلب الاقتراحات ,إضافة إلى المعلومات المشار إليها في الفقرات الفرعية )أ( إلى )ه( و)ك( من\n الفقرة 2من هذه المادة ،المعلومات التالية:\n جهة إلى العارضين بأن يقِّدموا\n أ .تعليمات بشأن إعداد الاقتراحات وتقديمها ،بما في ذلك تعليمات مو َّ\n ن واحد في مغلََّفينَ :يحتوي أحدهما على خصائص الاقتراح الفنّيـة\n الاقتراحات إلى الجهة الشارية في آ ٍ\n والوظيفّيـة وخصائصه المتعلِّقة بالأداء ،ويحتوي الآخر على جوانب الاقتراح المالّيـة؛\n ب .وصفاً للمجموعة أو المجموعات التي يمكن تقديم اقتراحات بشأنها ،في حال السماح للعارضين\n بتقديم اقتراحات بشأن مجموعة فحسب من موضوع الشراء؛\n ج .العملة أو العملات التي ُيصاغ بها سعر الاقتراح ويعَّبر بها عنه؛\n التخطيط\n الفعالّيـة والدمج في\n53 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\fد .الطريقة التي يوضع بها سعر الاقتراح ويعَّبر بها عنه ،بما في ذلك بيان بما إذا كان السعر سوف يشمل"}, {"o": 143, "l": "المادة 12", "b": "عناصر أخرى غير تكلفة موضوع الشراء نفسه ،مثل الرسوم الجمركية أو الضرائب؛\nهـ .وسائل طلب الاستيضاح من قبل العارضين بشأن طلب الاقتراحات وفق أحكام"}, {"o": 144, "l": "المادة 21", "b": "المادة 21من هذا\n القانون ،وبياناً بما إذا كانت الجهة الشارية َتعتزم عقد اجتماع للعارضين في هذه المرحلة؛\nو .إحالات مرجعية إلى هذا القانون وإلى مراسيمه التطبيقّيـة وسائر القوانين التي لها صلة مباشرة\n بإجراءات الشراء؛\n ز .إسم واحد أو أكثر من مو ّ\n ظفي الجهة الشارية أو مستخدميها يكون مسؤو ً\nلا عن الاتصال مباشرًة\nبالعارضين وبتلّقي اتصالات مباشرة منهم فيما يتعَّلق بإجراءات الشراء وكذلك التسمية الوظيفّيـة\n لذلك الموظف أو المستخَدم وعنوانه؛\nص عليه الفصل السابع من هذا القانون بشأن القرارات\n ح .إشارة إلى الحق بالشكوى أو المراجعة الذي ين ّ\n أو التدابير التي تّتخذها الجهة الشارية وُيزَعم بأنها لا تمتثل لأحكام هذا القانون؛\n ط .أية إجراءات شكلية ُتصبح لازمة ما أن ُيقَبل الاقتراح الفائز لكي يدخل عقد الشراء حِّيـز التنفيذ؛\n ي .أية متطلبات أخرى قد تقِّررها الجهة الشارية بما يتوافق مع هذا القانون ومراسيمه التطبيقّية.\n .5تقوم الجهة الشارية ،قبل فتح المغّلفات التي تحتوي على الجوانب المالّيـة من الاقتراحات ،بفحص وتقييم\nالخصائص الفنّيـة والوظيفّيـة للاقتراحات وخصائصها المتعّلقة بالأداء وفقاً للمعايير والإجراءات المحَّددة\n في طلب الاقتراحات.\nُ .6تدَرج فورا ً نتائج فحص وتقييم الخصائص الفنّيـة ووالوظيفّيـة للاقتراحات وتلك المتعِّلقة بالأداء في سجل\n إجراءات الشراء.\nت التي لا تفي خصائصها الفنّيـة والوظيفّيـة وتلك المتعِّلقة بالأداء بالمتطلبات الدنيا ذات\n ُ .7تعَتَبر الاقتراحا ُ\nمستجيبة للمتطلبات وُترَفض لهذا السبب .كما ُيبَّلغ كل عارض ُرِفض اقتراحه بأسباب الصلة اقتراحا ٍ\n ت غير ُ\nالرفض ،وُيعاد إليه المغّلف غير المفتوح الذي يحتوي على جوانب الاقتراح المالّيـة ،وذلك بعد الانتهاء من\n إجراءات التلزيم.\nت التي تفي مواصفاتها الفنّيـة والوظيفّيـة ومواصفاتها المتعّلقة بالأداء بالمتطلبات الدنيا"}, {"o": 145, "l": "المادة 21", "b": "ُ .8تعَتَبر الاقتراحا ُ\n ذات الصلة أو تفوقها اقتراحا ٍ\nت مستجيبة جوهرياً للمتطلبات .وتقوم الجهة الشارية بإبلاغ كل عارض قَّد َ\nم\nاقتراحاً مستجيباً جوهرياً للمتطّلبات بالدرجة التي أحرزتها خصائص اقتراحه الفنّيـة والوظيفّيـة وتلك المتعّلقة\nبالأداء .وتدعو الجهة الشارية جميع أولئك العارضين إلى جلسة فتح المغّلفات التي تحتوي على الجوانب\n المالّية لاقتراحاتهم.\nمستجيب\n ُ .9تقرأ الدرجة التي أحَرَزتها المواصفات الفنّيـة والوظيفّيـة والمواصفات المتعلقة بالأداء لكل اقتراح ُ\nجه إليهم الدعوة،\n للمتطلبات والجانب المالي المقابل من ذلك الاقتراح في حضور العارضين الذين ُتو َّ\n وفقاً للفقرة 8من هذه المادة ،إلى جلسة فتح المغّلفات التي تحتوي على الجوانب المالّيـة للاقتراحات.\n .10تقوم الجهة الشارية بمقارنة الجوانب المالّيـة من الاقتراحات المستجيبة للمتطلبات وتحِّدد على هذا\nالأساس الاقتراح الفائز وفقاً للمعايير والإجراءات المبَّيـنة في طلب الاقتراحات .ويكون الاقتراح الفائز هو\nالاقتراح الذي َيحصل على أفضل تقييم إجمالي من حيث ما يلي )أ( المعايير الأخرى غير السعرية المبّيـنة\n في طلب الاقتراحات و)ب( السعر.\n .11تنشر الجهة الشارية نتيجة التلزيم حسب الأصول.\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 54\n\f البند السادس | الشراء بالفاتورة"}, {"o": 146, "l": "المادة 60", "b": "المادة | 60الدعوة إلى الشراء بالفاتورة\n .1عند تطبيق هذه الطريقة وفقاً لأحكام"}, {"o": 147, "l": "المادة 47", "b": "المادة 47من هذا القانونَ ،تطلب الجهة الشارية عروض الأسعار من\n ضين .ويبلَّغ كل مورِّد أو\n أكبر عدد ممكن عملياً من المورِّدين أو المقاولين ،على ألاَّ يقلّ عددهم عن عر َ\n مقاول ُيطلَب منه عرض أسعار بما إذا كان يجب أن ُتدَرج في السعر أ ّ\n ي عناصر أخرى غير تكاليف الشيء\n ي نفقات نقل وتأمين ورسوم جمركية وضرائب تنطبق على ذلك.\n موضوع الشراء نفسه ،مثل أ ّ\n ُ .2يسمح لكل عارض بأن يقِّدم عرض أسعار واحدا ً فقط ،ولا ُيسمح له بتغيير عرضه .ولا ُتجرى مفاوضات بين\n ي عارض بشأن عرض الأسعار الذي قّدمه.\n الجهة الشارية وأ ّ\n ُ .3يكتفى ببيان موّقع من أصحاب الحقوق يتضّمن تفصيل الخدمات او اللوازم او الأشغال عند تعّذر تقديم\n فاتورة ،كما يمكن الاكتفاء بالفاتورة عند تعّذر الحصول على عرضين."}, {"o": 148, "l": "المادة 61", "b": "المادة | 61العرض الفائز بالشراء بالفاتورة\n يكون عرض الأسعار الفائز هو العرض الأدنى سعرا ً الذي يفي باحتياجات الجهة الشارية كما هو محَّدد في\n طلب عرض الأسعار .\n البند السابع | الاتفاق الرضائي"}, {"o": 149, "l": "المادة 62", "b": "المادة | 62إجراءات التعاقد بالاتفاق الرضائي\n عندما تقوم الجهة الشارية بالشراء من مصدر واحد وفقاً للمادة 46من هذا القانون:\n .1تبِّلغ الجهة الشارية هيئة الشراء العام نّيـتها بإجراء عقد بالتراضي وَتنشر إشعارا ً بالشراء بطريقة الاتفاق\n الرضائي على المنصة الإلكترونّيـة المركزّيـة في هيئة الشراء العام وعلى موقعها الالكتروني إن ُوجد ،وذلك\n قبل //10//عشرة أيام على الأقل من تاريخ إبرام العقد .وُيضَّمن الإشعار ،كحٍّد أدنى ،المعلومات التالية:\n أ .إسم الجهة الشارية وعنوانها؛\n خصاً لأه ِّ\n م لأحكام والشروط المطلوبة في عقد الشراءَ ،يشمل طبيعَة وكمية السلع الُمراد توريدها ب .مل ّ\n ومكان تسليمها ،أو طبيعة وموقع الأشغال الُمراد تنفيذها ،أو طبيعة الخدمات والموقع الذي ُيراد\n م فيه توريد السلع أو إنجاز الأشغال أو تقديم الخدمات؛\n تقديمها فيه ،وكذلك الوقت المطلوب أن َيت ّ\n ن العقد سُيبرم بطريقة الاتفاق الرضائي.\n ج .أ ّ\n ق أحكام الفقرة الأولى من هذه المادة في الحالات الُمشار إليها في الفقرتين الثانية والرابعة من\n .2لا ُتطَّب ُ"}, {"o": 150, "l": "المادة 46", "b": "المادة 46من هذا القانون.\n التخطيط\n الفعالّيـة والدمج في\n55 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\f .3تقوم الجهة الشارية بطلب اقتراح أو عروض أسعار من عارض وحيد ،وُتجري مفاوضات مع هذا العارض ،ما\n لم تكن تلك المفاوضات غير ممكنة عملياً في الظروف المحيطة بعملية الشراء المعنّية.\n .4يمكن للجهة الشارية أن ُتسِند التلزيم إلى العارض دون أن تَّتبع إجراءات تنافسية.\n البند الثامن | اتفاقات الاطار"}, {"o": 151, "l": "المادة 63", "b": "المادة | 63إرساء الاتفاق الإطاري\n ُ .1ترسي الجهة الشارية الاتفاق الإطاري بإحدى الوسيلتين التاليتين:\nأ .بواسطة إجراءات مناقصة عمومية ،وفقاً لأحكام البند الثاني من هذا الفصل ،بما لا يتعارض مع أحكام\n هذا البند؛\nب .بواسطة طرق شراء أخرى وفقاً للأحكام ذات الصلة من البنود الأول والثالث والرابع من هذا الفصل،\n بما لا يتعارض مع أحكام هذا البند.\n ُ .2تطَّبـق أحكام هذا القانون التي ُتن ِّ\nظم محتويات الدعوة والتأهيل المسبق ،عند اعتماده ،على المعلومات\nالتي توَّفر للعارضين عندما ُيدعون لأول مرة للمشاركة في إجراءات اتفاق إطاري ،بما لا يتعارض مع أحكام\n هذا البند .وُتبِّين الجهة الشارية في تلك المرحلة ،إضافة إلى ذلك ،ما يلي:\n ن الشراء سوف يجري بصفته إجراء اتفاق إطاري؛\n أ .أ ّ\n ب .ما إذا كان الاتفاق الإطاري سُيبَرم مع مورِّد أو مقاول أو استشاري أو مقِّدم خدمات واحد أو أكثر؛\nمقِّدمي الخدمات\n ج .الحّد الأدنى أو الأقصى المفروض على عدد المورّدين أو المقاولين أو الاستشاريين أو ُ\nالذين سوف يكونون أطرافاً في الاتفاق الإطاري إذا كان الاتفاق سوف ُيبَرم مع أكثر من مورِّد أو\n مقاول أو استشاري أو مقِّدم خدمات واحد؛\n د .شكل الاتفاق الإطاري وأحكامه وشروطه وفقاً للمادة 64من هذا القانون.\n ُ .3تطَّبق أحكام"}, {"o": 152, "l": "المادة 24", "b": "المادة 24من هذا القانون على إرساء الاتفاق الإطاري ،بعد إجراء التعديلات اللازمة."}, {"o": 153, "l": "المادة 64", "b": "المادة | 64المتطلبات المتعلقة بالاتفاقات الإطارية\n ُ .1يبَرم الاتفاق الإطاري خطياً ،وُيبَّين فيه ما يلي:\nأ .مدة الاتفاق الإطاري ،التي يجب أّلا تقل عن سنة ولا تزيد عن أربع سنوات ،وهي غير قابلة للتمديد ولا\n ي من الحالات ولا يمكن تغيير شروطها؛\n للتجديد في أ ّ\n حِّدَدت عند إبرام الاتفاق الإطاري؛\n ب .وصف لموضوع الشراء وسائر أحكام وشروط الشراء التي ُ\nج .تقديرات أحكام وشروط الشراء التي لا يمكن تحديدها بدقة كافية عند إبرام الاتفاق الإطاري ،بقدر ما\n تكون معروفة؛\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 56\n\f مقِّدم خدمات واحد سوف\n د .ما إذا كان الاتفاق الإطاري الذي ُيبرم مع أكثر من مورِّد أو مقاول أو استشاري أو ُ\n ينطوي على تنافس في مرحلة ثانية من أجل إرساء عقد الشراء بمقتضى الاتفاق الإطاري ،وإذا كان\n الأمر كذلك:\n (1بيان بأحكام وشروط الشراء التي سوف ُتحَّدد أو سوف ُتنَّقح خلال التنافس في المرحلة الثانية؛\n (2الإجراءات الخاصة بأي تنافس في المرحلة الثانية والتكرار المتوّقع لذلك التنافس ،والمواعيد\n النهائية المتوخاة لتقديم عروض المرحلة الثانية؛\n (3الإجراءات والمعايير التي ُتطَلق أثناء التنافس في المرحلة الثانية ,بما فيها التثقيل لتلك المعايير\n وكيفية تطبيقها ,وفقاً للمادتين 17و 18من هذا القانون .وإذا جاز أن َتختلف نسب التثقيل لمعايير\n التقييم أثناء التنافس في المرحلة الثانية ،فيتعَّين أن ُيحِّدد الاتفاق الإطاري نطاق الاختلاف\n المسموح به؛\n م إرساؤه على أدنى العروض المقَّدمة سعرا ً\n (4ما إذا كان عقد الشراء بمقتضى الاتفاق الإطاري سيت ّ\n أو على أفضل العروض؛\n (5طريقة إرساء عقد الشراء.\n مقِّدم خدمات واحد كاتفاق واحد بين جميع\n ُ .2يبَرم الاتفاق الإطاري مع أكثر من مورِّد أو مقاول أو استشاري أو ُ\n الأطراف."}, {"o": 154, "l": "المادة 64", "b": "ُ .3يضَّمن الاتفاق الإطاري ،إضافة إلى المعلومات الأخرى المحَّددة في هذه المادة ،المعلومات الضرورية\n لتيسير العمل بالاتفاق الإطاري على نحو فّعال ،بما فيها المعلومات المتعّلقة بكيفية الاطلاع على نص\n الاتفاق والإشعارات الخاصة بعقود الشراء المقبلة المندرجة في إطاره ،والمعلومات اللازمة المتعّلقة\n بطرق الاتصال ،في حال الاتصال الالكتروني على سبيل المثال لا الحصر."}, {"o": 155, "l": "المادة 65", "b": "المادة | 65المرحلة الثانية من إجراءات الاتفاق الإطاري\n ُ .1يَرسى كل عقد شراء بمقتضى الاتفاق الإطاري وفقاً لأحكام ذلك الاتفاق وشروطه ووفقاً لأحكام هذه\n المادة.\n مقِّدم ي عقد شراء بمقتضى الاتفاق الإطاري إ َّ\n لا على مورِّد أو مقاول أو استشاري أو ُ .2لا يجوُز إرساء أ ِّ\n خدمات كان طرفاً في ذلك الاتفاق.\n م"}, {"o": 156, "l": "المادة 24", "b": "المادة 24من هذا القانون ,باستثناء الفقرة 2منها ،على قبول العرض الُمقَّدم الفائز\n .3تسري أحكا ُ\n بمقتضى الاتفاقات الإطارية غير المنطوية على تنافس في المرحلة الثانية.\n ت\n .4في الاتفاق الإطاري الذي ينطوي على تنافس في المرحلة الثانية تسري على إرساء عقد الشراء الإجراءا ُ\n التالية:\n أُ .تص ِ\n در الجهُة الشارية دعوة خطية إلى تقديم العروض ُتو َّ\n جه في وقت واحد على نحو:\n مقِّدم خدمات طرف في الاتفاق الإطاري؛ أو ل ك َّ\n ل مورِّد أو مقاول أو استشاري أو ُ (1يشم ُ\n مقِّدمي الخدمات الأطراف في الاتفاق\n (2يقتصُر على المورِّدين أو المقاولين أو الاستشاريين أو ُ\n الإطاري القادرين في ذلك الحين على تلبية حاجات تلك الجهة الشارية فيما يخص موضوع الشراء،\n التخطيط\n الفعالّيـة والدمج في\n57 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\fسل في الوقت نفسه إشعارٌ بالتنافس في المرحلة الثانية إلى جميع الأطراف في\n شرط أن ُير َ\n الاتفاق الإطاري لكي َيتسنى لهم المشاركة في التنافس في المرحلة الثانية؛\n بُ .تضَّمن الدعوة إلى تقديم العروض المعلومات التالية:\n (1بيان يعيد تأكيد أحكام الاتفاق الإطاري وشروطه القائمة التي ُتدَرج في عقد الشراء المرتقب ،مع\nتحديد أحكام وشروط الشراء التي تخضع للتنافس في المرحلة الثانية ،وتقديم تفاصيل إضافية عن\n تلك الأحكام والشروط عند الاقتضاء؛\n (2بيان يعيد تأكيد الإجراءات والمعايير المتعّلقة بإرساء عقد الشراء الُمرتَقب بما في ذلك التثقيل\n وكيفية تطبيقها؛\n (3التعليمات الخاصة بإعداد العروض؛\n (4كيفيَة تقديم العروض والمكان والموعد النهائي لتقديمها؛\nمقِّدمي الخدمات بتقديم عروض بشأن\n (5في حال السماح للمورِّدين أو المقاولين أو الاستشاريين أو ُ\n مجموعة واحدة فقط من موضوع الشراء ،وصفاً للمجموعة أو المجموعات التي يجوز تقدي ُ\nم عرض\n بشأنها؛"}, {"o": 157, "l": "المادة 24", "b": "(6الآلية المعتمدة لوضع سعر العرض وطريقة التعبير عنه ،بما في ذلك بيان بما إذا كان السعر يشمل\n عناصر أخرى غير تكلفة موضوع الشراء نفسه ،مثل ما قد ينطبق من رسوم جمركية وضرائب؛\n (7إحالا ٍ\nت مرجعيًة إلى هذا القانون ومراسيمه التطبيقّيـة وسائر القوانين والمراسيم التي لها صلة\nمباشرة بإجراءات الشراء ،بما فيها تلك التي تسري على الشراء الذي َيتضَّمن معلومات سرّيـة،\n والمكان الذي يمكن فيه الاطلاع على تلك القوانين والمراسيم؛\n مستخدميها يكون مسؤو ً\nلا عن الاتصال مباشرة (8إسم واحد أو أكثر من موظفي الجهة الشارية أو ُ\nبالعارضين وِبَتَلّقي اتصالات مباشرة منهم فيما يتعّلق بالتنافس في المرحلة الثانية ،وكذلك\n التسمية الوظيفّيـة لذلك الموظف أو المستخَدم وعنوانه؛\n (9إشعارا ً بالحق الذي تنص عليه"}, {"o": 158, "l": "المادة 103", "b": "المادة 103من هذا القانون في الشكوى أو المراجعة بشأن القرارات\nوالتدابير التي تّتخذها الجهة الشارية وُيزعم بأنها لا تمتثل لأحكام هذا القانون ،إلى جانب معلومات\nي فترة تجميد فبياناً بهذا الشأن والأسباب\n عن مدة فترة التجميد المنطِبقة ،وفي حال عدم انطباق أ ِّ\n الداعية إلى ذلك؛\nن ُيقَبـل العرض المقَّدم الفائز لكي يبدأ تنفيذ عقد الشراء ,بما\n جبة ما أ ْ\n ي إجراءات شكلية تصبح متو ّ\n (10أ َّ\n في ذلك ,عندما يكون منطبقاً ,إبرام عقد شراء خطي وفق"}, {"o": 159, "l": "المادة 24", "b": "المادة 24من هذا القانون؛\nي متطّلبات أخرى تقِّررها الجهة الشارية وفقاً لهذا القانون ومراسيمه التطبيقّيـة بشأن إعداد\n (11أ َّ\n العروض وتقديمها وبشأن سائر جوانب التنافس في المرحلة الثانية؛\nع العروض المقَّدمة التي تتلقاها وُتحِّدد العرض الفائز وفقاً لمعايير التقييم\n جُ .تقِّيم الجهُة الشارية جمي َ\n والإجراءات الُمبَّينة في الدعوة إلى تقديم العروض؛\n دَ .تقَبـل الجهُة الشارية العرض الُمقَّدم الفائز وفقاً للمادة 24من هذا القانون.\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 58\n\f الفصل الرابع | أحكام خاصة بالشراء الالكتروني"}, {"o": 160, "l": "المادة 66", "b": "المادة | 66نظام المشتريات الالكتروني\n صصة للشراء الالكتروني عبر استخدام وسائل وتقنيات\n ُتنشأ لدى هيئة الشراء العام منصة الكترونية مخ ّ\n معلوماتية رقمية لتأمين حاجات الجهات الشارية من لوازم وأشغال وخدمات.\n مقِّدمي\n يجب أن تشتمل هذه المنصة على آلية تسجيل إلكترونية ُتتيح للمورِّدين والمقاولين والاستشاريين و ُ\n الخدمات إمكانية التسجيل عبر الإنترنت للتأُّهل للمشاركة في الشراء العام الالكتروني.\n صص المنصة صفحات خاصة لتقديم العروض واستلامها إلكترونياً ،وَتعمل هذه الصفحات فقط من تاريخ\n ُتخ ِّ\n إصدار المنافسة حتى وقت إغلاقها ،ويكون تاريخ ووقت إغلاق التلزيمات الإلكترونّيـة هو نفس تاريخ ووقت\n إغلاق التلزيمات التقليدية.\n َيشُمل نظام الشراء الإلكتروني الإعلان عن الشراء وتقديم العروض وفتحها والتعاقد إلكترونياً كما يحتوي على\n حدة للإعلانات التقليدية واستخدام الوثائق النموذجية.\n مو َّ\n سوق افتراضية ،وُيشّكل بوابة ُ"}, {"o": 161, "l": "المادة 67", "b": "المادة | 67إجراءات الشراء الالكتروني\n ضع إجراءات الشراء الإلكتروني لأعلى درجات الخصوصية والسّرية والأمان وشفافية المعلومات وَتَتمَّتع\n َتخ َ\n من نظام الشراء الإلكتروني سّرية وسلامة المعاملات على\n المبادلات الإلكترونّيـة بالقوة الثبوتية ،كما ُيؤ ِّ\n شبكة معلوماتية مفتوحة دون تمييز بين المتعاملين ،وهو يخضع للقوانين والأنظمة المرعية الإجراء والمتعلقة\n بالتبادل الإلكتروني.\n ُيعَمل بالتوقيع الإلكتروني وفقاً لمقتضيات القوانين والأنظمة المرعية الإجراء والمتعّلقة بالتوقيع الإلكتروني."}, {"o": 162, "l": "المادة 68", "b": "المادة | 68التسجيل بالنظام الالكتروني\n يجب على المستخدمين التسجيل بنظام الشراء الإلكتروني للتمّكن من النفاذ إليهُ .يخِّول هذا التسجيل كل\n معِّرف شخصي )إسم مستخدم( ُيمِّكنه من استخدام نظام الشراء الإلكتروني.\n مستخدم الحصول على ُ\n عند تقديم طلبات التسجيل والعروض الكترونياًُ ،يثِّبت النظام الإرسال وتاريخه وساعته.\n التخطيط\n الفعالّيـة والدمج في\n59 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية"}, {"o": 163, "l": "المادة 69", "b": "المادة | 69تقديم العروض الكترونيًا\n عند استخدام الجهة الشارية نظام الشراء الالكترونيُ ،تقَّدم ك ّ\nل العروض الكترونياً ،وعند َتعُّذر التقديم الكترونياً،\nلأسباب فنية أو تقنية ،يمكن تقديم العرض أو جزء منه بالطرق التقليدية وذلك خلال المهل المحَّددة لقبول\n الطلبات أو العروض."}, {"o": 164, "l": "المادة 70", "b": "المادة | 70فتح وتقييم العروض الكترونيًا\nضع فتح العروض وتقييمها للأحكام المنصوص عليها في هذا القانون وتكون الجلسة علنية الكترونياً عبر\n َيخ َ\n وسائل التواصل الافتراضية ،ويجري التلزيم والتعاقد وأمر المباشرة الكترونياً."}, {"o": 165, "l": "المادة 71", "b": "المادة | 71تطبيق الشراء الالكتروني\nُتِعّد هيئة الشراء العام دقائق تطبيق الشراء الإلكتروني وُتحَّدد بموجب مرسوم ُيَّتخذ في مجلس الوزراء بناء\n على اقتراح رئيس مجلس الوزراء.\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 60\n\f صص وبناء القدرات\n الفصل الخامس | التخ ّ"}, {"o": 166, "l": "المادة 72", "b": "المادة | 72التدريب\n مستمر إلزامي تقوم به وزارة المالّيـة-معهد باسل\n صص ُ\n ضع القائمون بمهام الشراء العام لتدريب متخ ِّ\n َ .1يخ َ\n فليحان المالي والاقتصادي.\n سق التدريب مع المعهد الوطني للإدارة والجهات المعنّيـة مع الحفاظ على مبدأ التآزر والتكامل في\n .2ين َّ\n جع\n الأدوار بين مختلف المعاهد ومراكز التدريب التي ُتعنى بتعزيز القدرات على المستوى الوطني وُيش َّ\n تعزيز النهج التعاوني مع مراكز المعرفة على سبيل المثال لا الحصر الجامعات ومراكز الأبحاث ومراكز\n السياسات العامة.\n جـه التدريب في قسم ٍ منه إلى القطاع الخاص.\n ُ .3يمكن أن َيَتو َّ\n صص برامج تدريبية لتعزيز نزاهة المعنيين بالشراء ،من القطاعين العام والخاص ،لرفع مستوى الوعي\n ُ .4تخ َّ\n حول مخاطر عدم النزاهة ،مثل الفساد والاحتيال والتواطؤ والتمييز ،والعقوبات المرتبطة بها ،وتطوير\n المعرفة حول السبل لمواجهة هذه المخاطر.\n َ .5يشمل التدريب الدوري القضاة الإداريين والماليين المعنيين بتنفيذ هذا القانون وذلك بعد موافقة ك ّ\n ل\n من رئيس مجلس شورى الدولة ورئيس ديوان المحاسبة.\n َ .6يَتضَّمن التدريب دعم تطبيق أهداف التنمية المستدامة."}, {"o": 167, "l": "المادة 73", "b": "المادة | 73التسمية الوظيفّيـة\n ُ .1يدَرج الشراء العام كوظيفة محَّددة ضمن الهيكل الوظيفي في الدولة .تحِّدد المراسيم التطبيقّيـة أ ُ ُ\n طر\n الكفايات المعرفية والمهارات والخبرة المهنية والسلوكيات إضافة إلى التوصيف الوظيفي وشروط\n التوظيف و/أو التعيين والترفيع الخاصة بالعاملين في الشراء ُتِعُّدها هيئة الشراء العام بالتنسيق مع مجلس\n الخدمة المدنية ،بالإضافة إلى توفير الخيارات الوظيفّيـة المحِّفزة والتنافسية القائمة على الجدارة.\n ُ .2تنشأ في الهيكل التنظيمي للجهة الشارية وحدة للشراء أو ُيعَّدل هذا الهيكل ،وفقاً للاقتضاء ،وتكون هذه الوحدة\n مسؤولة عن عمليات الشراء وفقاً لأحكام هذا القانونُ .تشَّكل هذه الوحدة من الموظفين الذين خضعوا للتدريب\n وفقاً للمادة 72أعلاه ،وعلى أن يتناسب عديد هذه الوحدة وكفايات أعضائها مع حجم ونوع الشراء لديها.\n خذ في مجلس الوزراء بناًء على اقتراح\n ُ .3يحّدد ملاك وحدة الشراء لدى كل جهة شارية بموجب مرسوم ُيَّت َ\n المرجع المختص.\n .4يمكن لوحدة الشراء طلب المشورة التقنية ،عند الاقتضاء ،من هيئة الشراء العام ،أو استطلاع رأيها في\n موضوع معَّين يتعلق بالشراء.\n التخطيط\n الفعالّيـة والدمج في\n61 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\f الفصل السادس | حوكمة الشراء العام\n البند الأول | هيئة الشراء العام"}, {"o": 168, "l": "المادة 74", "b": "المادة | 74إنشاء هيئة الشراء العام\nُ .1تنشأ بموجب هذا القانون هيئة إدارية مستقلة تسّمى “هيئة الشراء العام” تماِرس الصلاحيات والمهام\n المبَّيـنة في متنه يكون مركزها في مدينة بيروت.\n .2تتمَّتع الهيئة بالشخصية المعنوية وبالاستقلاَلين المالي والإداري .كما لها الصفة والمصلحة القانونية\n للطعون بشأن القرارات المرتِبطة بعملية الشراء وفقاً لأحكام الفصل السابع من هذا القانون.\n .3تشمل صلاحيات الهيئة جميع الجهات الشارية وفقاً للتعريف المحَّدد لها بموجب هذا القانون.\nُ .4تحَّدد ملاكات ومهام العاملين وشروط التعيين في هيئة الشراء العام بموجب مرسوم يّتخذ في مجلس\nالوزراء بناًء على اقتراح رئيس مجلس الوزراء بعد إنهاء هيئة الشراء العام واستشارة مجلس شورى الدولة،\n خلال مهلة ستة أشهر من تاريخ صدور مرسوم تشكيل الهيئة.\nضع الهيئة لأحكام المرسوم رقم 4517تاريخ ) 1972/12/13النظام العام للمؤسسات العامة( غير أنها\n .5لا َتخ َ\nتخضع لأحكام هذا القانون ولرقابة ديوان المحاسبة المؤَّخرة ولرقابة التفتيش المركزي ومجلس الخدمة\n المدنية."}, {"o": 169, "l": "المادة 75", "b": "المادة | 75تشكيل الهيئة\nُ .1تشَّكل الهيئة من رئيس وأربعة أعضاء ُيعَّيـنون بموجب مرسوم ُيَّتخذ في مجلس الوزراء بناًء على اقتراح\n رئيس مجلس الوزراء وفقاً لشروط وآلية التعيين المف َّ\nصلة في المادة ُ .78تحَّدد ولاية كل من الرئيس\n والأعضاء الأربعة بخمس سنوات قابلة للتجديد مرة واحدة فقط.\nَ .2تَّتخذ الهيئة قراراتها بغالبية الأعضاء الذين تتألف منهم قانوناً ،وَتَتوّلى الهيئة مجتمعة المهام والصلاحيات\nالمنصوص عليها في هذا القانون ،بموجب نظام داخلي ُيحَّدد فيه توزيع المهام بين الأعضاء وطرق\n ووسائل تنفيذ القرارات الصادرة عن الهيئة.\n .3في ما خلا الرئيس الذي ُتطَّبـق بشأنه أحكام الفقرة الأولى من"}, {"o": 170, "l": "المادة 81", "b": "المادة 81من هذا القانونُ ،يعَتَبر كل عضو\n لا من الناحية المسلكية في حال أخ َّ\nل عن قصد أو إهمال بالواجبات التي تفرضها من أعضاء الهيئة مسؤو ً\nعليه القوانين والأنظمة النافذة المرعية الإجراء .لا تحول الملاحقة التأديبية بشأن الأعضاء أو بشأن\n الرئيس دون ملاحقتهم عند الاقتضاء أمام المحاكم المدنية أو الجزائية المختصة.\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 62"}, {"o": 171, "l": "المادة 76", "b": "المادة | 76مهام هيئة الشراء العام\n ُتعنى الهيئة بتنظيم الشراء العام والإشراف عليه ومراقبته وتطوير إجراءاته وُن ُ\n ظمه وأدائه كما ُتعنى بالتنسيق\n بين مختلف الجهات الشارية وتقديم المساندة الفنّيـة والإرشاد لها .ولها أن تقوم بالمهام التي أ ُنيطت بها،\n ومنها على سبيل المثال لا الحصر:\n .1الاقتراح على مجلس الوزراء السياسات العامة المتعلقة بالشراء؛\n .2تصميم وإدارة وتشغيل المنصة الإلكترونّيـة المركزّيـة للشراء العام والشراء الإلكتروني؛\n حد َيصدر عنها وتبويبها ونشرها وفق\n مو َّ\n .3جمع خطط الشراء السنوية الواردة من الجهات الشارية وفق نموذج ُ\n الأصول على المنصة الإلكترونّيـة المركزّيـة المعتمدة بحسب"}, {"o": 172, "l": "المادة 11", "b": "المادة 11من هذا القانون؛ على أن تتضَّمن\n ضر\n صلة عن الأنواع والكميات وطرق التعاقد والقطاعات المعنّيـة بشكل يسمح للسوق بالتح ُّ\n معلومات مف َّ\n للمنافسة؛\n َ .4نشر كافة الإعلانات والإشعارات المتعِّلقة بالمشتريات وبإجراءات التأهيل والتلزيم وفق الأصول على\n المنصة الإلكترونّيـة المركزّيـة المعتمدة وإلزام الجهات الشارية بذلك؛\n .5وضع وتيويم لائحة باللوازم والخدمات والأشغال البسيطة التي ُيمكن أن ُيؤدي شراؤها بطريقة مركزية\n إلى تحقيق القيمة الفضلى من إنفاق المال العام ،واقتراح الجهة التي تقوم بالشراء المركزي لكل نوع\n منهاُ .تَقّر هذه اللائحة بمرسوم ُيَّتخذ في مجلس الوزراء بناء على اقتراح رئيسه؛\n .6إبداء الرأي باتفاقات الإطار المشار إليها في الفصل الثالث من هذا القانون؛\n .7إصدار قرارات بشأن الموافقة على استخدام الجهة الشارية طريقة المناقصة على مرحلتين؛\n .8إصدار إرشادات وتوضيحات حول النصوص القانونية النافذة المتعلقة بالشراء العام ،بما في ذلك إصدار\n الأدّلة والقواعد الإرشادية؛\n ق لها في هذا الإطار\n .9مراقبة وتقييم تطبيق النصوص القانونية والقواعد التي َترعى الشراء العام ,ويح ّ\n الا ّ\n طلاع على سجل الشراء لدى الجهة الشارية ,مع مراعاة سرية البيانات بحسب أحكام"}, {"o": 173, "l": "المادة 6", "b": "المادة 6من هذا\n القانونُ .تن ِّ\n ظم الهيئة تقارير دورية تتناول مكا ِ\n من الخلل و/أو مخالفة القوانين في كل الجهات الشارية،\n وترفعها إلى رئاسة الجمهورية ومجلس النواب ومجلس الوزراء وديوان المحاسبة والتفتيش المركزي،\n وتنشرها وفق الأصول؛\n .10إحالة أي مستندات أو وثائق تتعّلق بعقد أو إجراء يخضع لأحكام هذا القانون إلى المرجع الجزائي المختص\n ي مخالفة ُتعا ِ\n قب عليها القوانين الجزائية ،كما وطلب إحالة الموظف الذي تقوم في حال الاشتباه بحصول أ ّ\n شبهة حول توا ُ\n طِئه إلى المراجع الرقابية المختصة؛\n صة المركزّيـة\n جمع البيانات والمستندات الخاصة بعمليات الشراء العام ،على كافة المستويات ،على المن ّ\n َ .11\n بما في ذلك أنواع وطرق التعاقد والقطاعات الاقتصادية المشاركة وبيانات تنفيذ المشاريع الممَّولة من\n جهات مانحة وغيرها ،وذلك في قاعدة بيانات مركزية لديها ،بشكل يتيح سهولة قراءة وتحليل هذه البيانات\n والمستندات وبحسب المعايير الدولّيـة المعتمدة في هذا المجال؛\n .12حفظ وتحديث سجلات العقود العامة ونشرها على المنصة الإلكترونّيـة المركزّيـة الُمعتمدة ،مع مراعاة\n السرية بالنسبة للعقود العامة المتعِّلقة بالأمن والدفاع الوطني ومراعاة أحكام المادة السادسة من هذا\n القانون؛\n التخطيط\n الفعالّيـة والدمج في\n63 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\f .13حفظ قرارات الإقصاء في سج ّ\nل علني خاص وتدوين ملاحظاتها عليها إن ُوِجدت ,وتضمينها في تقاريرها.\n ُين َ\n شر سج ّ\nل الإقصاء على المنصة الإلكترونّيـة المركزّيـة المعتمدة ,وتكون هيئة الشراء العام مسؤولة عن\n تحديث هذا السجل بحسب"}, {"o": 174, "l": "المادة 40", "b": "المادة 40من هذا القانون؛\n .14التحّقق من مؤهلات أعضاء لجان التلزيم والاستلام لدى الجهات الشارية وتضمين تقاريرها ،عند الاقتضاء،\n مدى مطابقة هذه المؤهلات لشروط الخبرة والاختصاص المطلوبة؛\n .15معالجة وتحليل المعلومات الخاصة بعمليات الشراء العام ،ووضع وإصدار معايير الأداء وتحرير تقارير\n تحليلية وإحصائية ونشرها؛\n .16إصدار مستندات ونماذج معيارية لإجراءات الشراء العام بما فيها دفاتر الشروط النموذجية وملفات التأهيل\n النموذجية ،وتوفيرها للجهات الشارية لاعتمادها إلزامياً؛\n .17اقتراح أنظمة لتطبيق التدقيق الداخلي فيما يتعَّلق بإجراءات الشراء وعملياته لدى الجهات الشارية؛\n .18وضع شرعة قواعد السلوك والأخلاق المهنية الخاصة بعمليات الشراء العام المنصوص عليها في"}, {"o": 175, "l": "المادة 10", "b": "المادة\n 10من هذا القانون؛\n .19وضع الإرشادات والكتّيبات والتوضيحات في ما يتعّلق بقواعد وإجراءات الشراء العام وتقديم النصح والمساعدة\nحدة المعتمدة؛\n والخبرات للجهات الشارية والعارضين المحتملين ،وتوفير المعلومات عبر المنصة الإلكترونّيـة المو ّ\n .20اقتراح سياسة التدريب المتعّلقة بالشراء العام مع الأخذ بالاعتبار الأولويات وحاجات الجهة الشارية\n والخبرات الوطنّية المتوافرة والممارسات الدولّية الجّيدة؛\n .21تقديم اقتراحات وتوصيات إلى الجهات المعنّية حول وسائل وسبل التطوير والتشجيع على الابتكار في\nالشراء العام وتحفيز المؤسسات الصغيرة والمتوسطة على المشاركة في الشراء وتحسين التطبيقات\n واقتراح تعديل الأنظمة والقوانين؛\n .22تقديم التوصيات المتعِّلقة بتعديل السقوف المالّيـة الواردة في هذا القانون إلى مجلس الوزراء عبر رئيسه؛\n .23استطلاع رأي الجمهور والقطاع الخاص عند اقتراح تعديلات تنظيمية أو قانونية على منظومة الشراء العام\nم اعتمادها ِبنشر مشاريع التعديل على المنصة الإلكترونّيـة المركزّيـة ،على سبيل\n وشرح الخيارات التي ت ّ\n المثال لا الحصر ودعوة العموم لإبداء الاقتراحات والملاحظات؛\n .24التعاون مع المؤسسات الدولّيـة والهيئات الأخرى محلياً ودولياً لتطوير منظومة الشراء العام؛\n .25وضع تقارير دورية عند الإقتضاء وتقرير سنوي عن سير عمل الهيئة ُيبَّلغ إلى مجلس النواب ومجلس\n الوزراء والجهات الرقابية وُتن َ\n شر للعموم."}, {"o": 176, "l": "المادة 77", "b": "المادة | 77صلاحيات رئيس الهيئة\n ُتناط برئيس الهيئة الصلاحيات التالية:\n .1ترّؤس الجهاز الإداري بصفته رئيساً للهيئة والرئيس التسلسلي للعاملين فيها؛\n .2تمثيل الهيئة تجاه الغير وأمام القضاء والتوقيع عنها؛\n .3الدعوة إلى الاجتماعات غير العادية عند الاقتضاء ،وإعداد جداول أعمال جميع الاجتماعات والتحضير لها\n وإدارتها؛\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 64\n\f وفقاً لأحكام\n .4تحريك حساب الهيئة لدى مصرف لبنان بالاتحاد مع المحتسب أو المدير المالي للهيئةِ ،\n نظامها المالي؛\n .5السهر على تنفيذ القرارات وتطبيق الأحكام المرعّية الإجراء ذات الصلة وإدارة الهيئة وتسيير أعمالها\n اليومية؛\n .6إعداد مشروع موازنة سنوية للهيئة وفقاً للقوانين والأنظمة النافذة؛\n .7انتداب كلما دعت الحاجة ممثّل عن الهيئة لحضور جلسات التلزيم التي تجري في الجهة الشارية بصفة\n مرا ِ\n قب ولا يكون له حق التصويت؛ ُ\n ي مرجع آخر مختص؛\n ق بتقديم الطعون لدى هيئة الاعتراضات والمراجعات أمام مجلس شورى الدولة وأ ّ\n .8الح ّ\n .9إحالة المشاريع والآراء والتوصيات والقرارات والتقارير الدورية التي ينص عليها القانون إلى المراجع\n الدستورية والإدارية والرقابية المختصة."}, {"o": 177, "l": "المادة 78", "b": "المادة | 78شروط وآلية تعيين رئيس وأعضاء الهيئة\n مع مراعاة شروط التعيين المنصوص عليها في المادة الرابعة من المرسوم الاشتراعي رقم 59/112تاريخ\n ) 1959/6/12نظام الموظفين( وتعديلاته باستثناء شر َ\n طي السن والمباراةُ ،تعَتَمد الشروط والآلية التالية لتعيين\n رئيس وأعضاء الهيئة:\n أ .أن يكونوا حائزين على شهادة ماجستير على الأقل في الشراء العام أو في الادارة العامة أو العلوم\n المالّية أو بالاقتصاد أو الحقوق أو الهندسة أو العلوم السياسية والادارية ،أو إدارة الأعمال أو الإدارة\n المالّيـة أو تكنولوجيا المعلومات؛\n ب .أن يتّمتعوا بخبرة مثبتة في مجال الشراء العام لا تقل عن 10سنوات.\n جُ .يِعّد مجلس الخدمة المدنّيـة الإعلان لملء مركز رئيس وأعضاء الهيئة والمتضِّمن المؤهلات والشروط\n الواجب توافرها بالإضافة إلى معايير تقييم المرشحين التي تعُّدها اللجنة المشار إليها في النبذة “ز”،\n وينشره على الموقع الإلكتروني للمجلس على أن یتضمن النشر مهلة تقدیم طلبات الترشیح.\n دُ .تقَّدم طلبات الترشیح من قبل من تتوافر فیهم المؤهلات والشروط ضمن المهلة المحددة وذلك عبر\n حدة موجودة على الموقع الإلكتروني الخاص بمجلس الخدمة المدنية على ألا\n استمارة إلكترونیة مو ّ\n ُتقَبل طلبات الترشیح المقَّدمة بالید أو خلافاً لذلك.\n هـ .يتوّلى مجلس الخدمة المدنّيـة قبول الطلبات المستوفية الشروط والمواصفات وفقاً للفقرة الأولى\n من هذه المادة.\n وُ .یِعّد مجلس الخدمة المدنّيـة تقریرا ً َیتضّمن اللوائح الرقمیة لطلبات الترشیح المقبولة ،ولوائح إسمیة\n م إیداعها لجنة اختيار المرشحين المشار\n لطلبات الترشیح غیر المقبولة مع تبیان أسباب عدم قبولها ،ویت ّ\n إليها في النبذة ”ز” أدناه من هذه الفقرة.\n زُ .تقّيم طلبات الترشيح المقبولة من قبل لجنة مؤلفة من:\n • رئيس الهيئة الوطنّية لمكافحة الفساد\n التخطيط\n الفعالّيـة والدمج في"}, {"o": 178, "l": "المادة 78", "b": "65 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\f • رئيس ديوان المحاسبة\n • رئيس مجلس الخدمة المدنية\n • رئيس التفتيش المركزي\n يتوّلى رئيس مجلس الخدمة المدنية تنسيق وإدارة أعمال هذه اللجنة.\nوفقاً لمعاییر الاختصاص والمؤِّهلات والشهادات وسنوات الخبرة\n حُ .تقَّيم طلبات الترشيح المقبولة ِ\nم ضع بنتیجتها العلامات وفقاً لمعّد ٍ\nل عام یت ّ وتنُّوعها وإتقان اللغات الأجنبیة وغیرها من المعايير ،وتو َ\nالتوافق علیه وُیصار على أساسه إلى وضع لائحة بأسماء المرشحین المقبولين لمرحلة المقابلة\n الشفهية مع تبیان أسباب عدم قبول الطلبات الأخرى ،على أن ُتِعّد اللجنة تقریرا ً بنتائج عملها.\nمعَلنة حتى تحديد موعد إجراء المقابلات الشفهیةُ .تجرى ط .تبقى أسماء المر ّ\n شحین المقبولین غیر ُ\nالمقابلات الشفهیة مع المرشحین المقبولة طلباتهم من قبل لجنة الاختيار وذلك في اجتماع ُیحَّدد\n لهذه الغایة على أن ُتجرى المقابلات في مجلس الخدمة المدنیة.\n ي .يقترح رئيس مجلس الوزراء أسماء الناجحين في المقابلة الشفهّيـة لك ّ\nل منصب وفقاً لترتیب العلامات،\nلعرضها على مجلس الوزراء لُيصار إلى اختيار من يعِّينهم ،وذلك بعد تقديم المستندات الُمثِبتة لتوافر\n الشروط والتثُّبت من حيازة المر ّ\n شح لها ومن صحتها."}, {"o": 179, "l": "المادة 79", "b": "المادة | 79حالات التمانع والتفّرغ\n .1يلتزم رئيس وأعضاء الهيئة ،طيلة مدة ولايتهم وحتى بعد انتهائها ،بالسرية المهنية بالنسبة لكل\nالمعلومات التي اطلعوا عليها بمناسبة قيامهم بمهامهم أو بسببها ،وُيمنع عنهم الإفصاح عنها إّلا أمام\nالأجهزة الرقابية والقضائية .يشمل هذا الموجب المعلومات التي ُتصِّنفها الهيئة على أنها سرية وفقاً\n لأنظمتها وقراراتها.\n .2يقتضي أن يكون ك ّ\n ل من الرئيس والأعضاء متفِّرغاً.\n .3لا يجوز تعيين رئيس وأعضاء الهيئة من ضمن الفئات الآتية:\nأ .من يكون له أية مصلحة مباشرة أو غير مباشرة في أية شركة أو مؤسسة مشاِركة في الشراء العام أو\n مع أية جهة شارية.\n ب .من أعلن توُّقفه عن الدفع أو أ ُعِلن إفلاسه قضائياً.\n ج .من صدر بحِّقه قرار تأديبي قضى بعقوبة غير التنبيه أو اللوم.\nي عمل آخر عام أو خاص مأجور أو غير مأجور خلال توّليهم ُ .4يح َّ\n ظر على رئيس وأعضاء الهيئة ممارسة أ ّ\nمهامهم ،بما فيه ،على سبيل المثال ،رئاسة أو عضوية الوزارة أو مجلس النواب ،ورئاسة أو عضوية\nمجلس إدارة مؤسسة عامة أو شركة خاصة أو مصرف ،ورئاسة أو عضوية هيئة عامة ،ورئاسة أو عضوية\n مجلس بلدي أو شركة خاصة تتوّلى إدارة مرفق عام.\nُ .5يمَنع على رئيس وأعضاء الهيئة خلال مدة ولايتهم وبعد مدة لا تقل عن السنتين من انتهائها ،أن يتوّلوا\nي موقع مسؤولية في الشركات التي تكون قد شاركت بإجراءات شراء ضمن\n بشكل مباشر أو غير مباشر أ ّ\n إطار هذا القانون خلال فترة توّليهم صلاحياتهم.\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 66\n\f جب على كل من الرئيس وأعضاء هيئة الشراء العام الإفصاح خطياً على أ ّ\n ي مستجدات من شأنها التأثير َ .6يتو َّ\n على عضويته وفقاً لأحكام هذا القانون .في حال إخلال أ ّ\n ي عضو بهذا الموجب تطَّبق بحقه الأحكام المرعية\n الإجراء.\n َ .7يحُلف ك ّ"}, {"o": 180, "l": "المادة 79", "b": "ل من الرئيس والأعضاء أمام رئيس الجمهورية وقبل ممارسته مهامه ،اليمين القانونية التالية:\n “أقسم بالله العظيم بأن أؤّدي واجباتي بأمانة واستقلال واخلاص ،وأن أكون حريصاً على تطبيق القوانين\n والأنظمة ،وأن أحافظ على أسرار الوظيفة وكرامتها”."}, {"o": 181, "l": "المادة 80", "b": "المادة | 80اجتماعات الهيئة\n َ .1تجَتمع الهيـئة بشكل دوري ،مرة واحدة على الأقل ك ّ\n ل أسبوع دون الحاجة إلى توجيه دعوة من رئيسها\n وَتَّتخذ قراراتها بالأغلبية.\n ُ .2يحَّدد موعد الاجتماع الدوري في الجلسة الأولى التي تعقدها ،وفي حال عدم انعقاد الاجتماع لأي سبب\n كان َينعقد الاجتماع في اليوم الذي يليه.\n صص جدول أعمال الجلسات الدورية المذكورة للبحث في شؤون أعمال الهيئة وبأي مواضيع ُتطرح من\n ُ .3يخ َّ\n ي من الأعضاء.\n قبل الرئيس أو أ ّ\n ُ .4يِعّد الرئيس جدول الأعمال وُيبِّلغه إلى الأعضاء قبل موعد الاجتماع بيومين على الأقل.\n ُ .5يبَّلغ جدول الأعمال إلى الأعضاء بأي وسيلة مناسبة بما في ذلك البريد الإلكتروني.\n .6في حال غياب الرئيس ،يترأس اجتماع الهيئة العضو الأكبر سناً.\n ي من الأعضاء دون عذر مشروع عن حضور ثلاثة اجتماعات متتالية أو عن حضور ستة\n .7إذا َتغَّيب الرئيس أو أ ّ\n معفّياً من مهامه حكماً. اجتماعات خلال السنةُ ،يعتَبر مستقي ً\n لا أو َ"}, {"o": 182, "l": "المادة 81", "b": "المادة | 81انتهاء العضوية\n ي من الأعضاء الأربعة بانتهاء المدة المحّددة وفقاً للمادة 75من هذا القانون أو\n .1تنتهي ولاية الرئيس وأ ّ\n بالوفاة أو بالاستقالة أو بفقدان الأهلية أو أي شرط من شروط التعيين أو التمانع أو التفّرغ ،أو إذا حاَل\n وضعه الصحي أو العقلي دون قيامه بمهامه ،أو بمرسوم ُيّتخذ في مجلس الوزراء بناء على اقتراح رئيس\n مجلس الوزراء عند إخلالهم بواجباتهم الوظيفة ،بعد أن تتحّقق من ذلك هيئة مؤّلفة من رئيس الهيئة\n الوطنّية لمكافحة الفساد ،ورئيس مجلس الخدمة المدنّيـة ،ورئيس ديوان المحاسبة وبقرار تتخذه بالأكثرية\n بناًء على إحالة رئيس التفتيش المركزي بهذا الشأن.\n .2في حال شغور مركز الرئيس ينوب عنه العضو الأكبر سناً .يقوم مجلس الوزراء بملء الشغور خلال مهلة\n شهر واحد على الأكثر ووفقاً لقواعد التعيين المحددة في هذا القانون.\n التخطيط\n الفعالّيـة والدمج في\n67 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية"}, {"o": 183, "l": "المادة 82", "b": "المادة | 82التعويضات\n يتقاضى ك ّ\nل من رئيس الهيئة والأعضاء تعويضات شهرية مقطوعة ُتحَّدد بمرسوم ُيَّتخذ في مجلس الوزراء\n بناًء على اقتراح رئيس مجلس الوزراء."}, {"o": 184, "l": "المادة 83", "b": "المادة | 83مالية الهيئة\n .1يكون للهيئة موازنة مستقلة وتتأّلف مواردها المالّيـة مما يلي:\nأ .مساهمة مالية سنوية خاصة ُتدَرج في فصل خاص ضمن باب رئاسة مجلس الوزراء في قانون الموازنة\n العامة للدولة وتكون كافية لتغطية مصاريف الهيئة ونشاطاتها؛\n ب .المنح والهبات غير المشروطة من المؤسسات الدولّيـة المانحة مع مراعاة تضارب المصالح؛\n ي موارد منصوص عليها في قوانين أخرى وغير ملحوظة بموجب هذه المادة.\n ج .أ ّ\n .2توَدع أموال الهيئة في حساب خاص لدى مصرف لبنان ،ويتوّلى رئيس الهيئة عقد نفقاتها وفق الأصول\n المنصوص عليها في قانون المحاسبة العمومية والقوانين والأنظمة المرعّيـة الإجراء.\n .3تضع الهيئة مشروع موازنة سنوية وفقاً للقوانين والأنظمة النافذة ويحَّدد في نظامها المالي كيفية\n إعداد الموازنة وآلية الإنفاق وسائر المسائل المالّيـة المتعلقة بسير عملها.\nُ .4يفَتح اعتماد إضافي في الموازنة العامة للهيئة للسنة التشغيلية الأولى بعد صدور هذا القانون وفقاً\n للأصول."}, {"o": 185, "l": "المادة 84", "b": "المادة | 84علانية المعطيات\nَ .1تضع الهيئة بمتناول الجمهور بالوسائل الرقمية و/أو الورقية المتاحة جميع المعطيات والمستندات\nوالسجلات والبيانات مع مراعاة السرية بالنسبة للعقود العامة المتعلقة بالأمن والدفاع الوطني ومراعاة\n أحكام المادة السادسة من هذا القانون.\nَ .2تنشر الهيئة عند نهاية كل سنة مالية على المنصة الإلكترونّيـة المركزّيـة لديها ،على الأقل ،بياناً حول\n وضعية الأصول والموجودات لديها وخلاصة عن موازنتها."}, {"o": 186, "l": "المادة 85", "b": "المادة | 85قرارات الهيئة\n .1تخضع قرارات الهيئة لمبدأ التعليل ،وعلى الهيئة أن ُتبِّين في حيثيات القرار الُمَّتخذ أسبابه وأهدافه.\n .2لا تصبح قرارات الهيئة نافذة إلا من تاريخ تبليغها أو نشرها وفقاً لأحكام هذا القانون.\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 68"}, {"o": 187, "l": "المادة 86", "b": "المادة | 86طرق المراجعة في قرارات الهيئة\n .1يعود لكل صاحب مصلحة الحق في الطعن على القرارات المتعِّلقة بعمليات الشراء العام الصادرة عن\n الهيئة وفقاً لأحكام الفصل السابع من هذا القانون.\n .2تكون سائر القرارات الإدارية الصادرة عن الهيئة أو المتكِّونة بوجهها وغير المتعّلقة بإجراءات الشراء العام،\n قابلة للمراجعة أمام مجلس شورى الدولة في حال توافر الشروط القانونية لذلك."}, {"o": 188, "l": "المادة 87", "b": "المادة | 87النظام الداخلي والأنظمة الإدارية وأنظمة العاملين\n ضع الهيئة نظامها الداخلي والأنظمة الإدارية والمالّيـة وأنظمة العاملين لديها ،بعد استشارة مجلس الخدمة\n َت َ\n المدنية ومجلس شورى الدولة ،في مهلة أقصاها ثلاثة أشهر من تاريخ إنشائها ،على أن َتصدر بموجب\n خذ في مجلس الوزراء بناًء على اقتراح رئيس مجلس الوزراء ،وذلك خلال مهلة أقصاها شهران من\n مراسيم ُتَّت َ\n تاريخ إحالة مشاريع المراسيم إليه من قبل الهيئة."}, {"o": 189, "l": "المادة 88", "b": "المادة | 88أحكام انتقالية\n ُ .1تلغى إدارة المناقصات وُتنقل ملاكاتها والعاملون فيها إلى هيئة الشراء العام دون تعديل في الرتبة\n والراتب مع احتفاظهم بحقهم في القدم المؤّهل للتدرج على أن تتوافر فيهم شروط التعيين المحددة في\n المادة الرابعة من المرسوم الاشتراعي رقم 59/112تاريخ ) 1959/6/12نظام الموظفين( وتعديلاته\n باستثناء شر َ\n طي السن والمباراة .ويكون مدير عام إدارة المناقصات رئيساً للهيئة ،كما يكون الموظفون\n والمتعاقدون والأجراء الحاليون في إدارة المناقصات من ضمن الهيكل الاداري لهيئة الشراء العام.\n .2إلى حين تعيين الهيئة ،يتوّلى رئيس الهيئة مهامها.\n البند الثاني | هيئة الاعتراضات"}, {"o": 190, "l": "المادة 89", "b": "المادة | 89إنشاء هيئة الاعتراضات\n ت الإعتراضات\n ُ .1تنشأ بموجب هذا القانون هيئة مستقلة تسمى “هيئة الاعتراضات الإدارية” ُتعنى بب ّ\n ي من الجهات\n الُمقّدمة بشأن الإجراءات أو القرارات الصريحة أو الضمنية الصادرة عن الجهة الشارية أو أ ّ\n المعنّيـة الادارية بعملَيـة الشراء أو المتكّونة بوجهها ،بما في ذلك ملفات التلزيم.\n َ .2تنظر الهيئة ،دون سواها وبصورة حصرّيـة في الاعتراضات بشأن القرارات الصريحة أو الضمنية المتعّلقة\n باجراءات الشراء المقّدمة إليها مباشرًة في المرحلة السابقة لتوقيع العقد ،وذلك خلافاً لأي نص آخر.\n التخطيط\n الفعالّيـة والدمج في\n69 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\f .3لا تخضع الهيئة لأحكام المرسوم رقم 4517تاريخ ) 1972/12/13النظام العام للمؤسسات العامة( غير أنها\nتخضع لأحكام هذا القانون ولرقابة ديوان المحاسبة المؤخرة ولرقابة التفتيش المركزي ومجلس الخدمة المدنية."}, {"o": 191, "l": "المادة 90", "b": "المادة | 90تشكيل الهيئة\nُ .1تشَّكل الهيئة من رئيس وثلاثة أعضاء ُيعَّينون بموجب مرسوم ُيَّتخذ في مجلس الوزراء بناًء على اقتراح\n رئيس مجلس الوزراء وفقاً لشروط وآلية التعيين المف َّ\nصلة في"}, {"o": 192, "l": "المادة 91", "b": "المادة 91أدناهُ .تحَّدد ولاية كل من الرئيس\n والأعضاء الثلاثة بأربع سنوات قابلة للتجديد مرة واحدة فقط.\n ون الهيئة في مهامها جهاز إداري متخصص.\n ُ .2يعا ِ"}, {"o": 193, "l": "المادة 91", "b": "المادة | 91شروط وآلية تعيين رئيس وأعضاء هيئة الاعتراضات\n .1مع مراعاة شروط التعيين المنصوص عليها في المادة الرابعة من المرسوم الاشتراعي رقم 59/112تاريخ\n) 1959/6/12نظام الموظفين( وتعديلاته باستثناء شرطَي السن والمباراةُ ،تعتمد الشروط التالية لتعيين\n رئيس وأعضاء الهيئة:\nأ .أن يكونوا حائزين على شهادة ماجستير على الأقل في القانون أو الشراء العام أو في الإدارة العامة\nأو العلوم المالّيـة أو بالاقتصاد أو الحقوق أو الهندسة أو العلوم السياسية والإدارية ،أو إدارة الأعمال\n أو الإدارة المالّيـة أو تكنولوجيا المعلومات أو ما يعادلها؛\n مثََّبـتة لا تقل عن 10سنوات في المجالات المتعلِّقة بالشراء العام.\n ب .أن يتّمتعوا بخبرة ُ\n .2كما ُتعَتَمد آلية التعيين المنصوص عليها في"}, {"o": 194, "l": "المادة 78", "b": "المادة 78من هذا القانون لتعيين رئيس وأعضاء الهيئة.\n ُ .3يعَّين الموظفون في الجهاز الإداري حسب الأصول."}, {"o": 195, "l": "المادة 92", "b": "المادة | 92حالات التمانع والتفّرغ\nَ .1يلتِزم رئيس وأعضاء الهيئة ،طيلة مدة ولايتهم وحتى بعد انتهائها ،بالسرية المهنية بالنسبة لكل\nالمعلومات التي اطّلعوا عليها بمناسبة قيامهم بمهامهم أو بسببها ،وُيمَنع عنهم الإفصاح عنها إّلا أمام\nالأجهزة الرقابية والسلطة القضائية .يشمل هذا الموجب المعلومات التي ُتصّنفها الهيئة على أنها سرية\n وفقاً لأنظمتها وقراراتها.\n .2يقتضي أن يكون ك ّ\n ل من الرئيس والأعضاء متفّرغاً.\n .3لا يجوز تعيين رئيس وأعضاء الهيئة من ضمن الفئات الآتية:\nأ .من يكون له أية مصلحة مباشرة أو غير مباشرة في أية شركة أو مؤسسة مشاركة في الشراء العام أو\n مع أية جهة شارية.\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 70\n\f ب .من أَعلن توُّقفه عن الدفع أو أ ُعِلن إفلاسه قضائياً.\n ج .من صدر بحقه قرار تأديبي قضى بعقوبة غير التأنيب أو التنبيه أو اللوم في ما خص أعضاء الهيئة من\n القطاع العام.\n ي عمل آخر عام أو خاص مأجور أو غير مأجور خلال توّليهم ُ .4يح َّ\n ظر على رئيس وأعضاء الهيئة ممارسة أ ّ\n مهامهم ،بما فيه ،على سبيل المثال ،رئاسة أو عضوية الوزارة أو مجلس النواب ،ورئاسة أو عضوية\n مجلس اإدارة مؤسسة عامة أو شركة خاصة أو مصرف ،ورئاسة أو عضوية هيئة عامة ،ورئاسة أو عضوية\n مجلس بلدي أو شركة خاصة تتوّلى إدارة مرفق عام.\n جب على كل من رئيس وأعضاء هيئة الاعتراضات الإفصاح خطياً عن أي مستجدات من شأنها التأثير على\n َ .5يتو َّ\n عضويته وفقاً لأحكام هذا القانون .في حال إخلال أ ّ\n ي عضو بهذا الموجب تطَّبق بحقه الأحكام المرعية الإجراء.\n َ .6يحُلف ك ّ\n ل من رئيس وأعضاء الهيئة أمام رئيس الجمهورية وقبل ممارسته مهامه ،اليمين القانونية التالية:\n “أقسم بالله العظيم بأن أؤّدي واجباتي بأمانة واستقلال واخلاص ،وأن أكون حريصاً على تطبيق القوانين\n والأنظمة ،وأن أحافظ على أسرار الوظيفة وكرامتها”."}, {"o": 196, "l": "المادة 93", "b": "المادة | 93انتهاء العضوية\n ي من الأعضاء الثلاثة في إحدى الحالتين التاليتين:\n .1تنتهي ولاية الرئيس وأ ّ\n أ .بانتهاء المدة المحددة وفقاً للمادة 90من هذا القانون أو بالوفاة أو بالاستقالة أو فقدان الأهلية أو أي\n شرط من شروط التعيين أو التمانع أو التفّرغ ،أو إذا حاَل وضعه الصحي أو العقلي دون قيامه بمهامه\n خذ في مجلس الوزراء بناًء على اقتراح رئيس مجلس الوزراء؛\n وُيكَّرس ذلك بمرسوم ُيَّت َ\n خذ في مجلس الوزراء بناًء على اقتراح رئيس مجلس\n ب .عند إخلالهم بواجباتهم الوظيفّيـة بمرسوم ُيَّت َ\n الوزراء ،بعد أن تتحّقق من ذلك هيئة مؤّلفة من رئيس الهيئة الوطنّيـة لمكافحة الفساد ،ورئيس مجلس\n الخدمة المدنّيـة ،ورئيس ديوان المحاسبة وبقرار تّتخذه بالأكثرية بناًء على إحالة رئيس التفتيش المركزي\n بهذا الشأن.\n .2في حال شغور مركز الرئيس ينوب عنه العضو الأكبر سناً .يقوم مجلس الوزراء بملء الشغور خلال مهلة\n شهر واحد على الأكثر ووفقاً لقواعد التعيين المحّددة في هذا القانون.\n ي من الأعضاء مستقي ً\n لا أو معفياً من مهامه حكماً إذا تغَّيب دون عذر مشروع عن حضور ُ .3يعتَبر الرئيس أو أ ّ\n ثلاثة جلسات متتالية أو عن حضور ستة جلسات خلال السنة."}, {"o": 197, "l": "المادة 94", "b": "المادة | 94التعويضات\n يتقاضى ك ّ\n ل من رئيس الهيئة والأعضاء تعويضات شهرية مقطوعة ُتحَّدد بمرسوم ُيَّتخذ في مجلس الوزراء\n بناء على اقتراح رئيس مجلس الوزراء.\n التخطيط\n الفعالّيـة والدمج في\n71 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية"}, {"o": 198, "l": "المادة 95", "b": "المادة | 95مالية هيئة الاعتراضات\n .1يكون لهيئة الاعتراضات موازنة مستقلة وتتأّلف مواردها المالّية مّما يلي:\nأ .مساهمة مالية سنوية ُتدرج في فصل خاص ضمن باب رئاسة مجلس الوزراء في قانون الموازنة\n العامة للدولة.\n ب .الرسوم المستوفاة تطبيقاً لنظامها الداخلي ،في حال اعتماد استيفاء رسوم.\n ي موارد منصوص عليها في قوانين أخرى وغير ملحوظة بموجب هذه المادة.\n ج .أ ّ\nضع الهيئة مشروع موازنتها وفقاً للقوانين والأنظمة النافذة ،وُيحَّدد في نظامها المالي كيفية إعداد\n َ .2ت َ\n الموازنة وآلية الانفاق وسائر المسائل المالّيـة المتعلقة بسير عملها.\n .3توَدع أموال هيئة الاعتراضات في حساب خاص لدى مصرف لبنان ،وَيتولى رئيس الهيئة عقد نفقاتها وفق\n الأصول المنصوص عليها في قانون المحاسبة العمومية والقوانين المرعية الإجراء.\nُ .4يفَتح اعتماد إضافي في الموازنة العامة للهيئة للسنة التشغيلية الأولى بعد صدور هذا القانون وفقاً للأصول."}, {"o": 199, "l": "المادة 96", "b": "المادة | 96آلية عمل الهيئة\nل ملف اعتراض لجنة مصّغرة تسمى “لجنة الاعتراضات” يرأسها هو وتتأّلف من\n ُ .1يشِّكل الرئيس لك ّ\n عضَوين من الأعضاء الثلاثة الذين تتأّلف منهم هيئة الاعتراضات بحسب الاختصاص.\nم\nُ .2يمكن للهيئة أن تستعين بخبرات من القطاع الخاص بحسب نوع ملف الاعتراض وطبيعة عملية الشراء .يت ّ\nاختيار الخبير من القطاع الخاص بحسب الاختصاص وبالقرعة من بين جداول الخبراء المعنيين بموضوع الشراء\nصل عليها بحسب الآلية المنصوص عليها في الفقرة 5أدناه ،وذلك بحضور\n المعتَرض عليه والتي ُيستح َ\nأعضاء الهيئة ،على أن لا ُيستعان بالخبير من القطاع الخاص نفسه أكثر من ثلاث مّرات متتالية ،ومع التقيّد\nبموجب عدم تضارب المصالح .في هذه الحالُ ،يعّد الخبير تقريره بحسب الحالة وَيرفعه إلى لجنة الاعتراضات.\n .3يرأس الرئيس هيئة الاعتراضات بالإضافة إلى جميع اللجان ويدير اجتماعاتها ومناقشاتها.\nَ .4تنظر لجان الاعتراضات في الشكاوى المقَّدمة أمامها وَتَّتخذ قراراتها بالأكثرّيـة وعليها أن تعِّلل هذه\nصل عناصرها التقنية والواقعية وتبِّين الأسباب التي استندت إليها ،وفقاً لأحكام الفصل\n القرارات وتف ِّ\nالسابع من هذا القانون .في حال الاستعانة بخبير من القطاع الخاص ومخالفة رأيه من قبل اللجنة ،عليها\n عندئذ أن تعِّلل الأسباب التي دفعتها إلى عدم الأخذ برأيه.\n َ .5يستح ِ\nصل رئيس هيئة الاعتراضات قبل شهر تشرين الأول من كل سنة على جداول الخبراء الإسمية مرفقة\n بالسير الذاتية من ك ّ\nل من نقابة المحامين في بيروت ونقابة المحامين في طرابلس ونقابَتي المهندسين\nفي بيروت وطرابلس ونقابَتي الأطباء في بيروت وطرابلس ونقابة العلوم المعلوماتية وجمعية الصناعيين\nونقابة مقاولي الأشغال العامة والبناء ونقابة الصيادلة ونقابة خبراء المحاسبة المجازين واتحاد غرف التجارة"}, {"o": 200, "l": "المادة 96", "b": "والصناعة والزراعة في لبنان وغيرها من النقابات المهنية على أن يكون هؤلاء من اصحاب الشهادات\nالعلمية الجامعية وذوو الخبرة المثبتة في مجال اختصاصهم والسمعة الحسنة والأخلاق المهنية العالية\n ويختار من بينهم بالقرعة ،عند الاقتضاء ،الخبير من القطاع الخاص بحسب الاختصاص وموضوع الاعتراض.\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 72\n\f ي من خبراء أو ممثّلي القطاع الخاص في حال ثَُبـتت ملاحقتهم أو الحكم عليهم بأ ّ\n ي جنحة أو .6لا يجوز اختيار أ ّ\n جناية أو عقوبة مسلكية أو في حال تضارب المصالح أو في حال أ ُعلن إفلاسهم."}, {"o": 201, "l": "المادة 97", "b": "المادة | 97النظام الداخلي والأنظمة الإدارية وأنظمة العاملين\n ضع الهيئة نظامها الداخلي والأنظمة الإدارية والمالّية وأنظمة العاملين لديها ،بعد استشارة مجلس الخدمة\n َت َ\n المدنية ومجلس شورى الدولة ،في مهلة أقصاها ثلاثة أشهر من تاريخ إنشائها ،على أن َتصدر بموجب\n مراسيم ُتّتخذ في مجلس الوزراء بناًء على اقتراح رئيس مجلس الوزراء ،وذلك خلال مهلة أقصاها شهران من\n تاريخ إحالة مشاريع المراسيم إليه من قبل الهيئة."}, {"o": 202, "l": "المادة 98", "b": "المادة | 98التقارير\n ُ .1تِعّد الهيئة تقريرا ً سنوياً ُتبِّين في متنه المسائل المطروحة أمامها وطريقة معالجتها والتوصيات المقترحة،\n وُين َ\n شر حسب الأصول ،وَترفع نسخة عنه إلى مجلس النواب ورئيس ديوان المحاسبة ورئيس مجلس\n الخدمة المدنية ورئيس التفتيش المركزي ورئيس هيئة الشراء ورئيس الهيئة العليا للتأديب.\n .2ترفع الهيئة تقارير دورية إلى الهيئات الرقابية بحسب موضوع المخالفات إن كانت مخالفات مالية أو\n وظيفية مرفقة بتوصياتها."}, {"o": 203, "l": "المادة 99", "b": "المادة | 99السرية\n يلتزم رئيس وأعضاء الهيئة بالمحافظة على سرّيـة المداولات بما لا يتعارض مع أحكام هذا القانون.\n البند الثالث | لجان التلزيم والاستلام"}, {"o": 204, "l": "المادة 100", "b": "المادة | 100لجان التلزيم :تشكيلها ومهامها\n أو ً\n لا :تشكيل لجان التلزيم\n .1تتألف لجنة التلزيم لدى الجهة الشارية من رئيس وعضَوين أصيَلين على الأقل ومن رئيس وعضَوين\n رديَفين يكّملان اللجنة عند غياب الرئيس أو أحد الأعضاء ،على أن يكون عدد أعضائها دائماً مفردا ً .يجب أّلا\n يكون الرئيس أو الأعضاء في حالة تضارب مصالح مع المشاركين في إجراءات الشراء ،وأن تتصّرف اللجنة\n ل عن الجهة الشارية في ك ّ\n ل أعمالها وقراراتها. بشكل مستق ّ\n التخطيط\n الفعالّيـة والدمج في\n73 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\f .2يتم تأليف لجان التلزيم لدى الجهات الشارية من أهل الخبرة والاختصاص وفقاً لأسس تضعها هيئة الشراء\n العام على أن تكون الأولوية في تشكيل هذه اللجان للأشخاص المدرّبين على الشراء العام.\n ثانيًا :مهام لجنة التلزيم\n .1تتوّلى لجان التلزيم حصرا ً دراسة ملفات التأهيل المسبق وفتح وتقييم العروض ،وبالتالي تحديد العرض\n الأنسب.\nي وض ع\n حى عن مهامه في اللجنة المذكورة في حال وقع بأ ّ .2على رئيس اللجنة وعلى ك ٍّ\n ل من أعضائها أن يتن ّ\n من أوضاع تضارب المصالح أو توَّقع الوقوع فيه ،وذلك فور معرفته بهذا التضارب.\n .3يمكن للجنة التلزيم الاستعانة بخبراء من خارج أو داخل الإدارة للمساعدة على التقييم الفني والمالي عند\nالإقتضاء ،وذلك بقرار من المرجع الصالح لدى الجهة الشارية .يخضع اختيار الخبراء من خارج الإدارة إلى\nأحكام هذا القانون .يلتزم الخبراء السرية والحياد في عملهم ولا يحق لهم أن يقِّرروا بإسم اللجنة أو أن\nيشاركوا في مداولاتها أو أن يفصحوا عنها علانية ،ويمكن دعوتهم للاستماع والشرح من قبل الجهات\n م إلزامياً إلى محضر التلزيم.\n ض ّ\n جب على الخبراء تقديم تقرير خطي للجنة ُي َ\n المعنّيـة .كما يتو ّ\nي عضو مخالف"}, {"o": 205, "l": "المادة 100", "b": ".4في حال التباين في الآراء بين أعضاء اللجنة ،تؤخذ القرارات بأغلبية أعضائها وُيدِّون أ ّ\n أسباب مخالفته."}, {"o": 206, "l": "المادة 101", "b": "المادة | 101لجان الاستلام :تشكيلها ومهامها\n .1يتم تأليف لجان الاستلام لدى الجهات الشارية من أهل الخبرة والاختصاص وفقاً لأسس تضعها هيئة\n الشراء العام على ان تكون الأولوية في تشكيل هذه اللجان للأشخاص المدرّبين على الشراء العام.\nُ .2تعَّين لجنة الاستلام لكل عملية شراء بقرار من المدير العام في الإدارات والمؤسسات العامة وبقرار من السلطة\nم\nالتقريرية في البلديات وغيرها من الهيئات ،وهي تختلف في قوامها وأعضائها عن لجنة التلزيم ولا تض ّ\nالأشخاص الذين اشتركوا في الإشراف على التنفيذ أو الذين درسوا السوق أو وضعوا القيمة التقديرية للشراء.\n تتأّلف كل لجنة من رئيس وعضَوين على الأق ّ\nل من داخل الإدارة وُيراعى في تأليفها إشراك أصحاب الاختصاص.\n َ .3يجري الاستلام على مرحلتين مؤّقتاً ونهائياً ،ويمكن أن يجري مرة واحدة أو على مراحل تتناول ك ّ\nل مرحلة\n منها جزءا ً من التلزيم.\nُ .4تبِّين اللجنة في الاستلام المؤقت ما إذا كانت الأشغال أو اللوازم أو الخدمات التي جرى التعاقد عليها قد\nم تنفيذها أو تقديمها وفقاً لشروط العقد والعرض المواَفق عليه والذي أصبح جزءا ً من العقد ،وما إذا\n ت ّ\nكان الملتزم قد نّفذ الموجبات الملقاة على عاتقه كافًة ،وتتثّبت في إستلام اللوازم أن الأصناف المستلمة\nوأعدادها مطاِبقة للشروط والمواصفات الفنّيـة المحَّددة في شروط العقد وهي صالحة وخالية من\nجـل في المحضر التاريخ والساعة التي ُتجرى فيها عملية\n العيوب وكمياتها مطابقة لجدول التسليم .يس َّ\nالاستلام ويوِّقع عليه رئيس وأعضاء اللجنة مهما كانت وجهة تصويتهم )موافقة أو عدم موافقة( ،ويجري\n الاستلام النهائي بعد انقضاء فترة الضمان وُيعاد بموجبه ضمان حسن التنفيذ إلى الملتزم.\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 74\n\f .5على اللجنة رفض الاستلام إذا وجدت مخالفة لشروط العقد ،أما إذا رأت أن العقد قد ُنِّفذ بصورة عامة"}, {"o": 207, "l": "المادة 101", "b": "وفقاً لأحكام دفتر الشروط مع وجود بعض النواقص أو العيوب الطفيفة وغير الجوهرية التي لا تحول دون\n استعمال اللوازم أو الأشغال أو الخدمات وفق الغاية التي أ ُبرم العقد من أجلها ،فيمكنها أن تقوم\n بالاستلام على أن َتفرض على الملتزم جزاءات تتناسب مع النواقص المرتكبةُ .تحَّدد دقائق تطبيق هذه\n الفقرة في مرسوم ُيّتخذ في مجلس الوزراء بناًء على اقتراح رئيسه وإنهاء هيئة الشراء العام.\n .6يمكن للجنة الاستعانة بخبرات من خارج الإدارة في حال عدم توافر الخبرات المطلوبة لصحة الاستلام في\n أحد أعضائها على الأقل ،على أن ُتطّبـق أحكام هذا القانون في اختيار الخبير من خارج الإدارة.\n .7على الخبير ،في حال الاستعانة بخبرات خارجية ،تقديم تقرير خطي للجنة الاستلام.\n .8على لجنة الإستلام إتمام عملها في الوقت المحدد ووفقاً لأحكام هذا القانون وشروط العقد ،ولا تترّتب\n ي عملية استلام جارية خلافاً لذلك ،وُيعتبر عضو لجنة الاستلام الممتنع أو\n ي نتائج قانونية على أ ّ\n أ ّ\n حق مسلكياً المتخِّلف دون عذر مشروع عن أداء الموجبات التي تقع على عاتقه مسؤو ً\n لا عن عمله وُيلا َ\n وتأديبياً أمام المراجع المختصة .كما لا ُيعمل بالإستلام الضمني أو الواقعي دون محاضر موضوعة وفقاً\n للأصول ُتظهر الحقوق المترّتبة وقيمتها.\n ي شكل من أشكال الاستلام الحاصل خلافاً\n ي مبالغ مترِّتبة نتيجة أ ّ ُ .9يح َّ\n ظر على المراجع المختصة تسديد أ ّ\n لهذا القانون.\n البند الرابع | سلطات التعاقد"}, {"o": 208, "l": "المادة 102", "b": "المادة | 102سلطات التعاقد\n تتولى سلطات التعاقد القيام بمهامها في ما يتعّلق بإجراءات الشراء والتعاقد بحسب أحكام هذا القانون،\n ومنها:\n .1تخطيط مشترياتها العامة وتضمينها لخطة الشراء السنوية الخاصة بها في موازناتها بشكل يضمن توّفر\n الاعتمادات اللازمة ،وجدولتها في سياق متعّدد السنوات عند الاقتضاء.\n .2وضع آليات لدراسة وتقييم وتحليل حاجاتها الشرائية بحسب ما تقتضيه أحكام هذا القانون.\n .3إرسال المعلومات والبيانات إلى هيئة الشراء العام بحسب ما تنص عليه أحكام هذا القانون ومراسيمه\n التطبيقّيـة.\n .4التقّيد بنشر المعلومات المطلوبة بمقتضى أحكام هذا القانون ومراسيمه التطبيقّيـة على موقعها\n الإلكتروني إن ُوجد ،وعلى المنصة الإلكترونّيـة المركزّيـة لدى هيئة الشراء العام بشكل يضمن الشفافية\n مع مراعاة حق الوصول إلى المعلومات.\n .5وضع آليات واضحة لإعداد دراسات السوق بحسب ما تقتضيه أحكام هذا القانون.\n متاحة بحسب ما تقتضيه أحكام هذا القانون.\n .6إعداد ملفات التلزيم وجعلها ُ\n .7الإعلان تباعاً عن مشترياتها وفق الأصول وبحسب"}, {"o": 209, "l": "المادة 12", "b": "المادة 12من هذا القانون وعلى المنصة الإلكترونّيـة\n المركزّيـة لدى هيئة الشراء العام.\n التخطيط\n الفعالّيـة والدمج في\n75 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\f .8إدارة ومتابعة تنفيذ العقود بشكل يضمن تحقيق القيمة الفضلى من إنفاق المال العام والمحافظة على\n المصلحة العامة ،بحسب ما تقتضيه أحكام هذا القانون.\n .9وضع الخطط لإدارة المخاطر ولتحقيق أهداف التنمية المستدامة في الشراء العام.\n .10وضع تقرير سنوي عن عمليات الشراء المجراة وفقاً لنموذج تضعه هيئة الشراء العام ،وإرساله إلى ديوان\n المحاسبة وهيئة الشراء العام ونشره وفق الأصول.\n .11غير ذلك من المهام المحددة في هذا القانون وسائر القوانين والأنظمة.\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 76\n\f الفصل السابع | إجـراءات الاعتـراض"}, {"o": 210, "l": "المادة 103", "b": "المادة | 103الحق في الاعتراض\n ي إجراء أو قرار صريح أو ق لك ّ\n ل ذي صفة ومصلحة ،بما في ذلك هيئة الشراء العام ،الإعتراض على أ ّ َ .1يح ّ\n ي من الجهات المعنّية بالشراء في المرحلة السابقة لنفاذ العقد، ضمني تّتخذه أو تعتمده أو ُت َ\n طِّبقه أ ّ\n ويكون مخالفاً لأحكام هذا القانون والمبادئ العامة المتعلقة بالشراء العام.\n .2يكون الاعتراض على القرارات السابق تحديدها ،ويعود لك ّ\n ل من تتوافر فيه الشروط المذكورة في الفقرة\n الأولى من هذه المادة الاعتراض وفقاً للآلية الإلزامية الآتية:\n أ .طلب إعادة نظر بمقتضى"}, {"o": 211, "l": "المادة 105", "b": "المادة 105من هذا القانون؛\n ب .شكوى بمقتضى"}, {"o": 212, "l": "المادة 106", "b": "المادة 106من هذا القانون؛\n ج .مراجعة قرارات هيئة الاعتراضات لدى مجلس شورى الدولة.\n .3لحين تشكيل الهيئة المنصوص عليها في هذا القانون تتبع اجراءات الاعتراض المعمول بها لدى مجلس\n شورى الدولة."}, {"o": 213, "l": "المادة 104", "b": "المادة | 104مفعول الاعتراض\n حظر توقيع العقد أو الإتفاق الإطاري أو وضعه موضع التنفيذ قبل صدور\n .1يترّتب على تقديم الإعتراض َ\n القرارات النهائية بشأنه إدارياً أو قضائياً أو انصرام المهل المحّددة لصدورها ،وعلى الجهة الشارية الإلتزام\n بهذا الحظر فور إبلاغها:\n أ .طلب إعادة النظر أو الشكوى من هيئة الاعتراضات بطريقة التبليغ )بصورة الكترونية(؛\n ي طريقة من طرق التبليغ المّتبعة أمام هذا المجلس.\n ب .أو المراجعة أمام مجلس شورى الدولة ،بأ ّ\n َ .2تنَتهي مدة الحظر المشار إليه في الفقرة 1من هذه المادة بإنقضاء //5//خمسة أيام عمل من تاريخ إبلاغ\n صاحب الشكوى أو المراجعة أو الجهة الشارية ,حسب الحالة ,وجميع المشاركين الآخرين في إجراءات\n الاعتراض ,بقرار الجهة الشارية بحسب"}, {"o": 214, "l": "المادة 105", "b": "المادة 105أو هيئة الاعتراضات بحسب المادة .106\n َ .3يحق لهيئة الاعتراضات أو مجلس شورى الدولة تقرير إنهاء الحظر والسماح للجهة الشارية بناًء على طلبها،\n أو تلقائياً ،إستئناف الإجراءات الآيلة إلى توقيع العقد أو الاتفاق الإطاري ،وذلك في الحالات الإستثنائية\n التي ُتبّررها العجلة ومقتضيات المصلحة العامة وبهدف تلافي ضرر أكيد قد يلحق بها نتيجة وقف العمل\n أو تأّخر تنفيذ العقدُ .يدَرج قرار رفع الحظر في سجل إجراءات الشراء مع الأسباب الداعية إلى اتخاذه ،وُيبلَّغ\n فورا ً من ك ّ\n ل من الجهة الشارية وصاحب الشكوى وجميع المشاركين الآخرين في إجراءات الاعتراض وفي\n إجراءات الشراء.\n التخطيط\n الفعالّيـة والدمج في\n77 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\f .4لا ُتقبل الاعتراضات المقَّدمة مباشرة أمام مجلس شورى الدولة بشأن القرارات الصريحة أو الضمنية\n المرتبطة بإجراءات الشراء في مرحلة ما قبل التعاقد.\n .5يبقى قرار حظر توقيع العقد قائماً عند تقديم طلب مراجعة أمام مجلس شورى الدولة وذلك لمدة //7//\nسبعة أيام عمل من تاريخ تقديم الطلب بحيث ُيرفع حكماً بعد هذه المدة ما لم يقّرر مجلس شورى الدولة\n الابقاء عليه بقرار صريح.\nن الأسباب المتعّلقة بالمخالفات المرتبطة بعملية الشراء والتي لم تبادر الجهات المعنّيـة ،باستثناء هيئة\n .6إ ّ\nالشراء العام ،إلى إثارتها خلال المهل المحّددة في متن هذا الفصل ُتعَتَبر غير مجدية وبالتالي لا يمكن\n لهذه الجهات اللجوء إليها لاحقاً لتقديم اعتراض بحسب أحكام هذا الفصل."}, {"o": 215, "l": "المادة 105", "b": "المادة | 105تقديم طلب إعادة النظر\nي صاحب مصلحة أن ٌيقِّدم طلب إعادة نظر بشأن قرار أو تدبير اتخذته الجهة الشارية في سياق\n َ .1يجوز لأ ِّ\nإجراءات الشراء .خلافاً لكل نص آخرُ ،تقَّدم طلبات إعادة النظر بصورة حصرية أمام هيئة الاعتراضات\n المنصوص عليها في البند الثاني من الفصل السادس من هذا القانون.\n ُ .2يقَّدم طلب إعادة النظر إلى هيئة الاعتراضات خطياً خلال الفترات الزمنّية التالية:\nأ .قبل الموعد النهائي لتقديم العروض إذا كانت تتعلق بشروط الدعوة أو التأهيل المسبق أو القرارات أو\n التدابير التي اتخذتها الجهة الشارية في هذا السياق؛\nب .خلال فترة التجميد البالغة //10//عشرة أيام عمل والتي تبدأ من تاريخ تبليغ العارض الفائز )ما ُيعرف\nبالملتزم المؤقت( بحسب ما تنص عليه الفقرة 2من"}, {"o": 216, "l": "المادة 24", "b": "المادة 24من هذا القانون ،إذا كانت تتعلق\nبالقرارات أو التدابير الأخرى التي اتخذتها الجهة الشارية في إطار إجراءات الشراء .وفي حال لم تطّبـق\n ي وقت يسبق نفاذ عقد الشراء أو الاتفاق الإطاري.\n أي فترة تجميد ،ففي أ ّ\nُ .3تحيل هيئة الاعتراضات بطريقة الكترونية طلب إعادة النظر حكماً إلى الجهة الشارية فور تلّقيها هذا الطلب،\nكما تنشر إشعارا ً بهذا الخصوص على المنصة الإلكترونّيـة المركزّيـة لدى هيئة الشراء العام يتضّمن ملخصاً\n عن الطلب وأسبابه.\n .4على الجهة الشارية أن ُتصدر قرارا ً بشأن طلب إعادة النظر وفقاً للفقرة 5من هذه المادة خلال //5//خمسة\nم ُتحيله فورا ً بطريقة إلكترونية إلى\n أيام عمل من تاريخ تلّقي الإحالة الإلكترونّية من لجنة الاعتراضات ومن ث ّ\nهيئة الاعتراضات التي تبلغ بدورها القرار إلى مقّدم الطلب وإلى جميع المشاركين الآخرين في إجراءات\n الاعتراض وفي إجراءات الشراء ،وذلك خلال يوم عمل واحد من َتَلّقيها قرار الجهة الشارية.\n .5يمكن للجهة الشارية ،عندما َتَّتِخذ قرارا ً بشأن إعادة النظر ،أن ُتلغي أ ّ\nي قرار أو تدبير اّتخذته في سياق\n حح هذا القرار أو التدبير أو ُتعِّدله أو ُتؤِّكده.\n إجراءات الشراء موضوع الطلب ،أو أن ُتص ِّ\n .6إذا لم ُتِحل الجهة الشارية قرارها بشأن إعادة النظر إلى هيئة الاعتراضات بحسب مقتضيات الفقرة 4من\n هذه المادة وخلال المهلة الزمنّية المحددة فيهاُ ،يَعّد ذلك قرارا ً ضمنياً بالرفض من قبلها.\n .7تكون جميع القرارات الصادرة عن الجهة الشارية بموجب الفقرة الخامسة من هذه المادة ,باستثناء القرارات\nالضمنية بالرفض ,قرارات خطية ُتبَّين فيها التدابير المَّتخذة والأسباب الداعية إلى اِّتخاذهاُ .تدِرج الجهة\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 78\n\f الشارية في سجل إجراءات الشراء الذي تنص عليه"}, {"o": 217, "l": "المادة 9", "b": "المادة 9من هذا القانون ما يلي:\n أ .القرارات الصادرة عنها؛\n ب .الإحالة التي تلّقتها من هيئة الاعتراضات بموجب هذه المادة."}, {"o": 218, "l": "المادة 106", "b": "المادة | 106تقديم شكوى لدى هيئة الاعتراضات\n .1خلافاً لكل نص آخرُ ,تقَّدم الشكاوى بصورة حصرية إلى هيئة الاعتراضات بشأن أ ّ\n ي قرار أو تدبير اّتخذته\n الجهة الشارية أو أي من الجهات المعنّيـة بالشراء في سياق إجراءات الشراء أو بشأن عدم إصدار الجهة\n الشارية قرارا ً بمقتضى"}, {"o": 219, "l": "المادة 105", "b": "المادة 105من هذا القانون خلال المهل الزمنّيـة المنصوص عليها في تلك\n المادة ،مرفقة بالأسباب القانونية والواقعية المبنية عليها.\n ُ .2تقَّدم الشكاوى خطياً خلال الفترات الزمنّية التالية:\n أ .قبل الموعد النهائي لتقديم العروض إذا كانت تتعلق بشروط الدعوة أو التأهيل المسبق أو القرارات أو\n التدابير التي اتخذتها الجهة الشارية في هذا السياق؛\n ب .خلال فترة التجميد البالغة //10//عشرة أيام عمل والتي تبدأ من تاريخ تبليغ العارض الفائز )ما ُيعرف\n بالملتزم المؤقت( بحسب ما تنص عليه الفقرة 2من"}, {"o": 220, "l": "المادة 24", "b": "المادة 24من هذا القانون ،إذا كانت تتعلق بالقرارات\n أو التدابير الأخرى التي اتخذتها الجهة الشارية في إطار إجراءات الشراء .وفي حال لم تطّبق أي فترة\n تجميد ،ففي اي وقت يسبق نفاذ عقد الشراء أو الاتفاق الإطاري.\n جُ .تقَّدم الشكاوى بشأن عدم إصدار الجهة الشارية قرارا ً بمقتضى"}, {"o": 221, "l": "المادة 105", "b": "المادة 105من هذا القانون خلال\n المهل الزمنّية المحددة في تلك المادة خلال مهلة خمسة //5//أيام عمل من الموعد الذي كان ينبغي\n فيه إبلاغ مقّدم طلب اعادة النظر بقرار الجهة الشارية وفقاً لأحكام"}, {"o": 222, "l": "المادة 105", "b": "المادة 105من هذا القانون.\n .3بعد أن تتلقى الشكوى ،تقوم هيئة الاعتراضات على الفور بما يلي:\n ن ذلك ضرورياً لحماية مصالح ُ\n مقِّدم الشكوى وإذا كانت أَ .تأخذ قرارا ً بتعليق إجراءات الشراء إذا رأت أ ّ\n مستندة على أسباب مهمة .في هذه الحالة يكون التعليق لمدة عشرة //10//أيام عمل\n الشكوى جدية و ُ\n ي\n في حال تلّقت الشكوى قبل الموعد النهائي لتقديم العروض؛ كما يجوز لهيئة الاعتراضات أن تمّدد أ ّ\n مطَّبق أو ترفعه ،مع مراعاة الأحكام المنصوص عليها في هذه المادة؛\n تعليق ُ\n بُ .تبَّلغ الجهة الشارية وجميع المشاركين المبّيـنة هويتهم في إجراءات الشراء الذين تتعّلق بهم الشكوى\n بمضمون تلك الشكوى؛\n ج .في حال قّررت الهيئة تعليق الإجراءات ،فهي تحِّدد مدة التعليق وتبلغ جميع المشاركين المبّيـنة هويتهم\n في إجراءات الشراء الذين تتعّلق بهم الشكوى بقرارها بشأن التعليق؛\n دً .تنشر إشعارا ً يتضّمن ملخصاً عن موضوع الشكوى وأسبابها على المنصة الإلكترونّيـة المركزّيـة لدى\n هيئة الشراء العام.\n .4يجوز لهيئة الاعتراضات أن ترفض الشكوى إن هي قّررت انها لا تستند إلى أسس قانونية أو واقعية،\n وعليها عندئذ أن ُتبلغ مقّدم الشكوى والجهة الشارية وجميع المشاركين الآخرين في إجراءات الشراء\n بالرفض وبالأسباب الداعية إليه .ويشّكل هذا الرفض قرارا ً بشأن الشكوى.\n التخطيط\n الفعالّيـة والدمج في\n79 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\fجه الإشعارات إلى مقِّدم الشكوى والجهة الشارية والمشاركين الآخرين في إجراءات الشراء بموجب\n .5تو ّ\nالفقرتين 3و 4من هذه المادة ,في موعد أقصاه ثلاثة //3//أيام عمل تلي صدور القرارات المتعّلقة بها.\nجهاً بموجب الفقرة الفرعية ) 3ب( من هذه المادة بتمكين هيئة\n .6تقوم الجهة الشارية ,فور تلقيها إشعارا ً مو ّ\n الاعتراضات من الا ّ"}, {"o": 223, "l": "المادة 105", "b": "طلاع الفعلي على كل ما في حوزتها من وثائق تتعلق بإجراءات الشراء.\n .7تتخذ الهيئة واحدا ً أو أكثر من التدابير التالية ،حسب ما يكون مناسباً:\n أ .إلزام الجهة الشارية وغيرها من الجهات المعنّيـة بالإمتناع عن أي إجراء يخالف أحكام هذا القانون؛\nب .إلغاء كلياً أو جزئياً تصّرف الجهة الشارية أو قرارها الذي لا يمتثل لأحكام هذا القانون في إطار ما قبل\n التعاقد؛\nج .إلزام الجهة الشارية التي اّتبَعت إجراءات مخاِلفة لأحكام هذا القانون بتصحيحها كما وتصحيح أي قرار\n صادر عنها لا يمتثل لأحكام هذا القانون في إطار ما قبل التعاقد؛\n د .التأكيد على أي قرار صادر عن الجهة الشارية؛\n هـ .إنهاء إجراءات الشراء؛\n و .رفض الشكوى؛\n ز .اتخاذ تدابير بديلة بحسب ما تقتضيه الظروف.\n .8تبلغ هيئة الاعتراضات ديوان المحاسبة والنيابة العامة لديه وهيئة الشراء العام والتفتيش المركزي بالمخالفات\n المكتشفة من قبلها عند البت بالشكوى وذلك لإتخاذ الإجراءات اللازمة.\n .9يصدر قرار هيئة الاعتراضات بمقتضى الفقرة 7من هذه المادة في مهلة //20//عشرين يوم عمل يلي\nتلّقي الشكوى .وتقوم الهيئة فورا ً بعد ذلك بتبليغ القرار إلى الجهة الشارية ومقِّدم الشكوى ،وإلى جميع\nالمشاركين الآخرين في إجراءات الاعتراض وفي إجراءات الشراء .ويسقط مع صدور القرار أي تعليق\n لإجراءات الشراء تكون قد قررته هيئة الاعتراضات.\n .10تكون جميع القرارات الصادرة عن هيئة الاعتراضات بمقتضى هذه المادة ,باستثناء القرارات الضمنية\nبالرفض ,قرارات خطية ومعّللة تبّين التدابير المّتخذة والأسباب الداعية إلى اتخاذهاُ .تدِرج الجهة الشارية\n في سجل إجراءات الشراء الذي تنص عليه"}, {"o": 224, "l": "المادة 9", "b": "المادة 9من هذا القانون ما يلي:\n أ .الشكوى التي تلقتها هيئة الاعتراضات بمقتضى هذه المادة؛\n ب .القرارات الصادرة عن هيئة الاعتراضات.\nَ .11تقبل قرارات هيئة الإعتراضات المراجعة أمام مجلس شورى الدولة خلال سبعة أيام عمل من تاريخ تبُّلغها,\nويتكَّون نتيجة انصرام المهلة المحددة في الفقرة 9من هذه المادة والتزام الهيئة الصمت بشأن الطلب\nالمقَّدم إليها أو التمّنع عن إبلاغ قرارها وفقاً لأحكام هذا القانون ،قرارا ً ضمنياً بالرفض يكون بدوره قابلاً\n للمراجعة أمام مجلس شورى الدولة.\nت بالشكوى وإصدار قرار\n ي اجراءات رقابية في حال وجودها ،وذلك إلى حين الب ّ\n .12إن تقديم الشكوى ُيجِّمد أ ّ\n بشأنها.\nي جهة رقابية أخرىُ ،وجب تبرير قرارها والنشر على المنصة الإلكترونّيـة\n .13عند مخالفة قرار الهيئة من قبل أ ّ\n المركزّيـة لكي يصبح نافذا ً.\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 80"}, {"o": 225, "l": "المادة 107", "b": "المادة | 107حقوق المشاركين في الاعتراض\n .1يحق لكل صاحب صفة ومصلحة التقّدم بالاعتراض بمقتضى"}, {"o": 226, "l": "المادة 103", "b": "المادة 103من هذا القانون.\n ُ .2يمنع أي مشارك يبّلغ بحسب الأصول بالإجراءات ,بما في ذلك إجراءات التأهيل المسبق ,لكنه يتخّلف عن\n المشاركة فيها من الاعتراض لاحقاً بمقتضى المادتين 105و 106من هذا القانون بشأن القرارات أو\n التدابير المتخذة من الهيئة أو من الجهة الشارية.\n .3مع مراعاة أحكام"}, {"o": 227, "l": "المادة 103", "b": "المادة 103من هذا القانون ,يحق للجهة الشارية أن تشارك في إجراءات الاعتراض\n بمقتضى"}, {"o": 228, "l": "المادة 106", "b": "المادة 106من هذا القانون.\n .4يحق للمشاركين في إجراءات الاعتراض بمقتضى هذا القانون ,أن يحضروا جميع جلسات الاستماع ,وأن\n يكونوا ممثلين فيها وان ُيستمع إليهم وأن يقّدموا الأدلة والإثباتات بجميع وسائل الإثبات وان يطلبوا\n عقد أي جلسة استماع وجاهية ,ولهم حق الوصول إلى سجل إجراءات الاعتراض ,مع الإحتفاظ بأحكام"}, {"o": 229, "l": "المادة 108", "b": "المادة 108من هذا القانون."}, {"o": 230, "l": "المادة 108", "b": "المادة | 108السرية في اجراءات الاعتراض\n لا ُتفشى أية معلومات في سياق إجراءات الاعتراض إذا كان القيام بذلك يعّرض مصالح الدولة الأمنية للخطر\n أو إذا كان يخالف القانون أو يعيق تنفيذه .أما في حال كانت المعلومات تمس بالمصالح التجارّية المشروعة\n للمورّدين أو المقاولين أو تعيق التنافس المنصف ،فيقتضي أن يتقّدم طالب السرية بطلب موافقة هيئة\n الشراء العام.\n التخطيط\n الفعالّيـة والدمج في\n81 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\f الفصل الثامن | النزاهة والمساءلة"}, {"o": 231, "l": "المادة 109", "b": "المادة | 109الشفافية\nَ .1تنتهج سلطات التعاقد سياسة نشر إلزامية تعلن بموجبها عن خططها للشراء وتفاصيل تطبيقها بما في\nذلك سير عمليات الشراء وإجراءات تلزيمها وعقدها ونتيجة استلامها وتنفيذها وقيمتها النهائية ،وذلك\n وفق أحكام هذا القانون ومراسيمه التطبيقّية.\nَ .2تستعين سلطات التعاقد للإعلان عن المعلومات المذكورة بجميع وسائل النشر المتاحة لها ،التقليدية منها\nكالجريدة الرسمية والصحف ،أو الوسائل الحديثة كالمواقع الإلكترونّيـة ،ويكون النشر إلزامياً على المنصة\n الإلكترونّيـة المركزّيـة لدى هيئة الشراء العام ،وعلى الموقع الإلكتروني الخاص بالجهة الشارية إن ُوجد.\n .3لا َيحّد من النشر إّلا ما كان سّرياً بطبيعته تطبيقاً للمادة 6من هذا القانون.\nُ .4تجمع البيانات الخاصة بالشراء العام ،على المستويات كافًة وفق أحكام هذا القانون ،في قاعدة بيانات\nمركزية ُتنشأ لهذه الغاية لدى هيئة الشراء العام كجزء من المنصة الإلكترونّيـة المركزّيـة .يكون الوصول إليها\n متاحاً مجاناً للمواطنين والمعنيين مع مراعاة أحكام"}, {"o": 232, "l": "المادة 6", "b": "المادة 6من هذا القانون.\nُ .5يتاح الوصول المجاني إلى المعلومات الخاصة بالمشتريات العامة من خلال المنصة الإلكترونّيـة المركزّيـة\n في هيئة الشراء العام والمواقع الإلكترونّيـة الخاصة بالجهات الشارية."}, {"o": 233, "l": "المادة 110", "b": "المادة | 110النزاهة\n .1مع مراعاة أحكام"}, {"o": 234, "l": "المادة 6", "b": "المادة 6من هذا القانونُ ،تلِزم سلطة التعاقد كل العاملين لديها المولجين بعمليات\n الشراء بما هو آ ٍ\n ت:\nأ .عدم إفشاء أية معلومات أو معطيات تتعّلق بالأسرار الفنّيـة أو التجارّيـة والجوانب السرية للعروض،\n والتي اتصلت بعلمهم أو حصلوا عليها جّراء القيام بالمهام الموكلة إليهم.\nب .عدم تقديم معلومات اتصلت بعلمهم أو حصلوا عليها جّراء القيام بالمهام الموكلة إليهم ،تشّكل\nمنفعة لأشخاص ثالثين وبما يخالف مبدأ المعاملة العادلة والمتسأوية لجميع العارضين المنصوص\n عليه في المادة الأولى من هذا القانون.\n .2يلتزم موظفو سلطة التعاقد والعاملون لديها بقواعد السلوك المنصوص عليها في"}, {"o": 235, "l": "المادة 10", "b": "المادة 10من هذا\nالقانون وبالمعايير الأخلاقية والمهنية ،ويمتنعون عن الممارسات الفاسدة ،بما في ذلك على سبيل\nالمثال لا الحصر الاحتيال والتواطؤ والاختلاس وصرف النفوذ والتهديد وكذلك تفادي تضارب المصالح،\n معَّرف في المادة الثانية من هذا القانون والقوانين الأخرى ذات الصلة.\n كما هو ُ\n .3تستبعد سلطة التعاقد ك ّ\nل موظف أو عامل لديها مسؤول عن تقييم أو إبرام عقد شراء أو مراقبة تنفيذه\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 82\n\f خالف أحكام هذا القانون من المشاركة في القرارات المتعّلقة بالشراء ،وتحيله إلى المراجع المختصة لاّتخاذ\n العقوبات الجزائية والتأديبية المنصوص عليها في القوانين النافذة ذات الصلة.\n ُ .4تلِزم سلطة التعاقد العاملين لديها بمتابعة برامج تدريب على النزاهة ،لرفع مستوى الوعي حول مخاطر\n عدم النزاهة ،مثل الفساد والاحتيال والتواطؤ ومراعاة أو تمييز فريق على آخر ،والعقوبات المرتبطة بها،\n ولتطوير المعرفة حول السبل لمواجهة هذه المخاطر وتعزيز ثقافة النزاهة.\n َ .5تشَتِرط سلطة التعاقد على المتعاملين معها الالتزام بأعلى معايير الأخلاق المهنية والمواطنة الصالحة\n بخاصة خلال فترة الشراء وتنفيذ العقد ,تحت طائلة اتخاذ قرارات استبعاد بحقهم وفق ما تنص عليه"}, {"o": 236, "l": "المادة 8", "b": "المادة\n 8من هذا القانون .ولتحقيق هذا الموجب ،على العارضين والملتزمين الامتناع عن الممارسات التالية:\n ي شيء ذي قيمة ،سواء بشكل\n أ“ .ممارسة فاسدة” وتعني عرض أو استلام أو تسليم أو استدراج أ ّ\n ل عام في عملية الشراء أو في تنفيذ العقد؛\n مباشر أو غير مباشر للتأثير في عمل مسؤو ٍ\n ب“ .ممارسة احتيالية” تؤدي إلى تشويه الحقائق أو إغفالها للتأثير في عملية الشراء أو تنفيذ العقد؛\n ج“ .ممارسات تواطؤية” من شأنها وضع أية خطة أو ترتيب بين اثنين أو أكثر من العارضين بهدف تقديم\n أسعار على مستويات زائفة وغير تنافسية؛\n د“ .ممارسات قهرية” تؤدي إلى إيذاء أشخاص في انفسهم أو في أهلهم أو في ممتلكاتهم ،أو\n التهديد بإيذائهم ،سواء بشكل مباشر أو غير مباشر ،للتأثير في مشاركتهم في عملية الشراء أو تنفيذ\n عقد شراء؛\n ي ممارسة تؤّدي إلى التأثير سلباً في عملية الشراء وبما يخالف مبادىء هذا القانون.\n هـ .أ ّ\n .6لا يحق للملتزم أو شركائه أو العاملين لديه تقاضي أية تعويضات أو عمولات أو حسومات أو دفعات\n متعلقة بالالتزام ،غير المبالغ المستحقة بموجب العقد المبرم مع سلطة التعاقد."}, {"o": 237, "l": "المادة 111", "b": "المادة | 111التدقيق الداخلي\n .1يتولى ،بقرار من رأس الإدارة ،واحد أو أكثر من العاملين لدى الجهة الشارية مهمة التدقيق الداخلي\n لتطبيق كافة أحكام هذا القانون والمراسيم والقرارات التنظيمية ،بما يتوافق مع حجم هذه الجهة وعدد\n وقيمة العقود التي تجريها.\n .2يقوم العاملون المذكورون في الفقرة الأولى من هذه المادة بإبلاغ كل من هيئة الشراء العام والهيئات\n الرقابية المختصة فورا ً عن أية مخالفات أو إهمال نتيجة التدقيق الداخلي ،وايداع نسخة إلى رأس الإدارة.\n ُ .3تَّتبع في التدقيق الداخلي المعايير والأصول التي تضعها هيئة الشراء العام.\n .4على هيئة الشراء العام والجهات الشارية إبلاغ الهيئات الرقابية المختصة بالمخالفات المرتَكبة من قبل\n الموظفين العامين لاتخاذ الإجراءات اللازمة وفق القوانين والأنظمة النافذة .لا تحول الملاحقات التأديبية\n والمالّيـة دون الملاحقة الجزائية أمام المحاكم المختصة.\n التخطيط\n الفعالّيـة والدمج في\n83 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية"}, {"o": 238, "l": "المادة 112", "b": "المادة | 112العقوبـات\nبالإضافة إلى العقوبات المنصوص عليها في هذا القانون والقوانين الأخرى ولاسّيما قانون العقوبات،\n ُتطَّبـق العقوبات التالية:\n أو ً\n لا :العقوبات الجزائية\n ُ .1يعاَقب ك ّ\nل من يخالف أحكام الفقرة الأولى من"}, {"o": 239, "l": "المادة 110", "b": "المادة 110من هذا القانون بالحبس من شهرين إلى\nسنتين ،وبالغرامة من عشرين ضعفاً إلى مئتي ضعف الحد الادنى للأجور النافذ بتاريخ المخالفة ،أو إحدى\n هاَتين العقوبَتين .وُتضاَعف الغرامة في حال التكرار.\n ُ .2يعاَقب ك ّ\nل من يخالف أحكام الفقرة 5من"}, {"o": 240, "l": "المادة 110", "b": "المادة 110بالحبس لمدة لا تقل عن سنتين وبغرامة تتراوح ما\nبين ضعَفي وثلاثة أضعاف المنفعة المادية المتوّقعة أو المحّققة ،وفي حال تعّذر تحديد قيمة المنفعة\nالمادية المتوقعة بشكل دقيق ُتطّبـق غرامة تتراوح ما بين عشرين ضعفاً ومئتي ضعف الحد الادنى للأجور\n النافذ بتاريخ المخالفة.\n ُ .3يعاَقب المو ّ\n ظف أو المشرف وك ّ\nل من اشترك في الإشراف واستلام الخدمات أو اللوازم أو الأشغال\nالمنّفذة بالحبس من سنة إلى ثلاث سنوات وبغرامة تتراوح ما بين ضعَفي وثلاثة أضعاف قيمة الجزء من\nالعقد المسؤول عن مراقبة تنفيذه أو استلامه أو الاشراف عليه ،إذا تغاضى عن ضبط المخالفات المرتكبة\nجب اتخاذها أو التخّلف عن أو أخ ّ\n ل بتنفيذ شروط العقد أو أهمل المراقبة أو تأّخر عن القيام بالإجراءات المتو ّ\n القيام بموجباته الوظيفّيـة وفق الأصول ،ك ّ\n ل حسب مسؤوليتهُ .تشَّدد العقوبة في حال التكرار.\nُ .4يطَّبـق قانون العقوبات والقوانين المتعّلقة بمكافحة الفساد وخاصة قانون مكافحة الفساد في القطاع\nالعام وانشاء الهيئة الوطنّيـة لمكافحة الفساد رقم 2020/175تاريخ 2020/5/8وتعديلاته وقانون التصريح\nعن الذمة المالّيـة والمصالح ومعاقبة الإثراء غير المشروع رقم 189تاريخ 2020/10/16وتعديلاته وسائر\nالقوانين ذات الصلة على الجرائم التي تقع تحت طائلتها والمرتبطة بتنفيذ هذا القانون .وعند تعارض هذه\n القوانين في ما بينها ُتطَّبق العقوبة الأشّد بحق الملاحقين.\nُ .5يعاَقب الشريك والمحّرض والمتدّخل والمستفيد بالعقوبة عينها المقّررة للفاعل الأصلي في الجرائم\n المبّيـنة أعلاه.\nُ .6يسأل الملتزم من بين الأشخاص المعنويين ,جزائياً ,عن أفعال مديريه وأعضاء إدارته وممثّليه وعّماله\nعندما يأتون هذه الأفعال بإسم الشخص المعنوي المذكور أو بإحدى وسائله وفق أحكام"}, {"o": 241, "l": "المادة 210", "b": "المادة 210من\n قانون العقوبات.\n ثانيًا :العقوبات التأديبية والمالّية\n ُيلاِحق ديوان المحاسبة وإدارة التفتيش المركزي ،ك ٌّ\nل في مجال اختصاصه ،أصحاب القرار والموظفين والعاملين\n لدى كل الجهات الشارية وغيرها من الهيئات المختصة بالشراء العام.\n ثالثًا :الغرامات المالّية\nَ .1يفرض ديوان المحاسبة ،عفوا ً أو بناًء على طلب هيئة الشراء العام ،الغرامات بحق الجهات الشارية وُيلزمها\nبدفع غرامة مالية تتراوح ما بين عشرين ضعفاً ومئتي ضعف الحد الادنى للأجور النافذ بتاريخ المخالفة،\n قانون الشراء العام في لبنان | رقم 244تاريخ 29تموز 2021 84\n\f وفق حجم المخالفة وخطورتها ،في حال مخالفتها الأحكام المنصوص عليها في هذا القانون وأنظمته\n التطبيقّيـة ،ولاسّيما التي تتعلق بما يلي:\n أ .مخالفة إجراءات الشراء المنصوص عليها في هذا القانون؛\n ب .تجزئة الشراء خلافاً للقانون؛\n ج .مخالفة أحكام مكافحة الفساد عند إجراء عمليات الشراء العام؛\n د .عدم اّتخاذ الإجراء المناسب لتفادي ،تحديد ومنع تضارب المصالح في إجراءات الشراء؛\n هـ .عدم الالتزام بأصول اعتماد طرق الشراء القانونية؛\n و .مخالفة أصول النشر والإعلان وفق ما تنص عليه أحكام هذا القانون؛\n ز .عدم إيداع هيئة الشراء العام وهيئات الرقابة وهيئة الاعتراضات المعلومات والمستندات المطلوبة\n وفق الأصول؛\n ح .عدم الالتزام بموجب التخطيط المنصوص عليه في"}, {"o": 242, "l": "المادة 11", "b": "المادة 11من هذا القانون؛\n ط .عدم الالتزام بالمهل القانونية للإعلان ولتقديم العروض وللاستلام وعدم احترام فترة التجميد؛\n ي .مخالفة مهل أصول إيداع ضمانات العرض وحسن التنفيذ؛\n ك .إرساء التلزيم على عرض لا تتوّفر فيه الشروط المطلوبة أو لا يشّكل أفضل العروض المقّدمة؛\n ل .إلغاء الشراء خلافاً للأصول المحّددة في هذا القانون؛\n م .عدم إنشاء سج ّ\n ل الشراء المنصوص عليه في"}, {"o": 243, "l": "المادة 9", "b": "المادة 9من هذا القانون أو إدراج المعلومات فيه خلافاً\n للأصول؛\n ن .عدم وضع التقرير السنوي المنصوص عليه في"}, {"o": 244, "l": "المادة 102", "b": "المادة 102من هذا القانون؛\n س .ارتكاب الأخطاء في تسجيل العروض المقّدمة؛\n ع -إعاقة وصول العارضين إلى المعلومات والمستندات المتاحة قانوناً؛\n ف .تعديل الشروط والمواصفات قبل وبعد التعاقد خلافاً لأحكام هذا القانون.\n ُ .2يلَزم الملتزم إدارياً من قبل هيئة الشراء العام بدفع غرامة مالية تتراوح ما بين عشرين ضعفاً ومئتي\n ضعف الحد الادنى للأجور النافذ بتاريخ المخالفة ،وذلك عند مخالفته أحكام هذا القانون ومراسيمه التطبيقّيـة.\n .3يحق للجهة الشارية وللملتزم الطعن بقرارات التغريم أمام مجلس شورى الدولة.\n رابعًا :إساءة استخدام الحق في الإعتراض\n ُ .1يعاقب العارض الذي يسيء استعمال حّقه في الاعتراض المنصوص عليه في الفصل السابع من هذا\n القانون بغرامة مالية تتراوح ما بين عشرين ضعفاً ومئتي ضعف الحد الادنى للأجور النافذ بتاريخ اساءة\n استخدام الحق في الاعتراض.\n َ .2تفرض هيئة الشراء العام هذه الغرامة بناًء على طلب هيئة الاعتراضات.\n .3تثبت الإساءة في استعمال الحق عند رّد الاعتراضات المقّدمة ثلاث مرات متتالية ،أو عند ثبوت تقديم\n الاعتراض لمجّرد المماطلة أو عدم الجدية الواضحة.\n .4عند توقيع الغرامة من قبل هيئة الشراء العام وفق هذا البند ,تطِّبق الجهة الشارية إجراءات الإقصاء\n المنصوص عليها في"}, {"o": 245, "l": "المادة 40", "b": "المادة 40من هذا القانون.\n .5يحق للملتزم طلب الطعن بقرارات التغريم والإقصاء أمام مجلس شورى الدولة.\n التخطيط\n الفعالّيـة والدمج في\n85 الإستدامة التخصص الشفافية النزاهة والمنافسة المساءلة الموازنة الشمولية\n\f الفصل التاسع | أحكام انتقالية ختامّيـة"}, {"o": 246, "l": "المادة 113", "b": "المادة | 113الملفات الجارية\nم الإعلان عنها قبل دخول هذا القانون حّيـز التنفيذ القوانين النافذة\n ُتطَّبـق على عمليات الشراء الجارية والتي ت ّ\n بتاريخ الإعلان عن الشراء."}, {"o": 247, "l": "المادة 114", "b": "المادة | 114إلغاء المواد المتعارضة\nُ .1تلغى المواد المئة وواحد وعشرون حتى المئة وو