insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (12,'قوانين','قانون المحاسبة العمومية','1963-12-30','https://www.ppa.gov.lb/ar/pages/details/12','{"https://admin.ppa.gov.lb/storage/listing-pages/files/fgvPNpYGNXzteVvjmQZczVMd4ZBfi5tvrU93-1760210953.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/fgvPNpYGNXzteVvjmQZczVMd4ZBfi5tvrU93-1760210953.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=12),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "قانون المحاسبة العمومية\n مرسوم رقم - 14969صادر في 30/12/1963\n إن رئيس الجمھورية اللبنانية،\n بناء على الدستور اللبناني ال سيما"}, {"o": 1, "l": "المادة 58", "b": "المادة 58منه،\n وبما أن الحكومة أحالت على مجلس النواب بموجب المرسوم رقم 14315تاريخ 4/11/1963مشروع القانون\n المعجل الرامي إلى تحديد أصول المحاسبة العمومية،\n وبما أنه انقضى أكثر من أربعين يوما ً على إحالة ھذا المشروع إلى مجلس النواب دون أن يبت به،\n وبناء على اقتراح وزير المالية،\n وبعد موافقة مجلس الوزراء في جلسته المنعقدة بتاريخ 30كانون األول ،1963\n يرسم ما يأتي:\n المادة -1وضع موضع التنفيذ مشروع القانون المعجل\n المحال على مجلس النواب بموجب المرسوم رقم 14315تاريخ 4/11/1963وهذا نصه:\n الباب الأول -أحكام عامة\n »المادة -1يحدد ھذا القانون أصول إعداد موازنة الدولة ،وتنفيذھا ،وقطع حسابھا ،وإدارة األموال العمومية،\n واألموال المودعة في الخزينة.\n»المادة -2األموال العمومية ھي أموال الدولة ،والبلديات والمؤسسات العامة التابعة للدولة أو البلديات ،وأموال سائر\n األشخاص المعنويين ذوي الصفة العمومية.\n»المادة -3الموازنة صك تشريعي تقدر فيه نفقات الدولة ووارداتھا عن سنة مقبلة ،وتجاز بموجبه الجباية واإلنفاق.\n »المادة -4تتألف الموازنة من قانون الموازنة والجداول اإلجمالية والتفصيلية الملحقة به.\n »المادة -5قانون الموازنة ھو النص المتضمن إقرار السلطة التشريعية لمشروع الموازنة.\n يحتوي ھذا القانون على أحكام أساسية تقضي بتقدير النفقات والواردات ،وإجازة الجباية ،وفتح االعتمادات الالزمة\n\f لإلنفاق ،وعلى أحكام خاصة تقتصر على ما له عالقة مباشرة بتنفيذ الموازنة.\n »المادة -6تتألف موازنة الدولة من الموازنة العامة ،وموازنات ملحقة ،وموازنات استثنائية.\n تحدث الموازنات الملحقة والموازنات االستثنائية بقوانين خاصة ،وتطبق عليھا أحكام ھذا القانون ،إال إذا تضمنت\n األحكام الخاصة بھا نصوصا ً مخالفة.\n »المادة -7توضع الموازنة لسنة مالية تبدأ في أول كانون الثاني وتنتھي في 31كانون األول."}, {"o": 2, "l": "المادة 58", "b": "»المادة -8تقيد الواردات والنفقات في حسابات موازنة السنة التي قبضت أو دفعت فعليا ً في خاللھا.\n»المادة -9يمكن تصحيح األخطاء المادية واألخطاء في التنسيب بقرار من وزير المالية يصدر بناء على طلب اإلدارة\n المختصة حتى الخامس عشر من شھر آذار من السنة التالية.\n »المادة -10تقسم الموازنة إلى قسمين:\n -1قسم النفقات ،ويتضمن االعتمادات المفتوحة بمواجھة ھذه النفقات.\n -2قسم الواردات ،ويتضمن الواردات المخصصة لتغطية ھذه االعتمادات.\n »المادة -11االعتمادات على نوعين:\n -1أساسية وھي التي تفتح بموجب قانون الموازنة.\n -2إضافية وھي التي تزاد إلى االعتمادات األساسية بعد نشر الموازنة.\n واالعتمادات اإلضافية على نوعين:\n -1تكميلية وھي التي تفتح لمواجھة نقص في بند معين.\n -2استثنائية وھي التي تفتح لمواجھة نفقة لم يخصص لھا اصال اي اعتماد في الموازنة.\n »المادة -12ال تفتح االعتمادات إال ضمن نطاق الموازنات المذكورة في المادة .6\n غير أنه يجوز بصورة استثنائية فتح اعتماد في موازنة ما قبل تصديقھا شرط أن يدون فيھا.\n الباب الثاني -إعداد الموازنة العامة\n »المادة -13يضع كل وزير قبل نھاية شھر أيار من السنة مشروعا ً بنفقات وزارته عن السنة التالية ،ويرسله إلى\nوزير المالية مشفوعا ً بالمستندات واإلحصاءات واإليضاحات الالزمة لتبرير كل اعتماد من االعتمادات المطلوبة ،وذلك\n وفقا ً ألصول يحددھا وزير المالية.\n »المادة -14يقدر وزير المالية الواردات باالستناد إلى تخمينات وزارته وتخمينات الوزراء الذين يقومون بطرح أو\n جباية بعض الواردات لحسابه.\n\f »المادة -15تقدر واردات السنة الجديدة استناداً إلى العنصرين التاليين:\n أ -تحصيالت السنة األخيرة التي أنجز مشروع قطع حسابھا.\n ب -تحصيالت األشھر المنصرمة من السنة الجارية.\n ولوزير المالية أن يعدل التقدير على أساس أوضاع يعتمدھا ،على أن يبرر أسبابھا."}, {"o": 3, "l": "المادة 58", "b": "»المادة -16يجمع وزير المالية تقديرات النفقات ،ويقابلھا بتقديرات الواردات ،ويضع مشروع الموازنة بعد أن يؤمن\n التوازن بين قسميھا.\nوإذا جاوزت االعتمادات المطلوبة الواردات المقدرة كان على وزير المالية أن يؤمن التوازن باقتراح ما يراه ضروريا ً\n من التدابير التالية:\n أ -تخفيض النفقات.\n ب -تغطية الفرق بمأخوذات من مال االحتياط إذا كان ذلك ممكنا ً.\n ج -إيجاد موارد جديدة.\n »المادة -17يقدم وزير المالية مشروع الموازنة إلى مجلس الوزراء قبل أول أيلول مشفوعا ً بتقرير يحلل فيه\n االعتمادات المطلوبة ،والفروقات الھامة بين أرقام المشروع وبين أرقام موازنة السنة الجارية.\n »المادة -18يقر مجلس الوزراء مشروع الموازنة في صيغته النھائية ،ويودعه السلطة التشريعية ضمن المھلة\n المحددة في الدستور.\n ويقدم وزير المالية إلى السلطة التشريعية ،قبل أول تشرين الثاني ،تقريراً مفصالً عن الحالة االقتصادية والمالية في\n البالد وعن المبادئ التي اعتمدتھا الحكومة في مشروع الموازنة.\n»المادة -19ال يجوز إدخال أي زيادة على مشروع الموازنة ،أو مشاريع االعتمادات اإلضافية ،خالل المناقشة بھا في\n اللجنة النيابية المختصة وفي مجلس النواب ،إال بعد أخذ رأي وزارة المالية الخطي وموافقة مجلس الوزراء.\n الفصل الأول -النفقات\n »المادة -20معدلة وفقا ً للقانون 55/66تاريخ 3/9/1966\n تقسم موازنة النفقات إلى جزئين:\n -الجزء األول :ويحتوي على النفقات العادية.\n -الجزء الثاني :ويحتوي على نفقات التجھيز واإلنشاء ومساھمات الدولة اإلنمائية.\n يحدد مفھوم كل من نفقات الجزئين المذكورين بقرار يصدر عن وزير المالية.\n »المادة -21معدلة وفقا ً للقانون 55/66تاريخ 3/9/1966\nيوزع كل من الجزئين المذكورين من قسم النفقات إلى أبواب .ويحدد عدد األبواب في كل جزء بقرار من وزير المالية."}, {"o": 4, "l": "المادة 58", "b": "»المادة -22يقسم الباب إلى فصول يختص كل منھم بإدارة واحدة أو مجموعة من اإلدارات ،أو بمشروع واحد أو\n مجموعة من المشاريع .ويقسم الفصل إلى بنود يختص كل منھا بنفقات من نوع واحد ،أو نفقات متشابھة ،ويقسم\n\f البند ،عند االقتضاء ،إلى فقرات.\n يعتمد في تقسيم االعتمادات جدول نموذجي يحدد بقرار من وزير المالية.\n »المادة -23يبين في بند الرواتب:\n -1فيما يتعلق بالموظفين الدائمين والمؤقتين:\n -عدد الموظفين اإلجمالي بحسب الفئة ،مع مجموع رواتبھم وملحقاتھا.\n -2فيما يتعلق بالمتعاقدين.\n -عددھم مع مجموع رواتبھم وملحقاتھا.\n -3فيما يتعلق باإلجراء:\n أ -لألجراء الدائمين :عددھم مع مجموع أجورھم وملحقاتھا.\n ب -لألجراء غير الدائمين :مجموع أجورھم وملحقاتھا.\n »المادة -24يمكن توزيع اعتمادات األشغال المتشابھة إلى فقرات ضمن البند الواحد.\n وتطبق في ھذه الحال األحكام التالية:\n -1يعتبر االعتماد المرصد لكل مشروع بمثابة فقرة مستقلة.\n -2يجوز النقل من االعتماد المرصد ألحد المشاريع إلى مشروع آخر:\n أ -بعد تلزيم األشغال ،شرط أن يحتفظ بخمسة عشر بالمئة على األقل من مقدار االعتماد\n األساسي.\n ب -بعد إتمام المشروع وتصفية الصفقة.\n -3ال يجوز النقل إال لمشروع مماثل للمشروع األول وواقع في المنطقة نفسھا.\n»المادة -25معدلة وفقا ً للقانون 55/66تاريخ 3/9/1966والقانون رقم 12/73تاريخ 2/3/1973والقانون رقم\n 12/74تاريخ 9/5/1974والقانون رقم 32/75تاريخ 28/8/1975والمرسوم رقم 10880تاريخ 2/2/1976\n والمرسوم االشتراعي رقم 43تاريخ 26/5/1977\n -1يفرد في كل باب من قسم النفقات فصل تصرف منه قيمة األحكام النقدية الصادرة على الدولة والمصالحات التي\n تجريھا ،وذلك عندما ال تتوافر لھذه النفقات اعتمادات في البنود المختصة.\n ً\nيغذى ھذا النص بطريقة النقل من االعتماد اإلجمالي المرصد في باب احتياطي الموازنة وفقا ألحكام"}, {"o": 5, "l": "المادة 26", "b": "المادة 26التالية.\n -2ترد المبالغ التي استوفتھا الخزينة خطأ أو بدون وجه حق عن طريق تنزيلھا من حساب إيرادات الموازنة التي\n قيدت أصالً فيھا ،أي بقيدھا في الجھة المدينة من حساب اإليرادات وال يفتح أي اعتماد في الموازنة لھذه الغاية.\n يقيد في حقل المبالغ المحصلة من قطع حساب الموازنة األرصدة فقط لحسابات اإليرادات.\n -3يفرد في كل باب من قسم النفقات ،خالل مدة انتقالية تنتھي في سنة 1966فصل يدعى نفقات السنين السابقة،\n تؤخذ منه المبالغ التي ترتبت لصالح الغير في السنوات السابقة لعام 1963والتي لم تصرف خاللھا.\n وال يرصد أي اعتماد في الفصل المذكور عند تنظيم الموازنة ،بل تغطى النفقات التي تصرف منه بمأخوذات من مال\n االحتياط تصدق بقانون قطع الحساب.\n »المادة -26\n -1ترصد في باب احتياطي الموازنة:\n أ -اعتمادات احتياطية للنفقات المشتركة بين عدة وزارات ،كمساعدات المرض والوفاة\n واألحكام النقدية والمصالحات إلخ...\n ب -اعتماد احتياطي للنفقات الطارئة ،يستعمل لتغذية بنود الموازنة التي نفذت اعتماداتھا ،أو\n لفتح اعتمادات استثنائية ،على أن ال يقل ھذا االعتماد االحتياطي عن واحد بالمئة من مجموع\n اعتمادات الجزئين األول والثاني من الموازنة.\n -2في حال نفاذ االعتمادات المرصدة لألحكام النقدية والمصالحات يجوز للحكومة أن تفتح بمرسوم يتخذ في مجلس\n\f الوزراء االعتمادات التكميلية الالزمة وأن تغطي ھذه االعتمادات بمأخوذات من مال االحتياط تصدق بقانون قطع\n الحساب .وتطبق أيضا ً أحكام ھذه الفقرة في حال نفاذ االعتمادات المرصدة لمعاشات التقاعد وتعويضات الصرف من\n الخدمة.\n -3ال تصرف أية نفقة من اعتمادات ھذا الباب مباشرة ،بل تنتقل ھذه االعتمادات عند الحاجة إلى سائر بنود الموازنة\n على الوجه التالي:\n -بقرار من وزير المالية ،بناء على اقتراح اإلدارة المختصة ،وبعد تأشير المراقب المركزي لعقد النفقات ،فيما يتعلق"}, {"o": 6, "l": "المادة 26", "b": "باالعتمادات المذكورة في المقطع )أ( من الفقرة السابقة.\n -بمرسوم يصدر بناء على اقتراح الوزير المختص ووزير المالية ،فيما يتعلق باالعتمادات المذكورة في المقطع )ب(\n من الفقرة السابقة.\n »المادة -1 -27مع مراعاة أحكام"}, {"o": 7, "l": "المادة 85", "b": "المادة 85من الدستور و"}, {"o": 8, "l": "المادة 26", "b": "المادة 26من ھذا القانون ،ال تفتح االعتمادات اإلضافية\n إال بقانون.\n وتغطى ھذه االعتمادات بطريقة النقل من بنود أخرى ،أو من باب احتياطي الموازنة ،أو أخذاً من مال االحتياط ،أو\n بموارد جديدة.\n -2مع مراعاة أحكام"}, {"o": 9, "l": "المادة 26", "b": "المادة 26من ھذا القانون ،ال تنقل االعتمادات من بند إلى آخر إال بقانون.\n -3مع مراعاة"}, {"o": 10, "l": "المادة 114", "b": "المادة 114من ھذا القانون ،ال تدور االعتمادات من موازنة سنة معينة إلى موازنة السنة التالية إال\n بقانون.\n »المادة -1 -28مع مراعاة أحكام"}, {"o": 11, "l": "المادة 24", "b": "المادة 24من ھذا القانون تنقل االعتمادات من فقرة إلى فقرة ضمن البند الواحد\nبقرار من الوزير المختص بعد تأشير المراقب المركزي لعقد النفقات .ويجوز النقل بالطريقة نفسھا إلى فقرة جديدة إذا\n كانت ھذه الفقرة ھي من نوع النفقات التي يختص بھا البند.\n -2تنقل االعتمادات المرصدة في بابي الديون المتوجبة األداء واحتياطي الموازنة من فقرة إلى فقرة ضمن البند\n الواحد ،بقرار من وزير المالية بعد تأشير المراقب المركزي لعقد النفقات.\n -3يجوز إجراء النقل من فقرة إلى أخرى في موازنة سنة معينة لغاية 31كانون الثاني من السنة الالحقة.\n الفصل الثاني -الواردات\n »المادة -29يتألف قسم الواردات في الموازنة من جزئين:\n األول :ويحتوي على الواردات العادية المخصصة لتغطية نفقات الجزئين األول والثاني من قسم النفقات.\n الثاني :ويحتوي على الواردات المخصصة لتغطية نفقات الجزء الثالث من قسم النفقات.\n وتتألف الواردات األخيرة من:\n -1مأخوذات من مال االحتياط.\n -2الواردات التي تخصص أو تحدث بقوانين خاصة.\n»المادة -30يوزع كل جزء من قسم الواردات إلى أبواب ،ويقسم الباب إلى فصول يختص كل منھا بفئة من الواردات،\n ويقسم الفصل إلى بنود يختص كل منھا بإيراد معين.\n ويفرد في كل جزء فصل خاص تقيد فيه األموال التي تدفعھا الخزينة خطأ أو بغير حق وتستردھا فيما بعد.\n ويعتمد في تقسيم الواردات جدول نموذجي يحدد بقرار من وزير المالية.\n »المادة -31يفرد في كل جزء من قسم الواردات باب خاص بفصل وحيد للمأخوذات من مال االحتياط .ويقسم ھذا\n\f الفصل إلى بنود وفقا ً للجدول النموذجي المذكور في المادة السابقة.\n الباب الثالث -تنفيذ الموازنة العامة\n الفصل الأول -تنفيذ الواردات\n القسم الأول -طرح الضرائب والرسوم\n »المادة -32تطبق على طرح الضرائب والرسوم األصول التالية ما لم ينص القانون على خالف ذلك."}, {"o": 12, "l": "المادة 24", "b": "»المادة -33تتولى طرح الضرائب المباشرة التي تجبى بموجب جداول تكليف ،الدائرة المالية المختصة في كل\n محافظة ،ويعطي ھذه الجداول القوة التنفيذية رئيس مصلحة الواردات.\nويتولى طرح الضرائب والرسوم األخرى رئيس الدائرة المالية أو الوحدة المختصة في كل محافظة بموجب أوامر قبض\n تصدر عنه.\n ويتولى فرض الغرامات المرجع الذي يتولى طرح الضريبة أو الرسم ما لم ينص القانون على خالف ذلك.\n »المادة -34معدلة وفقا ً للمرسوم 6103تاريخ 5/10/1973\n -يمكن تدارك كل كتمان أو نقص في التكليف بالضرائب والرسوم المباشرة وغير المباشرة حتى آخر السنة الثالثة بعد\n السنة التي كان يجب أن يجري فيھا التكليف ،وذلك بموجب جداول تكليف أو أوامر قبض إضافية للتكاليف المكتومة،\n وبموجب جداول تكليف أو أوامر قبض تكميلية للتكاليف الناقصة.\n وفضالً عن مدة التدارك المنوه عنھا في الفقرة األولى من ھذه المادة ،تتمتع الدوائر المالية المختصة بمدة أخرى\n استثنائية لتدارك حق الخزينة في فرض الضريبة أو الرسم على كل ربح أو دخل أو إيراد أو صك يكشفه حكم قضائي\n أو قرار تحكيمي أو تحرير تركة أو اتفاق رضائي ،وكذلك لتصحيح كل تكليف يتقرر إبطاله.\n وتنتھي ھذه المدة االستثنائية بتاريخ 31كانون األول من السنة التي تلي سنة إقرار األبطال أو انكشاف الربح أو\n الدخل أو اإليراد أو الصك الخاضع للتكليف.\n »المادة -35يعلن عن وضع جداول التكليف األساسية قيد التحصيل بواسطة الجريدة الرسمية واإلذاعة والصحف\n المحلية .وتلصق عند االقتضاء ،إعالنات بھذا المعنى في مكاتب المحتسبين ،وفي أماكن االجتماعات والساحات\n العمومية .وتبين في اإلعالن المھل المحددة للدفع واالستفادة من الحسم القانوني ،واالعتراض ،وتاريخ بدء كل منھا.\n »المادة -36تبدأ مھلة االعتراض على الضرائب المفروضة بموجب جداول تكليف أساسية اعتباراً من اليوم التالي\n لتاريخ نشر اإلعالن المتعلق بھا في الجريدة الرسمية."}, {"o": 13, "l": "المادة 24", "b": "وتبدأ مھلة االعتراض على الضرائب المفروضة بموجب جداول تكليف إضافية أو تكميلية ،وعلى الضرائب والرسوم\n المفروضة بموجب أوامر قبض ،اعتباراً من اليوم التالي لتاريخ إبالغ المكلف ھذه المستندات.\n\f يجري ھذا التبليغ بكتاب مضمون مع إشعار باالستالم ،وفي حال غياب المكلف أو تمنعه عن االستالم ،يتم التبليغ\n بواسطة اإلدارة المختصة وفقا ً ألحكام التبليغ المنصوص عليھا في قانون أصول المحاكمات المدنية.\n وتحدد مھلة االعتراض بشھرين للضرائب المباشرة التي تطرح بموجب جداول تكليف ،وبشھر واحد للضرائب\n والرسوم األخرى.\n »المادة -1 -37تحدد أصول االعتراض على مختلف الضرائب والرسوم ومھل البت بھا من قبل اإلدارة ولجان\nاالعتراضات بمرسوم يصدر بناء على اقتراح وزيري المالية والعدلية خالل ثالثة أشھر من تاريخ نشر ھذا القانون في\n الجريدة الرسمية.\n -2تقوم األصول والمھل المحددة في المرسوم المذكور مقام جميع النصوص الخاصة المتعلقة باالعتراضات الواردة\n في مختلف قوانين الضرائب والرسوم.\n »المادة -38خالفا ً ألي نص آخر ،ال يجوز لدوائر الضرائب في مديرية المالية العامة أن تقرر إلغاء التكاليف\n بالضرائب والرسوم ،أو تخفيضھا ،إال بموافقة رئيس مصلحة الواردات ،باستثناء ما يتعلق منھا بخطأ مادي أو بمبلغ\n ال يتجاوز 50بالمئة من قيمة التكليف شرط أن ال يتجاوز في مطلق األحوال /500/ل .ل .لكل تكليف.\n »المادة -39يؤمن الرقابة على مختلف عمليات طرح الضرائب والرسوم التي تتولى أمرھا مديرية المالية العامة\n جھاز لمراقبة التحقيق تحدد صالحياته وكيفية ممارسة أعماله ،بمرسوم يصدر بناء على اقتراح وزير المالية.\n القسم الثاني -تحصيل الضرائب والرسوم\n »المادة -40ال يجوز تحصيل أي ضريبة أو رسم ما لم تجز السلطة التشريعية ذلك بموجب قانون الموازنة أو أي\n قانون آخر .ويالحق المخالف وفقا ً ألحكام"}, {"o": 14, "l": "المادة 361", "b": "المادة 361من قانون العقوبات.\n »المادة -41تحصل الضرائب والرسوم باالستناد إلى جداول التكليف أو أوامر القبض التي طرحت بموجبھا ،إال إذا\n كانت من النوع الذي يؤديه المكلف مباشرة بواسطة إلصاق الطوابع أو االوراق المماثلة .وال يجوز لغير المحتسبين\n ومعاونيھم أن يؤمنوا تحصيل الضرائب والرسوم وسواھا من الواردات العمومية.\n »المادة -42معدلة وفقا ً للقانون 55/66تاريخ 3/9/1966\nإن الضرائب والرسوم على اختالفھا ،تسقط عن المكلفين بعامل مرور الزمن في 31كانون األول من السنة الرابعة بعد\n السنة التي جرى فيھا التكليف .ينقطع مرور الزمن بمجرد الشروع في المالحقات الفردية المنصوص عليھا في\n القانون .ويعتبر اإلنذار شروعا ً في المالحقة شرط أن يبلغ وفقا ً ألحكام المرسوم االشتراعي رقم 147تاريخ\n .12/6/1959\n يجدد اإلنذار عند االقتضاء قبل انقضاء أربع سنوات على تاريخ إبالغه لصاحب العالقة.\n»المادة -43تحفظ جداول التكليف سحابة عشر سنوات ،وتحفظ أوامر القبض سحابة خمس سنوات إال إذا قرر ديوان\n المحاسبة قبل انقضاء مدة الحفظ إبراء ذمة المسؤولين عن التحصيل.\n\f »المادة -44يؤمن الرقابة على عمليات تحصيل الضرائب والرسوم التي تتولى أمرھا مديرية المالية العامة جھاز\n لمراقبة الجباية تحدد صالحياته وكيفية ممارسة أعماله بمرسوم يصدر بناء على اقتراح وزير المالية.\n القسم الثالث -تحصيل ديون الدولة و وارداتها الأخرى\n»المادة -45تراعى في تصفية وتحصيل ديون الدولة ووارداتھا األخرى من غير الضرائب والرسوم األحكام المختصة\n بكل منھا.\n أما الديون والواردات التي لم تعين القوانين النافذة طرق تصفيتھا وتحصيلھا ،وإجراء المالحقة بشأنھا ،فتصفى\n بموجب أوامر تحصيل يصدرھا رئيس اإلدارة المختصة وتحصل وفقا ً لألصول المتبعة في تحصيل الضرائب المباشرة\n والرسوم المماثلة لھا."}, {"o": 15, "l": "المادة 361", "b": "يمكن االعتراض على أمر التحصيل أمام المحكمة العدلية الصالحة في محل إقامة المعترض خالل شھرين من تاريخ\n تبليغ المدين شخصيا ً أو في محل إقامته .وال يوقف االعتراض تنفيذ أمر التحصيل إال إذا قررت المحكمة ذلك كليا ً أو\n جزئيا ً.\n القسم الرابع -بيع أموال الدولة\n »المادة -46تباع أموال الدولة غير المنقولة وفقا ً لألحكام المختصة بھا.\n »المادة -47معدلة وفقا ً للقانون رقم 16/78تاريخ 2/5/1978والقانون رقم 49/87تاريخ 21/11/1987\n والقانون رقم 14تاريخ 20/8/1990و معدلة بموجب القانون رقم 583تاريخ ) 23/4/2004قانون الموازنة\n العامة والموازنات الملحقة لعام (2004\n تباع أموال الدولة المنقولة:\n -1بالتراضي اذا كانت قيمتھا المخمنة ال تزيد عن 3.000.000ل.ل) .ثالثة ماليين ليرة لبنانية(.\n -2باستدراج العروض اذا كانت قيمتھا المخمنة ال تزيد عن 6.000.000ل.ل) .ستة ماليين ليرة لبنانية(.\n -3بالمزايدة العمومية وبالظرف المختوم اذا كانت قيمتھا المخمنة تزيد عن 6.000.000ل.ل) .ستة ماليين ليرة\n لبنانية(.\nتطبق على البيع بالتراضي وباستدراج العروض وبالمزايدة العمومية األحكام المختصة بصفقات اللوازم واألشغال ما لم\n ينص القانون على خالف ذلك.\n _________________\n نص"}, {"o": 16, "l": "المادة 47", "b": "المادة 47قبل التعديل بموجب القانون رقم 583تاريخ 23/4/2004\nالمادة -47معدلة وفقا ً للقانون رقم 16/78تاريخ 2/5/1978والقانون رقم 49/87تاريخ 21/11/1987والقانون رقم 14تاريخ 20/8/1990\n تباع أموال الدولة المنقولة:\n -1بالتراضي إذا كانت قيمتھا المخمنة ال تزيد على خمسماية ألف ليرة لبنانية.\n -2باستدراج عروض إذا كانت قيمتھا المخمنة ال تزيد على ) 1.500.000مليون وخمسماية ألف ليرة لبنانية(.\n -3بالمزايدة العمومية وبالظرف المختوم إذا كانت قيمتھا المخمنة تزيد على مليون وخمسماية ألف ليرة لبنانية.\nتطبق على البيع بالتراضي وباستدراج العروض وبالمزايدة العمومية األحكام المختصة بصفقات اللوازم واألشغال ما لم ينص القانون على خالف ذلك.\n المادة -48معدلة وفقا ً للقانون رقم 583تاريخ ) 23/4/2004قانون الموازنة العامة والموازنات الملحقة لعام\n (2004\n\f يبت بصفقات بيع االموال المنقولة:\n -2في االدارة المركزية:\n -المدير المختص اذا كانت قيمة الصفقة ال تجاوز 150.000ل.ل.\n -المدير العام المختص اذا كانت قيمة الصفقة تزيد على 150.000ل.ل .وال تجاوز 600.000ل.ل.\n -الوزير المختص اذا كانت قيمة الصفقة تجاوز 600.000ل.ل.\n -3في المحافظات واالقضية:\n -القائمقام اذا كانت قيمة الصفقة ال تجاوز 150.000ل.ل.\n -المحافظ اذا كانت قيمة الصفقة تزيد على 150.000ل.ل .وال تجاوز 600.000ل.ل.\n -الوزير المختص اذا كانت قيمة الصفقة تجاوز 600.000ل.ل.\n __________________\n نص"}, {"o": 17, "l": "المادة 48", "b": "المادة 48قبل التعديل\n يبت بصفقات بيع األموال المنقولة:\n -1في اإلدارة المركزية:\n -المدير المختص إذا كانت قيمة الصفقة ال تجاوز /25000/ل .ل.\n -المدير العام المختص إذا كانت قيمة الصفقة تزيد على/ 25000 /ل .ل وال تجاوز /100000/ل .ل.\n -الوزير المختص إذا كانت قيمة الصفقة تجاوز /100000/ل .ل.\n 2\n -في المحافظات األقضية:\n -القائمقام إذا كانت قيمة الصفقة ال تجاوز /25000/ل .ل.\n -المحافظ إذا كانت قيمة الصفقة تزيد على /25000/ل .ل وال تجاوز / 100000/ل .ل.\n -الوزير المختص إذا كانت قيمة الصفقة تجاوز /100000 /ل .ل.\n »المادة -49تخمن األموال المنقولة بواسطة لجنة تؤلف في كل إدارة بقرار من المرجع الصالح للبت بالصفقة.\n »المادة -50تعرض على ديوان المحاسبة معامالت البيع الخاضعة لرقابته من قبل المرجع الصالح للبت بالصفقة.\n القسم الخامس -أحكام عامة\n »المادة -51تقيد الواردات المقبوضة برمتھا في قسم الواردات من الموازنة.\n »المادة -52تقبل بمرسوم يتخذ في مجلس الوزراء األموال التي يقدمھا للدولة األشخاص المعنويون والحقيقيون،\n وتفيد في قسم الواردات من الموازنة.\n وإذا كانت لھذه األموال وجھة إنفاق معينة فتحت لھا بالطريقة نفسھا اعتمادات بقيمتھا في قسم النفقات.\n»المادة -53تمسك وزارة المالية لكل نوع من أنواع واردات الموازنة ،ولكل سنة على حدة ،حسابا ً مستقالً تبين فيه:\n -بقايا السنين السابقة كل سنة على حدة.\n -مجموع الواردات المحققة بموجب جداول التكليف وأوامر القبض الصادرة في خالل السنة.\n -مجموع التحصيالت حتى 21كانون األول من السنة موزعة بين السنة الجارية وكل سنة من السنين السابقة.\n -المحسومات القانونية التي استفاد منھا المكلفون.\n -البقايا غير المحصلة في نھاية السنة.\n وتمسك كل وزارة حسابا ً مفصالً بالواردات التي تتولى أمرھا ،ولكل سنة على حدة ،باالستناد إلى أوامر القبض أو\n التحصيل التي تصدرھا أو تصدر بناء لطلبھا."}, {"o": 18, "l": "المادة 48", "b": "الفصل الثاني -تنفيذ النفقات\n »المادة -54مراحل تنفيذ النفقة أربع:\n -1العقد.\n -2التصفية.\n -3الصرف.\n -4الدفع.\n القسم الأول -عقد النفقة\n »المادة -55عقد النفقة ھو القيام بعمل من شأنه أن يرتب دينا ً على الدولة.\n »المادة -56يعقد النفقة الوزير المختص ما لم ينص القانون على خالف ذلك.\n»المادة -57ال تعقد النفقة إال إذا توفر لھا اعتماد في الموازنة .وال يجوز استعمال االعتماد لغير الغاية التي أرصد من\n أجلھا.\n »المادة -58معدلة وفقا ً للقانون 55/66تاريخ 3/9/1966\n توقف عمليات عقد نفقات اللوازم واألشغال بتاريخ 30تشرين الثاني من السنة غير أنه يجوز عقدھا في الحاالت\n الطارئة المستعجلة التي يعود تقديرھا للوزير المختص ووزير المالية.\n »المادة -59معدلة وفقا ً للقانون رقم 49/87تاريخ 21/11/1987\n ال تعقد أي نفقة على حساب سنة مالية قبل بدئھا.\n غير أنه يمكن ،اعتباراً من أول تشرين األول من كل سنة ،أن تعقد على حساب السنة المقبلة النفقات الدائمة التي\n تقضي المصلحة العامة باستمرارھا ،وذلك ضمن حدود االعتمادات المرصدة لھا في موازنة السنة الجارية ،كما يمكن\n خالل الفترة التي تسبق نشر الموازنة أن تعقد ھذه النفقات بعد بدء السنة الجديدة ،وذلك ضمن حدود االعتمادات\n المرصدة لھا في موازنة السنة السابقة.\n كما يمكن إجراء معامالت التصفية والصرف والدفع خالل السنة المالية المختصة.\n »المادة -60معدلة وفقا للقانون 4/80تاريخ 7/4/1980والقانون رقم 42/88تاريخ 23/6/1988\n -1توضع الموازنات االثنتا عشرية على أساس االعتمادات الدائمة المرصدة في موازنة السنة السابقة على أن يؤخذ\n بعين االعتبار ما أضيف إليھا وما أسقط منھا من اعتمادات دائمة.\n أما اعتمادات احتياطي الموازنة فال تعتبر المبالغ المنقولة منھا مسقطة.\n -2يحق للحكومة أن توزع بمرسوم يتخذ في مجلس الوزراء بناء على اقتراح الوزير المختص ووزير المالية مجموع"}, {"o": 19, "l": "المادة 48", "b": "اعتمادات اإلنشاء والتجھيز في كل موازنة اثنتي عشرية على مختلف اإلدارات العامة وفقا ً لحاجاتھا ،على أن تتقيد في\n ھذا التوزيع باالعتمادات المخصصة لكل إدارة عامة في مشروع موازنة السنة الجارية.\n -3يحق للحكومة قبل تصديق الموازنة ،بمراسيم تتخذ في مجلس الوزراء ،نقل اعتمادات على أساس القاعدة االثني\n عشرية من احتياطي الموازنة ،لتغذية مختلف البنود.\n »المادة -61كل معاملة تؤول إلى عقد نفقة يجب أن تقترن ،قبل توقيعھا ،بتأشير مراقب عقد النفقات .غير أنه يجوز\n في الحاالت المستعجلة الطارئة ،أن يشرع المرجع الصالح في عقد النفقة ضمن نطاق االعتمادات المرصدة لھا قبل\n الحصول على تأشير مراقب عقد النفقات شرط أن يعرض عليه المعاملة للتسوية بمھلة أسبوع على األكثر من تاريخ\nالعقد مع بيان األسباب التي بررت إقدامه على ھذا التدبير ويبقى عاقد النفقة مسؤوالً عنھا حتى تسوية عقدھا بصورة\n قانونية.\n يربط بكل معاملة تؤول إلى عقد نفقة طلب حجز االعتماد المختص بھا) .طلب عقد نفقة(.\n»المادة -62يوقع طلب حجز االعتماد الالزم لعقد النفقة محاسب اإلدارة المختصة أو من يفوضه بذلك بموافقة رئيسه\n التسلسلي.\n »المادة -63تنظم طلبات حجز االعتمادات:\n -عن السنة كلھا إذا كانت تتعلق برواتب ،وما شابه من نفقات الموظفين.\n -عن ثالثة أو ستة أشھر ،إذا كانت تتعلق بالنفقات الدائمة األخرى.\n وينظم طلب مستقل كلما اقتضى األمر.\n ويمكن تنظيم طلب إجمالي احتياطي لحجز االعتماد الالزم للنفقات الدائمة التي ال تسمح طبيعتھا بأن ينظم لھا طلب\n مستقل في كل مرة.\n »المادة -1 -64يتولى مراقبة عقد النفقات باسم وزير المالية:\n -رئيس مصلحة الموازنة ومراقبة النفقات بصفة مراقب مركزي لعقد النفقات.\n -مراقبون لدى الوزارات يمثلون المراقب المركزي.\n -2يمكن المراقب المركزي أن يعھد بتمثيله في بعض الوزارات إلى موظفين تابعين له يتولون التدقيق في المعامالت"}, {"o": 20, "l": "المادة 48", "b": "المعروضة عليه .وله أن يفوض إليھم بعض صالحياته.\n -3تحدد أصول مراقبة عقد النفقات بمرسوم يصدر بناء على اقتراح وزير المالية ،وتحدد صالحيات المراقبين لدى\n الوزارات بقرار من وزير المالية.\n -4يوزع المراقبون بين الوزارات بقرار من وزير المالية بناء على اقتراح المدير العام.\nوال يجوز للمراقب لدى إحدى الوزارات أن يباشر مھمته قبل أن يكون قد أمضى فترة تدريب ال تقل عن ثالثة أشھر في\n مصلحة الموازنة ومراقبة النفقات.\n »المادة -65الغاية من تدقيق المراقب التثبت من األمرين التاليين:\n -توفر اعتماد النفقة وصحة تنسيبھا.\n -انطباق المعاملة على القوانين واألنظمة النافذة ،إال إذا كانت خاضعة لرقابة مجلس الخدمة المدنية فال تدقق عندئذ إال\n من الناحية المالية.\n »المادة -66يؤشر المراقب على طلب حجز االعتماد وعلى المعاملة ويعيد األوراق إلى مصدرھا في خالل خمسة أيام\n على األكثر من تاريخ ورودھا إليه .وإذا انقضت ھذه المھلة دون أن يبت بھا ،جاز لإلدارة المختصة استعادة المعاملة\n وتنفيذھا على مسؤوليته.\nأما إذا احتاج المراقب إلى طلب إيضاحات خطية من اإلدارة المختصة فيعطى مھلة خمسة أيام تبدأ من تاريخ ورود ھذه\n\f اإليضاحات إليه .وذلك لمرة واحدة.\n وإذا كانت المعاملة تخضع لرقابة ديوان المحاسبة المسبقة أرسلھا المراقب إليه ،قبل التأشير مقرونة بمطالعته.\n »المادة -67يعتبر تأشير المراقب على طلب حجر االعتماد بمثابة تأشير على المعاملة فيما خص:\n -1النفقات التي تعقد ببيان أو فاتورة وفقا ً ألحكام الفقرة األولى من"}, {"o": 21, "l": "المادة 151", "b": "المادة 151من ھذا القانون.\n -2أوامر سفر الموظفون.\n -3تدرج الموظفين.\n -4وبصورة عامة النفقات التي حجز لھا اعتماد إجمالي وفقا ً ألحكام الفقرة األخيرة من"}, {"o": 22, "l": "المادة 63", "b": "المادة 63من ھذا القانون.\n »المادة -68تأشير المراقب على نوعين:\n -كلي ويشمل قيمة النفقة المطلوب عقدھا بكاملھا.\n -جزئي ويقتصر على قسم من النفقة المطلوب عقدھا.\n وفي حال إعطاء تأشير جزئي ،أو في حال رفض التأشير ،يتوجب على المراقب أن يعلل أسباب قراره.\n وال يعتبر التأشير جزئيا ً عندما ينتج عنه تخفيض النفقة المطلوب عقدھا بسبب خطأ مادي أو حسابي.\n »المادة -1 -69إذا أعطى المراقب المركزي تأشيراً جزئياً ،أو رفض التأشير ،توجب عليه أن يعرض المعاملة على\n وزير المالية .فإذا وافق وزير المالية على رأيه حق للوزير المختص أن يعرض األمر على مجلس الوزراء للبت به.\nوإذا لم يوافق وزير المالية على الرأي المذكور ،فعلى المراقب المركزي أن يتقيد بقرار الوزير مع مراعاة أحكام قانون\n ديوان المحاسبة.\n -2إذا أعطى المراقب لدى إحدى الوزارات تأشيراً جزئيا ً أو رفض التأشير توجب عليه عرض المعاملة على المراقب\nالمركزي .فإذا وافق المراقب المركزي على رأيه عرض المعاملة على وزير المالية وفقا ً ألحكام الفقرة السابقة .وإذا لم\n يوافق فعلى المراقب أن يتقيد بقرار المراقب المركزي.\n»المادة -70ال يجوز لمجلس الوزراء أن يوافق على عقد نفقة رفض المراقب التأشير عليھا بسبب عدم وجود اعتماد\n كاف لھا.\n »المادة -71يمكن اإلدارة المختصة أن تأخذ رأي المراقب لديھا في قضاياھا المالية وخصوصا ً في مشروع الموازنة\n وطلبات االعتمادات اإلضافية التي تقدمھا.\n »المادة -72يمكن المرجع الصالح للعقد أن يطلب زيادة أو تخفيض نفقة سبق عقدھا ،على أن يربط بطلب التعديل\n جميع المستندات الالزمة.\n القسم الثاني -تصفية النفقة\n»المادة -73تصفية النفقة ھي إثبات ترتب الدين على الدولة ،وتحديد مقداره ،واستحقاقه ،وعدم سقوطه بحكم مرور\n الزمن أو بأي سبب آخر.\n\f »المادة -74يتولى التصفية المحاسب المختص أو من يفوض إليه ذلك بموافقة رئيسه التسلسلي."}, {"o": 23, "l": "المادة 63", "b": "ويتولى محاسب مديرية المالية العامة تصفية النفقات التي تصرف من باب الديون المتوجبة األداء.\n»المادة -75معدلة وفقا ً للقانون 49/87تاريخ 21/11/1987والقانون رقم 14تاريخ 20/8/1990والقانون رقم\n 280تاريخ 15/12/1993وقانون موازنة عام 1993\n تبنى التصفية على المستندات التي من شأنھا إثبات الدين.\n تحدد ھذه المستندات ،بالنسبة لكل نوع من أنواع النفقات ،بقرار من وزير المالية يتخذ بعد استطالع رأي ديوان\n المحاسبة ،وينشر في الجريدة الرسمية.\n ويكتفى ببيان مصدق من رئيس الوحدة التي تولت تنفيذ النفقة ،إذا كانت ھذه النفقة ال تجاوز 50000ل .ل.\n تعتبر الجداول التي تصدر عن المركز األلكتروني في مديرية المالية العامة .والعائدة للرواتب واألجور ومعاشات\n التقاعد وملحقاتھا والتعويضات الشھرية على كافة أنواعھا بحكم المصفاة وال تحتاج إلى توقيع المصفين .تحدد عند\n االقتضاء دقائق تطبيق ھذه الفقرة بقرار من وزير المالية.\n »المادة -1 -76تجري التصفية عفواً ،وإذا تعذر ذلك ،فبناء على طلب الدائن.\n -2على المصفي أن ينجز التصفية في مھلة خمسة أيام على األكثر من تاريخ تسلمه األوراق الثبوتية المتعلقة بھا.\n -3يحق للدائن أن يطلب من المصفي شھادة تبين تاريخ تقديم طلبه وتفصيل األوراق المبرزة.\n »المادة -77تتم التصفية على السند المتضمن تفصيل الدين.\n القسم الثالث -صرف النفقة\n »المادة -78صرف النفقة ھو إصدار حوالة تجيز دفع قيمتھا.\n»المادة -1 -79يتولى إصدار حواالت الصرف ،باسم وزير المالية رئيس مصلحة الصرفيات في وزارة المالية ،ولھذا\nالموظف أن يفوض بعض صالحياته إلى موظفين تابعين لمصلحته ،شرط أن يكونوا من الفئة الثالثة على األقل .كما له\nأن يعھد بتمثيله في بعض الوزارات إلى موظفين من مصلحته يتولون التدقيق محليا ً في المعامالت وتحضير الحواالت."}, {"o": 24, "l": "المادة 63", "b": "-2يمكن ،عند االقتضاء ،أن يعھد بمھمة إصدار الحواالت في اإلدارات العامة والمحافظات ،ما عدا محافظة بيروت،\n إلى موظفين من الفئة الثالثة على األقل تابعين لمالك وزارة المائية ،على أن يتم ذلك بمرسوم.\n -3على اآلمر بالصرف أن ينجز معاملة الصرف في مھلة سبعة أيام من تاريخ ورودھا إليه وتمدد ھذه المھلة إلى\n عشرة أيام فيما خص معامالت صرف الرواتب.\n أما إذا احتاج اآلمر بالصرف إلى طلب إيضاحات خطية من اإلدارة المختصة فيعطى مھلة خمسة أيام تبدأ من تاريخ\n ورود ھذه اإليضاحات إليه وذلك لمرة واحدة.\n »المادة -80يمكن المثابرة على صرف نفقات السنة المالية حتى تاريخ 31كانون الثاني من السنة الالحقة ،على أن\n تقيد بتاريخ 31كانون األول من السنة التي صرفت على حسابھا.\n »المادة -81معدلة وفقا للقانون 55/66تاريخ 3/9/1966\n إن المبالغ التي ترتبت على الدولة لصالح الغير خالل سنة مالية معينة ولم تصرف قبل أول شباط من السنة الالحقة،\n\f ألي سبب كان تدعى نفقات السنين السابقة.\n »المادة -82ال يجوز إصدار الحوالة إال بعد التثبت من األمور التالية:\n -1اقتران معاملة عقد النفقة بتوقيع المرجع الصالح للعقد وتأشير مراقب عقد النفقات.\n -2انطباق تنسيب النفقة على معاملة العقد.\n -3صحة حسابات النفقة.\n -4انطباق معاملة التصفية على القوانين واألنظمة المالية فقط.\n »المادة -83تنظم حوالة لكل صاحب حق عندما تصرف من بند واحد أو فقرة واحدة.\n »المادة -84تنظم الحوالة باسم الدائن ،ولو عين وكيالً أو مندوبا ً عنه للقبض ،وباسم الورثة في حال وفاته .وتنظم\n باسم رئيس مصلحة الخزينة إذا كانت الدولة صاحبة الدين ،وباسم المحتسب المختص إذا كان صاحب الدين بلدية أو\n مؤسسة عامة.\n وتنظم باسم المحافظ المختص إذا كانت تتعلق بمبالغ تعود لقرى ليس لھا بلديات ،على أن يودع المبلغ أمانة باسم\n المحافظ المذكور لدى محتسب القضاء المركزي.\n »المادة -85يمكن تنظيم الحوالة:"}, {"o": 25, "l": "المادة 63", "b": "-1باسم معتمد للقبض تعينه اإلدارة المختصة ،فيما يتعلق برواتب الموظفين ونفقاتھم ،ومعاشات التقاعد.\n -2باسم الموظف الذي دفع المبلغ من ماله ،فيما يتعلق بأجور النقل ،وبعض النفقات النثرية.\n -3باسم القيم على السلفة ،فيما يتعلق بالنفقات التي يدفعھا من أصلھا.\nويمكن بناء على طلب اإلدارة المستملكة ،أن تنظم الحواالت المتعلقة بتعويضات االستمالك باسم محتسب القضاء الذي\nتقع فيه العقارات المستملكة ،أو القضاء المتاخم له ،على أن تنظم شروط دفع ھذه التعويضات بقرار من وزير المالية.\n »المادة -86تبلغ إلى المرجع الصالح إلصدار الحواالت قرارات الحجز ،وصكوك التنازل المتعلقة بديون مترتبة على\n الدولة .وال يعتد بأي تبليغ يوجه إلى سواه.\n وعلى المرجع المذكور أن يجيب ضمن المھلة القانونية الجھة التي أبلغته الحجز ،وأن يدون الحجز أو التنازل على\n الحوالة قبل إصدارھا.\n »المادة -87معدلة وفقا ً للقانون 55/66تاريخ 3/9/1966\n يوقع الحوالة المرجع الصالح إلصدارھا ويرسلھا إلى المحتسب المختص لتأمين دفعھا.\n»المادة -88إذا فقدت حوالة ،أعطي صاحبھا نسخة عنھا ،بناء على طلب منه يبين فيه أسباب الفقدان ،وعلى شھادة\n خطية من المحتسب المركزي بأن الحوالة لم تدفع وبأنه أخذ علما ً بوجوب عدم دفعھا.\n القسم الرابع -دفع النفقة\n »المادة -89معدلة وفقا ً للقانون رقم 55/66تاريخ 3/9/1966\n\f تصبح الحوالة صالحة للدفع بعد تأشير المحتسب المركزي ،أو من يفوض إليه ذلك بموافقة المدير العام المختص.\n وعلى ھذا الموظف:\n أ -أن يرفض التأشير وأن يعيد الحوالة إلى مصدرھا مع بيان أسباب الرفض في الحاالت التالية:\n أوالً -إذا كانت الحوالة غير مذيلة بتوقيع المرجع الصالح إلصدارھا.\n ثانيا ً -إذا كانت األوراق المثبتة للنفقة غير مربوطة بالحوالة.\n ثالثا ً -إذا كان اسم صاحب الدين ،أو موضوع النفقة ،أو مقدارھا غير منطبق على األوراق الثبوتية."}, {"o": 26, "l": "المادة 63", "b": "ب -إنجاز المعاملة ووضع أمر الدفع العائد للحوالة تحت تصرف اإلدارة المختصة في مھلة ثالثة أيام من تاريخ\n ورودھا إليه.\n »المادة -90معدلة وفقا ً القانون 55/66تاريخ 3/9/1966\n تنظم شروط دفع الحواالت التي يجري إصدارھا في المحافظات بمرسوم يتخذ بناء على اقتراح وزير المالية.\n»المادة -91تدفع الحواالت نقداً من الصندوق المعين فيھا ،ويمكن أن يجري الدفع بواسطة تحويل لحساب مصرفي.\n »المادة -92تدفع رواتب الموظفين عن شھر كانون الثاني بصورة استثنائية خالل العشرة أيام األخيرة من شھر\n كانون األول.\n الفصل الثالث -تأدية النفقات بدون حوالة مسبقة\n القسم الأول -أحكام عامة\n »المادة -93يمكن تأدية بعض النفقات بدون حوالة دفع مسبقة على أن تنظم الحوالة فيما بعد على سبيل التسوية.\n إن النفقات التي يمكن تأديتھا على الصورة المبينة أعاله ھي:\n -1الرواتب واألجور وملحقاتھا ،ومعاشات التقاعد ،وتعويضات حملة األوسمة العسكرية.\n -2النفقات النثرية العادية ،والنفقات المستعجلة ،وسوى ذلك من النفقات التي ال تسمح طبيعتھا أو الظروف بدفعھا\n مباشرة بالطريقة العادية.\n »المادة -94تنظم بمرسوم شروط تأدية النفقات المبينة في الفقرة األولى من المادة السابقة.\nأما النفقات المبينة في الفقرة الثانية فتؤدى بواسطة سلفات دائمة أو طارئة تسمى سلفات موازنة وتعطى وفقا ً ألحكام\n المواد التالية ضمن االعتمادات المرصدة في الموازنة.\n القسم الثاني -سلفات الموازنة\n\f »المادة -95السلفة الدائمة ھي التي تعطى إلى اإلدارات العامة لتأمين نفقاتھا المستمرة خالل السنة الجارية.\n والسلفة الطارئة ھي التي تعطى إلى اإلدارات العامة أو إلى شخص معين لتأدية نفقة يمكن مبدئيا ً أن ال تجدد.\n أولاً -السلفات الدائمة\n »المادة -96يدير السلفة الدائمة قيم يعين بقرار من وزير المالية والوزير المختص.\n يحدد في ھذه القرار:"}, {"o": 27, "l": "المادة 63", "b": "-مقدار السلفة التي يجب أن يعادل مبدئيا ً ثالثة أضعاف النفقات الشھرية المرتقبة.\n -نوع النفقات التي يمكن دفعھا من أصل السلفة.\n ً\n -المھلة القصوى لتقديم األوراق المثبتة للنفقات وتسديد السلفة نھائيا ،على أن ال يتجاوز ذلك 31كانون الثاني من\n السنة التالية على أبعد حد.\n -اسم القيم على السلفة ،ومركزه ،ونوع الكفالة التي قد يلزم بتقديمھا ،ومقدارھا.\n»المادة -97تعطى السلفة الدائمة بدون تأشير مسبق من مراقب عقد النفقات .غير أنه ال يجوز للقيم أن يؤدي منھا\n غير النفقات التي سبق عقدھا وتصفيتھا وفقا ً لألصول.\n »المادة -98يدفع المحتسب المركزي السلفة الدائمة إلى القيم بناء على القرار القاضي بإعطائھا.\n »المادة -99تسدد النفقات المؤداة من أصل السلفة بحواالت تصدر باسم القيم .وتجدد السلفة بمقدار المبالغ\n المصروفة بموجب ھذه الحواالت دون حاجة إلى استصدار أي قرار جديد.\n »المادة -100يتولى القيم على السلفة:\n -قبض السلفة وحواالت التسديد.\n -تأمين التأديات.\n -جمع األوراق المثبتة للنفقة وتقديمھا إلى المرجع الصالح إلصدار الحواالت بصورة منتظمة في آخر كل شھر.\n -مسك حساب للسلفة تحدد أصوله بقرار من وزير المالية.\n »المادة -101تجري معامالت التصفية والصرف العادية استناداً إلى األوراق المثبتة التي يقدمھا القيم .وإذا تبين\nلمصلحة الصرفيات أن بعض األوراق المثبتة غير نظامية ،عمدت إلى إصدار الحوالة بمقدار األوراق الصالحة ،وإلى\n إعادة األوراق األخرى إلى اإلدارة المختصة في مھلة خمسة أيام على األكثر .ويجوز في الحالة األخيرة زيادة قيمة\n السلفة بمقدار األوراق الموقوف صرفھا.\n»المادة -102إن السلفات الدائمة التي يتجاوز مقدارھا حداً يعود تقديره لوزير المالية ،يجب أن تودع باسم القيم في\n صندوق من صناديق الدولة يعينه القرار القاضي بإعطاء السلفة.\n »المادة -103تحدد بقرار من وزير المالية أصول التأدية بواسطة السلفات الدائمة."}, {"o": 28, "l": "المادة 63", "b": "ثانياً -السلفات الطارئة\n »المادة -104تعطى السلفة الطارئة بقرار من مدير المالية العام بعد تأشير مراقب عقد النفقات.\n يحدد في ھذا القرار:\n -مقدار السلفة.\n -وجھة اإلنفاق.\n -الشخص الذي تعطى السلفة باسمه.\n -المھلة القصوى لتقديم األوراق المثبتة لتسديد السلفة نھائياً ،على أن ال يتجاوز ذلك 31كانون الثاني من السنة\n التالية على أبعد حد.\n »المادة -105تدفع السلفة الطارئة بموجب أمر دفع ينظمه المرجع الصالح إلصدار الحواالت استناداً إلى القرار\n القاضي بإعطاء السلفة.\n »المادة -106تنظم حوالة التسديد باسم الشخص الذي أعطي السلفة.\n ثالثاً -أحكام مشتركة بين السلفات الدائمة والسلفات الطارئة\n »المادة -107ال تستعمل السلفة في غير الغاية التي أعطيت من أجلھا ،وتراعى في استعمالھا األحكام القانونية\n القاضية بتنظيم األموال العمومية.\n »المادة -108تسدد السلفة إما نقداً بإعادة قيمتھا إلى الخزينة ،أو بأوراق مثبتة للنفقة ،أو بالطريقتين معاً ،وذلك\n ضمن المھلة المحددة في القرار القاضي بإعطائھا.\n »المادة -109إن القيم على السلفة مسؤول شخصيا ً على أمواله الخاصة عن قيمتھا .وعليه أن يبرر عند كل طلب\n وجودھا لديه إما نقداً ،وإما بأوراق مثبتة لما أنفقه من أصلھا.\n»المادة -110على رئيس مصلحة الخزينة أن يؤمن تدقيق حسابات السلفات مرة على األقل كل ستة أشھر ،ويحق له\n أن يحسم مباشرة من راتب القيم على السلفة وتعويضاته المبالغ التي ال يثبت استعمالھا ،أو التي يتجاوز في إنفاقھا\n مقدار النفقات المستحقة ،أو التي ال يسددھا في المواعيد المحددة ،كما له أن ينفذ تلقائيا ً بحقه أي تدبير قانوني آخر\n يؤمن استرداد ھذه المبالغ.\n الفصل الرابع -أحكام مختلفة\n\f»المادة -111إذا عقدت نفقة وفقا ً ألحكام القانون قبل الحصول على تأشير مراقب عقد النفقات ،وكان يقابلھا اعتماد،\n صرفت على سبيل التسوية ،على أن يالحق المسؤولون أمام ديوان المحاسبة."}, {"o": 29, "l": "المادة 63", "b": "»المادة -112الوزير مسؤول شخصيا ً على أمواله الخاصة عن كل نفقة يعقدھا متجاوزاً االعتمادات المفتوحة لوزارته\nمع علمه بھذا التجاوز ،وكذلك عن كل تدبير يؤدي إلى زيادة النفقات التي تصرف من االعتمادات المذكورة إذا كان ھذا\n التدبير غير ناتج عن أحكام تشريعية سابقة.\nوال تحول ھذه المسؤولية دون مالحقة الموظفين الذين تدخلوا بعقد النفقة ،وتصفيتھا ،وصرفھا ،أمام ديوان المحاسبة،\n ما لم يبرزوا أمراً خطيا ً من شأنه إعفاؤھم من المسؤولية.\n»المادة -113على مراقب عقد النفقات ،وعلى غيره من المراجع عند االقتضاء ،كل فيما خصه ،أن يعلم المدعي العام\n لدى ديوان المحاسبة بالمخالفات المبينة في المادتين السابقتين.\n »المادة -114معدلة وفقا ً للقانون 89تاريخ 7/9/1991والقانون رقم 201تاريخ 2/3/1993والقانون 490\n تاريخ 15/2/1996\n -1تلغى االعتمادات التي لم تعقد حتى 31كانون األول من السنة.\n -2تدور إلى موازنات السنين الالحقة.\n أ -االعتمادات المرصدة في البند 7من الجزء االول المخصصة اسميا واالعتمادات المرصدة\n في البنود 20و 21و 22و 23ومن الجزء الثاني وفي البنود 40و 41و 42و 43من\n الجزء الثاني سواء اكانت معقودة أم ال ،وذلك حتى نفاذھا أو إنجاز األعمال التي أرصدت لھا\n وذلك مع مراعاة احكام المادة السابعة عشرة من ھذا القانون وتطبيق احكام ھذه المادة على\n االعتمادات التي تدور من الموازنة العامة والموازنة الملحقة للعام 1995الى الموازنة\n العامة والموازنة الملحقة للعام .1996\n ب -االعتمادات المرصدة في الجزئين األول والثاني التي عقدت ولم تصرف حتى 31\n كانون األول من السنة ،إذا كان يتعلق بھا حق الغير ،وكذلك إذا كانت تعود ألشغال باألمانة\n بوشر بھا فعالً قبل آخر السنة.\n يجري التدبير بقرار من وزير المالية يصدر بناء على طلب اإلدارة المختصة قبل أول آذار من السنة التالية .ويجوز"}, {"o": 30, "l": "المادة 63", "b": "للمرجع الصالح لعقد النفقة ،قبل صدور القرارات القاضية بتدوير االعتمادات المذكورة في المقطع »أ« من الفقرة\n ) ،(2عقد النفقات التي تصرف من ھذه االعتمادات ،شرط أن ال تتجاوز قيمة ھذه النفقة رصائد االعتمادات الباقية\n بدون استعمال بتاريخ 31كانون األول.\n »المادة -115معدلة وفقا للمرسوم االشتراعي رقم 57تاريخ 5/8/1967\n تسقط حكما ً بمرور الزمن ،وتتالشى نھائيا ً لصالح الدولة ،الديون التي لم تصف أو لم تصرف أو لم تدفع لغاية 31\n كانون األول من السنة الرابعة بعد السنة المالية التي نشأ فيھا الدين ،إال إذا كان التأخير ناتجا ً عن اإلدارة أو التداعي\n أمام القضاء.\n »المادة -116معدلة وفقا للقانون 55/66تاريخ 3/9/1966\n -1تصرف نفقات السنين السابقة التي لم تسقط بمرور الزمن من االعتمادات المدورة لھذه الغاية إلى موازنة السنة\n الجارية.\n كما يمكن إذا سمحت حالة االعتمادات بذلك أن تصرف ھذه النفقات من اعتمادات موازنة السنة الجارية.\n -2مع مراعاة أحكام الفقرة األولى من ھذه المادة ،تصرف نفقات السنين السابقة العائدة لما قبل سنة 1963والتي لم\n\f تسقط بمرور الزمن ،من الفصل المختص بنفقات السنين السابقة في موازنة السنة الجارية وفقا ً ألحكام الفقرة 3من"}, {"o": 31, "l": "المادة 25", "b": "المادة 25\n »المادة -117إن المبالغ التي تدفعھا الخزينة خطأ أو بغير حق وتستردھا خالل السنة المالية التي صرفت خاللھا\n يمكن أن تضاف إلى اعتماد الوزير المختص بقرار من وزير المالية .وعلى الوزير المختص أن يقدم إلى وزير المالية\n طلبا ً بھذا الشأن خالل مدة أقصاھا 31كانون األول من السنة ذاتھا.\n »المادة -118لوزير المالية ،إذا وجد ضرورة لذلك ،أن يقترح على مجلس الوزراء وقف استعمال بعض االعتمادات\nالمرصدة في الموازنة .ولمجلس الوزراء أن يقرر الموافقة على االقتراح إذا كانت الظروف الراھنة تبرر اتخاذ مثل ھذا\n التدبير.\n »المادة -119تمسك وزارة المالية حسابات مستقلة لما يعقد ويصرف ويدفع من النفقات ،وتمسك اإلدارات المختصة\n حسابات مقابلة لما تعقده وتصفيه وما يصرف من نفقات.\n الفصل الخامس -أحكام خاصة بنفقات اللوازم والأشغال والخدمات\n »المادة -120تنفذ نفقات اللوازم ،واالشغال ،والخدمات ،إما بواسطة صفقات تعقدھا اإلدارة مع الغير ،وإما بواسطة\n اإلدارة مباشرة أي بطريقة األمانة.\n القسم الأول -صفقات اللوازم والأشغال والخدمات\n »المادة -121تعقد صفقات اللوازم واألشغال والخدمات بالمناقصة العمومية.\n غير أن يمكن ،في الحاالت المبينة فيما يلي ،عقد الصفقات بطريقة المناقصة المحصورة ،أو استدراج العروض ،أو\n التراضي ،أو بموجب بيان أو فاتورة.\n »المادة -122تجرى المناقصات العمومية والمحصورة على أساس برنامج سنوي عام يعلن عنه في تواريخ ال يجوز\n أن تتعدى الشھر الثاني الذي يلي نشر الموازنة.\n »المادة -123ال يجوز تجزئة النفقة إال إذا رأى المرجع الصالح لعقد النفقة أن ماھية األشغال أو اللوازم أو الخدمات\n المراد تلزيمھا تبرر ذلك.\n أولاً -المناقصات العمومية\n\f »المادة -124تجرى المناقصة العمومية )المعبر عنھا فيما يلي بكلمة »المناقصة«( أما على أساس سعر يقدمه\n العارض ،وإما على أساس تنزيل مئوي من أسعار الكشف التخميني المبين في"}, {"o": 32, "l": "المادة 126", "b": "المادة 126من ھذا القانون.\n »المادة -125توضع للصفقات التي تعقد بالمناقصة دفاتر شروط عامة نموذجية تصدق بمراسيم وتنشر في الجريدة\n الرسمية .ويوضع لكل صفقة منھا دفتر شروط خاص تنظمه اإلدارة صاحبة العالقة ويوقعه المرجع الصالح لبت في\n الصفقة.\n »المادة -126معدلة وفقا ً للقانون 17/82تاريخ 18/3/1982\n تبين في دفتر الشروط الخاص المعلومات التالية:\n -أنواع اللوازم أو األشغال أو الخدمات المراد تلزيمھا وأوصافھا.\n -المؤھالت والشروط الخاصة التي يجب أن تتوفر في من يريد االشتراك في المناقصة.\n -عناصر المفاضلة :كلما كان في نية اإلدارة أن ال تتقيد بالسعر األدنى ،على أن تبين ھذه العناصر بصورة واضحة\n ومفصلة ،وأن يوضع لكل منھا معدل خاص عند االقتضاء.\n -األساس الذي يعتمد إلجراء المناقصة وفقا ً ألحكام المادة .124\n -شروط التنفيذ الخاصة.\n -مھلة التسليم.\n -مقدار الكفالة التي يجب تقديمھا لالشتراك في المناقصة ولضمان حسن قيام الملتزم بتعھداته.\n ويضم إلى دفتر الشروط الخاصة ،كلما كان ذلك ممكنا ً:\n -كشف تخميني بالكميات واألسعار.\n -جداول أسعار يتضمن وصفا ً لكل نوع من أنواع اللوازم أو األشغال أو الخدمات المراد تلزيمھا ،ويحدد لكل نوع سعراً\n مفقطا ً.\n يعتبر السعر الموضوع من قبل اإلدارة الحد األعلى للصفقة التي تجري على أساس التنزيل المئوي وتعلن اإلدارة عن\n الحد األقصى للتنزيل الذي يمكن أن يقبل به ويعتبر ھذا التنزيل الحد األدنى للصفقة.\n »المادة -127تكون الكفالة:\n -1إما نقدية تدفع قيمتھا إلى أحد صناديق الخزينة مباشرة ،أو إلى صندوق اإلدارة المختصة عند وجوده ،وذلك لقاء\n إيصال يربط بالعرض ،على أن تحول قيمتھا في الحالة الثانية إلى صندوق المالية المركزي فور إسناد االلتزام.\n -2وأما مصرفية صادرة عن مصرف مقبول ومحررة باسم المراكز المختصة أو باسم خزينة الدولة."}, {"o": 33, "l": "المادة 126", "b": "»المادة -128يعلن عن كل مناقصة في الجريدة الرسمية وفي ثالث صحف يومية على األقل ،قبل التاريخ المحدد\n للتلزيم بمدة 15يوما ً على األقل.\n ويمكن تخفيض المدة إلى خمسة أيام على األقل عند إعادة المناقصة ،أو عند الضرورة ،شرط أن يقترن التخفيض\n مسبقا ً بموافقة المرجع الصالح لعقد النفقة.\n كما يعلن وفقا ً لألصول نفسھا عن كل تعديل يطرأ على دفتر الشروط بعد نشر إعالن المناقصة.\n »المادة -129ملغاة وفقا للقانون رقم 16/78تاريخ 2/5/1978\n »المادة -130تجري المناقصات لجان تشكل خصيصا ً لكل الغاية.\n\f»المادة -131معدلة وفقا ً للمرسوم 3249تاريخ 17/5/1972والقانون رقم 16/78تاريخ 2/5/1978والقانون\n 17/82تاريخ 18/3/1983\nيسند االلتزام موقتا ً من قدم أدنى األسعار أو إلى من قدم أفضل العروض إذا كان دفتر الشروط يقضي باعتماد عناصر\nمفاضلة غير السعر ،على أن تعطى العروض المقدمة لسلع مصنوعة في لبنان أفضلية بنسبة 10بالمئة عن العروض\n المقدمة لسلع أجنبية شرط أن تحدد السلع الوطنية والشروط التي يجب أن تتوفر فيھا لالستفادة من ھذه األفضلية\n بمراسيم تتخذ في مجلس الوزراء بناء على اقتراح وزير االقتصاد الوطني.\n أما في االلتزامات التي تجري على أساس تنزيل مئوي فعلى لجنة المناقصة إسناد االلتزام مؤقتا ً إلى من قدم أدنى\n األسعار ضمن السعرين التقديريين.\n »المادة -132معدلة وفقا للمرسوم رقم 3249تاريخ 17/5/1972والقانون رقم 17/82تاريخ 18/3/1982\n إذا تساوت العروض بعد إعطاء السلع اللبنانية أفضلية 10بالمئة المذكورة في"}, {"o": 34, "l": "المادة 131", "b": "المادة 131أعاله أعيدت المناقصة\n بطريقة الظرف المختوم بين أصحابھا دون سواھم في الجلسة نفسھا ،فإذا رفضوا تقديم عروض جديدة أو إذا ظلت\n عروضھم متساوية عين الملتزم المؤقت بطريقة القرعة بين أصحاب العروض المتساوية.\n أما في االلتزامات التي تجري على أساس تنزيل مئوي فإذا تساوت العروض يعين الملتزم المؤقت بطريقة القرعة بين\n العروض المتساوية.\n »المادة -133معدلة وفقا لقانون الموازنة للعام 1994\n -1يبت الصفقة:\n -المدير المختص أو رئيس المصلحة في حال عدم وجود مدير إذا كانت قيمتھا ال تتجاوز عشرة ماليين ليرة لبنانية /\n /10.000.000ل .ل.\n -المدير العام إذا كانت قيمتھا تزيد على /10.000.000/ليرة لبنانية وال تتجاوز /35.000.000/ل .ل.\n -الوزير في الحاالت األخرى.\n -2ال تصبح الصفقة نھائية إال بعد إبالغ التصديق إلى الملتزم بالطريقة اإلدارية.\n »المادة -134ال يجوز مبدئيا ً عقد صفقات األشغال إال بعد إتمام جميع اإلجراءات القانونية التي تمكن اإلدارة من\n وضع يدھا على مواقع العمل ،غير أنه يمكن مباشرة معامالت التلزيم قبل إتمام ھذه اإلجراءات ،شرط أن ال تصدق\n الصفقة وتبلغ إلى الملتزم إال بعد وضع اليد على المواقع المذكورة.\n »المادة -135إذا ترتب على الملتزم في سياق التنفيذ مبلغ ما ،تطبيقا ً ألحكام دفتر الشروط ،حق لإلدارة اقتطاع ھذا\n المبلغ من الكفالة ودعوة الملتزم إلى إكمالھا ضمن مدة معينة ،فإذا لم يفعل اعتبر ناكالً ،وعمدت اإلدارة إما إلى إعادة\n المناقصة ،وإما إلى تنفيذ الصفقة باألمانة .فإذا أسفرت المناقصة الجديدة أو التنفيذ باألمانة عن وفر في األكالف عاد\n الوفر إلى الخزينة ،وإذا أسفرت عن زيادة في األكالف رجعت اإلدارة على الملتزم الناكل بالزيادة.\n وفي جميع األحوال تصادر الكفالة مؤقتا ً إلى حين تصفية الصفقة وفقا ً ألحكام ھذه المادة."}, {"o": 35, "l": "المادة 131", "b": "»المادة -136يفسخ العقد حكما ً بين اإلدارة والملتزم الذي يعلن إفالسه ،وتتبع فوراً اإلجراءات التالية:\n -1تصادر الكفالة مؤقتا ً لحساب الخزينة.\n -2تحصي اإلدارة األشغال أو اللوازم والخدمات المنفذة أو المواد المدخرة قبل تاريخ إعالن اإلفالس وتنظم بھا كشفا ً\n تصرف قيمته مؤقتا ً أمانة باسم الخزينة.\n -3توضع األشغال أو اللوازم أو الخدمات أو ما تبقى منھا باألمانة أو يعاد تلزيمھا فإذا أسفرت المناقصة الجديدة أو\nالتنفيذ باألمانة عن وفر في األكالف عاد الوفر إلى الخزينة ،ودفعت الكفالة وقيمة الكشف المبين في الفقرة السابقة إلى\n وكيل التفليسة .وإذا أسفرت عن زيادة في األكالف اقتطعت الزيادة من الكفالة وقيمة الكشف المذكور ودفع الباقي إلى\n وكيل التفليسة .وإذا لم يكف ذلك لتغطية الزيادة بكاملھا اكتفى باالستيالء على الكفالة وقيمة الكشف.\n\f »المادة -137معدلة وفقا للمرسوم رقم 55/66تاريخ 3/9/1966والقانون رقم 49/87تاريخ 21/11/1987و\n القانون رقم 14تاريخ 20/8/1990\n ال تدفع قيمة الصفقة إال بعد تنفيذھا.\n إال أنه يجوز لوزير المالية ،بناء على طلب الوزير المختص ،أن يعطي الملتزمين سلفات لقاء كفاالت مصرفية ،وإذا\n تعذر الحصول على ھذه الكفاالت ،علق إعطاء السلفة بدون كفالة على تصديق مجلس الوزراء.\n ال يجوز أن تتعدى السلفة %25من قيمة الصفقة على أن ال تتجاوز 30.000.000ل .ل .إال أنه يجوز في الحاالت\n االستثنائية الشذوذ عن األحكام السابقة بقرار من مجلس الوزراء.\n »المادة -138يمكن ،إذا نص دفتر الشروط على ذلك ،أن تدفع لقاء الخدمات المنجزة مبالغ على الحساب ال تتجاوز\n تسعة أعشار المبلغ المستحق ،ويبقى العشر موقوفا ً في الخزينة إلى أن يتم االستالم النھائي.\n ترد ھذه التوقيفات عند االستالم النھائي إذا كان دفتر الشروط ال يحدد مدة لضمان اللوازم أو األشغال ،وذلك بعد أن"}, {"o": 36, "l": "المادة 131", "b": "يسدد الملتزم الذمم التي تكون قد ترتبت عليه تطبيقا ً ألحكام دفتر الشروط.\n ويمكن اإلدارة أن تكف عن اقتطاع التوقيفات العشرية عندما ترى أنھا بلغت الحد الالزم للضمان.\n »المادة -139تستلم اللوازم واألشغال والخدمات في كل وزارة لجنة تعين بقرار من المدير العام ،على أن تضم ثالثة\n موظفين ينتمي أحدھم إلى الوحدة التي جرى التلزيم لمصلحتھا ،ويكون اآلخران من خارجھا.\n»المادة -140إذا خالف الملتزم في تنفيذ الصفقة دفتر الشروط أو بعض أحكامه قامت اإلدارة المختصة بإنذاره رسميا ً\n بوجوب التقيد بكامل موجباته ،وذلك ضمن مھلة معينة يعود لھا أمر تقديرھا .وإذا انقضت المھلة المحددة دون أن\n يقوم الملتزم بتنفيذ ما طلب إليه ،حق لإلدارة ،مع مراعاة أحكام دفتر الشروط العام أن تعتبره ناكالً وان تطبق بحقه\n أحكام"}, {"o": 37, "l": "المادة 135", "b": "المادة 135من ھذا القانون.\n وفي حال إعادة المناقصة ،ال يحق للملتزم الناكل أن يشترك فيھا مجدداً.\n أما إذا رأت لجنة االستالم أن الصفقة قد نفذت بصورة عامة وفقا ً ألحكام دفتر الشروط مع وجود بعض النواقص أو\n العيوب الطفيفة التي ال تحول دون إجراء االستالم ،فيمكنھا أن تقوم باالستالم وفقا ً لشروط تحدد بمرسوم يتخذ في\n مجلس الوزراء.\n »المادة -141ترد الكفالة إلى الملتزم بناء على مذكرة من اإلدارة المختصة بعد شھر على األكثر من تاريخ االستالم\nالنھائي .غير أنه يمكن اإلدارة قبل انقضاء مھلة التنفيذ ،أو بعد االستالم الموقت إذا كانت حالة األشغال تسمح بذلك ،أن\n ترد إلى الملتزم ،بناء على طلبه ،كامل ھذه الكفالة أو قسما ً منھا.\n »المادة -142إن الملتزم الذي توضع أشغاله باألمانة أو يعاد تلزيمھا لحسابه تطبيقا ً ألحكام ھذا القانون أو ألحكام\n دفتر الشروط العام يقصى عن المناقصات:\n -مدة ثالثة أشھر عند تطبيق ھذه اإلجراءات عليه للمرة األولى.\n -مدة سنة كاملة عند تطبيقھا عليه مرة ثانية خالل اثني عشر شھراً.\n -نھائيا ً عند تطبيقھا عليه مرة ثالثة خالل خمس سنوات.\n تبدأ المھل المذكورة أعاله من تاريخ القرار األول القاضي بوضع األشغال باألمانة أو إعادة تلزيمھا لحساب الملتزم.\n ثانياً :المناقصة المحصورة\n\f»المادة -143يمكن اإلدارة ،إذا كانت طبيعة اللوازم أو األشغال أو الخدمات ال تسمح بفتح باب المنافسة أمام الجميع،\n أن تحصر المناقصة بين فئة محدودة من المناقصين تتوفر فيھم المؤھالت المالية والفنية والمھنية المطلوبة.\n تحدد ھذه المؤھالت بصورة مفصلة في دفتر الشروط الخاص ،كما تحدد فيه سائر الضمانات التي يجب أن تتوفر في\n المناقصين والمواصفات التي يجب أن تتميز بھا األشغال أو المواد المطلوبة.\n »المادة -144تطبق على المناقصة المحصورة سائر األحكام المتعلقة بالمناقصات العمومية.\n ثالثاً :استدراج العروض"}, {"o": 38, "l": "المادة 135", "b": "»المادة -145معدلة وفقا للقانون رقم 16/78تاريخ 2/5/1978والقانون رقم 49/87تاريخ 21/11/1987\n والقانون رقم 14تاريخ 20/8/1990و"}, {"o": 39, "l": "المادة 24", "b": "المادة 24من قانون الموازنة لعام 1994\n يمكن عقد الصفقات بطريقة استدراج العروض:\n أ -إذا كانت قيمتھا ال تجاوز 100.000.000ليرة لبنانية.\n ب -إذا كانت قيمتھا تجاوز 100.000.000ليرة لبنانية وكانت تتعلق:\n -1باألشغال التي تقوم بھا اإلدارة على سبيل التجربة أو الدرس ،شرط أن يقرر ذلك الوزير المختص.\n -2باألشياء والمواد والغالل التي يجب شراؤھا في مكان إنتاجھا نظراً لطبائعھا الخاصة.\n -3بالشحن والنقليات والضمان.\n -4باللوازم واألشغال والخدمات التي لم يقدم بشأنھا أي سعر في المناقصة ،أو قدمت بشأنھا أسعار غير مقبولة.\n -5باللوازم واألشغال والخدمات التي ال تسمح بعض الحاالت المستعجلة الناشئة عن ظروف طارئة بطرحھا في\n المناقصة ،على أن يقرر ذلك الوزير المختص.\n -6باللوازم واألشغال والخدمات الفنية التي ال تسمح طبيعتھا بطرحھا في المناقصة العمومية ،على أن يقرر ذلك\n الوزير المختص.\n »المادة -146معدلة وفقا للقانون رقم 16/78تاريخ 2/5/1978والقانون رقم 49/87تاريخ 21/11/1987\n والقانون رقم 14تاريخ 20/8/1990و"}, {"o": 40, "l": "المادة 24", "b": "المادة 24من قانون الموازنة لعام 1994\n تطبق على استدراج العروض النصوص المتعلقة بالمناقصات العمومية مع مراعاة األحكام التالية:\n -1يمكن أن يستعاض عن اإلعالن بتبليغ المعلومات الالزمة بطريقة سريعة ومضمونة إلى تجار الصنف أو أرباب\n المھنة الذين ترى اإلدارة فيھم مقدرة على تنفيذ الصفقة.\n -2تجري استدراج العروض للصفقة التي ال تجاوز قيمتھا 100.000.000ل .ل .لجنة خاصة تعين في كل إدارة\n عامة ،بقرار من الوزير ،وتجري الصفقات األخرى لجنة المناقصات.\n رابعاً -الاتفاق بالتراضي\n »المادة -147يمكن عقد االتفاقات بالتراضي ،مھما كانت قيمة الصفقة ،إذا كانت تتعلق:\n\f -1باللوازم واألشغال والخدمات التي ال يمكن وضعھا في المناقصة ،إما لضرورة بقائھا سرية ،وإما ألن مقتضيات\n السالمة العامة تحول دون ذلك ،شرط أن يقرر ذلك الوزير المختص.\n -2باللوازم واألشغال والخدمات اإلضافية التي يجب أن يعھد بھا إلى الملتزم األساسي لئال يتأخر تنفيذھا ،أو ال يسير\n سيراً حسنا ً فيما إذا جيء بملتزم جديد أثناء تنفيذ الصفقة ،ويجوز ذلك:\n -إذا كانت اللوازم واألشغال والخدمات غير متوقعة عند إجراء التلزيم األول ،ومعتبرة من لواحقه ،وتشكل جزءاً متمما ً\n له.\n -إذا كانت اللوازم واألشغال والخدمات يجب أن تنفذ بواسطة آالت وتجھيزات خاصة يستعملھا لملتزم في مكان العمل،\n على أن تكون غير متوقعة عند إجراء التلزيم ،وأن تشكل جزءاً متمما ً له.\n -3باألشياء التي ينحصر حق صنعھا في حامل شھادات اختراعھا.\n -4باألشياء التي ال يملكھا إال شخص واحد.\n -5باللوازم واألشغال والخدمات الفنية التي ال يمكن أن يعھد بتنفيذھا إال لفنانين أو اختصاصيين أو حرفيين أو\n صناعيين دل االختبار على اقتدارھم.\n -6باللوازم واألشغال التي يصنعھا ذوو العاھات المحتاجون المرخص لھم بالعمل من قبل وزارة العمل والشؤون\n االجتماعية ،على أن ال تجاوز أسعارھا األسعار الرائجة في السوق."}, {"o": 41, "l": "المادة 24", "b": "-7بنفقات الضيافة والتشريفات :وما شاكلھا من نفقات التمثيل.\n -8باللوازم واألشغال والخدمات التي أجريت من أجلھا:\n -مناقصتان متتاليتان.\n -أو استدراج عروض على مرتين متتاليتين.\n -أو مناقصة تالھا استدراج عروض.\n وذلك دون أن تسفر ھذه العمليات عن نتيجة إيجابية.\nويجب في ھذه الحالة أن ال يسفر االتفاق الرضائي عن سعر يتجاوز أنسب األسعار المعروضة أثناء عمليات التلزيم ،إال\n في حاالت استثنائية تبررھا اإلدارة في تقرير معلل.\n -9باللوازم واألشغال والخدمات التي يمكن أن يعھد بھا إلى المؤسسات العامة أو البلديات.\n -10باللوازم والخدمات التي تؤمنھا اإلدارة بواسطة المنظمات الدولية.\n -11باللوازم واألشغال والخدمات التي يمكن أن يعھد بھا بموافقة مجلس الوزراء إلى حكومات أجنبية أو مؤسسات\n تراقبھا ھذه الحكومات .وللحكومة في مثل ھذه الحالة أن تعفي الجھة التي تتعاقد معھا من الشروط المتعلقة بمحل\n اإلقامة والكفالة والغرامات وتوجب التسليم قبل القبض.\n -12باللوازم واألشغال والخدمات التي يقرر مجلس الوزراء تأمينھا بالتراضي بناء على اقتراح الوزير المختص.\n »المادة -148معدلة وفقا للقانون رقم 16/78تاريخ 2/5/1978والقانون رقم 49/87تاريخ 21/11/1987\n والقانون رقم 14تاريخ 20/8/1990و"}, {"o": 42, "l": "المادة 24", "b": "المادة 24من قانون الموازنة لعام 1994\n تحدد صالحيات المرجع الصالح لعقد الصفقات بالتراضي وفق ما يأتي:\n -المدير أو رئيس المصلحة في حال عدم وجود مدير إذا كانت قيمة الصفقة ال تتجاوز /10.000.000/ليرة لبنانية.\n -المدير العام إذا كانت قيمة الصفقة تزيد عن /10.000.000/ل .ل .وال تتجاوز /35.000.000/ل .ل.\n -الوزير في الحاالت األخرى.\n ويجري التعاقد بإحدى الطرق التالية:\n -1بموجب عقد بين المرجع المختص وصاحب العالقة.\n -2بموجب تعھد يذيل به صاحب العالقة دفتر الشروط الخاص.\n -3بموجب عرض من صاحب العالقة يوافق عليه المرجع المختص.\n -4بموجب تبادل مخابرات بين صاحب العالقة والمرجع المختص ،وفقا ً للعرف التجاري.\n »المادة -149تخضع االتفاقات بالتراضي ألحكام دفتر الشروط الخاص ويوضع لھا دفتر شروط خاص عند االقتضاء.\n\f وعالوة على أحكام المادتين السابقتين تطبق على االتفاقات بالتراضي أحكام المواد 137إلى 141من ھذا القانون.\n خامساً :صفقات الخدمات التقنية\n»المادة -150يمكن التعاقد بالتراضي على صفقات الخدمات التقنية )دروس ووضع دفاتر شروط ومراقبة تنفيذ أشغال\n ومشاريع إلخ (..مھما بلغت قيمتھا إذا كانت تجاوز إمكانيات اإلدارة.\n وتطبق على ھذه الصفقات األحكام التالية:\n -1ال يجوز التعاقد إال مع من تتوفر فيھم المؤھالت التقنية الالزمة ،على أن تبين ھذه المؤھالت بالتفصيل في دراسة\n تضعھا اإلدارة قبل عقد الصفقة.\n -2يمكن عقد االتفاق عند االقتضاء بعد مباراة تجري بين من تتوفر فيھم المؤھالت المذكورة.\n -3تخضع ھذه الصفقات لألحكام األخرى المتعلقة باالتفاقات بالتراضي.\n سادساً -الصفقات بموجب بيان أو فاتورة\n »المادة -151معدلة وفقا للقانون رقم 16/78تاريخ 2/5/1978والقانون 1/84تاريخ 13/6/1984والقانون\nرقم 49/87تاريخ 21/11/1987والقانون رقم 14تاريخ 20/8/1990و القانون رقم 247تاريخ 12/7/1993\n يمكن عقد الصفقات بموجب بيان أو فاتورة:"}, {"o": 43, "l": "المادة 24", "b": "-1إذا كانت قيمتھا ال تجاوز /3.000.000/ثالثة ماليين ليرة .يطبق ھذا اإلجراء على تنفيذ موازنة الجامعة اللبنانية\n دون الحاجة إلى استصدار نص آخر.\n -2إذا كانت أسعار المواد المراد شراؤھا محددة في تعريفة صادرة عن اإلدارة أو ھيئة دولية معترف بھا ويتعذر\n الحصول على سعر أدنى لھا.\n -3إذا كانت الصفقة تتعلق باستئجار آليات أشغال عامة بموجب تعرفة عامة تحدد بقرار من الوزير المختص.\n يعقد الصفقة رئيس الوحدة المختصة ،وتؤمن االستالم اللجنة المنصوص عليھا في المادة .139\n يحدد رؤساء الوحدات المختصة المخولون بعقد الصفقات بقرار من الوزير المختص في اإلدارات العامة وبقرار من\n رئيس السلطة التنفيذية في المؤسسات العامة والبلديات الخاضعة لقانون المحاسبة العمومية.\n القسم الثاني -الأشغال بالأمانة\n »المادة -152األشغال باألمانة ھي األشغال التي تتولى اإلدارة تنفيذھا بنفسھا.\n »المادة -153معدلة وفقا للقانون رقم 49/87تاريخ 21/11/1987و القانون رقم 14تاريخ 20/8/1990و"}, {"o": 44, "l": "المادة 24", "b": "المادة 24من قانون الموازنة لعام 1994\n\f يجيز األشغال باألمانة:\n -رئيس الوحدة المختصة إذا كانت قيمة الصفقة ال تتجاوز /3.000.000/ل .ل.\n -المدير أو رئيس المصلحة في حال عدم وجود مدير إذا كانت قيمة الصفقة تزيد عن /3.000.000/ل .ل .وال\n تتجاوز /10.000.000/ل .ل.\n -المدير العام إذا كانت قيمة الصفقة تزيد عن /10.000.000/ل .ل .وال تتجاوز /35.000.000/ل .ل.\n -الوزير إذا كانت قيمة الصفقة تزيد عن /35.000.000/ل .ل .وال تتجاوز /150.000.000/ل .ل.\n -مجلس الوزراء في الحاالت األخرى.\n »المادة -154يجب أن يعين في كل إدارة تتولى تنفيذ أشغال باألمانة جھاز خاص مھمته مراقبة تنفيذ ھذه األشغال\n باألمانة .يرتبط ھذا الجھاز برئيس اإلدارة مباشرة وال يتولى أي عمل من أعمال التنفيذ.\n »المادة -155على رئيس الوحدة التي تولت تنفيذ األشغال باألمانة أن يقدم إلى إدارته بنھاية األشغال بيانا ً مفصالً\n بالكميات المنفذة واألكالف المدفوعة على اختالف أنواعھا.\n يتولى جھاز المراقبة التدقيق في ھذا البيان ويحيله مذيالً بمطالعته إلى إدارة التفتيش المركزي.\n القسم الثالث -أحكام مشتركة\n»المادة -156يمارس القائمقام ضمن قضائه الصالحيات التي تخولھا أحكام ھذا الفصل إلى المدير .ويمارس المحافظ\nضمن محافظته الصالحيات التي تخولھا أحكام ھذا الفصل إلى المدير العام وذلك فيما يتعلق بصفقات اللوازم واألشغال\n والخدمات التي يجري عقدھا في القضاء أو المحافظة.\n»المادة -157تحدد بمرسوم يتخذ في مجلس الوزراء ،بناء على اقتراح وزير المالية ،دقائق تطبيق أحكام ھذا القانون\n المتعلق بصفقات اللوازم واألشغال والخدمات وال سيما شروط تصنيف الملتزمين وقبولھم لالشتراك في المناقصات.\n الباب الرابع -الخزينة\n الفصل الأول -أحكام أساسية\n»المادة -158تتولى خزينة الدولة جميع عمليات القبض والدفع التي يستوجبھا تنفيذ موازنة الدولة ،وإدارة الحسابات\n المفتوحة خارج الموازنة."}, {"o": 45, "l": "المادة 24", "b": "»المادة -159معدلو وفقا للقانون رقم 55/66تاريخ 3/9/1966\nيؤمن عمليات القبض والدفع لحساب الخزينة موظفون يطلق على كل منھم اسم المحتسب ،غير أنه يجوز للمحتسب أن\n\f يفوض بعض صالحياته إلى أحد المحاسبين التابعين له بموافقة رئيس مصلحة الخزينة.\n »المادة -160المحتسبون فئتان :مركزي ومحلي.\n -1المحتسب المركزي ھو الذي يسأل عن واردات الموازنة ونفقاتھا ،وعن العمليات الخارجة عن نطاق الموازنة.\n -2المحتسب المحلي ھو الذي يسأل عن العمليات الخارجة عن نطاق الموازنة ،ويؤمن محليا ً قبض واردات الموازنة\n ودفع نفقاتھا لحساب المحتسب المركزي المرتبط به.\n -3يجوز في بعض اإلدارات العامة تكليف محتسبھا المركزي توحيد جميع عمليات المحتسبين المحليين التابعين له،\n سواء أكانت ھذه العمليات عائدة للموازنة أو خارجة عن نطاقھا.\n -4إذا كان لدى إحدى اإلدارات العامة محتسب واحد ،اعتبر ھذا المحتسب بمثابة المحتسب المركزي من أجل تطبيق\n ھذا القانون.\n »المادة -161المحتسبون المركزيون ھم:\n -محتسب المالية المركزي.\n -محتسب الجمارك المركزي.\n -محتسب البريد والبرق المركزي.\n -المحتسب المركزي في كل إدارة ذات موازنة ملحقة.\n -كل موظف يعطى ھذه الصفة بمرسوم.\n »المادة -162المحتسبون المحليون ھم:\n -محتسبو المالية.\n -محتسبو الجمارك.\n -محتسبو البريد والبرق.\n -محتسبو اإلدارات ذات الموازنة الملحقة.\n -كل موظف يعطى ھذه الصفة بمرسوم.\n »المادة -163تدون العمليات التي يقوم بھا المحتسب في حسابات يمسكھا وفقا ً لتصميم عام للحسابات يقر بمرسوم\n يصدر بناء على اقتراح وزير المالية.\n»المادة -164تمسك حسابات األموال العمومية من قبل المحتسبين المركزيين ومصلحة المحاسبة العامة على أساس\n الطريقة ذات القيد المزدوج .ومن قبل المحتسبين المحليين على أساس الطريقة ذات القيد البسيط."}, {"o": 46, "l": "المادة 24", "b": "»المادة -165تمسك القيود إجباريا ً بالحبر ،وال يجوز مسكھا على اإلطالق بالرصاص ،كما ال يجوز الحك ،أو الحشو،\n أو المحو ،أو التطريس في األوراق والجداول ،والمستندات ،والقيود ،والسجالت ،بل يجوز تصحيح ما يمكن أن يقع\n فيھا من خطأ شرط أن يجري التصحيح بشكل ظاھر باألرقام واألحرف المفقطة ،وبحبر من لون يختلف عن اللون\n المستعمل في األصل ،وأن يذيل التصحيح بالتاريخ وبإمضاء واضعه.\n الفصل الثاني -المحتسبون\n\f القسم الأول -صلاحيات المحتسبين وموجباتهم\n »المادة -166يتولى المحتسبون:\n -تسليم جداول التكليف وأوامر القبض وأوامر التحصيل التي تودعھم إياھا المراجع المختصة وتأمين تحصيلھا.\n -تأمين المقبوضات أيا ً كان نوعھا.\n -تأمين المدفوعات إما بناء على حواالت أو أوامر دفع صادرة عن المرجع الصالح أو في بعض الحاالت بناء على\n أوامر دفع صادرة عنھم مباشرة.\n -حفظ أوراق الثبوت العائدة لھذه العمليات ومستندات المحاسبة.\n -مسك حسابات المحتسبية التي يديرونھا.\n »المادة -167يتولى محتسب المالية المركزي باإلضافة إلى ما تقدم ،توحيد ما يتعلق بالموازنة العامة من عمليات\n الواردات والنفقات التي يقوم بھا باقي المحتسبين المركزيين ،ويتولى أيضا ً إدارة حساب خزينة الدولة لدى المصرف\n المركزي.\n »المادة -168ال يجوز الجمع بين وظيفة المحتسب وأي وظيفة لھا عالقة بطرح الواردات ،أو أي وظيفة لھا عالقة\n بعقد النفقات أو تصفيتھا أو صرفھا.\n »المادة -169على المحتسب ،قبل أن يباشر وظفيته أن يقدم كفالة قانونية تحدد قيمتھا بقرار من وزير المالية ،وأن\n يحلف اليمين أمام ديوان المحاسبة.\n»المادة -170تقدم الكفاالت إما نقداً ،أو بتعھدات مصرفية صادرة عن مصارف مقبولة ،أو بتأمين عقارات مسجلة في\n الدوائر العقارية.\nتحفظ اإليصاالت والمستندات المتعلقة بالكفاالت المقدمة لدى مصلحة المحاسبة العامة في وزارة المالية مع نسخة عن\n النص القاضي بتعيين المحتسب."}, {"o": 47, "l": "المادة 24", "b": "»المادة -171ال يجوز للمحتسب أن يؤمن بنفسه قبض أو دفع األموال التي يشرف على إدارتھا ،بل يتولى ذلك\n بواسطة أمين صندوق أو جباة تابعين له ،إال في الحاالت التي تحدد بمرسوم خاص.\n »المادة -172على المحتسب أن يراقب أعمال أمناء الصناديق والجباة التابعين له ،وعليه أن يطالبھم بكل مخالفة أو\n تأخير في أعمالھم.\n القسم الثاني -مسؤولية المحتسب\n »المادة -173إن المحتسب مسؤول بأمواله الشخصية عن كل عملية قبض أو دفع تجري في المحتسبية التي يديرھا\n خالفا ً ألحكام القانون ،فضالً عما قد يتعرض له من عقوبات تأديبية أو جزائية.\n\f »المادة -174ال يسأل المحتسب إال عن إرادته الشخصية.\n »المادة -175تشمل مھمة المحتسب جميع العمليات التي يقوم بھا في محتسبيته من أول كانون الثاني لغاية 31\n كانون األول من كل سنة ،أو أثناء المدة التي استلم فيھا وظفيته ،إذا كانت ھذه المدة دون السنة.\n»المادة -176على المحتسبين المركزيين وكذلك على المحتسبين المحليين المنصوص عليھم في الفقرة 2من"}, {"o": 48, "l": "المادة 160", "b": "المادة\n 160أن يقدموا ،باسمھم وعلى مسؤوليتھم ،حسابات مھمتھم إلى ديوان المحاسبة.\nوعلى المحتسبين المحليين المنصوص عليھم في الفقرة 3من"}, {"o": 49, "l": "المادة 160", "b": "المادة 160أن يقدموا ،باسمھم وعلى مسؤوليتھم ،إلى\n المحتسب المركزي التابعين له ،حسابات مھمتھم ضمن شروط ومھل تحدد بمرسوم ال حق يصدر بناء على اقتراح\n وزير المالية.\n »المادة -177عند انتھاء مھمة المحتسب تجري عملية تسليم و تسلم بينه وبين خلفه بموجب محضر يوقعه كالھما،\n وبحضور مفتش مالي فيما يتعلق بالمحتسبين المركزيين ،وموظف تنتدبه اإلدارة المختصة فيما يتعلق بالمحتسبين\n المحليين .وترسل نسخة عن المحضر في الحالتين إلى التفتيش المالي.\n ويجب أن يضمن إلى ھذا المحضر ،بصورة إجبارية ،ميزان للحسابات موقوف بتاريخ إجراء عملية التسليم والتسلم.\n »المادة -178في حال وفاة المحتسب ،أو عدم تمكنه من القيام بدور التسليم والتسلم ،ينظم المحتسب الخلف ،حساب\n مھمة المحتسب السلف تحت إشراف مفتش مالي.\n »المادة -179ترد الكفالة بعد حصول المحتسب على براءة ذمة من ديوان المحاسبة ،وترد حكما ً بعد انقضاء ثالث\n سنوات على ترك المحتسب مھمته ،إذا تأخر الديوان في إصدار قراره إلى ما بعد ھذه المدة.\n»المادة -1 -180إن المحتسبين المحليين والجباة مسؤولون ماليا ً بالتضامن فيما بينھم عن الضرائب المباشرة وسائر\n األموال التي يعھد إليھم بتحصيلھا.\n ً\n -2إن رئيس دائرة تحصيل بيروت مسؤول ماليا عن الضرائب المباشرة وسائر األموال التي يعھد إليه بتحصيلھا ،وھو\n ملزم بتقديم الكفالة المتوجبة على المحتسبين.\n -3يحدد بمرسوم الحق يتخذ بناء على اقتراح وزير المالية مدى مسؤولية الموظفين المذكورين في الفقرتين األولى\n والثانية من ھذه المادة ،واإلجراءات الواجب اتباعھا لتخفيف مسؤوليتھم أو إبراء ذمتھم.\n »المادة -181يعد محتسبا ً مسؤوالً عن أعماله ،كالمحتسب الرسمي ،وخاضعا ً لموجبات ھذا األخير ،كل من تدخل في\n إدارة األموال العمومية من غير أن تكون له صفة المحتسب.\n الفصل الثالث -صلاحيات أمناء الصناديق والجباة ومسؤولياتهم"}, {"o": 50, "l": "المادة 160", "b": "»المادة -182يحصر حق التداول باألموال وحيازتھا في كل محتسبية بأمناء الصناديق والجباة ،إال في الحاالت التي\n\f تحدد في المرسوم المنصوص عليه في"}, {"o": 51, "l": "المادة 171", "b": "المادة 171من ھذا القانون.\n »المادة -183إن أمناء الصناديق مسؤولون عن حفظ األموال في المحتسبية التي يمارسون فيھا وظائفھم.\n »المادة -184إن الجباة مسؤولون عن حفظ األموال التي يجبونھا ،وعليھم أن يسددوھا دوريا ً إلى صناديق\n المحتسبية التي ينتسبون إليھا ،وفقا ً لشروط تحدد بقرار من وزير المالية .كما أنھم مسؤولون مالياً ،بالتضامن مع\n المحتسب التابعين له ،عن تحصيل الضرائب المباشرة وفقا ً ألحكام"}, {"o": 52, "l": "المادة 180", "b": "المادة 180من ھذا القانون.\n ويحظر على الجباة بصورة مطلقة دفع أية نفقة مھما كان نوعھا.\n »المادة -185يخضع أمناء الصناديق والجباة لنظام الكفالة أسوة بالمحتسبين.\n »المادة -186على أمين الصندوق أن يتحقق على مسؤوليته قبل الدفع من ھوية صاحب المال وصحة توقيعه.\n »المادة -187إذا كان المبلغ مستحقا ً لشخص متوف ،فعلى أمين الصندوق أن يطلب من أصحاب الحق المستندات\n الرسمية التي تثبت صفتھم .ويكتفي بشھادة من مختار المحلة إذا كان المبلغ دون 500ليرة.\n »المادة -188إذا كان صاحب المال أمياً ،أو عاجزاً عن التوقيع ،قامت بصمة اإلبھام مقام التوقيع ،على أن يصدق\n البصمة أمين الصندوق وشاھدان إذا كانت قيمة الحوالة ال تجاوز ألف ليرة.\n وألمين الصندوق في الحاالت األخرى أن يطلب تصديق البصمة من قبل كتابة العدل.\n »المادة -189يعطى لقاء كل مبلغ يقبضه أمناء الصناديق والجباة إيصال تحدد شكله وطريقة تنظيمه لكل إدارة أو\n وحدة مصلحة المحاسبة العامة في وزارة المالية.\n»المادة -190إن أي تحريف في إيصال صادر عن أمين صندوق أو جاب ،أو في إحدى نسخه ،مھما كان سببه ،يعتبر\n صادراً عن سوء نية ،وتفرض على مرتكبه العقوبات المنصوص عليھا في المادتين 461و 462من قانون\n العقوبات ،إال إذا كان ھذا التحريف لم يلحق أي ضرر باألموال العمومية.\n »المادة -191يجب إعطاء إيصال نظامي بكل مبلغ يقبض من األموال العمومية .وكل من يقوم بقبض أموال عمومية\n وال يعطي بھا إيصاالً نظاميا ً يعد مختلسا ً.\n»المادة -192يحدد رئيس مصلحة المحاسبة العامة في وزارة المالية ،بناء على اقتراح المحتسب المركزي المختص،\n الحد األعلى لألرصدة التي يجوز ألمناء الصناديق االحتفاظ بھا ،على أن يدفعوا ما يزيد على ھذه األرصدة إلى\n المصارف أو مراكز البريد التي تعين لھم.\n»المادة -193على اإلدارات التي تحصل بعض الواردات نقداً أن تكلف أحد موظفيھا بموافقة مصلحة المحاسبة العامة"}, {"o": 53, "l": "المادة 180", "b": "قبض ھذه األموال ومسك حساباتھا .ولھذه المصلحة أيضا ً أن توافق على طريقة قبض األموال المذكورة وتسديدھا،\n وعلى نماذج السجالت الواجب مسكھا.\n\f يسدد الموظف المذكور األموال التي قبضھا مرة في كل شھر ،على األقل ،إما إلى محتسب المالية المركزي ،وإما إلى\n محتسب المالية المحلي ،وذلك بناء على جدول يبين فيه القيمة المقبوضة ونوع اإليراد المحصل.\n ويمكن أن يساعد ھذا الموظف في عمليات القبض ،عند االقتضاء ،معاون أمين صندوق واحد أو أكثر.\n ويخضع ھذا الموظف ومن يعاونه في قبض األموال لموجبات أمناء الصناديق وبنوع خاص ألحكام المواد 185و\n 189و .192\n الفصل الرابع -حسابات الأموال\n القسم الأول -أحكام عامة\n »المادة -194تدقق مصلحة المحاسبة العامة عمليات المحتسبين والمحاسبين اإلداريين وتقوم بتوحيدھا.\n »المادة -195معدلة وفقا للقانون رقم 55/66تاريخ 3/9/1966\n تضع مصلحة المحاسبة العامة كل سنة:\n -قطع حساب الموازنة الذي يجب تقديمه إلى ديوان المحاسبة قبل 15آب من السنة التي تلي سنة الموازنة.\n -حساب المھمة العام الذي يجب تقديمه إلى ديوان المحاسبة قبل أول أيلول من السنة التي تلي سنة الحساب.\n -يبدأ تنظيم حساب المھمة العام ابتداء من حساب السنة التي يبدأ فيھا تطبيق التصميم العام للحسابات الملحوظ في"}, {"o": 54, "l": "المادة 163", "b": "المادة 163من ھذا القانون.\n »المادة -196إذا أسفر قطع حساب الموازنة عن زيادة في الواردات ،حولت ھذه الزيادة بموجب قانون القطع إلى\nحساب »مال االحتياط« وإذا أسفر عن زيادة في النفقات أجاز القانون المذكور تغطية العجز من مال االحتياط .وإذا كان\n مال االحتياط ال يكفي ،قيد العجز في حساب السلفات ،على أن يسدد إجباريا ً من أول موازنة تالية يظھر فيھا وفر ،وإن\n لم يكف ھذا الوفر فمن وفر السنوات الالحقة على التوالي.\n »المادة -197على الحكومة أن تحيل مشروع قانون قطع حساب الموازنة إلى مجلس النواب قبل أول تشرين الثاني\n من السنة التي تلي سنة الموازنة.\n القسم الثاني -أحكام خاصة ببعض الحسابات\n أولاً :مال الاحتياط\n\f»المادة -198يتكون مال االحتياط من زيادة واردات الموازنة على نفقاتھا .ويتولى مسك ھذا الحساب محتسب المالية\n المركزي تحت مراقبة مصلحة المحاسبة العامة.\n »المادة -199يستعمل مال االحتياط:\n -لتغطية نفقات السنين السابقة خالل الفترة االنتقالية المنصوص عليھا في"}, {"o": 55, "l": "المادة 25", "b": "المادة 25من ھذا القانون.\n -لتغطية االعتمادات المدورة.\n -لتغطية عجز الموازنة وفقا ً ألحكام"}, {"o": 56, "l": "المادة 196", "b": "المادة 196من ھذا القانون.\n -لتغطية االعتمادات اإلضافية )تكميلية واستثنائية(.\n -لتمويل المشاريع اإلنشائية.\n »المادة -200ال يجوز أخذ أي مبلغ من مال االحتياط إال بقانون .ويجب أن يدون فوراً كل مبلغ يقرر أخذه من مال\n االحتياط في قيود محتسب المالية المركزي.\n تحدد كيفية تدوين ھذه القيود بقرار يصدر عن وزير المالية.\n ثانياً :الودائع والكفالات\n »المادة -201تسلم الودائع والكفاالت إلى الخزينة ،بناء على تكليف صادر عن مرجع صالح ،وتدون في اإليصاالت\n المتعلقة بھا أسباب اإليداع ،وال ترد إلى أصحابھا إال بناء على تكليف من المرجع الصالح ،وبعد استرداد اإليصاالت.\n »المادة -202إذا فقدت إيصاالت الودائع أو الكفاالت استعيض عنھا بتعھد من أصحابھا بأن يتحملوا كل عطل وضرر\n قد ينتج عن سوء استعمال اإليصال المفقود طيلة خمس سنوات.\n ثالثاً :سلفات الخزينة\n »المادة -203سلفات الخزينة إمدادات تعطى من موجوداتھا:\n -1لتموين مستودعات اإلدارات العامة بلوازم مشتركة بين أكثر من إدارة واحدة.\n -2لشراء مواد قابلة الخزن ومعدة لالستعمال في سنة مالية جارية أو الحقة.\n -3لتغذية صناديق المؤسسات العامة و البلديات و كذلك الصناديق المستقلة المنشأة بقانون.\n »المادة -204يعلق منح سلفات الخزينة المعدة لتغذية أحد الصناديق المذكورة في الفقرة 3من المادة السابقة:\n -1على تثبت وزير المالية من إمكان الجھة المستلفة إعادة السلفة نقداً في المھلة المحددة لتسديدھا.\n -2على تعھد الجھة المستلفة بأن ترصد في موازنتھا إجباريا ً االعتمادات الالزمة لتسديد السلفة في المھلة المحددة.\n -3على موافقة السلطة التشريعية إذا كانت مھلة تسديدھا تجاوز االثني عشر شھراً.\n »المادة -205معدلة وفقا للقانون رقم 5/89تاريخ 5/1/1989والقانون رقم 41تاريخ 14/2/1991\n\f تعطى سلفات الخزينة للغاية المحددة في"}, {"o": 57, "l": "المادة 203", "b": "المادة 203من ھذا القانون بمرسوم بناء على اقتراح وزير المالية وطلب\n اإلدارات المختصة.\n وفي حاالت استثنائية طارئة يمكن إعطاء سلفات خزينة بمرسوم يتخذ في مجلس الوزراء.\n يتوجب على الحكومة أن تطلع المجلس النيابي على السلفات المقررة بظرف شھر.\n »المادة -206معدلة وفقا للقانون رقم 41تاريخ 14/2/1991\n يذكر في مرسوم يتخذ في مجلس الوزراء :القيم على السلفة في الحاالت المنصوص عليھا في الفقرتين 1و 2من"}, {"o": 58, "l": "المادة 203", "b": "المادة 203السابقتين ،والجھة المستلفة في الحالة المنصوص عليھا في الفقرة 3من المادة نفسھا .والغاية من\n السلفة ،ومقدارھا ،وطريقة دفعھا ،وشروط تسديدھا ،وغيرھا من الشروط التي يرى وزير المالية ضرورة فرضھا.\n »المادة -207معدلة وفقا للقانون رقم 41تاريخ 14/2/1991\n تدفع سلفات الخزينة بناء على أوامر صادرة عن المحتسب المركزي ويشار فيھا إلى المرسوم المتخذ في مجلس\n الوزراء الذي أجازھا.\n »المادة -208ال تستعمل السلفة في غير الغاية التي أعطيت من أجلھا.\n »المادة -209تسدد سلفات الخزينة المنصوص عليھا في الفقرتين 1و 2من"}, {"o": 59, "l": "المادة 203", "b": "المادة 203من ھذا القانون بموجب\n حواالت دفع صادرة على الموازنة.\n وتسدد سلفات الخزينة المنصوص عليھا في الفقرة 3من المادة نفسھا بإعادة قيمتھا نقداً إلى الخزينة ضمن المھل\n المحددة لذلك.\n »المادة -210على المحتسب أن يالحق تسديد سلفات الخزينة وفقا ً للشروط التي أعطيت بموجبھا وضمن المھل\n المحددة.\n »المادة -211معدلة وفقا للقانون رقم 41تاريخ 14/2/1991\nللمحتسب أن يحسم مباشرة من راتب القيم على السلفة وتعويضاته المبالغ التي ال يثبت استعمالھا ،أو التي ال يسددھا\n في المواعيد المحددة ،كما له أن ينفذ تلقائيا ً بحقه أي تدبير قانوني آخر يؤمن استرداد ھذه المبالغ.\n ويمكن بمرسوم يتخذ في مجلس الوزراء بناء على اقتراح وزير المالية أن يمدد مھلة التسديد في الحاالت والظروف\n االستثنائية.\n»المادة -212إذا تأخرت إحدى اإلدارات المستلفة عن تسديد سلفة الخزينة المعطاة له حق لمحتسب المالية المركزي\n أن يقتطعھا رأسا ً مما يكون لھذه اإلدارة من أموال لدى الخزينة.\n »المادة -213يضم إلى مشروع قانون قطع الحساب بيان بسلفات الخزينة المعطاة وفقا ً ألحكام"}, {"o": 60, "l": "المادة 203", "b": "المادة 203من ھذا\n القانون وبما سدد منھا خالل سنة الموازنة.\n الفصل الخامس -محاسبة المواد\n\f»المادة -214تشمل محاسبة المواد جميع القيود والمستندات الضرورية لتبيان موجودات المواد التي تملكھا اإلدارات\n العامة ولتسجيل حركتھا.\n »المادة -215على جميع اإلدارات العامة أن تمسك محاسبة للمواد .وعلى المؤسسات الخاضعة إلشراف الدولة أن\n تمسك محاسبة للمواد تمكن من ممارسة ھذا اإلشراف.\n »المادة -216كل شخص كلف بحفظ أو استعمال المواد المنصوص عليھا في"}, {"o": 61, "l": "المادة 214", "b": "المادة 214من ھذا القانون مسؤول\n عنھا ماليا ً.\n ويمكن أن تترتب المسؤولية نفسھا على األشخاص المكلفين بمسك حسابات المواد وبمراقبتھا.\n»المادة -217يقتصر تطبيق أحكام ھذا الفصل على المواد الموجودة داخل األراضي اللبنانية وفي البعثات اللبنانية في\n الخارج .وال تطبق على عتاد الجيوش القائمة بخدمة فعلية وال على العتاد المستعمل في المراكب البحرية والجوية.\n »المادة -218تنظم دقائق تطبيق أحكام ھذا الفصل بمرسوم يتخذ في مجلس الوزراء بناء على اقتراح وزير المالية.\n الباب الخامس -أحكام خاصة\n الفصل الأول -أحكام خاصة بالجيش وقوى الأمن الداخلي والأمن العام والمفارز الجمركية\n »المادة -219تدون اعتمادات الرواتب والتعويضات المتعلقة بأفراد الجيش ورجال قوى األمن الداخلي واألمن العام\n في بند واحد بدون توزيع.\n »المادة -220تتولى التلزيم لجنة خاصة تؤلف وفقا ً لنظام يحدد بمرسوم بناء على اقتراح الوزير المختص.\n »المادة -221يمكن عقد اتفاقات بالتراضي بما يحتاجه الجيش وقوى األمن الداخلي واألمن العام والمفارز الجمركية\n من لوازم وأشغال وخدمات في حالتي الحرب والطوارىء والحاالت االستثنائية التي تقضي باتخاذ تدابير فورية وذلك\n بناء على قرار مسبق من قائد الجيش.\n»المادة -222يمكن وزارة الدفاع الوطني عندما تعقد صفقات مع حكومات أجنبية أو مؤسسات تراقبھا أو توصي بھا\n ھذه الحكومات لشراء األسلحة والذخائر واألعتدة واألجھزة ،أن تعفي الجھة التي تتعاقد معھا من الشروط المتعلقة\n بمحل اإلقامة والكفالة ،والغرامات ،وبتوجب التسليم قبل القبض.\n\f »المادة -223يمكن وزارة الدفاع الوطني أن تطلب ،وفقا ً لألصول المحددة في"}, {"o": 62, "l": "المادة 117", "b": "المادة 117من ھذا القانون ،إعادة\n استعمال االعتمادات المقابلة:\n -1لقيمة المواد التي تقدمھا إدارة الجيش بقاء ثمن إلى الضباط واألفراد بصفتھم الشخصية.\n -2لقيمة المواد التي تلزم بھا إدارة الجيش الضباط واألفراد المسؤولين عن فقدانھا أو عطلھا.\n -3لقيمة األسلحة والذخائر واألعتدة واألجھزة التي تبيعھا قيادة الجيش من إحدى اإلدارات أو المؤسسات العامة.\n -4لقيمة المواد المستعملة وبدل الخدمات المؤداة لحساب اإلدارات والمؤسسات العامة أو لصالح أحد األشخاص\n الحقيقيين أو المعنويين.\n »المادة -224يجوز لوزارة الدفاع الوطني أن تقتطع من استحقاقات الرواتب التي تصرف من\n اعتمادات السنة الجارية المبالغ المدفوعة خطأ أو بدون حق في سنين سابقة.\n»المادة -225إن قيمة الرواتب وملحقاتھا ،وسلفات النقل واالنتقال التي تقبضھا القطع في سنة ما زيادة عن حقوقھا\nوتعيدھا إلى الخزينة قبل أول أيار من السنة التالية ،تدخل بتاريخ إعادتھا في واردات السنة الجارية وفقا ً ألحكام"}, {"o": 63, "l": "المادة 8", "b": "المادة\n 8من ھذا القانون.\n ويمكن أن يفتح بقرار من وزير المالية في بند الرواتب من موازنة الجيش اعتمادات إضافية توازي قيمة المبالغ\n المعادة ،على أن تغطى بزيادة مماثلة في الواردات.\n »المادة -226معدلة وفقا للقانون رقم 55/66تاريخ 3/9/1966\nاعتباراً من أول آب من كل سنة ،يجوز لوزير الدفاع الوطني أن يعقد على حساب السنة التالية ،نفقات تجھيز مقدارھا\n ثلثا االعتمادات المرصدة لھذه الغاية عن السنة الجارية في موازنات الجيش وقوى األمن الداخلي واألمن العام\n والمخصصة للمفارز الجمركية في موازنة وزارة المالية.\n وال يجوز أن تعقد بھذه الواسطة نفقات لم يسبق للسلطة التشريعية إن وافقت على مبدئھا.\n يمكن تطبيق أحكام المادتين 137و 138من ھذا القانون على الصفقات المذكورة في ھذه المادة حتى قبل دخول\n السنة الجديدة.\n »المادة -227ملغاة وفقا للقانون رقم 5/72تاريخ 1/2/1972\n »المادة -228يعين محتسبو المواد في الجيش بقرار من قائده.\n »المادة -229ال يخضع محتسبو الجيش لنظام الكفالة الذي يخضع له سائر المحتسبين.\n »المادة -230ال يجوز لديوان المحاسبة ،وال للمفتشين الماليين ،أن يطلبوا اإلطالع أو أن يطلعوا على وثائق\n ومعلومات تتعلق بالسر العسكري ،إال إذا وافق قائد الجيش على ذلك .وتجرى رقابة ديوان المحاسبة على حسابات\n المواد المختصة بالجيش محليا ً واستناداً إلى القيود التي تمسكھا القيادة واألوراق الثبوتية التي تبرزھا.\n »المادة -231معدلة وفقا للمرسوم رقم 1713تاريخ 26/1/1979والمرسوم االشتراعي رقم 39/83تاريخ\n 16/6/1983والمرسوم االشتراعي رقم 29/85تاريخ 23/3/1985\n -تطبق على قوى األمن الداخلي أحكام المواد من 220إلى 230ضمنا ً من ھذا القانون بحيث يمارس كل من وزير\n الداخلية والمدير العام لقوى األمن الداخلي الصالحيات الممنوحة لوزير الدفاع الوطني ولقائد الجيش كل فيما خصه."}, {"o": 64, "l": "المادة 8", "b": "أما بالنسبة لألمن العام والمفارز الجمركية فتطبق مع مراعاة التنظيم الخاص بكل من ھذين الجھازين ،أحكام المواد\n 220و 222و 228و 229و 230من ھذا القانون.\n الفصل الثاني -أحكام خاصة بالإنفاق في الخارج\n »المادة -232توضع تحت تصرف البعثات الخارجية سلفات موازنة دائمة تستعملھا كل بعثة لدفع نفقاتھا عن ستة\n أشھر على األكثر.\n»المادة -233تجري التلزيم في البعثات الخارجية لجنة خاصة تعين بقرار من رئيس البعثة ،كلما كان ذلك ممكناً ،وإال\n فيجري وفقا ً ألصول تحدد بقرار من وزير الخارجية والمغتربين.\n »المادة -234يمكن أن تثبت نفقات الوفود إلى الخارج ببيانات مفصلة يصدقھا رئيس الوفد على مسؤوليته.\n»المادة -235يمكن أن تثبت نفقات التمثيل في الخارج ببيانات مفصلة ينظمھا رئيس البعثة الخارجية ويصدقھا األمين\n العام لوزارة الخارجية والمغتربين.\n وتثبت بالطريقة نفسھا النفقات اإلدارية التي تؤديھا البعثات الخارجية إذا كانت النفقة ال تتجاوز 500ليرة كل مرة.\n »المادة -236تحدد أصول مسك السجالت ،وتنظيم القيود وقبض األموال ودفعھا وسوى ذلك من األمور التي تتعلق\n بمحاسبة البعثات الخارجية ،بتعليمات مشتركة تصدر عن وزيري المالية والخارجية والمغتربين.\n الفصل الثالث -أحكام خاصة بدفع الرواتب ومعاشات التقاعد\n »المادة -237تؤدى في أول كل شھر المخصصات والرواتب والتعويضات الشھرية الخاصة بالوظيفة أو الملحقة\n بالراتب.\n يطبق ھذا التدبير على جميع الموظفين الدائمين والمؤقتين باستثناء المتمرنين منھم ،كما تطبق على المتقاعدين\n وورثتھم.\n »المادة -238يبقى المبلغ المدفوع تنفيذاً ألحكام الفقرة السابقة حقا ً مكتسبا ً لمن قبضه وال يسترد شيء منه لصالح\n الخزينة في جميع الحاالت.\n الفصل الرابع -أحكام خاصة بوزارة البريد والبرق والهاتف\n\f»المادة -239تخضع محاسبة البريد والبرق والھاتف لألنظمة الخاصة بھا وألحكام ھذا القانون في كل ما ال يتعارض"}, {"o": 65, "l": "المادة 8", "b": "مع األنظمة المشار إليھا.\n الفصل الخامس -أحكام خاصة بالبلديات\n »المادة -240تحدد شروط تطبيق ھذا القانون على البلديات بمراسيم تصدر بناء على اقتراح وزيري الداخلية\n والمالية.\n الفصل السادس -المؤسسات العامة\n»المادة -241تحدد شروط تطبيق ھذا القانون على المصالح المستقلة وسواھا من المؤسسات العامة بمراسيم تصدر\n بناء على اقتراح وزير المالية ووزير الوصاية.\n الباب السادس -أحكام مختلفة\n »المادة -242معدلة وفقا للقانون رقم 55/66تاريخ 3/9/1966\nيجب إيداع جميع األموال العمومية المحددة في"}, {"o": 66, "l": "المادة 2", "b": "المادة 2من ھذا القانون في الحساب المفتوح لدى مصرف لبنان باسم\n الخزينة العامة.\n يحدد تاريخ تطبيق ھذه المادة بالنسبة للبلديات والمؤسسات العامة التابعة لھا بمرسوم يتخذ بناء على اقتراح وزيري\n الداخلية والمالية.\n »المادة -243معدلة وفقا للقانون رقم 55/66تاريخ 3/9/1966\n يحظر على اإلدارات العامة والبلديات والمؤسسات العامة واألشخاص المعنويين المذكورين في المادة الثانية من ھذا\n القانون فتح حسابات في المصارف الخاصة أو فتح حساب خاص بھا في مصرف لبنان.\n »المادة -244معدلة وفقا للقانون رقم 55/66تاريخ 3/9/1966\nيفتح في قيود مصلحة الخزينة في وزارة المالية حساب خاص باسم كل جھة من الجھات المذكورة في المادة السابقة.\n »المادة -245معدلة وفقا للقانون رقم 55/66تاريخ 3/9/1966\n تحدد بقرار من وزير المالية أو بقرار مشترك من وزير المالية ووزير الداخلية بالنسبة إلى البلديات والمؤسسات\n العامة البلدية ،األحكام المتعلقة بالمبالغ القصوى التي يحق لكل منھا االحتفاظ بھا في صناديقھا الخاصة وأصول\n\f تحريك الحسابات المنصوص عليھا في"}, {"o": 67, "l": "المادة 244", "b": "المادة 244أعاله.\n -تثابر اإلدارات العامة والبلديات والمؤسسات العامة المذكورة في ھذا الباب على قبض اإليرادات العائدة لھا .أما\n عمليات الدفع فتجري بواسطة صناديقھا إذا كانت قيمتھا ال تجاوز حد أقصى يعين بقرار من وزير المالية ،أو بقرار\nمشترك من وزيري المالية والداخلية بالنسبة للبلديات والمؤسسات العامة البلدية ،وتدفع بواسطة صندوق الخزينة إذا\n كانت تتجاوز ھذا الحد.\n -وتثابر اإلدارات والمؤسسات العامة التي ال توجد لديھا صناديق خاصة على القيام بجميع عمليات القبض والدفع\n بواسطة صندوق الخزينة.\n »المادة -246معدلة وفقا للقانون رقم 55/66تاريخ 3/9/1966\nال يجوز لمصلحة الخزينة أن توقف أية عملية دفع تأمر بھا إحدى الجھات التي لھا حساب خاص في قيودھا ،طالما أن\n لھا رصيداً دائنا ً كافيا ً في ھذا الحساب.\n »المادة -247معدلة وفقا للقانون رقم 55/66تاريخ 3/9/1966\n تحدد دقائق تطبيق المواد 242إلى 246من ھذا القانون وبنوع خاص ما يتعلق منھا بمسك الحسابات وتنظيم القيود\n وشكل السجالت والمطبوعات وطريقة دفع الخزينة لنفقات اإلدارات والمؤسسات التي لھا حساب في قيودھا وكذلك\nالمھل التي يجب إنجاز المعامالت المالية خاللھا ،بقرار من وزير المالية أو بقرار مشترك من وزيري المالية والداخلية\n بالنسبة للبلديات والمؤسسات العامة البلدية.\n »المادة -248معدلة وفقا للقانون رقم 55/66تاريخ 3/9/1966\n يلغى المرسوم االشتراعي رقم 117تاريخ 12حزيران 1959وتعديالته والمرسومين رقم 13665و 13684\n تاريخ 23آب ،1963والقانون الصادر في 4كانون الثاني 1945وكل نص آخر يتنافى وأحكام ھذا القانون أو ال\n يتفق مع مضمونه.\n »المادة -249ينشر ھذا القانون في الجريدة الرسمية ويعمل به اعتباراً من 31كانون األول سنة .«1963"}, {"o": 68, "l": "المادة 2", "b": "المادة 2\n المادة -2ينشر ويبلغ ھذا المرسوم حيث تدعو الحاجة.\n الذوق في 30كانون األول سنة 1963\n اإلمضاء :فؤاد شھاب\n صدر عن رئيس الجمھورية\n رئيس مجلس الوزراء\n اإلمضاء :رشيد كرامي\n رئيس مجلس الوزراء\n اإلمضاء :رشيد كرامي"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (13,'تقارير إدارة المناقصات','تقرير إدارة المناقصات لعام 2013','2013-12-23','https://www.ppa.gov.lb/ar/pages/details/13','{"https://admin.ppa.gov.lb/storage/listing-pages/files/30YZZxtGaJxSPJX3EkARKwDz4j6CVc23KPCO-1761478458.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/30YZZxtGaJxSPJX3EkARKwDz4j6CVc23KPCO-1761478458.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (14,'مذكرات الرئيس','مذكرة رقم 2022/1 : إيداع هيئة الشراء العام المعلومات العائدة للصفقات التي تجريها اعتبارًا من تاريخ ٢٩/٧/٢٠٢٢','2022-08-10','https://www.ppa.gov.lb/ar/pages/details/14','{"https://admin.ppa.gov.lb/storage/listing-pages/files/VBI2fDKIbBwSq0TXc2AS9LAqEstaZiAIpyCz-1779692918.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/VBI2fDKIbBwSq0TXc2AS9LAqEstaZiAIpyCz-1779692918.pdf"}','ocr') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=14),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "جك حب الشاء العام\nمذكرة رقم /١ ه.ش.ع / 7١71\nموجهة الى كافة الجهات الشارية لإيداع هيئة الشراء العام المعلومات العائدة للصفقات التي\nتجريها اعتبارًا من تاريخ ٠١77/17/79 ايا كان تاريخ الاعلان عنها\nنصت المادة الأولى من قانون الشراء العام على ما يلي:\nيحّدد هذا القانون قواعد إجراء الشراء العام وتنفيذه ومراقبته» وهو يرتكز على المبادىء التالية:\n.١ تطبيق الإجراءات التنافسية كقاعدة عامة.\n\". إتاحة فرص متكافئة دون تمييز للمشاركة في الشراء العام.\n*. توفير معاملة عادلة ومتساوية وشفافة ومسؤولة لجميع العارضين والملتزمين.\n4. علنية الإجراءات ونزاهتها ومهنيتها بشكل يفعل الرقابة والمحاسبة\n5. تشجيع التنمية الاقتصادية المحلية والعمالة الوطتية والإنتاج الوطني على أساس القيمة الفضلى من إنفاق\nالمال العام دون الإخلال بالفعالية.\nتخضع عمليات الشراء إلى قواعد الحوكمة الرشيدة وتأخذ بالاعتبار مقتضيات التنمية المستدامة.\nتُعتبر المبادىء العامة الواردة في هذه المادة من الانتظام القانوني العام»\nوبما أنه يُستفاد من نص هذه المادة ان المبادئ المتعلقة بالعلنية والشفافية والمنافسة هي من الانتظام العام ولا\nيجوز تفسير اي نص بما يخالفها.\nوبما أن المادة ١١ من قانون الشراء العام نصت على ما يلي: 'تُطبّق على عمليات الشراء الجارية والتي تم\nالاعلان عنها قبل دخول هذا القانون حيّز التتفيذ القوانين النافذة بتاريخ الاعلان عن الشراء\"»\nوبما أنه يتبين من المادتين اعلاه ان الصفقات التي أعلن عنها قبل 74 تموز 7٠١57 تخضع اجرائيًا لنظام\nالمناقصات وقانون المحاسبة العمومية» ولا تخضع لأحكام قانون الشراء العام الإجرائية» الا أنها تبقى خاضعة\nلموجب العلنية والشفافية والمنافسة»\nتمهذلك:\nيُطلب الى الجهات الشارية ايداع هيئة الشراء العام المعلومات العائدة للصفقات التي تجريها اعتبازا من تاريخ\n89 ايا كان تاريخ الاعلان عنها.\nهاري ععات ل سنا"}, {"o": 1, "l": null, "b": "7 رئيس هيئة الشراء العام\n| 2\nا ا\nيمكن للج نيه ايداع هيئة الشراء العام المعلومات المطلوبة على العنوان التالي: ا6©1/.1. 0114864603"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (15,'مذكرات الرئيس','مذكرة رقم 2024/1 : إعداد خطة الشراء السنوية المُوحّدة عن العام 2024','2024-01-17','https://www.ppa.gov.lb/ar/pages/details/15','{"https://admin.ppa.gov.lb/storage/listing-pages/files/lsK3yfKk1Ce5rqCbX1fDRJk2aW3ocmA8ixDb-1760214346.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/lsK3yfKk1Ce5rqCbX1fDRJk2aW3ocmA8ixDb-1760214346.pdf"}','ocr') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=15),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "0 الجمصورية اللبنائيتة\nتك هيئة الشراء العام\nمذكرة رقم ١ /ه.ش.ع/ ؛؟.؟\nموجهة الى كافة الجهات الخاضعة لأحكام قانون الشراء العام من أجل\n: إعداد خطة الشراء السنوبة المُوحّدة عن العام 4؟5١؟\nإن رئيس هيئة الشراء العام»\nبناءٌ على قانون الشراء العام رقم 7١71/5155 تاريخ ٠١5١/17/15 سيما المادة ١١ المعدلة بموجب القانون رقم\n18 تاريخ 5 1 5 والمادة كلا منهء»\nبناعً على الفقرة الثالثة من المادة ١١ من قانون الشراء العام التي نصّت على ما يلي: \" ترسل الجهة الشارية خطتها\nالمكتملة إلى هيئة الشراء العام في مهلة شهرين من بدء السنة المالية. تَعمّد هيئة الشراء العام إلى توحيد الخطط في\nخطة شراء سنوية موحّدة ونشرها خلال مهلة //١/[ يوم عمل \"\nبناءً على الفقرةٍ الثالثة من المادة 5 من قانون الشراء العام التي نصّت على ما يلي: \" جمع خطط الشراء السنوية\nالواردة من الجهات الشارية وفق نموذج مُوحّد يَصدر عن هيئة الشراء العام وتيويبها ونشرها وفق الأصول على ٠...\nالمنصة الإلكترونيّة المركزيّة المعتمدة بحسب المادة ١١ من هذا القانون؛ على أن تتضمّن معلومات مفصّلة عن. م\nالأنواع وإلكميات وطرق التعاقد والقطاعات المعنيّة بشكل يسمح للسوق بالتحضنُر للمنافسة \", . 1 0\nيُطلب إلى كافة الجهات الخاضعة لأحكام قانون الشراء العام ولأجل إعداد خطة الشراء السنوبة الموخدة؛ مايلي: ٠ ؛\nأولاً: إعداد خطة الشراء السنوية عن العام 7١74 مكتملة وإيداعها حيئة الشراء العام ضمن المهلة القانويئة. 0200\nثانيًا: ثرسل الجهات المعنية الخطة المشار إليها على البريد .. الإلكترؤتي :لهيئة الشراء العام 0 ١\n(أ./2001261©003.901) وفقًا للنموذج المتاح على الموقع الإلكتروني للهيئة بصبيغة (2<“081) على الشكل\nالتالي: : 1\nه موضوع الرسالة (5105[861): [اسم الجهة الشارية أو المتعاقدة]-[خطة_الشراء]-[العام][الأساسية]."}, {"o": 1, "l": null, "b": "ه يتم إعادة تسمية الملف وفقًا لما يلي: [اسم الجهة الشارية أو امتعاقدة]-إخطة_الشراء )جلك ؤيياسية]. .\n» على سبيل المثال: [وزارة المالية]-[خطة_الشراء]-[4 ؟١؟]-[الأساسية] . 0 0\nب 5-03 7 5\n1 00-5 31\nد 0\nآ آل ره سن - ١\nْ 0000\n1 طاءنامن.ةدرم لي\nا[.60.وممهاع ممم ةنا\nثَالثًا: نصّت الفقرة الرابعة من المادة ١ على أنه عند إدخال أيّ تعديل على الخطة؛ لا سيّما الحصول على قروض\nأو هبات» يجب على الجهة الشارية تشر هذا التعديل على موقعها الالكتروني إن وُجدء وعلى المنصة الإلكترونيّة\nالمركزيّة لدى هيئة الشراء العام؛ مع احترام مهل الإعلان المنصوص عنها في المادة ؟١.\nلذلك؛ يجب الإلتزام بما جاء في الفقرة (ثاتيًا) أعلاه من هذه المذكرة» عند التعديل وفقًا لما يلي:\n« موضوع الرسالة (]5[©6©1لا5): [اسم الجهة الشارية أو المتعاقدة]-[خطة_الشراء]-[العام]--[معدلة].\n» يتم إعادة تسمية الملف وفقًا لما يلي: [اسم الجهة الشاربة أو المتعاقدة]-[خطة_الشراء ]-[العام]-[معدلة].\nرليعًا: عند إعداد الخطة يجب على الجهات الشارية:\n« الإلتزام يأحكام قانون الشراء العام رقم 4 5 771/5.\n» ملء البيانات الواردة في هذا النموذج وفقًا لأحكام قانون الشراء العام وإرساله إلى هيئة الشراء العام بنسخته\nالإلكترونية على البريد الإلكتروني (60012616©0003.901/.1).\nخامسًا: بإنتظار أتمتة عملية إعداد خطة الشراء السنوية يجب تحميل النموذج بنسخته المحدّثة في كل مرة تريد\nالجهة الشارية وضع خططها السنوية أو تعديلهاء نظرًا للتحديثات التي قد تطرأ على هذا النموذج وعلى الطريقة\nوالآلية الإلكترونية التي سيتم بواسطتها تزويد هيئة الشراء العام بنسخة عن هذه الخطة.\nسادسًا: لحسن سير العمل» يجب متابعة الموقع الإلكتروني لهيئة الشراء العام لمعرفة كل جديد يتعلق بإعداد خطة\nالشراء السنوية وغيرها من الأمور المُتعلقة بتطبيق أحكام قانون الشراء العام."}, {"o": 2, "l": null, "b": "سابعًا: إن النشر على الموقع الإلكتروني لهيئة الشراء العام يعتبر بمثابة تبليغ عملا بأحكام الفقرة 0\" من المادة\nالثانية من قاتون الشراء العام.\nثامئًا: إيداع نسخة عن الخطة وتعديلاتها في سجل اجراءات الشراء لدى الجهة الشارية.\nبيروت فى لل ين\nمم مد\n0000-00\n1 0\n2\n11 فع) )\n١ 8 1\nل ومجسسشففة -ررة\nو و م ايا\nا\nصفحة 2/2"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (16,'مذكرات الرئيس','مذكرة رقم 2024/2 : تنظيم مهام ومسؤوليات الوحدات الإدارية العاملة في الشراء العام','2024-01-31','https://www.ppa.gov.lb/ar/pages/details/16','{"https://admin.ppa.gov.lb/storage/listing-pages/files/VYyUfI2XwHwif8uYizlzXZGdSygoBeGoopqx-1760214423.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/VYyUfI2XwHwif8uYizlzXZGdSygoBeGoopqx-1760214423.pdf"}','ocr') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=16),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "5 ظُ الجمهوريّة اللبنانيتة\nسطاضيت شفافية ٠ منافسة ٠ نزاهة\nمذكرة رقم ؟\"/هرش.ع./؛ ٠١7\nموجهة إلى الجهات الشارية\nحول تنظيم مهام ومسؤوليات الوحدات الإدارية العاملة في الشراء العام\nإن رئيس هيئة الشراع العام؛\nبناءًٌ على قانون الشراء العام رقم ٠١1/954 النافذ اعتبارا من تاريخ 7١77/17/79 وتعديلاته» سيما\nالمواد الأولى[المبادئ) والعاشرة (قواعد السلوك) و7\" (التدريب) و1/ (التسمية الوظيفية) 75 (مهام هيئة\nالشراء العام) و١٠٠ (لجان التلزيم) و1١١٠ (لجان الاستلام) و١١١ (التدقيق الداخلي) منه» 1\nوبما أن المادة الأولى من قانون الشراء العام قد نصت على خضوع عمليات الشراء إلى قواعد الحوكمة\nالرشيدة» ومنها النزاهة والمهنية والتخصصء والعلنية والشفافية» والمعاملة العادلة والمتساوية» والمساءلة\nوالمحاسبة» كما نصت على اعتبار المبادئ العامة الواردة في هذه المادة من الانتظام القانوني العام»\nوبما أن القانون قد تضمّن أسس حوكمة الشراء العام والأحكام التي ترعى التطبيقات والترتيبات والأنظمة\nالإجرائية الشاملة التي تضمن المستويات الملائمة من الرقابة والنزاهة في كافة مراحل الشراءء؛ بدءأ من\nتحضير خطة الشراء وصولا إلى الاستلام النهائي والتدقيق اللاحق»\nوبما أن قانون الشراء العام قد أرسى الإطار المؤسساتي وأوجب الإنشاء في الهيكل التنظيمي للجهات\nالشارية الخاضعة لأحكامه للوحدات المختصة بالشراء العام؛ وقد حدد مهماتها المتعلقة بإجراءات الشراء\nعلى أن تؤدي كل منها دورها بمهنية ونزاهة وتخصص على قاعدة الفصل بين المهام وثفعيل نظام الرقابة\nالداخلية, ومنح لها الاستقلالية حيت يلزم»\nوبما أن قانون الشراء العام قد حدد علاقة الجهات أو الوحدات المختصة ضمن الهيكل التنظيمي للجهات\nالشارية مع هيئة الشراء العام والمسؤوليات والموجبات تجاههاء\nوبما أنه وفي هذا الإطار فان الفصل السادس من قانون الشراء العام (حوكمة الشراء العام) قد عزز القواعد :."}, {"o": 1, "l": null, "b": "والمبادئ آنفة الذكر من خلال المهام التي أناطها بهيئة الشراء العام؛ سيما تلك المنصوص عليها في الفقرات\n.>2 و18و*ء” من المادة 5 من قانون الشراء العام\nوبما أنه وفي السياق عينه؛ فقد أولى القانون هيئة الشراء العام مهام وصلاحيات متعددة ومئها:\n» تحديد المعابير والأصول التي على الجهات الشارية اتباعها للتدقيق الداخلي»\n© تحديد أسس تأليف لجان التلزيم والاستلام والتحقق من مؤهلاتهاء جخيرية لير .\n: ك 0 77\n© وضع شرعة قواعد السلوك والأخلاق المهنية الخاصة بعمليات الشراء العام 46 / .\nره 0 د كم ١\n34 ضر يم ١\n١ ل ري\n22 م\nك6 الجمدوريّة اللبنائيتة\nدك هيثة الشراء العام\nمطاب شفافية ٠ منافسة ٠ نزاهة\nوبما ان الهيكل التنظيمي وفدًا لما تقدم بات يضم:\nوحدة الشراء العام المسؤولة عن عمليات الشراء وفقا لأحكام القانون» والتي لها حق طلب المشورة\nالتقنية» عند الاقتضاء» من هيئة الشراء العام؛ أو استطلاع رأيها في موضوع معيّن يتعلق بالشراء.\n» لجان التازيم المستقلة عن الجهة الشارية في كل أعمالها وقراراتهاء والمناط بها مسؤولية فتح وتقييم\nالعروض وققا للأسس المنصوص عليها في قانون الشراء العام والتي حدد القرار رقم\n/.ش.ع./77١؛ الصادر عن هيئة الشراء العام بتاريخ 7١71/1١/٠١ أسس تأليفها.\n© لجان الاستلام التي تقع على عاتقها مسؤولية الاستلام وفقأً للأسس المنصوص عليها في قانون\nالشراء العام والتي حدد القرار رقم 5/درش.ع./77١٠ الصادر عن هيئة الشراء العام بتاريخ\n١٠ أمسس تأليفها.\n» الوحدة المعنية بالتدقيق الداخلي؛ المناط بها مهمة مراقبة تطبيق أحكام قانون الشراء العام والمراسيم\nوالقرارات التنظيمية له» وهي ملزمة بإبلاغ كل من هيئة الشراء العام والهيئات الرقابية المختصة\nفور عن أية مخالفات أو إهمال نتيجة التدقيق الداخلي.\nل للك\nيطلب من كافة الجهات الشارية الخاضعة لأحكام قانون الشراء العام:"}, {"o": 2, "l": null, "b": "أولاً: إحداث وحدة للشراء العام في الهيكل التنظيمي للجهة الشارية أو تعديل هذا الهيكل وفق متطلبات\nالقانون» وإيلاء هذه الوحدة مسؤولية عمليات الشراءء واتخاذ كل ما يلزم من إجراءات واقتراحات\n1 لوضع هذا الموجب موضع التطبيق وفق مقتضيات المادة 73 من قانون الشراء العام.\nثانياً: اتخاذ قرار من رأس الادارة» لتولية واحد أو أكثر من العاملين لدى الجهة الشارية مهمة التدقيق\nالداخلي وفق المادة 111 من قانون الشراء العام على تكون الأولوية للعاملين في وحدة التدقيق الداخلي\n5 متى وجددت. 40\nثالثاً: يُعمل بهذه المذكرة من تاريخ نشرها على الموقع الالكتروني المعتبر بمثابة تاريخ التبليغ وفقًا لأحكام\nالفقرة ١5 من المادة الثانية من قانون الشراء العام.\nبيروت في ا ا ا / 5\n١ .. ركيسرهيئة الث لعا\nمصجحصير ننج يئه الشراع ١ م\n0 /\n0 اا\n١ 3 كود د. جان/العلية\n| : |\n: ا ْ\n:0 2/2"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (17,'توصيات الهيئة','المناقصة العمومية التي أعلنت عنها مؤسسة كهرباء لبنان','2022-08-23','https://www.ppa.gov.lb/ar/pages/details/17','{"https://admin.ppa.gov.lb/storage/listing-pages/files/rR579T0fpS4glBEFRx7Tb3JNYioGZCyIaRab-1763550130.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/rR579T0fpS4glBEFRx7Tb3JNYioGZCyIaRab-1763550130.pdf"}','ocr') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=17),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "0 الجمهوريّة اللبنانيتة\nوك هيئة الشراء العام\nتوصية رقم ١/إه.ش.ع/77١٠\nفي موضوع المناقصة العمومية التي أعلنت عنها مؤسسة كهرباء لبنان لتقديم خدمات إنتاج وتوزيع\nكهربائية ضمن حدود نطاق امتياز زحلة السابق المُعلن عنها بتاريخ ٠١77/17/7١ والتي حدد آخر\nموعد لتقديم عروضها بتاريخ 7071/8/١5\nأ إن رئيس هيئة الشراء العام»\nبناءً على المادة الأولى من قانون الشراء العام رقم ١44 تاريخ 7١71/17/١5 لتي تعتبر مبادئ المنافسة والمساواة والعلنية\nمن الانتظام القانوني العام»\nبناءً على المادة 75 من قانون الشراء العام التي تنيط بهيئة الشراء العام تنظيم الشراء العام والإشراف عليه ومراقبته.\nوتقديم المساعدة الفنية والإرشاد للجهات الشارية»\nبناءَ على المادة 88 فقرة ؟ من قانون الشراء العام التي تنيط برئيس هيئة الشراء العام مهام الهيئة إلى حين تعيينهاء\nوبما أنه طُلب إلى مؤسسة كهرباء لبنان بموجب كتاب رئيس هيئة الشراء العام رقم ١١/ه.ش.ع/75١23 تاريخ\n0ه ايداع هيئة الشراء العام الوثائق المتعلقة بهذه المناقصة في أقرب وقت ممكن على البريد الالكتروني\nالخاص بهيئة الشراء العام لتقدير مشروعيتها بالإستناد الى النصوص النافذة بتاريخ الإعلان عنهاء\nوبما أن مؤسسة كهرباء لبنان لم تودع هيئة الشراء العام الوثائق المتعلقة بالمناقصة المذكورة» بما فيها دفتر الشروط\nالخاص بالصفقة لنشره على الموقع الالكتروني الخاص بهيئة الشراء العام عملا بأحكام المادة 5١ من قانون الشراء العام»\nوبما أن المهلة المتبقية من الموعد المحدد كآخر مهلة لتقديم العروض بتاريخ 30217/8/57». لم تعد كافية لنشر دفتر\nالشروط الخاص بالصفقة والإطلاع عليه» كما أن موعد جلسة فض العروض غير مُحدد في الإعلان عن المناقصة»\nوبما أنه لم يتبين نشر الاعلان عن هذه المناقصة العالمية في وسائل نشر عالمية؛ وانما شر في الجريدة الرسمية بتاريخ"}, {"o": 1, "l": null, "b": "5:0» ضمن مهلة لا تتفق مع طبيعة موضوع الصفقة وتبدو غير كافية سيما في هذه الظروف الاستثنائية\nلتحضير العروض»\nلذلكء\nوحرصًا على تأمين الشفافية والمنافسة وتكافؤ الفرص»\nوحرصًا على نجاح هذه المناقصة العالمية المرتبطة بتأمين خدمات إنتاج وتوزيع الطاقة في نطاق إمتياز زحلة السابق»\nتوصي هيئة الشراء العام مؤسسة كهرباء لبنان بإلغاء اجراءات المناقصة المعلن عنها في 71/1/5١ 50: واعادة\nإجرائها وفقًا لدفتر شروط خاص يتم إعداده وفقًا للأصول ويُّنشر على المنصة الإلكترونية المركزية التابعة لهيئة\nالشراء العام؛ ه انيةطلب ابداء الرأي المسبق بشأنه عملا بأحكام المادة 77 من قانون الشراء العام.\nيه اللى”\n2-2 بيروت في 7077/8/15\n5 رفيس هيئة اشراء العام\nسح كم\nب\n033 0 د. جان) العلية\nا جان) العلي\n١ 100-10 961-1-728000+ 25\nطاء/امع3.8مم © قاممء 80\n/ط ا نامع همم. بجبوبما//: وماغط\nتبلغ نسخة الى جانب مؤسسة كهرباء لبنان عمماءع غ15 .ع0ا8 صنه9/0د8 مدصطاخ غعع:56 ه20ه8 - ماعبزهمة5 - انماع 8 ا"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (18,'مذكرات الرئيس','مذكرة رقم 2022/2 : موجهة الى كافة البلديات واتحادات البلديات في موضوع تطبيق قانون الشراء العام','2022-08-11','https://www.ppa.gov.lb/ar/pages/details/18','{"https://admin.ppa.gov.lb/storage/listing-pages/files/Qc0ozvJGgTzlLKyZGxfTcB6D7INMYYoESCpW-1762768382.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/Qc0ozvJGgTzlLKyZGxfTcB6D7INMYYoESCpW-1762768382.pdf"}','ocr') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=18),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "هر الجمهوريّة اللبنانيتة\nدادم سيئة الشراء العام\n\"كك\" شفافية . منافسة ٠ نزاهة\nمذكرة رقم /١ ه.ش.ع / 7٠١77\nموجهة الى كافة البلديات واتحادات البلديات في موضوع تطبيق قانون الشراء العام\nأخذ المشرّع اللبناني في قانون الشراء العام بعين الاعتبار الازمة المالية والاقتصادية التي تمرّ بها البلادء كما أخذ بعين\nالاعتبار حالة المالية العامة وقرارات منع التوظيفء ولذلك فقد نصت المادة ٠/ا في فقرتها الثانية على أن ' تنشأ في الهيكل\nالتنظيمي للجهة الشارية وحدة للشراء أو يُعدّل هذا الهيكل؛ وفقاً للاقتضاء؛ وتكون هذه الوحدة مسؤولة عن عمليات الشراء\nوفقأ لأحكام هذا القانون. تُشكّل هذه الوحدة من الموظفين الذين خضعوا للتدريب وفقا للمادة ؟ أعلاه» وعلى أن يتناسب\nعديد هذه الوحدة وكفايات أعضائها مع حجم ونوع الشراء لديها \".\nعندما يؤكد المشرّع على ان عديد الوحدة يجب ان يتناسب مع حجم الشراء لديها وانها تُشكّل من الموظفين الذين خضعوا\nللتدريب؛ فهو كأنه يقول بأن مهام الوحدة يتولاها شخص او اكثر من الادارة نفسها من المتدربين على الشراء العامء وذلك\nبحسب حجم الشراء في الادارة واهميته» دون الحاجة الى التوظيف من خارج الكادر البشري الموجود في الجهة الشارية.\nفيما يتعآق بلجان التلزيم؛ نصت المادة ٠٠١ من القانون في فقرتها الثانية- أولاً على ان \" قبل شهر تشرين الأول من كل\nسنة» تقترح الجهة الشارية لائحة بإسماء موظفين من إدارتها من الفئة الثالثة على الأقل ممّن لديهم خبرة مثبتة في مجال\nالشراء العام و/أو من بين المدرّبين عليه أصولاً وفقاً لأحكام هذا القانون» ويقوم بارسال هذه اللائحة إلى هيئة الشراء\nالعاموي؟\nعندما يقول المشرّع 'تقترح الجهة الشارية لائحة.... ' فهو لا يُلِم الاقتراح لجميع الجهات الشارية دون استثناءء بل تقترح"}, {"o": 1, "l": null, "b": "الجهات الشارية التي تنطبق عليها شروط هذه الفقرة» أي تلك التي تمتلك ضمن كادرها الوظيفي موظفين من الجية الثالثة\nوما فوق ومدرّبين أصولأء الخ....\nمن جهة أخرى؛ نصت المادة ٠٠١ نفسها في فقرتها الثالثة- اولاً على أن 'تُشكّل الجهة الشارية لجنة أو لجان التلزيم لديهاء\nعند تنفيذ خطتها السنوية للسنة المقبلة؛ من اللائحة الموحّدة الموضوعة من قبل هيئة الشراء العام؛ على أن يكون أحد\nالأعضاء على الأقل في كل لجنة من خارج موظفي الجهة الشارية\".\nأي أنّ المشرّع ألزم الجهة الشارية اختيار أعضاء لجنة التلزيم عند وجوب تشكيلها من ضمن اللائحة الموحّدة» وليس من\nضمن الجهة الشارية نفسها. أما شرط أن يكون أحد الاعضاء على الاقل من خارج موظفي الجهة الشارية» فهو لا يمنع أن\nيكون جميع الاعضاء من خارج الجهة الشارية» وبالتالي لا توجد مشكلة بالنسبة لتشكيل لجان التلزيم فيما يتعلق بالبلديات\nالتي تفتقر الى العدد الكافي من موظفي الفئة الثالثة.\nأما فيما يتعلّق بلجان الاستلام؛ فإنه يعود للسيد وزير الداخلية والبلديات عملا بقواعد الاختصاص اتخاذ الاجراء المناسب\nلتشكيل هذه اللجان تأميئًا لاستمرارية المرفق العا -\nب ١\n0 بيروت في ٠077/8/١١\nم\nل ١\n0 د. جان العلية\nيمكن للجهات الشارية ايداع هيئة الشراء العام المعلومات المطلوبة على العنوان التالي: 3.901.15مم ©001361ع"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (19,'مذكرات الرئيس','مذكرة رقم 2022/3 : خضوع عمليات الشراء لموجب تشكيل لجان التلزيم وفقًا لنص المادة 100 من قانون الشراء العام','2022-08-12','https://www.ppa.gov.lb/ar/pages/details/19','{"https://admin.ppa.gov.lb/storage/listing-pages/files/ruYwupukbFo5PpiNagL94MxnapBJG5so0L9v-1762768349.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/ruYwupukbFo5PpiNagL94MxnapBJG5so0L9v-1762768349.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=19),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "مذ�رة رقم / ٣ه.ش.ع ٢٠٢٢ /\n وفقا\n موجهة الى الجهات الشار�ة في موضوع خضوع عمل�ات الشراء لموجب تشكیل لجان التلز�م ً\n لنص المادة ١٠٠من قانون الشراء العام رقم ٢٤٤تار�خ ٢٠٢١/٧/٢٩\nعملا �القرار رقم /١ه.ش.ع ٢٠٢٢/الصادر عن رئ�س هیئة الشراء العام بتار�خ ُ ،٢٠٢٢/٨/٥تذ�ر\n ً\n هیئة الشراء العام �ما یلي:\n أولا :تخضع عمل�ات الشراء التي ُتجرى �الطرق التال�ة لموجب تشكیل لجان التلز�م ً\nوفقا لنص المادة ١٠٠ ً\n من قانون الشراء العام:\n المسبق\n -١التأهیل ُ\n -٢المناقصة العموم�ة\n -٣المناقصة على مرحلتین\n -٤طلب الاقتراحات للخدمات الاستشار�ة\n -٥ارساء العقود من ضمن الاتفاقات الاطار�ة المنطو�ة على تنافس في المرحلة الثان�ة\n -٦طلب عروض الأسعار\n ثان�ا :لا تخضع عمل�ات الشراء التي ُتجرى �الطرق التال�ة لموجب تشكیل لجان التلز�م ً\nوفقا لنص المادة ً\n ١٠٠من قانون الشراء العام:\n -١الفاتورة\n -٢الاتفاق�ات الرضائ�ة\n -٣ارساء العقود من ضمن الاتفاقات الإطار�ة غیر المنطو�ة على تنافس في المرحلة الثان�ة\n☎ +961-1-728000 ext.100-110\n📧📧 contact@ppa.gov.lb\nhttps://www.ppa.gov.lb/\n� Beirut - Sanayeh - Bordo Street Ahmad Baydoun Bldg. 1st Floor"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (20,'مذكرات الرئيس','مذكرة رقم 2022/4 : المتعلقة بموضوع تحضير دفاتر الشروط و نشر االإعلانات المتعلقة بعمليات الشراء','2022-08-19','https://www.ppa.gov.lb/ar/pages/details/20','{"https://admin.ppa.gov.lb/storage/listing-pages/files/I89QHv8g36rqhN4anQQ5yE9uofN8W9vz8yrH-1762768292.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/I89QHv8g36rqhN4anQQ5yE9uofN8W9vz8yrH-1762768292.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=20),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "مذكرة رقم / 4ه.ش.ع 2022 /\n موجهة الى الجهات الشارية في موضوع تحضير دفاتر الشروط\n ونشر االعالنات المتعلقة بعمليات الشراء\n ان رئيس هيئة الشراء العام،\n بناءًًعلىًقانونًالشراءًالعامًرقمًً244تاريخًً2021/7/29سيماًالموادًً76ً،ً52ً،51ً،12منهً ً،\n يوضح ما يلي:\nأوًالً:انًالجهاتًالشاريةًملزمةًبايداعًهيئةًالشراءًالعامً،وثائقًاالعالناتًالمتعلقةًبعملياتًالشراءًالتيًتجريهاً\nلنشرهاًعلىًالمنصةًااللكترونيةًالمركزيةًالتابعةًللهيئةًليبدأًمفعولهاًبالسريانً،وانًاالعالنًلنًيكونًلهًايً\nمفعولًقبلًنشرهًعلىًهذهًالمنصةً،وذلكًوفقاًللنموذجًالصادرًعنًهيئةًالشراءًالعامًوالموجودًعلىًموقعهاً\n االلكترونيً(المادةًً12منًقانونًالشراءًالعام)ً .\nعًالصفقةًوتعقيداتهًاعتباراًمنًتاريخً\n ً ثانياً:تقدرًهيئةًالشراءًالعامًكفايةًمدةًاالعالنًبالنظرًالىًاهميةًمشرو\n ً\n نشرهًعلىًالمنصةًااللكترونيةًالمركزيةًفيًهيئةًالشراءًالعامً(المادةًً12منًقانونًالشراءًالعام).\nثالثًاً :تخضعًدفاترًالشروطًالخاصةًلموجبًالنشرًعلىًالمنصةًااللكت ًرونيةًالمركزيةًالتابعةًللهيئة ًوالموقعً\nااللكترونيًللجهةًالشاريةًانًوجدًسندًاًللمادةًً 51منًقانونًالشراءًالعامً،وهيًالًتخضعًلموجبًالموافقةً\nالمسبقةًمنًقبلًهيئةًالشراءًالعامً،انماًتقومًالهيئةًانطالقًاًمنًموجباتهاًالمتعلقةًبمراقبةًتطبيقًالنصوصً\nالقانونيةًوالقواعدًالتيًترعىًالشراءًالعامًسندًاًللفقرةًالتاسعةًمنًالمادةًً 76منًقانونًالشراءًالعامً،بإبداءً\nمالحظاتها ًعلى ًدفاتر ًالشروط ًلناحيةًاستجابتها ًللمبادئًوالقواعد ًواالجراءات ًالمنصوصًعليهاًفي ًقانونً\n الشراءًالعامً .\nابعاً :يمكنًللجهاتًالشاريةًعرضًدفترًالشروطًالخاصًعلىًهيئةًالشراءًالعامًقبلًالشروعًفيًاجراءاتً\n رً\n االعالنًعنًالصفقةً،البداءًالرأيًسندًاًالحكامًمقدمةًالمادةًً76منًقانونًالشراءًالعام.\n ☎ +961-1-728000 ext.100-110\n 📧 contact@ppa.gov.lb"}, {"o": 1, "l": null, "b": "https://www.ppa.gov.lb/\n 🌍 Beirut - Sanayeh - Bordo Street Ahmad Baydoun Bldg. 1st Floor"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (21,'مذكرات الرئيس','مذكرة رقم 2022/5 : المتعلقة بموضوع تجزئة بعض النفقات','2022-08-19','https://www.ppa.gov.lb/ar/pages/details/21','{"https://admin.ppa.gov.lb/storage/listing-pages/files/EafwtHjzsb2lP9oZVYLWNbNX5o8TX7P037Zp-1779692543.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/EafwtHjzsb2lP9oZVYLWNbNX5o8TX7P037Zp-1779692543.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=21),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "Page 1 of 2\n مذكرة رقم / 5ه.ش.ع 2022 /\n موجهة الى الجهات الشارية في موضوع تجزئة بعض النفقات\n ان رئيس هيئة الشراء العام،\n بناءًًعلىًقانونًالشراءًالعامًرقمًً244تاريخًً2021/7/29سيماًالمادتينًً14وً113منهً ً،\n يوضح ما يلي:\nًحيز ًالتنفيذ ًولم ًتنفذ ًكاملً\n ًمعينة ًقد ًاتخذت ًقبل ًدخول ًقانون ًالشراء ًالعام ّ\n بما ًأن ًق اررات ًتجزئة ًصفقات ّ\nمفاعيلها ً في ًظل ًالقانون ًالقديمً ،األمر ًالذي ًيطرح ًمصير ًهذه ًالق اررات ًوالنتائج ًالتي ًتترتب ًعليها ًوفقً\n التالي:\nأول :يجب ًالتمييز ًبين ًق اررات ًالتجزئة ًالصادرة ًقبل ًدخول ًقانون ًالشراء ًالعام ًحيز ًالتنفيذ ًبتاريخً\n ً\n ً،2022/7/29وتلكًالصادرةًبعدًدخولهًحيزًالتنفيذ:\n -1بالنسبة ًلق اررات ًالتجزئة ًالصادرة ًقبل ًدخول ًقانون ًالشراء ًالعام ًحيز ًالتنفيذ ًفي ًً ،2022/7/29فإنً\n مشروعيةًهذهًالق ارراتًتقاسًبالرجوعًالىًالمادةًً123منًقانونًالمحاسبةًالعمومية.\nإنًاإلنفاقًعلىًالمشترياتًالعموميةًمنًهذهًالق ارراتًلناحيةًاختيارًطرقًالشراءًووضعًدفاترًالشروطً\nالخاصة ًيخضع ًألحكام ًقانون ًالمحاسبة ًالعمومية ًلغاية ًً ،2022/7/29وألحكام ًقانون ًالشراء ًالعامً\nاعتبارًمنًذلكًالتاريخً،أماًبالنسبةًللعملياتًاإلجرائيةًالتاليةًلعمليةًاإلعالنًعن ًالصفقةًفهيًتخضعً\n ا\nألحكام ًقانون ًالمحاسبة ًوالعمومية ًونظام ًالمناقصات ًإذا ًتم ًاإلعالن ًعن ًالصفقة ًقبل ًً2022/7/29\nولقانونًالشراءًالعام ًإذاًتمًاإلعالنًبعدًذلكًالتاريخً،كماًأنًالق ارراتًالتنفيذيةًالالحقةًلق ارراتًالتجزئةً\nوالتيًبوشرًبهاًفعليًاًقبلًنفاذًالقانونًالجديدًوالتيًتترتبًوتكتملًنتائجهاًبعدًنفاذهًفهيًتبقىًخاضعةً\nلألحكام ًالسارية ًقبله ًما ًدامت ًمرتبطة ًومتصلة ًبإجراءات ًتنفيذية ًبدأت ًفعليًا ًقبل ًالتاريخ ًآنف ًالذكرً،"}, {"o": 1, "l": null, "b": "وذلك ًعمالً ًباألثر ًالمباشر ًللقانون ًالجديد ًوعدم ًرجعيته ًليطبق ًعلى ًحاالت ًبدأت ًفعليًا ًبالتكون ًقبلً\n نفاذهً .\n ً\n ً\n ً\n ً\n ☎ +961-1-728000 ext.100-110\n 📧 contact@ppa.gov.lb\n https://www.ppa.gov.lb/\n 🌍 Beirut - Sanayeh - Bordo Street Ahmad Baydoun Bldg. 1st Floor\n\fPage 2 of 2\n ً\n ً\n -2بالنسبةًلق ارراتًالتجزئةًالتيًتصدرًبعدًدخولًقانونًالشراءًالعامًحيزًالتنفيذً،فيجبًالتقيدًباألحكامًالتيً\nجزاء ًعنً\n فصلتها ًالمادة ًً 14من ًقانون ً ًالشراء ًالعام ًكتنوع ًمصادر ًالتوريد ًوتعددها ًاو ًاختالف ًاأل ً\n ّ\nبعضهاًبماًيؤديًالىًمنفعةًأكيدةًمنًالتجزئةً،وهذهًاألحكامًأوردتها ًالمادةًً 14علىًسبيلًالمثالًالً\nالحصرً ،ولكنهاًربطتًامكانيةًالتجزئةًفيًكلًالحاالتًبتحقيقًمنفعةًأكيدةًمنهاًللشراءً،وبالتاليًفإنً\nقرًاراتًالتجزئةًالتيًتصدرًفيًظلًهذهًالمرحلةًاالنتقاليةًحيثًشارفتًالسنةًالماليةًعلىًاإلنتهاءًوعدمً\nتوفرًال ًوقتًالكافيًإلجراءًتلزيماتًوفق ًاألصولً،ومعًدخولًإجراءاتًقانونًالشراءًالعامًحيزًالتنفيذً\nمنذًوقتًقصيرًوعمالًًبمبدأًإستم ارريةًالمرافقًالعامةًيجبًأنًتكونًمتقيدةًبحدودًاألحكامًالتيًأوردتهاً\n المادةًً14منًقانونًالشراءًالعام.\nثانياً:الًيجوزًبأيًحالًاللجوءًإلىًتجزئةًالشراءًإلىًجزئياتًلتطبيقًأحكامًخاصةًبكلًجزءًمنهاًبغرضً\n ً\n تخفيضًالقيمةًالتقديريةًلمشروعًالشراءًاوًبقصدًالتهربًمنًالرقابةًأوًمنًتطبيقًاحكامًقانونًالشراءًالعام.\n☎ +961-1-728000 ext.100-110\n📧 contact@ppa.gov.lb\nhttps://www.ppa.gov.lb/\n🌍 Beirut - Sanayeh - Bordo Street Ahmad Baydoun Bldg. 1st Floor"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (22,'مذكرات الرئيس','مذكرة رقم 2022/6 : المتعلقة بطريقة الاعلان عن عمليات الشراء التي تقوم بها الجهات الشارية بطريقة الشراء بالفاتورة','2022-08-19','https://www.ppa.gov.lb/ar/pages/details/22','{"https://admin.ppa.gov.lb/storage/listing-pages/files/FxCZ11LDg36XFueVl2hIPib98Gj6j2k8WsV2-1779201028.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/FxCZ11LDg36XFueVl2hIPib98Gj6j2k8WsV2-1779201028.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=22),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "مذكرة رقم / 6ه.ش.ع 2022 /\n حول طريقة االعالن عن عمليات الشراء\n التي تقوم بها الجهات الشارية بطريقة الشراء بالفاتورة\n ان رئيس هيئة الشراء العام،\n بناء على قانون الشراء العام رقم 244تاريخ 2021/7/29سيما المواد 76 ،26 ،12و 88منه،\n وبناء على البند الثاني من الفصل الثالث منه الذي يحكم طريقة الشراء بالفاتورة،\n يوضح ما يلي:\nأو اال :إن إجراءات الشراء بالفاتورة ال تخضع لموجب اإلعالن بحسب المادة 12من قانون الشراء العام ،وهو ما\n يبينه البند السادس من الفصل الثالث الذي ينظم طريقة الشراء بالفاتورة.\n ّ\nثاني ا :تخضع اجراءات الشراء بالفاتورة لمبدأ العلنية وألحكام المادة 26من قانون الشراء العام (قواعد االعالن عن\nأن على الجهة الشارية أن تَنشر ،مرة في السنة على\n ارساء التلزيم) ،ال سيما الفقرة 2منها ،والتي تنص على \"ّ ...\nاألقل ،إعالنا جامعا لك ّل ما أُرسي من عقود من هذا القبيل ،\"...باإلشارة إلى موجب نشر إعالن بإرساء التلزيم أو\nالملتزم وقيمة العقد (فقرة 1من اتفاق إطاريُ ،ي َّ\n حدد فيه إسم ُ ٌ االتفاق اإلطاري ،وذلك عندما َيبدأ نفاذ العقد أو يُ َبرم\n َّ\nالمحدد في شروط استخدام طريقة الشراء بالفاتورة المادة )26بالنسبة للعقود التي تتخطى قيمتها السقف المالي\n(فقرة 2من المادة )26أي سقف 100مليون ليرة لبنانية .أما عمليات الشراء التي ال تتخطى قيمتها سقف الـ100\n مليون ليرة لبنانية ،فهي تُنشر بإعالن جامع على األقل مرة في السنة.\n تقدم،\n بناء على ما ّ\n ا\nُيطلب الى جميع الجهات الشارية نشر إعالن جامع عن عمليات الشراء التي تقوم بها باستخدام طريقة الشراء\nبالفاتورة بحسب نموذج يصدر الحقا مرتين في السنة على األقل ،وذلك على موقعها االلكتروني إن ُوجد ،كما\nإرسال اإلعالن الجامع إلى هيئة الشراء العام بهدف النشر على المنصة االلكترونية المركزية للهيئة ،وذلك خالل\n المهل التالية:"}, {"o": 1, "l": null, "b": ".1خالل شهر كانون الثاني من كل سنة لعمليات الشراء التي جرت في النصف الثاني من السنة ،ابتداء من\n كانون الثاني .2023\n .2خالل شهر تموز من كل سنة لعمليات الشراء التي جرت في النصف األول من السنة ،ابتداء من تموز .2023\n☎ +961-1-728000 ext.100-110\n📧 contact@ppa.gov.lb\nhttps://www.ppa.gov.lb/\n🌍 Beirut - Sanayeh - Bordo Street Ahmad Baydoun Bldg. 1st Floor"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (23,'مذكرات الرئيس','مذكرة رقم 2022/7 : مدى خضوع عمليات البيع بالتراضي وباستدراج العروض وبالمزايدة العمومية لأحكام قانون الشراء العام','2022-08-29','https://www.ppa.gov.lb/ar/pages/details/23','{"https://admin.ppa.gov.lb/storage/listing-pages/files/IHjNoUfNLa1Olnqm7C8PLNAPcLgAFOeG1a51-1760435937.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/IHjNoUfNLa1Olnqm7C8PLNAPcLgAFOeG1a51-1760435937.pdf"}','ocr') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=23),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "2-35 الجمهوريّة اللبنانيتة\nمو سيكة الشراء العام\nسلف - شفافية ٠ منافسة ٠. نزاهة\nمذكرة رقم ٠7 / ه.ش. 55\nفي موضوع مدى خضوع عمليات البيع بالتراضي وباستدراج العرومض\nوبالمزايدة العمومية لأحكام قانون الشراء العام\nإن رئيس هيئة الشراء العام»\nبناءً على قانون الشراء العام رقم 745 تاريخ 5١7١/1/١1 سيما المادتين 5 و88 فقرة (1) منه»\nيوضح ما يلي:\nنصّت المادة 45 من قانون المحاسبة العمومية على ما يلي: 'ثباع أموال الدولة غير المنقولة وفقًا للأحكام المُختصّة بها\"\nويُذكر في هذا المجال القراران رقم ١44 تاريخ ١175/1/٠١ المتعلق بأملاك الدولة العامة ورقم ١5 تاريخ ١157/5/55\nالمتعلق بإدارة وبيع أموال الدولة الخاصة.\nنصّت المادة 4 من قانون المحاسبة العمومية على أن 'تُطبّق على البيع بالتراضي وباستدراج العروض وبالمزايدة العمومية\nالأحكام المُختصة بصفقات اللوازم والأشغال ما لم ينص القانون على خلاف ذلك\".\nحدد القسم الأول من الفصل الخامس من قانون المحاسبة العمومية الأحكام الخاصة بصفقات اللوازم والأشغال والخدمات\n(المواد ١١١ حتى ١5١ ضمنًا).\nبتاريخ ٠١77/9/15 أصبح القانون رقم ١45 تاريخ ٠١71/17/١5 (قانون الشراء العام) نافذًا عملا بأحكام المادة ١١5 منه.\nنصّت المادة ١١5 من قانون الشراء العام على أن 'تثلغى المواد ١1١ حتى ١5١ ضمئًا من قانون المحاسبة العمومية\nالموضوع موضع التنفيذ بموجب المرسوم رقم ١4355 الصادر بتاريخ .197517/17/5١\nيُطرح السؤال: مع إلغاء الأحكام الخاصة بصفقات اللوازم والأشغال والخدمات في قانون المحاسبة العمومية: ما هي\nالقواعد الإجرائية المُطبّقة على بيع أموال الدولة بالتراضي أو باستدراج العروض أو بالمزايدة العمومية؟\nبما أنه بالرجوع الى نص المادة 47 من قانون المحاسبة العمومية؛ نرى أنّه تُطبّق على البيع بالتراضي وباستدراج العروض"}, {"o": 1, "l": null, "b": "وبالمزايدة العمومية الأحكام المُختصّة بصفقات اللوازم والأشغال ما لم ينص القانون على خلاف ذلك»\nوبما أن قانون الشراء العام رقم 44 تاريخ :5071/17/١4 قد ألغى الأحكام المُختصّة بصفقات اللوازم والأشغال والخدمات\nالواردة في المواد ١١١ حتى ١5١ ضمنًا من قانون المحاسبة العمومية واستبدلها بالأحكام المنصوص عليها في قانون الشراء\nالعام»\nوبما أن المادة 4 من قانون المحاسبة العمومية قد أخضعت بيع أموال الدولة بالتراضي وباستدراج العروض وبالمزايدة\nالعمومية إلى الأحكام المُختصّة بصفقات اللوازم والأشغال من دون ذكر أرقام مواد أو قانون مُحدد بذاته»\nلسسشدلقه»\nتطبّق على عمليات البيع بالتراضي وباستدراج العروض «بالمزايدة العمومية أحكام قانون الشراء العام.\n- , بيروت في ١١77/8/59\n3-0 7 رئيس هيئة الشراء العام\nو 2-١\nحم د. جان يه\nملي . مدن اي\nا ا إل ١١"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (24,'مذكرات الرئيس','مذكرة رقم 2022/8 : التعاقد مع مقدّم العرض الوحيد في عمليات الشراء بالفاتورة التي تجريها الجهات الشارية','2022-09-19','https://www.ppa.gov.lb/ar/pages/details/24','{"https://admin.ppa.gov.lb/storage/listing-pages/files/ZfGU7rVfEVZkI93dNajMegtaCW5V275DYLZZ-1760222151.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/ZfGU7rVfEVZkI93dNajMegtaCW5V275DYLZZ-1760222151.pdf"}','ocr') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=24),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "5 ' 2 1 عووم\nالجمصوريّة اللبنانيتة\n.7 هيئة الشراء العام\nمذكرة رقم م / ه.ش.ع / ٠١7١\nفي موضوع التعاقد مع مقدّم العرض الوحيد في عمليات الشراء بالفاتورة\nالتي تجريها الجهات الشارية\nان رئيس هيئة الشراء العام\nبناء على قانون الشراء العام رقم ١45 تاريخ 5١7١/1/١5 سيما المواد 20١ هق 45. لاك .ل ال كلا\nو88 منه»\nيوضح ما يلي:\nنص البند الثاني من الفصل الثاني من قانون الشراء العام بعنوان قواعد عامة لإعداد واجراء وتنفيذ عمليات\nالشراء في المواد من ١9 الى 58 منه ضمنًا على إجراءات التلزيم وهي تطبّق على طرق الشراء كافة بمقدار عدم\nتعارضها مع النصوص الخاصة بها.\nأجازت الفقرة (4) من المادة ١5 من قانون الشراء العام التعاقد مع مقدم العرض الوحيد المقبول استثنائيًا عند\nتوافر الشروط التالية مجتمعة:\n-١ أن تكون مبادىء وأحكام هذا القانون مُطبّقة وأن لا يكون العرض الوحيد ناتجًا عن شروط حصرية\nتَضْمَّتَها دفتر الشروط الخاص بمشروع الشراء؛\n-١ أن تكون الحاجة أساسية ومُلِحَة والسعر مُنسّجماً مع دراسة القيمة التقديرية؛\n\"- أن يتضمّن تشر قرار الجهة الشارية بقبول العرض الفائز (التلزيم المؤقت) نصّأ صريحاً بتقدّم العارض\nالوحيد المقبول ونيّة التعاقد معه.\nبما ان الشراء بالفاتورة هو طريقة استثنائية لاجراء عمليات الشراء» فيتوجب على الجهات الشارية عند اجرائها\nعملية شراء بالفاتورة أن تطلب عروض أسعار من أكبر عدد ممكن من العارضين تأميئًا للتنافسية» وذلك تطبيقًا\nللفقرة )١( من المادة ٠١ وايضًا للفقرة )١( من المادة 55 التي أوجبت على الجهة الشارية عند اعتمادها طرق\nشراء اخرى غير المناقصة العمومية أن تسعى إلى زيادة التنافس إلى أقصى حد ممكنء؛ على ألا يقل عدد\nعروض الاسعار المطلوبة من الجهة الشارية عن عرضين.\n<-موائة الب\n|| | 2ض\n<١ 22 / |\n2 2 معط"}, {"o": 1, "l": null, "b": "وبما أن المشرّع قد أجاز كقاعدة إجرائية استثنائية في المادة 5؟ فقرة (4) منها التعاقد مع مقدم العرض الوحيد\nالمقبول عند توفر شروط محددة»\nوبما أن المادة ١5 تطبق على كافة طرق الشراء المحددة في المادة 4١ من قانون الشراء العام في ما لا يتعارض\nمع طبيعتها او مع نصوصها الخاصة؛ وذلك لكونها تقع تحت البند الثاني من الفصل الثاني؛ أي القواعد العامة\nالتي تتعلّق باجراءات التلزيم»\nأولًّا: يكون التعاقد مع مقدم العرض الوحيد مقبولًا في طرق الشراء كافة عند توافر شروط الفقرة (4) من المادة\n5 من قانون الشراء العام بقدر عدم تعارضها مع اجراءات كل طريقة على حدة.\nثانيًا: في حال الشراء بالفاتورة» تدرج الجهة الشارية قرارها المعلّل بالسير بالعرض الوحيد المقدّم في سجل\nإجراءات الشراء» على أن يتضمن التعليل توجيه طلب العروض إلى أكبر عدد ممكن من العارضين أقلّه اثنتين\nوتجاوب عارض واحد فقط؛ أو عند الاقتضاء أسباب طلب عرض من مورد واحد.\nحك ت فى 9١/5/؟7.”\n5ك رية ابر 1 بيروت في 3/15[\nاح 7 ئيس هيئة الشراء العا\n2 1 /// رئيس هيئة الشراء العام\n<١ 22 / /| ا\n/ و روي ل د. جان ١\nا"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (25,'مذكرات الرئيس','مذكرة رقم 2022/9 : تشكيل اللوائح الموحدة للجان التلزيم والإستلام للعام 2023','2022-10-05','https://www.ppa.gov.lb/ar/pages/details/25','{"https://admin.ppa.gov.lb/storage/listing-pages/files/vpWICyK3Z0A9psseLr0rPheEFIvrfXsj4Q43-1778748131.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/vpWICyK3Z0A9psseLr0rPheEFIvrfXsj4Q43-1778748131.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=25),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "Page 1 of 2\n مذكرة رقم / 9ه.ش.ع 2022 /\n تشكيل اللوائح الموحدة للجان التلزيم واإلستالم للعام 2023\n ان رئيس هيئة الشراء العام،\n بناءًًعلىًقانونًالشراءًالعامًرقمًً٢٤٤تاريخًً،٢٠٢1/٧/1٩الًسيماًالمادتينًً1٠٠وً1٠1منهًً ،\n بناءًعلىًالق اررينًرقمً/1ه.ش.عً٢٠٢٢/تاريخًً،٢٠٢٢/ً8/5ورقمً/٢ه.ش.عًً٢٠٢٢/تاريخًً ،ً٢٠٢٢/ً٩/1٤\n يوضح ما يلي:\n نصتًالمادةًً1٠٠منًقانونًالشراءًالعامًفيًالفقرةًالثانيةًمنهًعلىًماًيليًً :\n ّ\n\" ًقبلًشهرًتشرينًاألولًمنًكلًسنةً،تَقتَرحًالجهةًالشاريةًالئحةًبإسماءًموظفينًمنًإدارتهاًمنًالفئةًالثالثةً\nاءًالعامًو/أوًمنًبينًالمدربينًعليهًأصوالًوفقاًألحكامًهذاً\n ّ ًممن ًلديهمًخبرةًمثبتةًفيًمجالًالشر\n علىًاألقل ّ\n ّ\nالقانونً،ويقومًبارسالًهذهًالالئحةًإلىًهيئةًالشراءًالعامً.بعدئذً،تعمدًهذهًالهيئةً،وقبلًنهايةًشهرًتشرينًالثانيً\nائحًبالئحةًموحدةًترسلهاًإلىًهيئةًالتفتيشًالمركزيًوديوانًالمحاسبةًوالهيئةًالعلياً\n ّ منًالعامًنفسهً،إلىًتوحيدًاللو\nالمقررةً بحقهم ً،فيً حالً\n للتأديبً للتقصيً عنً األسماءً المقترحةً وبيانً المخالفاتً المنسوبةً إليهمً أوً العقوباتً َّ\nفً\n بتصر ً\n ّ المالحقينً والمعاقبينً وتضعً هذهً الالئحةً\n َ وجودها ً.تُنِّّقحً الهيئةً الالئحةً النهائيةً وتشطبً منهاً أسماءً\nاإللكترونيةً لديها ً.الً تكونً الئحةً األسماءً علنيةً\n ّ الجهاتً الشاريةً فيً قاعدةً البياناتً الخاصةً علىً المنصةً\nللعمومً.وفيًحالًتبينتًحاجةًإلىًإدخالًأسماءًجديدةً،تعمدًالجهةًالشاريةًإلىًإبالغًهيئةًالشراءًالعامًبذلكً\n ّ\n آلليةًالمفصلةًفيًهذهًالفقرًةً\"ً .\n ّ ًإضافةًاألسماءًإلىًالالئحةًالموحدةًبحسبًا\n ّ علىًأنًيتم\n ّ\n كماًنصتًالمادةًً1٠1فيًفقرتهاًاالولىًعلىًماًيليًً :\n ّ\n\" ًقبلًشهرًتشرينًاألولًمنًكلًسنةً،تَقتَرحًالجهةًالشاريةًالئحةًبإسماءًموظفينًمنًإدارتهاًمنًالفئةًالثالثةً"}, {"o": 1, "l": null, "b": "علىًاالقلًمنًبينًالمدربينًأصوالًوفقاًألحكامًهذاًالقانونً،وتقومًبارسالًهذهًالالئحةًإلىًهيئةًالشراءًالعامً.\n ّ\nائحًبالئحةًموحدةًترسلهاًإلىًهيئةً\n ّ تعمدًهذهًالهيئةً،وقبلًنهايةًشهرًتشرينًالثانيًمنًالعامًنفسهً،إلىًتوحيدًاللو\nالتفتيشًالمركزيًوديوانًالمحاسبةًوالهيئةًالعلياًللتأديبًللتقصيًعنًاألسماءًالمقترحةًوبيانًالمخالفاتًالمنسوبةً\nإليهمًأوًالعقوباتًالمقررةًبحقهمً،فيًحالًوجودهاً.تنِّّقحًالهيئةًالالئحةًالنهائيةًوتشطبًمنهاًأسماءًالمالحقينً\n ّ\n\f Page 2 of 2\nيةًفيًقاعدةًالبياناتًالخاصةًعلىًالمنصةًاإللكترونيةًلديهاً.الًتكونً\n ّ المعاقبينًوتضعهاًبتصرفًالجهاتًالشار\n ّ و\nالئحةًاألسماءًعلنيةًللعمومً.وفيًحالًتبينتًحاجةًإلىًادخالًأسماءًجديدةً،تعمدًالجهةًالشاريةًإلىًإبالغً\n ّ\nدةًبحسبًاآلليةًالمفصلةًفيًهذهًالفقرةً\"ً ً،\n ّ ًإضافةًاإلسماءًإلىًالالئحةًالموح\n ّ ًّ\n اءًالعامًبذلكًعلىًأنًيتم\n هيئةًالشر\n لــــــــــــــذلك،\n ُيطلب الى كافة الجهات الشارية وألجل تكوين اللوائح الموحدة المشار إليها في الماد َتين 100و 101من\n قانون الشراء العام ،ما يلي:\nن ًالمقترحينًللجانًالتلزيمً واإلستالم ًالنهائيةً،\n أول :ايداعًهيئةًالشراءًالعاًم ًفيًأقربًوقتًممكنً ،أسماء ًالموظفي ً\n ً\n كلًعلىًحدة.\n ٌ\nثانيا :تُرسلً الجهاتً الشاريةً ًاألسماءً المشارً اليهاً ً،علىً البريدً اإللكترونيً لهيئةً الشراءً\n ً\n العام ًcontact@ppa.gov.lbوفقاًللنموذجًالمنشورًعلىًالموقعًاإللكترونيًللهيئةًبصيغةً(ً)Excelفقطً.\nً،بحيثًيصبحًتشكيلًلجانًالتلزيمًواإلستالمًمنًخارجًهذهً\n ُ ثال ًثاُ :يعملًبهذهًاللوائحًابتداءًمنًتاريخً٢٠٢3/ً1/٢\n اللوائحًمخالفاًللقانونً.\n ً\n ً\n ً\n ًًًًًبيروت فــي 2022/10/5\n رئيس هيئة الشراء العام\n د .جان العّلية"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (26,'مذكرات الرئيس','مذكرة رقم 2022/10 : التعاقد مع مقدّم العرض الوحيد المقبول','2022-10-24','https://www.ppa.gov.lb/ar/pages/details/26','{"https://admin.ppa.gov.lb/storage/listing-pages/files/4aCyW8Q9sNKEmGKIM3r5jZecUqvkvXNoD4wv-1760222242.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/4aCyW8Q9sNKEmGKIM3r5jZecUqvkvXNoD4wv-1760222242.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=26),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "مذكرة رقم /10ه.ش.ع2022 /\n موجهة إلى كافة الجهات الخاضعة ألحكام قانون الشراء العام\n مقدم العرض الوحيد المقبول\n بخصوص التعاقد مع ّ\n إن رئيس هيئة الشراء العام،\n بناء على قانون الشراء العام رقم 2021/244تاريخ ،2021/7/19ال سيما المادتَين 13و 25منه،\n ً\n يوضح ما يلي:\nوبما أن الفقرة ( )4من المادة 25من قانون الشراء العام ،قد أجازت للجهة الشارية اتخاذ قرار معلل بالتعاقد\n مع مقدم العرض الوحيد المقبول إذا توافرت الشروط التالية مجتمعة:\n -1أن تكون مبادىء وأحكام هذا القانون ُمطبَّقة وأن ال يكون العرض الوحيد ناتجاً عن شروط حصرية\n ضم َنها دفتر الشروط الخاص بمشروع الشراء؛\n تَ َّ\n نس ِجماً مع دراسة القيمة التقديرية؛ -2أن تكون الحاجة أساسية ِ\n ومل ّحة والسعر ُم َ\n ُ\n نصاً صريحاً ِب ُّ\nتقدم العارض يتضمن َنشر قرار الجهة الشارية بقبول العرض الفائز (التلزيم المؤقت) ّ\n َّ -3أن\n ونية التعاُقد معه.\n الوحيد المقبول ّ\nطالع على المستندات اإلدارية والفنية لمعرفة مدى انطباقها على أحكام\n وبما أنه يقتضي على لجنة التلزيم اإل ّ\nسندا للمادة 100من قانون الشراء\n دفتر الشروط الخاص بالصفقة ،وتقرير ما إذا كان العرض مقبوًال أم الً ،\n العام،\nسندا لما ورد في الفقرة ( )4أعاله ،توضع وفًقا ألحكام المادة 13\n وبما أنه يقتضي وجود دراسة تقديرية للصفقة ً\n من قانون الشراء العام،\n لـــــــــــــذلك،\nيمكن للجنة التلزيم المش ّكلة لدى الجهة الشارية ،فتح العرض الوحيد لمعرفة مدى انطباقه على أحكام دفتر\nالشروط الخاص بالصفقة ،وتقرير ما إذا كان العرض مقبواًل أم ًل ،شرط أن يقترن هذا األمر بدراسة تقديرية\n وفقا لألصول.\n للصفقة اعدتها الجهة الشارية قبل اإلعالن عن الصفقة ا\nبيروت في 2022/10/24\n رئيس هيئة الشراء العام\n د.جان العلية"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (27,'مذكرات الرئيس','مذكرة رقم 11 : الإلتزام بتطبيق أحكام قانون الشراء العام وإيداع هيئة الشراء العام المعلومات المتعلقة بالصفقات التي تجريها','2022-10-24','https://www.ppa.gov.lb/ar/pages/details/27','{"https://admin.ppa.gov.lb/storage/listing-pages/files/vP3YqFEblc5yvWKW3r6mUdDPxrOlFnaDbzHs-1761805298.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/vP3YqFEblc5yvWKW3r6mUdDPxrOlFnaDbzHs-1761805298.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=27),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "مذكرة رقم / 11ه.ش.ع2022 /\n موجهة إلى كافة الجهات الشارية من أجل اإللتزام بتطبيق أحكام قانون الشراء العام\n وإيداع هيئة الشراء العام المعلومات المتعلقة بالصفقات التي تجريها\n إن رئيس هيئة الشراء العام،\n بناء على قانون الشراء العام 2021/244تاريخ 2021/7/19ال سيما المادة 76و( 112العقوبات) منه،\n ً\n يوضح ما يلي:\n بناء على مذكرة هيئة الشراء العام رقم /1ه.ش.ع 2022/تاريخ .2022/8/10\n ً\nوبما أنه تبين عدم إلتزام بعض الجهات الشارية بأحكام قانون الشراء العام وعدم ايداع هيئة الشراء العام\n المعلومات المتعلقة بالصفقات التي تجريها ،ما يشكل مخالفة واضحة لقانون الشراء العام،\n لـــــــــــــــــــــــذلك،\n يطلب إلى كافة الجهات المعنية بتطبيق أحكام قانون الشراء العام ما يلي:\nالتقيد بأحكام المذكرة رقم /1ه.ش.ع 2022/الصادرة عن رئيس هيئة الشراء العام بتاريخ\n أواًل :وجوب ّ\n 2022/8/10لناحية ايداع هيئة الشراء العام كافة المعلومات المتعلقة بالصفقات التي تجريها ،وكل ما ُينشر\nعلى الموقع اإللكتروني لهيئة الشراء العام www.ppa.gov.lbمن ق اررات ومذكرات وتوصيات من أجل حسن\nسير العمل ،تحت طائلة إتخاذ اإلجراءات القانونية المناسبة تطبيًقا ألحكام قانون الشراء العام ،والسيما المادة\n 112منه ،باإلضافة إلى اعتبار كل ما يتم نشره على الموقع اإللكتروني لهيئة الشراء العام بمثابة تبليغ رسمي\n وإلزامي لكافة الجهات المعنية بتطبيق أحكام قانون الشراء العام.\nثانيا :إيداع هيئة الشراء العام نتائج الصفقات ومسار العقود عند اإلقتضاء ،والتي تم اإلعالن عنها على المنصة\n ا\n اإللكترونية المركزية لدى هيئة الشراء العام.\nبيروت في 2022/10/24\n رئيس هيئة الشراء العام\n د.جان العلية"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (28,'مذكرات الرئيس','مذكرة رقم 2022/12 : التواصل مع هيئة الشراء العام على بريدها الإلكتروني','2022-11-04','https://www.ppa.gov.lb/ar/pages/details/28','{"https://admin.ppa.gov.lb/storage/listing-pages/files/o4MWvkxBBn25FBLvWuJmixmrxJFYoxEJGk9p-1761804816.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/o4MWvkxBBn25FBLvWuJmixmrxJFYoxEJGk9p-1761804816.pdf"}','ocr') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=28),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "7 الجمهوريّة اللبنانيتة\nد هيئة الشراء العام\n89 شفافية ه منافسة ه نزاهصة\nمذكرة رقم 12/ه.ش.ع/ 2022\nموجهة إلى كافة الجهات الخاضعة لأحكام قانون الشراء العام\nبخصوص التواصل مع هيئة الشراء العام على بربدها الإلكتروني\nإن رئيس هيئة الشراء العام»\nبناء على قانون الشراء العام رقم 2021/244 تاريخ 2021/7/19.\nيوضح ما يلي:\nمن أجل حسن سير العمل والتواصل السليم والسريع بين هيئة الشراء العام وكافة الجهات الخاضعة لأحكام\nقانون الشراء العام» يرجى التواصل مع هيئة الشراء العام على بريدها الإلكتروني (ط!.60136]©802.9017)\nبشكل واضح ولا سيما لناحية:\nأُولّا: عنوان الرسالة الإلكترونية (964[طانا5) على الشكل التالي:\n1- بالنسبة للجهات الشارية أو المتعاقدة» يرجى كتابة عنوان الرسالة الإلكترونية كالتالي:\n[اسم الجهة الشارية أو المتعاقدة]-[موضوع الرسالة]-[مرجع الموضوع]-[تفصيل موجز].\nعلى سبيل المثال وليس الحصر:\n٠ إبلدية عجلتون]-[أسماء الموظفين المقترحين للجان التلزيم]-[كتاب/قرار رقم 32/ع/2022].\n« إوزارة الصحة]-[إعلان عن مناقصة تلزيم أدوية]-[رقم 56/ص/2022]-[تخفيض مدة الإعلان].\n© [هيئة إدارة قطاع البترول]-[استفسار حول قانون الشراء العام].\n[مصلحة مياه بيروت وجبل لبنان]- [طلب بيان رأي حول دفتر شروط]-[شراء مضخات].\n2- بالنسبة للجهات الأخرى» يرجى كتابة عنوان الرسالة الإلكترونية كالتالي:\n[اسم الجهة/الشركة/المؤسسة/الجمعية/المنظمة/الشخص/ الخ.]-[الموضوع].\nثانيًا : المرفقات (5أداع816]2©1610) :\nيجب تسمية وترقيم جميع المرفقات بما يتلاءم مع موضوع الرسالة. على سبيل المثال وليس الحصر:\n« 005.إوزارة الصحة]-[إعلان عن مناقصة تلزيم أدوية]-[رقم 56_,ص_2022]\n٠ «006.[مصلحة مياه بيروت وجبل لبنان]-[دفتر شروط_رقم_221]-[شراء مضخات].\n9 بيروت في 2022/11/4\n0 رئيس هيئة الشراء العام\nا للب"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (29,'مذكرات الرئيس','مذكرة رقم 2022/13 : إعداد خطة الشراء السنوية الموحدة عن العام 2022','2022-11-04','https://www.ppa.gov.lb/ar/pages/details/29','{"https://admin.ppa.gov.lb/storage/listing-pages/files/WiaLCnk3BuzSYWdeb7C0nsvsG0qcvH4Kjrnn-1762850797.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/WiaLCnk3BuzSYWdeb7C0nsvsG0qcvH4Kjrnn-1762850797.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=29),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "مذكرة رقم / 13ه.ش.ع2022 /\n موجهة الى كافة الجهات الخاضعة ألحكام قانون الشراء العام من أجل\n إعداد خطة الشراء السنوية الموحدة عن العام 2022\n إن رئيس هيئة الشراء العام،\nبناء على قانون الشراء العام 2021/244تاريخ 2021/7/19ال سيما المادة 11منه (وضع خطط الشراء)،\n ً\n والمادة ( 76مهام هيئة الشراء العام)،\n يوضح ما يلي:\n نصت الفقرة الثالثة من المادة 11من قانون الشراء العام على ما يلي:\n ّ\n \" تُ ِ\nرسل الجهة الشارية خطتها المكتملة إلى هيئة الشراء العام في مهلة عشرة أيام عمل من تاريخ إقرار الموازنة.\n موحدة ونشرها خالل //10//عشرة أيام عمل \"،\n عمد هيئة الشراء العام إلى توحيد الخطط في خطة شراء سنوية َّ\n تَ َ\n كما نصت الفقرة الثالثة من المدة 76على ما يلي:\nوحد َيصدر عن هيئة الشراء العام وتبويبها\n \" جمع خطط الشراء السنوية الواردة من الجهات الشارية وفق نموذج ُم َّ\nاإللكترونية المركزّية المعتمدة بحسب المادة 11من هذا القانون؛ على أن\n ّ ونشرها وفق األصول على المنصة\n ُّ\nبالتحضر المعنية بشكل يسمح للسوق\n ّ مفصلة عن األنواع والكميات وطرق التعاقد والقطاعات\n تتضمن معلومات َّ\n َّ\n للمنافسة \"،\nوبما أنه بتاريخ 2022/11/15تم نشر الموازنة العامة للعام 2022في الجريدة الرسمية (العدد 49تاريخ\n )2022/11/15وفًقا لألصول،\n لـــــــــذلك،\nيطلب إلى كافة الجهات الخاضعة ألحكام قانون الشراء العام وألجل إعداد خطة الشراء السنوية الموحدة ما يلي:\n أولا :إعداد خطة الشراء عن العام 2022مكتملة وإيداعها هيئة الشراء العام ضمن المهلة القانونية.\nثانيا :ترسل الجهات المعنية الخطة المشار إليها على البريد اإللكتروني لهيئة الشراء العام ا\n( )contact@ppa.gov.lbوفًقا للنموذج المنشور على الموقع اإللكتروني للهيئة بصيغة ( )Excelعلى الشكل\n التالي:\nصفحة 2/1"}, {"o": 1, "l": null, "b": "موضوع الرسالة ([ :)Subjectاسم الجهة الشارية أو المتعاقدة][-خطة_الشراء][-العام][-األساسية]. •\n • يتم إعادة تسمية الملف وفًقا لما يلي[ :اسم الجهة الشارية أو المتعاقدة][-خطة_الشراء][-العام][-األساسية].\n • على سبيل المثال[ :وزارة المالية]–[خطة_الشراء]–[[–]2022األساسية]\nسيما\n أي تعديل على الخطة ،ال ّ ثال اثا :ورد في الفقرة الرابعة من المادة 11المشار إليها أعاله ،أنه عند إدخال ّ\nالحصول على قروض أو هبات ،يجب على الجهة المعنية نشر هذا التعديل على موقعها االلكتروني إن ُو ِجد ،وعلى\nاإللكترونية المركزّية لدى هيئة الشراء العام ،مع احترام مهل اإلعالن المنصوص عنها في المادة .12لذلك،\n ّ المنصة\n (ثانيا) أعاله من هذه المذكرة ،عند التعديل وفًقا لما يلي:\n يجب اإللتزام بما جاء في الفقرة ً\n موضوع الرسالة ([ :)Subjectاسم الجهة الشارية أو المتعاقدة][-خطة_الشراء][-العام][-معدلة]. •\n • يتم إعادة تسمية الملف وفًقا لما يلي[ :اسم الجهة الشارية أو المتعاقدة][-خطة_الشراء][-العام][-معدلة].\n ابعا :أثناء إعداد الخطة يجب على الجهات المعنية التقيد بما يلي:\n را\n • اإللتزام بأحكام قانون الشراء العام رقم .2021/244\n • يراعى التسلسل في استيفاء االحتياجات والتقيد بالقواعد والتعليمات ذات الصلة.\n• يجب على الجهات المعنية الرجوع إلى مخازنها للتأكد من أن االحتياجات المطلوبة غير متوفرة أو متوفرة\n بكميات غير كافية.\n• يجب ملء البيانات الواردة في هذا النموذج ،وفًقا ألحكام قانون الشراء العام ،2021/244وارساله إلى هيئة\n الشراء العام بنسخته اإللكترونية على البريد اإللكتروني (.)contact@ppa.gov.lb\nالمحدثة في كل مرة تريد\n ّ خامسا :بإنتظار أتمتت عملية إعداد خطة الشراء السنوية يجب تحميل النموذج بنسخته\n ا\nظر للتحديثات التي قد تط أر على هذا النموذج وعلى الطريقة\n الجهة الشارية وضع خططها السنوية أو تعديلها ،ن ًا"}, {"o": 2, "l": null, "b": "واآللية اإللكترونية التي سيتم بواسطتها تزويد هيئة الشراء العام بنسخة عن هذه الخطة.\nساد اسا :لحسن سير العمل ،يجب متابعة الموقع اإللكتروني لهيئة الشراء العام لمعرفة كل جديد يتعلق بإعداد خطة\n اما بقانون الشراء العام.\n التنظيمية إلتز ً\n ّ الشراء السنوية وغيرها من األمور\nسابعا :إن كل ما يتم نشره على الموقع اإللكتروني لهيئة الشراء العام يعتبر بمثابة تبليغ رسمي وإلزامي لكافة الجهات\n ا\n المعنية بتطبيق قانون الشراء العام.\n ثامانا :إيداع نسخة عن الخطة وتعديالتها في سجل اجراءات الشراء لدى الجهة الشارية.\n بيروت في 2022/11/16\n رئيس هيئة الشراء العام\n د .جان العلية\nصفحة 2/2"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (30,'نماذج','نموذج (اسم الجهة الشارية أو المتعاقدة)-(تسجيل)-(المنصة الإلكترونية)','2022-12-02','https://www.ppa.gov.lb/ar/pages/details/30','{"https://admin.ppa.gov.lb/storage/listing-pages/files/NestZ1K3Iwg7goFk1jNUOJfjxYLGwQogoCF2-1750162901.xlsx","https://admin.ppa.gov.lb/storage/listing-pages/files/NestZ1K3Iwg7goFk1jNUOJfjxYLGwQogoCF2-1750162901.xlsx"}',null) on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (31,'مذكرات الرئيس','مذكرة رقم 2022/14 : التسجيل على المنصة الإلكترونية المركزية لدى هيئة الشراء العام','2022-12-02','https://www.ppa.gov.lb/ar/pages/details/31','{"https://admin.ppa.gov.lb/storage/listing-pages/files/6QKcCjZCBLWph6MDBxDbLJldDabTC0t94A74-1760213910.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/1792132682-نموذج التسجيل على المنصة.xlsx","https://admin.ppa.gov.lb/storage/listing-pages/files/6QKcCjZCBLWph6MDBxDbLJldDabTC0t94A74-1760213910.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/1792132682-نموذج التسجيل على المنصة.xlsx"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=31),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "مذكرة رقم /14ه.ش.ع2022/\n موجهة إلى كافة الجهات الشارية أو المتعاقدة الخاضعة ألحكام قانون الشراء العام\n بخصوص التسجيل على المنصة اإللكترونية المركزية لدى هيئة الشراء العام\n إن رئيس هيئة الشراء العام،\n بناء على قانون الشراء العام رقم 2021/244تاريخ .2021/7/19\n ً\n يوضح ما يلي:\nنصت المادة ( 102سلطات التعاقد) من قانون الشراء العام على بعض مهام سلطات التعاقد ومن بينها اإلعالن\nتباعاً عن مشترياتها وفق األصول وبحسب المادة ( 12اإلعالن عن الشراء) من هذا القانون وعلى المنصة\n اإللكترونية المركزّية لدى هيئة الشراء العام.\n ّ\n لـــــــــذلك،\nُيطلب إلى كافة الجهات الشارية أو المتعاقدة الخاضعة ألحكام قانون الشراء العام ومن أجل التحضير لتمكينها\n المركزية لدى هيئة الشراء العام ،ما يلي:\n ّ اإللكترونية\n ّ من اإلعالن على المنصة\n تزويد هيئة الشراء العام بالمعلومات الخاصة باألشخاص المكلفين نشر اإلعالنات على المنصة أولا:\n اإللكترونية المركزّية لدى هيئة الشراء العام وفًقا للنموذج المنشور على الموقع اإللكتروني للهيئة\n ّ\n بصيغة ( ،)Excelباإلضافة إلى نسخة موقعة وفًقا للصول من قبل المرجع المختص.\n ترسل هذه المعلومات على البريد اإللكتروني ( ،)register@ppa.gov.lbعلى أن يتضمن ثانيا:\n ا\n موضوع الرسالة ( )Subjectوأسماء الملفين المرفقين ( )Attachmentsالمعلومات التالية:\n [اسم الجهة الشارية أو المتعاقدة][-تسجيل][-المنصة اإللكترونية].\n حصرا.\n ً إن صحة المعلومات التي يتم نشرها بواسطة الجهة الشارية المعنية ،هي على مسؤوليتها ثال اثا:\n إن أي سوء استخدام لحساب الشخص المعني بنشر اإلعالنات ،تتحمل مسؤوليته الجهة الشارية ابعا:\n را\n حصرا.\n ً المعنية\n اإللكترونية المركزّية لدى هيئة الشراء العام لتمكين\n ّ خامسا :يعلن في وقت الحق عن جهوزّية المنصة\n ا\n الجهات الشارية من البدء بعملية اإلعالن عن مشترياتها على هذه المنصة."}, {"o": 1, "l": null, "b": "بيروت في 2022/12/02\n رئيس هيئة الشراء العام\n د .جان العّلية"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (32,'مذكرات الرئيس','مذكرة رقم 2022/15 : تضمين دفاتر الشروط ما ينص على انطباق أحكام قانون مقاطعة العدو الإسرائيلي على الشركات الأجنبية','2022-12-07','https://www.ppa.gov.lb/ar/pages/details/32','{"https://admin.ppa.gov.lb/storage/listing-pages/files/Sl1j1covmZYHYD46aVNcbXeHaHhiL2N7ZqIq-1760222017.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/Sl1j1covmZYHYD46aVNcbXeHaHhiL2N7ZqIq-1760222017.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=32),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "مذكرة رقم /15ه.ش.ع2022/\n موجهة إلى كافة الجهات الشارية أو المتعاقدة الخاضعة ألحكام قانون الشراء العام\nبخصوص تضمين دفاتر الشروط ما ينص على انطباق أحكام قانون مقاطعة العدو اإلسرائيلي\n على الشركات األجنبية\n إن رئيس هيئة الشراء العام،\n بناء على قانون الشراء العام رقم 2021/244تاريخ ،2021/7/19\n ً\n بناء على القانون الصادر في 23حزيران ( 1955مقاطعة اسرائيل)،\nبناء على المرسوم رقم 12562الصادر في 19نيسان ( 1963تنظيم مكتب مقاطعة\n ً\n اسرائيل)،\n يوضح ما يلي:\nُيطلب إلى كافة الجهات الشارية أو المتعاقدة الخاضعة ألحكام قانون الشراء العام ،تضمين\nبندا بوجوب استحصال الشركات األجنبية التي ترغب باإلشتراك في\n دفاتر الشروط الخاصة ً\nالصفقات العمومية ،أو إبرام عقود بموجب إتفاقات رضائية ،على إفادة من وزارة اإلقتصاد\nوالتجارة اللبنانية (مكتب مقاطعة إسرائيل) ،تُثبت أن الشركة األجنبية تنطبق عليها أحكام\n قانون مقاطعة العدو االسرائيلي ،وانه ال مانع من التعاقد معها لهذه الناحية.\n بيروت في 2022/12/7\n رئيس هيئة الشراء العام\n د .جان العلية"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (33,'مذكرات الرئيس','مذكرة رقم 2022/16 : تذكير بايداع هيئة الشراء العام اسماء اعضاء لجان التلزيم والاستلام عن العام ٢٠٢٣','2022-12-13','https://www.ppa.gov.lb/ar/pages/details/33','{"https://admin.ppa.gov.lb/storage/listing-pages/files/EEOFBFglwhWndPv2uCZR23AhZaqSMWCaLf54-1761804238.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/EEOFBFglwhWndPv2uCZR23AhZaqSMWCaLf54-1761804238.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=33),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "مذكرة رقم /16ه.ش.ع2022/\n موجهة إلى كافة الجهات الخاضعة ألحكام قانون الشراء العام\n بخصوص تشكيل اللوائح الموحدة للجان التلزيم واإلستالم عن العام 2023\n إن رئيس هيئة الشراء العام،\n بناء على قانون الشراء العام رقم 2021/244تاريخ 2021/7/19ال سيما المادتين 100و 101منه،\n ً\n بناء على المذكرة رقم /9ه.ش.ع 2022/الصادرة عن رئيس هيئة الشراء العام بتاريخ ،2022/10/5\n ً\n يوضح ما يلي:\nتذكر هيئة الشراء العام كافة الجهات الخاضعة ألحكام قانون الشراء العام بضرورة إيداعها أسماء أعضاء\nلجان التلزيم واإلستالم عن العام 2023عبر البريد اإللكتروني contact@ppa.gov.lbوفق نموذج Excel\nعمال بالمذكرة رقم /9ه.ش.ع 2022/تاريخ\n ً الصادر عنها والمنشور على موقعها اإللكتروني،\n ،2022/10/5وذلك في أقرب وقت ممكن ،للتمكن من إعداد اللوائح الموحدة عن العام 2023وفًقا لألصول\nوإيداعها الجهات الشارية قبل نهاية العام ،2022وان اي معلومات تصل بغير النموذج المذكور ال يعتد بها.\n بيروت في 2022/12/13\n رئيس هيئة الشراء العام\n د .جان العلية"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (34,'مذكرات الرئيس','مذكرة رقم 2022/17 : بخصوص الإطلاع والحصول على اللوائح الموحدة للجان التلزيم والإستلام عن العام 2023','2022-12-30','https://www.ppa.gov.lb/ar/pages/details/34','{"https://admin.ppa.gov.lb/storage/listing-pages/files/sQdLcGc722CX5gGNLXYiLLJeYL8VE1VAAxok-1761803617.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/sQdLcGc722CX5gGNLXYiLLJeYL8VE1VAAxok-1761803617.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=34),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "مذكرة رقم /17ه.ش.ع2022/\n موجهة الى كافة الجهات الخاضعة لأحكام قانون الشراء العام\n بخصوص الإطلاع والحصول على اللوائح الموحدة للجان التلزيم والإستلام عن العام 2023\n إن رئيس هيئة الشراء العام،\n بنا ًء على قانون الشراء العام سيما المواد ١٠٠ ،٨٨و ١٠١منه،\nبنا ًء على مذكرتي رئيس هيئة الشراء العام رقم /١٦ه.ش.ع ٢٠٢٢/تاريخ ،٢٠٢٢/١٢/١٣ورقم\n /١٤ه.ش.ع ٢٠٢٢/تاريخ ،٢٠٢٢/١٢/٥\n يوضح ما يلي:\nوعملا بموجباتها القانونية ستضع اللوائح الموحدة المتعلقة بأعضاء لجان التلزيم والإستلام ً ان هيئة الشراء العام\nوتوفرها بشكل إلكتروني للجهات الشارية التي سبق وارسلت المعلومات المتعلقة بالأشخاص المكلفين من أجل\nالتسجيل على المنصة الإلكترونية المركزية لدى هيئة الشراء العام وفقًا للمذكرة رقم /١٤ه.ش.ع ٢٠٢٢/تاريخ\n ،٢٠٢٢/١٢/٥ابتدا ًء من تاريخ ،2023/1/3وبنا ًء عليه:\n -1يتم التواصل مع هيئة الشراء العام على البريد الإلكتروني register@ppa.gov.lbمن قبل الأشخاص\n المكلفين من أجل الحصول على هذه اللوائح او الاطلاع عليها )بعد ورودها من الهيئات الرقابية المعنية(.\n عا وبشكل مستمر ،عند الاقتضاء. -2تحدث هذه اللوائح تبا ً\n -3ان اللوائح الموحدة غير متاحة للعموم ،وتاليًا يقع على عاتق الجهات الشارية مسؤولية الحفاظ على المعلومات\n الواردة ضمنها ،وعدم اتاحتها للعموم.\nتذكر هيئة الشراء العام كافة الجهات الخاضعة لأحكام قانون الشراء العام ،من أجل تشكيل لجان التلزيم والاستلام،\nبضرورة التقيد بأحكام المادتين ١٠٠و ١٠١من قانون الشراء العام المعدلة بموجب المادة ١١٩من قانون الموازنة\nالعامة للعام ،٢٠٢٢لناحية إيداع هيئة الشراء العام اللوائح المطلوبة وضمن المهل القانونية .كما التقيد بالمذكرات\n الصادرة عن هيئة الشراء العام ذات الصلة ،لناحية:\n -1إرسال أسماء أعضاء لجان التلزيم والإستلام بأسرع وقت ممكن بصيغة الكترونية Excelبحسب النموذج"}, {"o": 1, "l": null, "b": "المتاح على الموقع الإلكتروني للهيئة ،على البريد الإلكتروني contact@ppa.gov.lbوفقًا للمذكرة رقم\n /١٦ه.ش.ع ٢٠٢٢/تاريخ .٢٠٢٢/١٢/١٣\n -2إرسال المعلومات المتعلقة بالأشخاص المكلفين بالتسجيل على المنصة الإلكترونية المركزية لدى هيئة الشراء\nالعام بحسب النموذج المتاح على الموقع الإلكتروني للهيئة ،على البريد الإلكتروني register@ppa.gov.lb\n وفقًا للمذكرة رقم /١٤ه.ش.ع ٢٠٢٢/تاريخ .٢٠٢٢/١٢/٥\nان عدم التزام الجهات الشارية بموجباتها ،المشار إليها في هذه المذكرة يرتب عليها المسؤولية لناحية عدم تمكنها\n من تشكيل لجان التلزيم والاستلام للعام .٢٠٢٣\n بيروت في 2022/12/30\n رئيس هيئة الشراء العام\n د .جان العلية"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (35,'مذكرات الرئيس','مذكرة رقم 2022/1 : بخصوص تطبيق أحكام المذكرة رقم 17/ه.ش.ع/2022 تاريخ 30/12/2022 بما يتّفق مع أحكام قانون الشراء العام قبل التعديل','2023-01-12','https://www.ppa.gov.lb/ar/pages/details/35','{"https://admin.ppa.gov.lb/storage/listing-pages/files/2024-11-09-1731177693-memo_20230112_1.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/2024-11-09-1731177693-memo_20230112_1.pdf"}',null) on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (36,'مذكرات الرئيس','مذكرة رقم 2023/2 : آلية نشر النتائج والعقود لكافة عمليات الشراء التي تجريها','2023-02-16','https://www.ppa.gov.lb/ar/pages/details/36','{"https://admin.ppa.gov.lb/storage/listing-pages/files/o7ZulpwupSmVBOejUPXyJ5EEZ4Dud009lTpM-1773683342.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/o7ZulpwupSmVBOejUPXyJ5EEZ4Dud009lTpM-1773683342.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=36),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "مذكرة رقم / 2هـ.ش.ع2023 /\n موجهة الى كافة الجهات الخاضعة ألحكام قانون الشراء العام\n حول آلية نشر النتائج والعقود لكافة عمليات الشراء التي تجريها\n إن رئيس هيئة الشراء العام،\nبنا ًء على قانون الشراء العام 2021/244تاريخ 2021/7/19ال سيما المادة األولى والمادة الثانية\n (الفقرة ،)35والمواد 84 ،76 ،62 ،46 ،24و 109منه،\n يوضح ما يلي:\nنصّت الفقرة الرابعة من المادة األولى من قانون الشراء العام على أن أحد مبادئ هذا القانون هو علنية\n اإلجراءات ونزاهتها ومهنيتها بشكل يفعّل الرقابة والمحاسبة،\nصت الفقرة 35من المادة الثانية من هذا القانون على أن يت ّم النشر إلزاميًا على المنصة كما ن ّ\nاإللكترونيّة المركزيّة لدى هيئة الشراء العام ،وعلى الموقع االلكتروني للجهة الشارية إن ُوجد .كما\nي وسيلة أخرى تراها الجهة الشارية منا ِسبة ،على أنيجوز ،باإلضافة إلى ذلك ،أن يت ّم النشر عبر أ ّ\n يُعت ّد بتاريخ النشر على المنصة اإللكترونيّة في كافّة المهل المنصوص عليها في هذا القانون،\nصت المادة 109على أن تَنتهج سلطات التعاقد سياسة نشر إلزامية تعلن بموجبها عن خططها كما ن ّ\nللشراء وتفاصيل تطبيقها بما في ذلك سير عمليات الشراء وإجراءات تلزيمها وعقدها ونتيجة\nاستالمها وتنفيذها وقيمتها النهائية ،وذلك وفق أحكام هذا القانون ومراسيمه التطبيقيّة .ويكون النشر\nإلزاميا ً على المنصة اإللكترونيّة المركزيّة لدى هيئة الشراء العام ،وعلى الموقع اإللكتروني الخاص\nبالجهة الشارية إن ُوجد .وال يَحد من النشر إ ّال ما كان س ّريا ً بطبيعته تطبيقا ً للمادة 6من قانون الشراء\n العام،\nصت الفقرة الرابعة من المادة 76على أن من مهام هيئة الشراء العام نَشر كافة اإلعالنات كما ن ّ\nواإلشعارات المتعلِّقة بالمشتريات وبإجراءات التأهيل والتلزيم وفق األصول على المنصة اإللكترونيّة"}, {"o": 1, "l": null, "b": "المركزيّة المعتمدة وإلزام الجهات الشارية بذلك؛ ونصت الفقرة 8منها على قيامها بإصدار إرشادات\nوتوضيحات حول النصوص القانونية النافذة المتعلقة بالشراء العام ،بما في ذلك إصدار األدلّة\n والقواعد اإلرشادية؛\nصت الفقرة األولى من المادة 84من قانون الشراء العام على أن تَضع الهيئة بمتناول الجمهور كما ن ّ\nبالوسائل الرقمية و/أو الورقية المتاحة جميع المعطيات والمستندات والسجالت والبيانات مع مراعاة\nالسرية بالنسبة للعقود العامة المتعلقة باألمن والدفاع الوطني ومراعاة أحكام المادة السادسة من هذا\n القانون،\n\f بنا ًء لما تقدّم،\nيُطلب إلى كافة الجهات الخاضعة ألحكام قانون الشراء العام ،وألجل االلتزام بعلنية المعطيات\n وموجب النشر ،التقيّد بما يلي:\n أوالً :عند إبرام عقود االتفاق بالتراضي:\n -1فيما خص إجراءات التعاقد بالتراضي المنصوص عليها في الفقرات األولى والثالثة والخامسة\n من المادة ٤٦من قانون الشراء العام ،يتم النشر على مرحلتين ،وفقًا لما يلي:\nالمرحلة األولى :تبلِّغ الجهة الشارية هيئة الشراء العام نيّتها بإجراء عقد بالتراضي وتَنشر إشعاراً\n بالشراء بطريقة االتفاق الرضائي على الـمنصة اإللكترونيّة الـمركزيّة لدى هيئة الشراء العام\n وعلى موقعها االلكتروني إن ُوجد ،قبل /10/عشرة أيام على األقل من تاريخ إبرام العقد ،وذلك\n وفق النموذج الصادر عن هيئة الشراء العام والمتاح على موقعها اإللكتروني.\n المرحلة الثانية :بعد انقضاء فترة العشرة أيام المنصوص عليها أعاله وعند توقيع العقد ،تنشر\n الجهة الشارية هذا العقد ،كما تم التوقيع عليه ،على المنصة االلكترونية المركزية لدى هيئة\n الشراء العام وعلى الموقع االلكتروني للجهة الشارية إن ُوجد.\n -2فيما خص إجراءات التعاقد بالتراضي المنصوص عليها في الفقرة الثانية من المادة :٤٦\n يتم نشر العقد الناتج عن عقد اإلتفاق بالتراضي على المنصة االلكترونية المركزية لدى هيئة"}, {"o": 2, "l": null, "b": "الشراء العام وعلى الموقع االلكتروني للجهة الشارية إن ُوجد ،وذلك عند زوال حالة الطوارئ\n واإلغاثة.\nثانيًا :فيما خص العقود الناشئة عن مناقصة/مزايدة عمومية ،طلب عروض األسعار ،اتفاق اطاري،\n مناقصة على مرحلتين أو طلب االقتراحات للخدمات االستشارية:\n -1بعد التأ ُّكد من العرض الفائز سندًا ألحكام المادة 24من قانون الشراء العام ،تُبلغ الجهة الشارية\nالعارض الذي ق َّدم ذلك العرض ،كما تنشر بالتزامن قرارها بشأن قبول العرض الفائز (التلزيم\nالـمؤقت) على المنصة اإللكترونية المركزية لدى هيئة الشراء العام وعلى موقعها اإللكتروني ان\nوجد ،وذلك وفقًا للنموذج الصادر عن هيئة الشراء العام والمتاح على موقعها اإللكتروني ،على\n أن تبدأ فترة التجميد البالغة عشرة أيام عمل ،من تاريخ هذا النشر.\n -2عند انتهاء فترة التجميد المنصوص عليها في الفقرة ( )1أعاله وتوقيع العقد ،تقوم الجهة الشارية\nبنشر العقد ،كما تم التوقيع عليه ،على المنصة االلكترونية المركزية لدى هيئة الشراء العام وعلى\n موقعها االلكتروني إن ُوجد.\n ثالثا ً :تُرسل الجهات الشارية كافة المعلومات المنصوص عليها في الفقرتين ً\nأوال وثانيًا أعاله على\nالبريد اإللكتروني لهيئة الشراء العام contact@ppa.gov.lbضمن المهل ال ُمحددة لنشرها على\n المنصة اإللكترونية المركزية لدى هيئة الشراء العام وفقًا لألصول.\n بيروت في 2023/2/1٦\n رئيس هيئة الشراء العام\n د .جان العلية"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (37,'مذكرات الرئيس','مذكرة رقم 2023/3 : إلزامية نشر المعلومات المتعلقة بالصفقات على المنصة الإلكترونية المركزية لدى هيئة الشراء العام أيًا كان مصدر تمويلها','2023-05-17','https://www.ppa.gov.lb/ar/pages/details/37','{"https://admin.ppa.gov.lb/storage/listing-pages/files/nkwjO8SQFqZaPwZX0o9nG4ul1ntSONZwP5Kl-1779692661.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/nkwjO8SQFqZaPwZX0o9nG4ul1ntSONZwP5Kl-1779692661.pdf"}','ocr') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=37),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "292 ديئة الشراء العام اوه\nلكت\" زؤؤية . منافسة ٠ نزاهة افسة ٠ تزاد\nمذكرة رقم 1 /إه.ش. ع / ا 11 لذ\nحول إلزامية نشر المعلومات المتعلقة بالصفقات التي تجريها كافة الجهات الخاضعة\nلأحكام قانون الشراء العام على المنصة الإلكترونية المركزية لدى هيئة الشراء العام يا\nكان مصدر تمويلها\nبناءً على قانون الشراء العام رقم 7١5١/1555 تاريخ ٠١5١/1/15 سيما المواد الأولى» الثانية (ففرة ؟)»\nالثالتة و\"”/ا منه»\nيوضح ما يلي:\nعلى كافة الجهات الخاضعة لأحكام قانون الشراء العام وجوب نشر المعلومات المتعلقة بالصفقات التي\nتجريهاء على المنصة الإلكترونية المركزية لدى هيئة الشراء العام» أيّا كان مصدر تمويلهاء بما في ذلك\nالتمويل من العائدات المالية للدولة اللبنانية من حقوق السحب الخاصة.\nالبلسسسيبي 3\n< ب بيروت في ٠١77/5/11\n22١ 5 1 / رئيس هيئة الشراء العام\n|| | هصتت | |\n// ا ف 2 ١ 1\nطاءلامل.قمم 20 /\nلف طا./ا0ن.دمم©ه1ء ةدم لقع انون تدرج مهتم فصن"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (38,'مذكرات الرئيس','مذكرة رقم 2023/4 : تأليف لجان التلزيم والإستلام بعد تعديل قانون الشراء العام بموجب القانون رقم 309 تاريخ 19/4/2023','2023-08-02','https://www.ppa.gov.lb/ar/pages/details/38','{"https://admin.ppa.gov.lb/storage/listing-pages/files/2024-11-09-1731185739-memo_20230802_4.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/0kDuaNYPosUFBCJXPqrJrNj67YyvWeaiAiPD-1760221277.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/2024-11-09-1731185739-memo_20230802_4.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/0kDuaNYPosUFBCJXPqrJrNj67YyvWeaiAiPD-1760221277.pdf"}','ocr') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=38),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "1 الجمهوريّة اللبنانيتة\n225 ديئة الشراء العام\nمذكرة رقم 4 /ه.ش.ع/77 ٠٠١\nتتعلق بتأليف لجان التلزيم والإستلام بعد تعديل\nقانون الشراء العام بموجب القانون رقم \"٠١5 تاريخ 5077/4/١9\nبما أنّ القانون رقم 04\" تاريخ ,5075/5/١3 قد ألغى الفقرتين (؟و\"؟) من المادة )٠٠١(\nوالفقرتّين (١و\") من المادة »)٠١١( بحيث لم يعد يتوجب على الجهات الشارية إرسال لوائح إسمية\nلعرضها على التفتيش المركزي وديوان المحاسبة والهيئة العليا للتأديب لنشرها ليبدأ العمل بهاء\nوبما أنّ موجب إرسال اللوائح الإسمية مسبقاً قد انتفى بموجب التعديل المشار إليه أعلاه؛ مع احتفاظ\nهيئة الشراء العام بحقها في طلب هذه اللوائح عند الإقتضاءء للتأكد أن الجهات الشارية قد التزنمت\nبالقواعد القانونية والمعايير الصادرة عن الهيئة في موضوع تأليف لجان التلزيم والإستلام؛\nلجل كيك\nيرجى أخذ العلم م9\nرقب انزن2,” سروك ني : 01/4/15\"\n- 06\n١ كر رئيس هيئة الشراء العام\n8 مج\"\nةا رع\nاش > 00\n1"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (39,'مذكرات الرئيس','مذكرة رقم 2023/5 : موجهة الى كافة الجهات الخاضعة لأحكام قانون الشراء العام حول إيداع هيئة الشراء العام التصاريح عن صاحب الحق الاقتصادي','2023-08-03','https://www.ppa.gov.lb/ar/pages/details/39','{"https://admin.ppa.gov.lb/storage/listing-pages/files/7YyeAcbKYLoIvaVxbMPLBs0dNsjE2gWDfJUz-1760221168.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/7YyeAcbKYLoIvaVxbMPLBs0dNsjE2gWDfJUz-1760221168.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=39),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "مذكرة رقم /5هـ.ش.ع2023 /\n موجهة الى كافة الجهات الخاضعة ألحكام قانون الشراء العام\n حول إيداع هيئة الشراء العام التصاريح عن أصحاب الحق االقتصادي\n إن رئيس هيئة الشراء العام،\nبما ان القانون رقم ( ٢٠٢٣/٣٠٩تعديل بعض مواد قانون الشراء العام) الصادر في ٢٠٢٣/٤/١٩عدل\nالبند األول من المادة ٧من قانون الشراء العام (شروط مشاركة العارضين) بإضافة شرط «ي -التصريح\n عن أصحاب الحق االقتصادي حتى آخر درجة ملكية»،\nوبما ان المجلس الدستوري قد رد الطعن المقدم بالقانون رقم ( ٢٠٢٣/٣٠٩تعديل بعض مواد قانون الشراء\nالعام) في جميع األسباب التي بني عليها بموجب قراره رقم ٢٠٢٣/٧تاريخ ٢٠٢٣/٥/١١المنشور في\n الجريدة الرسمية في العدد ٢٤تاريخ ،٢٠٢٣/٦/٨\nوبما ان الفقرة ( )٩من المادة ٧٦من قانون الشراء العام «مهام هيئة الشراء العام» نصت على انه من مهام\nويحق لها في\n ّ هيئة الشراء العام «مراقبة وتقييم تطبيق النصوص القانونية والقواعد التي تَرعى الشراء العام،\nطالع على سجل الشراء لدى الجهة الشارية ،مع مراعاة سرية البيانات بحسب أحكام المادة ٦ هذا اإلطار اال ّ\nمكامن الخلل و/أو مخالفة القوانين في كل الجهاتِّ من هذا القانون .تُن ِّّ\n ظم الهيئة تقارير دورية تتناول\nالشارية ،وترفعها إلى رئاسة الجمهورية ومجلس النواب ومجلس الوزراء وديوان المحاسبة والتفتيش المركزي،\n وتنشرها وفق األصول»،\nوبما ان الفقرة ( )١١من المادة ٧٦من قانون الشراء العام «مهام هيئة الشراء العام» قد نصت على ان من\n«جمع البيانات والمستندات الخاصة بعمليات الشراء العام ،على كافة المستويات،\n مهام هيئة الشراء العام َ\nالمنصة المركزّية بما في ذلك أنواع وطرق التعاقد والقطاعات االقتصادية المشاركة وبيانات تنفيذ\n ّ على\nالممولة من جهات مانحة وغيرها ،وذلك في قاعدة بيانات مركزية لديها ،بشكل يتيح سهولة قراءة\n َّ المشاريع\n الدولية المعتمدة في هذا المجال»،"}, {"o": 1, "l": null, "b": "ّ وتحليل هذه البيانات والمستندات وبحسب المعايير\nوبما ان الفقرة ( )١٥من المادة ٧٦من قانون الشراء العام «مهام هيئة الشراء العام» نصت على انه من\nمهام هيئة الشراء العام «معالجة وتحليل المعلومات الخاصة بعمليات الشراء العام ،ووضع وإصدار معايير\n األداء وتحرير تقارير تحليلية وإحصائية ونشرها»،\n1/2\n\f لــــــــــــذلك،\n ُيطلب إلى كافة الجهات الخاضعة ألحكام قانون الشراء العام ما يلي:\nأوالا :إيداع هيئة الشراء العام التصاريح عن أصحاب الحق االقتصادي لكافة الصفقات المعلن عنها على\nالموقع اإللكتروني لهيئة لهيئة الشراء العام اعتبا ار من تاريخ ،٢٠٢٣/٦/٨والتي قدمت لها عروض ،بغض\nالنظر عن مسار التلزيم ،باستثناء عمليات الشراء بالفاتورة ،مع مراعاة احكام المذكرة رقم /٦هـ.ش.ع٢٠٢٢/\n تاريخ .٢٠٢٢/٨/١٩\nثاني ا :تضمين دفاتر الشروط الخاصة تقديم العارض التصريح عن أصحاب الحق االقتصادي على الشكل\nيبين فيه أصحاب الحق االقتصادي حتى آخر درجة ملكية بحسب النموذج\n التالي\" :تصريح من العارض ّ\nم ١٨الصادر عن و ازرة المالية (كل شخص طبيعي يملك او يسيطر فعليا في المحصلة النهائية على النشاط\n الذي يمارسه العارض ،بصورة مباشرة او غير مباشرة ،سواء كان هذا العارض شخص طبيعي او معنوي).\n بيروت في 2023/8/3\n رئيس هيئة الشراء العام\n د .جان العلية\n2/2"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (40,'مذكرات الرئيس','مذكرة رقم 2023/6 : حول تضمين دفاتر الشروط المتعلقة بصفقات التأمين حصول العارض على إفادة من وزارة الإقتصاد والتجارة – لجن مراقبة هيئات الضمان','2023-08-09','https://www.ppa.gov.lb/ar/pages/details/40','{"https://admin.ppa.gov.lb/storage/listing-pages/files/0yFlUW23RpVUMnY9kgtINR1fG56Whh10ZGdw-1760221330.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/0yFlUW23RpVUMnY9kgtINR1fG56Whh10ZGdw-1760221330.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=40),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "مذكرة رقم /6هـ.ش.ع2023 /\n موجهة الى كافة الجهات الخاضعة ألحكام قانون الشراء العام\n حول تضمين دفاتر الشروط المتعلقة بصفقات التأمين حصول العارض على\n إفادة من وزارة اإلقتصاد والتجارة – لجنة مراقبة هيئات الضمان –\n إن رئيس هيئة الشراء العام،\n بناء على قانون الشراء العام سيما المادة 76منه،\n ً\nالمسجل لدى هيئة\n بناء على كتاب وزير اإلقتصاد والتجارة رقم /2349ل.م.ض 2023/.تاريخ ُ 2023/7/26\n ً\n الشراء العام برقم /1010ه.ش.ع 2023/تاريخ ،2023/7/26\n ُيقرر ما يلي:\nُيطلب إلى كافة الجهات الخاضعة ألحكام قانون الشراء العام تضمين دفاتر الشروط المتعلقة بصفقات التأمين،\nحصول العارض على إفادة من و ازرة اإلقتصاد والتجارة – لجنة مراقبة هيئات الضمان– ال يعود تاريخها ألكثر\nمن ثالثة أشهر من تاريخ جلسة فض العرض ،تفيد بأن شركة التأمين التي يمّثلها العارض مستوفية للشروط\nحدثة لدى اللجنة عن المطلوبة بحسب القانون ،وأن هذه اإلفادة قد أُعطيت باإلستناد إلى آخر المعلومات ُ\n الم ّ\n شركات التأمين.\n بيروت في 2023/8/9\n رئيس هيئة الشراء العام\n د .جان العلية\n1/1"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (41,'مذكرات الرئيس','مذكرة رقم 2023/7 : بوجوب تضمين دفاتر الشروط الخاصة طلب : إفادات صادرة عن الصندوق الوطني للضمان الاجتماعي، وزارة المالية، من البلدية التي تقع أعمال المناقصة ضمن نطاقها.','2023-10-31','https://www.ppa.gov.lb/ar/pages/details/41','{"https://admin.ppa.gov.lb/storage/listing-pages/files/eBAssyAAhrKhZUaK3VNHwHJhcFfiEZSrAZjH-1760221815.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/eBAssyAAhrKhZUaK3VNHwHJhcFfiEZSrAZjH-1760221815.pdf"}','ocr') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=41),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "م الجمصوريّة اللبنانيتة\nفكت هيئةالشراء العام\nبيروت في : 0 ١١ 1\nمذكرة رقم_ ره .ش.ع./ ٠١77\nإن رئيس هيئة الشراء العام»\nبناءً على المادة 848 من قانون الشراء العام»\nبناءً على المادة 7 من قانون الشراء العام التي نصّت في البند اولاً: شروط المشاركة - الفقرة (ج)\n'الايفاء بالتلزيمات الضريبيّة واشتراكات الضمان الاجتماعي' .\nيُذكر جميع الجهات الشارية الخاضعة لأحكام قانون الشراء العام بوجوب تضمين دفاتر الشروط الخاصة\nطلب الافادت التالية كشرط للمشاركة في المشتريات العموميّة:\n-١ إفادة براءة ذمة صادرة عن الصندوق الوطني للضمان الاجتماعي.\n\"- إفادة براءة ذمة صادرة من وزارة المالية.\n-٠ إفادة براءة ذمة من البلدية التي تقع أعمال المناقصة ضمن نطاقهاء تفيد تسديد الرسوم البلدية\nالع\nرئيس هيئة الشراء العام\n27\n3 د د. جان العليّة\n0\n2"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (42,'مذكرات الرئيس','مذكرة رقم 2023/8 : حول الإفادات والمستندات التي يجب أن تتضمنها دفاتر الشروط الخاصة من ضمن الشروط الإدارية','2023-12-12','https://www.ppa.gov.lb/ar/pages/details/42','{"https://admin.ppa.gov.lb/storage/listing-pages/files/Ayujf5jFiGywptCVmnZsszk4ghCXyhsLyIdc-1760221743.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/Ayujf5jFiGywptCVmnZsszk4ghCXyhsLyIdc-1760221743.pdf"}','text') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=42),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "مذكرة رقم /8هـ.ش.ع2023/.\n موجهة إلى كافة الجهات الخاضعة ألحكام قانون الشراء العام\n حول اإلفادات والمستندات التي يجب أن تتضمنها دفاتر الشروط الخاصة من\n ضمن الشروط اإلدارية\n إن رئيس هيئة الشراء العام،\n بنا ًء على قانون الشراء العام رقم 2021/244وتعديالته ،سيما المادتين 7و 88منه،\n يقرر ما يلي:\n أوالً :ت ُلغى المذكرة رقم /7هـ.ش.ع 2023/.تاريخ 2023/10/31ويُستعاض عنها بما يلي:\nأ -على جميع الجهات الخاضعة ألحكام قانون الشراء العام تضمين دفاتر الشروط الخاصة ،على األقل،\n طلب اإلفادات والمستندات التالية من ضمن الشروط اإلدارية المتعلقة بالصفقات العمومية:\n -1كتاب التعهد (التصريح)...\n المفوض بالتوقيع عن العارض ونموذج توقيعه. ّ -2إذاعة تجارية يُبيَّن فيها صاحب الحق\n -3التفويض القانوني اذا وقع العرض شخص غير الشخص الذي يملك حق التوقيع عن العارض\n بحسب اإلذاعة التجارية ،مصدّق لدى الكاتب العدل.\n -4سجل عدلي للمفوض بالتوقيع أو \"من يمثله قانونًا\" ال يتعدى تاريخه الثالثة أشهر من تاريخ جلسة\n فض العروض.\n -5عقد الشراكة مصدق لدى الكاتب العدل في حال توجبه.\n -6شهادة تسجيل العارض لدى مديرية الضريبة على القيمة المضافة إذا كان خاضعا ً لها ،أو شهادة\n ً\nمسجال في عدم التسجيل اذا لم يكن خاضعًا ،وفي هذه الحالة يلتزم العارض بسعره وان أصبح\n الضريبة على القيمة المضافة خالل فترة التنفيذ.\n -7شهادة تسجيل العارض لدى وزارة المالية – مديرية الواردات.\n -8إفادة صادرة عن وزارة المالية تثبت إيفاء العارض باإللتزامات الضريبية المتوجبة عليه.\n -9براءة ذمة من الصندوق الوطني للضمان اإلجتماعي \"شاملة أو صالحة لإلشتراك في الصفقات\nالعمومية\" صالحة بتاريخ جلسة فض العروض ،تفيد بأن العارض سدد جميع اشتراكاته (يجب أن\nمسجال في الصندوق الوطني للضمان اإلجتماعي وترفض كل إفادة يُذكر عليها ً يكون العارض\n عبارة \"مؤسسة غير مسجلة\")."}, {"o": 1, "l": null, "b": "-10إفادة صادرة عن البلدية التي يقع المركز الرئيسي للعارض ضمن نطاقها بحسب شهادة التسجيل\n في السجل التجاري ،تفيد أنه سدد كامل الرسوم البلدية المتوجبة عليه.\n -11إفادة شاملة صادرة عن السجل التجاري تبيّن المؤسسين واألعضاء والمساهمين أو الشركاء،\n المفوضين بالتوقيع ،المدير ،رأس المال ،نشاط العارض والوقوعات الجارية.\n -12افادة صادرة عن المرجع المختص تُثبت ان العارض ليس في حالة إفالس.\n -13افادة صادرة عن المرجع المختص تُثبت ان العارض ليس في حالة تصفية قضائية.\n -14ضمان العرض المطلوب في دفتر الشروط الخاص بالصفقة وفقًا ألحكام المادتين 34و 36من\n قانون الشراء العام.\n 1/2\n\f -15تصريح من العارض يبيّن فيه صاحب/أصحاب الحق االقتصادي وفقًا للنموذج م 18الصادر عن\nوزارة المالية (كل شخص طبيعي يملك او يسيطر فعليًا في المحصلة النهائية على النشاط الذي\nيمارسه العارض ،بصورة مباشرة او غير مباشرة ،سواء كان هذا العارض شخص طبيعي او\n معنوي).\n -16نسخ عن بطاقات التعريف (هوية /جواز سفر) لصاحب (أصحاب) الحق االقتصادي.\n -17نسخ عن بطاقات التعريف (هوية /جواز سفر) لكل شخص يمثل العارض (من ينوب عن العارض\nمفوضفي عالقته مع سلطة التعاقد :وكيل قانوني ،ممثل الشخص المعنوي أو ال ّ\n بالتوقيع عنه.)...\n -18مستند تصريح النزاهة وفقًا للنموذج المتاح على الموقع اإللكتروني لهيئة الشراء العام.\n ب -في حال إشتراك عارض أجنبي يتوجب على هذا العارض أن يُراعي احد الشروط التالية:\n -1أن يكون من ضمن إئتالف يضم شركة لبنانية على األقل تتوفر فيها الشروط المطلوبة بموجب\n دفتر الشروط الخاص بالصفقة.\n -2الحضور الشخصي للممثل القانوني عن الشركة للمشاركة في إجراءات الشراء.\n -3أن يكون لها وكيل أو ممثل في لبنان مكلف توقيع العقد عنها.\n إضافةً إلى الشروط أعاله ،يتوجب على العارض األجنبي تقديم ما يلي:\n -1شهادة تسجيل الشركة أو المؤسسة لدى المراجع المختصة في بلده."}, {"o": 2, "l": null, "b": "-2إفادة من وزارة االقتصاد والتجارة اللبنانية تُثبت انطباق أحكام قانون مقاطعة العدو االسرائيلي\n على العارض.\n ً\n -3اإلفادات المطلوبة بموجب الفقرة (أوال-أ) أعاله بحسب قوانين البلد الذي يوجد فيه العارض،\n على أن تكون هذه اإلفادات مصدقة وفقًا لألصول من المراجع المختصة.\nج -يُحدَّد تاريخ صالحية كل إفادة وفقًا لطبيعتها على أن ال يزيد عن ستة أشهر من تاريخ جلسة فض\n العروض وذلك بالنسبة لإلفادات التي تصدر دون تاريخ صالحية.\nثانيًا :تُنشر هذه المذكرة على المنصة اإللكترونية المركزية لدى هيئة الشراء العام ويُعمل بها فور صدورها.\n بيروت في 2023/12/12\n رئيس هيئة الشراء العام\n د .جان العليًة\n 2/2"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (43,'مذكرات الرئيس','مذكرة رقم 2024/3 : موجهة إلى الجهات الشارية حول توضيح بعض مهام لجان التلزيم','2024-07-24','https://www.ppa.gov.lb/ar/pages/details/43','{"https://admin.ppa.gov.lb/storage/listing-pages/files/Txnt5e3oRpRVdQatjya31MDbCq7ngJiYwkWw-1760214482.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/Txnt5e3oRpRVdQatjya31MDbCq7ngJiYwkWw-1760214482.pdf"}','ocr') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=43),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "م الجمهورية اللبنانيتة\nدك هيئة الشراء العام\nملك .. شفافية ٠ منافسة ٠ه نزاهة\nمذكرة رقم ”/هرش.ع./؛ ٠١1\nموجهة إلى الجهات الشارية\nحول توضيح بعض مهام لجان التلزيم\nإن رئيس هيئة الشراء العام»\nبناءً على قانون الشراء العام رقم 5 ٠٠71/75 النافذ اعتباراً من تاريخ ٠١77/17/75 وتعديلاته» سيما\nالمواد ا ١ل دم كلاء حل 716٠١\nوبما أن المشترع وعملاً باحكام الفقرة ثانياً- ١ من المادة ٠٠١ من قانون الشراء العام قد اولى \"لجان\nالتلزيم حصرأً دراسة ملفات التأهيل المسبق وفتح وتقييم العروضء وبالتالي تحديد العرض الأنسب\".\nوبما أن مفهوم الجهة الشارية المحدد في الفقرة الثالثة من المادة الثانية يختلف إختلافا بين عن مفهوم لجان\nالتلزيم المذكور في المادة ٠٠١ من قانون الشراء العام» التي تتألف من أهل الخيرة والاختصاصء وفقاً\nلأسس وضعتها هيئة الشراء العام» بموجب القرار رقم 5/د.ش.ع تاريخ .7077/٠١/٠١\nوبما أن بعض مواد قانون الشراء العام قد اعطت الجهات الشارية بمعناها العام صلاحية القيام ببعض\nالاعمال التالية لمرحلة فتح العروضء كدراسة العروض وتصحيحها تمهيداً لتقييمها» ومن ثم اتخاذ القرار\nبقبول العرض أو رفضه.ء وذلك وفقاً للتالي:\n- المادة /٠ه/ قد نصّت على أن «تدرس الجهة الشارية العروض المالية على نحو منفصل بحيث\nتدرسها بعد الانتهاء من تدقيق وتقييم العروض الإدارية والفنية»» وفي الفقرة ” «تعتبر الجهة\nالشارية العرض مستجيباً للمتطلبات...»» وفي الفقرة \" «يجوز للجهة الشارية الطلب خطياً...»»\nوفي الفقرة 4 «ترفض الجهة الشارية العرض...»؛ وفي الفقرة © «ثُقيّم الجهة الشارية العروض\nالمقبولة...»؛ وفي الفقرة ٠ «تقوم الجهة الشارية بتقييم العروض ضمن مهلة...»\n- المادة /١١/ الفقرة ” من ثانياً نصّت على أن «نْصحّح الجهةٌ الشارية أي أخطاء حسابية محضة\nتكتشفها أثناء فحصها العروض...»\nلذلك"}, {"o": 1, "l": null, "b": "وبغية تصويب مسار الشراء العام؛ والتأكيد على مبدأ استقلالية عمل لجان التلزيم؛ توضح هيئة الشراء\nالعام ان المهام المشار اليها اعلاه» تدخل في صلب عمل لجان التلزيم التي تؤلفها كل جهة شارية وفقاً\nللأصول.\nبيروت فى 4؟/714/.1.٠\nمج كيو 7 رئيس هيئة الشر اع العام\n7\n|| | شت 80 ) )) د. جان اعد\nكت - ٠ ذا\nو ا\nلحي\n1/1"}]$j$::jsonb) e;
insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (44,'مذكرات الرئيس','مذكرة رقم 2024/4 : موجهة إلى كافة الجهات الخاضعة لأحكام قانون الشراء العام حول وضع تقرير سنوي عن عمليات الشراء المجراة وإرساله إلى ديوان المحاسبة وهيئة الشراء العام ونشره وفق الأصول','2024-07-24','https://www.ppa.gov.lb/ar/pages/details/44','{"https://admin.ppa.gov.lb/storage/listing-pages/files/JM0xUnbAgrD69DnuCmRMGntfiyJEZpzKGq3D-1760214567.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/gFvYNhDFeAouCWEJEX4Bz1ekdkHgyhhl7DTw-1760214640.xlsx","https://admin.ppa.gov.lb/storage/listing-pages/files/vlgp0vf32gq0XCuHCxkUZ1dxTVtqJqV5nGme-1760214732.xlsx","https://admin.ppa.gov.lb/storage/listing-pages/files/I177PKSfawV0yVMNUUEdik8OYWexUaZ0Itu5-1760216775.xlsx","https://admin.ppa.gov.lb/storage/listing-pages/files/V3bjY24k0rw1Xvxu0lMruS4qINaRNq3BGKkj-1760216864.xlsx","https://admin.ppa.gov.lb/storage/listing-pages/files/RX50683b1P5yMqc3JoGzkvYfTKxPwJgxtCCd-1760216917.xlsx","https://admin.ppa.gov.lb/storage/listing-pages/files/PBYIUbEkTcZZYJWPnJ8vU2ZaLtSG12ZGZUsw-1760218250.xlsx","https://admin.ppa.gov.lb/storage/listing-pages/files/JM0xUnbAgrD69DnuCmRMGntfiyJEZpzKGq3D-1760214567.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/gFvYNhDFeAouCWEJEX4Bz1ekdkHgyhhl7DTw-1760214640.xlsx","https://admin.ppa.gov.lb/storage/listing-pages/files/vlgp0vf32gq0XCuHCxkUZ1dxTVtqJqV5nGme-1760214732.xlsx","https://admin.ppa.gov.lb/storage/listing-pages/files/I177PKSfawV0yVMNUUEdik8OYWexUaZ0Itu5-1760216775.xlsx","https://admin.ppa.gov.lb/storage/listing-pages/files/V3bjY24k0rw1Xvxu0lMruS4qINaRNq3BGKkj-1760216864.xlsx","https://admin.ppa.gov.lb/storage/listing-pages/files/RX50683b1P5yMqc3JoGzkvYfTKxPwJgxtCCd-1760216917.xlsx","https://admin.ppa.gov.lb/storage/listing-pages/files/PBYIUbEkTcZZYJWPnJ8vU2ZaLtSG12ZGZUsw-1760218250.xlsx"}','ocr') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=44),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "ك0 الجمهوريّة اللبنانيتة\n2ت هيئةالشراء العام\nمذكرة رقم ؛/هد.ش.ع./؛ ٠١1\nموجهة إلى كافة الجهات الخاضعة لأحكام قانون الشراء العام\nحول وضع تقرير سنوي عن عمليات الشراء المجراة\nوإرساله إلى ديوان المحاسبة وهيئة الشراء العام ونشره وفق الأصول\nإن رئيس هيئة الشراء العام,\nبناءً على قانون الشراء العام سيما الفقرة الثانية من المادة 84 والفقرة العاشرة من المادة 29٠١5١\n1 يقرر ما يلي:\nأولا: يُطلب إلى كافة الجهات الخاضعة لأحكام قانون الشراء العام وضع تقرير عن عمليات الشراء المجراة\nوفقاً للنماذج المرفقة والموجودة على منصة هيئة الشراء العامء وذلك:\n- عن الفترة الممتدة من بدء العمل بقانون الشراء العام لغاية ٠١77/17/١ وذلك ضمن مهلة شهر\nواحد من تاريخ نشر هذه المذكرة على الموقع الالكتروني لهيئة الشراء العام.\n- ضمن مهلة شهر واحد من بداية كل سنة مالية عن أعمال السنة السابقة وذلك إبتداءً من العام\nع\nثانيًا: يتم إرسال هذا التفرير بصيغته الورقية وفقًا للأصول إلى ديوان المحاسبة وهيئة الشراء العام ويتم\nنشره وفقًا للأصول.\nثالتا: يجب تحميل النماذج بنسختها المحدّثة في كل مرة تريد الجهة الشارية وضع تقريرها السنويء نظرًا\nللتحديثات التي قد تطرأ على هذه النماذج وعلى الطريقة والآلية الإلكترونية التي سيتم بواسطتها تزويد\nهيئة الشراء العام بنسخة عن التقرير والنماذج.\nرابعًا: ترسل نسخة إلكترونية عن كل نموذج يتم تعبئته إلى هيئة الشراء العام على البريد الإلكتروني التالي\n(3.8077.1جم1)6ء212مع) بصيغة (اءه<8) على الشكل التالي:\nموضوع الرسالة (08ع[:5): [اسم الجهة الشارية أو المتعاقدة]-[اسم النموذج]-[العام].\n» يتم إعادة تسمية الملف: [الجهة الشارية]-[ نموذج تقرير سنوي - عمليات الشراء بموجب\nالمناقصة العمومية ]٠١77[-]\nخامسًا: لحسن سير العمل يجب متابعة الموقع الإلكتروني لهيئة الشراء العام لمعرفة كل جديد يتعلق"}, {"o": 1, "l": null, "b": "بالنماذج وغيرها من الأمور التنظيميّة إلتزامًا بقانون الشراء العام,\nملاحظة:\nنصت المادة ١ فقرة 77 من قانون الشراء العام على ما يلي: \" التبليغ: خلافاً لأيّ نص آخرء عام أو خاص؛\nلا يُعتدَ بأيَ تبليغ إلا الذي يتم إلزاميّاً عبر المنصّة الإلكترونيّة المركزيّة لدى هيئة الشراء العام.\"\nسنالك\n- إن كل ما يتم نشره على الموقع الإلكتروني لهيئة الشراء العام يعتبر بمثابة تبليغ رسمي وإلزامي لكافة\nالجهات المعنية بتطبيق قانون الشراء العام.\n- مايلي أسماء النماذج التي يجب تعبئتها بصيغة [وع:17 وإرفاقها بالتقرير:\n0 نموذج تقرير سنوي - عمليات الشراء بموجب المناقصة العمومية\n© نموذج تقرير سنوي - عمليات الشراء بموجب طلب عروض الأسعار\n0 نموذج تقرير سنوي - عمليات الشراء بموجب الفاتورة.\n0 نموذج تقرير سنوي - عمليات الشراء بموجب المناقصة على مرحلتين\n0 نموذج تقرير سنوي - عمليات الشراء بموجب الإتفاق الرضائني\n6 نموذج تقرير سنوي - عمليات الشراء بموجب طلب الإقتراحات للخدمات الإستشارية\nبيروت في 5؟//ا./ ٠.75\nس0 رئيس هينة الشراء العا\n7/4 سس 0 و\n7و ا // 5\nا ا\nو لشراء العاىحه\nبحسا"}]$j$::jsonb) e;
