insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=53),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "الجريدة الرسمية العدد 7:74/1١/1١ 5 ١ وعدم\n-5-5--- 2 0\nالبند 774 صيانة المركزي؛ يحمل رقم وتاريخ هذا المرسوم.\nالفقرة 4 صيانة وسائل النقل مدة السلفة: سنة واحدة إعتبارا من تاريخ تأدية\nالنبذة ١ صيانة وسائل النقل قيمة السلفة.\nلللرح د ال.ل. كيفية تسديد السلفة: تسدد هذه السلفة إما نقدا\nفقط مائة وأربعون مليون ليرة لبنانية أو بإعتماد يلحظ في موازنة الهيئة العليا للإغاثة للعام\n0ك كلدل\nالمجموع العام «جرستر14 /لل المادة الثانية: يعتبر مجرد استعمال الجهة\nفقط مائة وأربعون مليون ليرة لبنانية المستلفة لأي جزء من السلفة إقرارا منها بالقدرة على\nالمادة الثانية: ينشر هذا المرسوم ويبلغ حيث2 التسديد وفق الأسس المنصوص عليها في المادة الأولى\nتدعو الحاجة. من هذا المرسوم.\nبيروت في 774/1١/55 المادة الثالثة: لا يجوز للجهة المستلفة وعلى\nصدر عن مجلس الوزراء مسؤوليتها أن تستعمل السلفة أو أي جزء منها في غير\nالإمضاء: محمد نجيب ميقاتي الغاية التي اعطيت من أجلها.\nرئيس مجلس الوزراء المادة الرابعة: على مدير الخزينة مدير\n١ الإمضاء: محمد نجيب ميقاتي الصرفيات» مدير الموازنة ومراقبة النفقات في وزارة\n0 المدرا المالية وجهاز المحاسبة لدى الهيئة العليا للإغاثئة» كل\nرئيس مجلس الوزراء في نطاق إختصاصه ملاحقة تسديد هذه السلفة في\nالإمضاء: محمد نجيب ميقاتي موأعيدها.\nوزير المالية 506 0 500\nالمادة الخامسة: ينشر هذا المرسوم ويبلغ حيث\nالإمضاء: يوسف خليل تدعو الحاجة.\nت فى \"4/1/7 77\nبيروت في ١74/٠١/17\nمرسوم رقم 5085 ١ صدر عن مجلس الوزراء\nإعطاء الهيئة العليا للإغائة سلفة خزينة الإمضاء: محمد نجيب ميقاتي\nإن مجلس الوزراء, رئيس مجلس الوزراء\nبناء على الدستور لا سيما المادة /17/ منه» الإمضاء: محمد نجيب ميقاتي\nبناء على قانون المحاسبة العمومية وتعديلاته» لا رئيس مجلس الوزراء\n55 وما نه\nسيما المادة 3١\" وما يليها منه الإمضاء: محمد نجيب ميقاتي"}, {"o": 1, "l": null, "b": "بناء على القانون رقم 554 تاريخ 7074/1/17 00000\n(الموازنة العامة لعام 076 ؟)» 0\nبناء على اقتراح رئيس مجلس الوزراء ووزير خخ 0\nالماليةء\nوبعد موافقة مجلس الوزراء بتاريخ ,5074/١١/9 مرسوم رقم 051 5 ١\nيرسم ما يأتي: تعديل السقوف المالية الواردة في بعض مواد\nالمادة الأولى: تُعملى الهيئة العليا للإغاثة سلفة ون ااا\nخزينة بقيمة /1٠١,0٠0,0٠00,.00/ ل.ل. (فقط متا إن مجلس الوزراء\nمليار ليرة لبنانية). بناء على الدستور لاسيما المادة 7 منهء\nالغاية من السلفة: إستكمال تغطية التدابير بناء على القانون رقم ١44 تاريخ 7071/9/19\nوالإجراءات المتعلقة بخطة الطوارئ الوطنية. وتعديلاته (الشراء العام في لبنان) لاسيما المواد\nطريقة تأدية السلفة: بأمر من محتسب المالية !١ 4\"()- ا10(7- 44 ولا4ء\n(2 لعأسترط\n5640 الجريدة الرسمية العدد (١ 5 ب 574/5١3١\nبناء على المرسوم رقم ١١775 تاريخ بناء على الدستور لا سيما المادة 9\" منه,\n6 (تعديل السقوف المالية الواردة في بعض بناء على المرسوم الاشتراعي رقم ١١١ تاريخ\nمواد قانون الشراء العام)» وتعديلاته (نظام الموظفين)»\n: توصية هيئة الشراء العا\n00 على توصية هيئة الشر 0 بناء على المرسوم الاشتراعي رقم ١5١ تاريخ\nبناء على اقتراح رئيس مجلس الوزراء» 5 وتعديلاته (قانون القضاء العدلي) لا سيما\nوبعد موافقة مجلس الوزراء بتاريخ ١ *3١75/٠١/7 المادة 19 من\nيرسم ما ياتي: بناء على المرسوم الاشتراعي رقم 47 تاريخ\nالمادة الأولى: عُدَلت السقوف المالية المحدّدة في 89 وتعديلاته (نظام التقاعد والصرف من\nمواد قانون الشراء العام في لبنان المذكورة أدناه بحيث . الخدمة)ء\nتصبح كالتالي: 1\n1 بناء على المرسوم رقم ٠051 تاريخ 70١1/8/1١\n- العادة ١١ (وضبع خط الشراء): /٠١/ مليار ين .. المتضمن تعيين قساة متدرجين 0 ا\nلبنانية بدلا من /ه/ مليارات ليرة لبنانية. وإلحاقهم بمعهد الدروس القضائية قسم القضاء العدلي"}, {"o": 2, "l": null, "b": "المادة 4ل فقرة ١ (ضمان العرض): /0/ ١ ومن بينهم اليد جان طنوسء 1\nمليارات ليرة لبنانية بدلا من /5,؟/ مليار ليرة لبنانية. 00 51 ' 1 له\n7 _ 20 بناء الطلب م من القاضي السيد جان\nالمادة /59- فقرة ١ () (دفع قيمة العقد): /٠١/ طنوس الى مجلس القضاء الأعلى بتاريخ 7074/1/9\nمليار ليرة لبنانية بدلا من /5/ مليارات ليرة لبنانية. على الاستدعاء المقدم منه والمسجل لدينا برقم\n/ 1 85 00 0 م منه والمسجل لدينا +\n- المادة /44/ (شروط استخدام طلب عروض ل تاريخ 4/1/8 1ل\nالأسعار): /١5/ مليار ليرة لب